window.APP_DC=[{"name":"طوبيا","chapters":[{"label":"سفر طوبيا 1","verses":[{"n":1,"text":"كان طوبيا وهو من سبط ومدينة نفتالي التي في الجليل الاعلى فوق نحشون وراء الطريق الاخذ غربا والى يسارها مدينة صفت"},{"n":2,"text":"قد جلي في عهد شلمناسر ملك اشور الا انه مع كونه في الجلاء لم يفارق سبيل الحق"},{"n":3,"text":"حتى كان كل ما يتيسر له يقسمه كل يوم على من جلي معه من اخوانه الذين من جنسه"},{"n":4,"text":"ومع انه كان احدث الجميع في سبط نفتالي لم يكن على شيء من شؤون الاحداث"},{"n":5,"text":"وكان اذا قصدوا كلهم عجول الذهب التي عملها يا ربعام ملك اسرائيل يتخلف وحده عن سائرهم"},{"n":6,"text":"فيمضي الى اورشليم الى هيكل الرب وهناك كان يسجد للرب اله اسرائيل ويوفي جميع بواكيره واعشاره"},{"n":7,"text":"واذا كانت السنة الثالثة كان يجعل جميع اعشاره للدخلاء والغرباء"},{"n":8,"text":"وعلى هذا وامثاله كان مثابرا منذ صبوته على وفق شريعة الله"},{"n":9,"text":"ولما ان صار رجلا اتخذ له امراة من سبطه اسمها حنة فولد له منها ولد فسماه باسمه"},{"n":10,"text":"وادبه منذ صغره على تقوى الله واجتناب كل خطيئة"},{"n":11,"text":"ولما جلي مع امراته وولده الى مدينة نينوى حيث كانت كل عشيرته"},{"n":12,"text":"وقد كانوا كلهم ياكلون من اطعمة الامم كان هو يصون نفسه ولم يتنجس قط بماكولاتهم"},{"n":13,"text":"ولاجل انه كان يذكر الرب بكل قلبه اتاه الله حظوة لدى الملك شلمناسر"},{"n":14,"text":"فاطلق له ان يذهب حيثما شاء ويفعل ما يريد"},{"n":15,"text":"فكان يطوف على كل من كان في الجلاء ويرشدهم بنصائح الخلاص"},{"n":16,"text":"ثم انه قدم راجيس مدينة ماداي وكان معه مما اثره به الملك عشرة قناطير من الفضة"},{"n":17,"text":"فراى بين الجمهور الغفير الذي من جنسه رجلا من سبطه يقال له غابيلوس في فاقة فدفع اليه الزنة المذكورة من الفضة بصك"},{"n":18,"text":"وكان بعد ايام كثيرة ان مات الملك شلمناسر فملك سنحاريب ابنه مكانه فوقع بنو اسرائيل عنده موقع الكراهة"},{"n":19,"text":"وكان طوبيا يطوف كل يوم على جميع عشيرته ويعزيهم ويؤاسي كل واحد من امواله على قدر وسعه"},{"n":20,"text":"فيطعم الجياع ويكسو العراة ويدفن الموتى والقتلى بغيرة شديدة"},{"n":21,"text":"ولما قفل الملك سنحاريب من ارض يهوذا هاربا من الضربة التي حاقه الله بها بسبب تجديفه وطفق لحنقه يقتل كثيرين من بني اسرائيل كان طوبيا يدفن اجسادهم"},{"n":22,"text":"فنما ذلك الى الملك فامر بقتله وضبط جميع ماله"},{"n":23,"text":"فهرب طوبيا بولده وزوجته عاريا واختبا لان كثيرين كانوا يحبونه"},{"n":24,"text":"وكان بعد خمسة واربعين يوما ان قتل الملك ابناه"},{"n":25,"text":"فعاد طوبيا الى منزله ورد عليه كل ماله"}]},{"label":"سفر طوبيا 2","verses":[{"n":1,"text":"وكان بعد ذلك في يوم عيد الرب ان صنعت مادبة عظيمة في بيت طوبيا"},{"n":2,"text":"فقال لابنه هلم فادع بعضا من سبطنا من المتقين لله لياكلوا معنا"},{"n":3,"text":"فانطلق ثم عاد فاخبره ان واحدا من بني اسرائيل مذبوح ملقى في السوق فلما سمع طوبيا نهض من موضعه مسرعا وترك العشاء وبلغ الجثة وهو صائم"},{"n":4,"text":"فرفعها وحملها الى بيته سرا ليدفنها بالتحفظ بعد مغيب الشمس"},{"n":5,"text":"وبعد ان خبا الجثة اكل الطعام باكيا مرتعدا"},{"n":6,"text":"فذكر الكلام الذي تكلم به الرب على لسان عاموس النبي ايام اعيادكم تتحول الى عويل ونحيب"},{"n":7,"text":"ولما غربت الشمس ذهب ودفنها"},{"n":8,"text":"وكان جميع ذوي قرابته يلومونه قائلين لاجل هذا امر بقتلك وما كدت تنجو من قضاء الموت حتى عدت تدفن الموتى"},{"n":9,"text":"واما طوبيا فاذ كان خوفه من الله اعظم من خوفه من الملك كان لا يزال يخطف جثث القتلى ويخباها في بيته فيدفنها عند \nانتصاف الليل"},{"n":10,"text":"واتفق في بعض الايام وقد تعب من دفن الموتى انه وافى بيته فرمى بنفسه الى جانب الحائط ونام"},{"n":11,"text":"فوقع ذرق من عش خطاف في عينيه وهو سخن فعمي"},{"n":12,"text":"وانما اذن الرب ان تعرض له هذه التجربة لتكون لمن بعده قدوة صبره كايوب الصديق"},{"n":13,"text":"فانه اذ كان لم ينفك عن تقوى الله منذ صغره وحافظا لوصاياه لم يكن يتذمر على الله لما ناله من بلوى العمى"},{"n":14,"text":"ولكنه ثبت في خوف الله شاكرا له طول ايام حياته"},{"n":15,"text":"وكما كان القديس ايوب يعيره الملوك كان انسباء هذا وذووه يسخرون من عيشته قائلين"},{"n":16,"text":"اين رجاؤك الذي لاجله كنت تبذل الصدقات وتدفن الموتى"},{"n":17,"text":"فيزجرهم طوبيا قائلا لا تتكلموا كذا"},{"n":18,"text":"فانما نحن بنو القديسين وانما ننتظر تلك الحياة التي يهبها الله للذين لا يصرفون ايمانهم عنه ابدا"},{"n":19,"text":"وكانت حنة امراته تذهب كل يوم الى الحاكة وتاتي من تعب يديها بما يتاتى لها تحصيله من الميرة"},{"n":20,"text":"واتفق انها اخذت جديا وحملته الى البيت"},{"n":21,"text":"فلما سمع بعلها صوت ثغاء الجدي قال انظروا لعله يكون مسروقا فردوه على اربابه اذ لا يحل لنا ان ناكل ولا نلمس شيئا \nمسروقا"},{"n":22,"text":"فاجابته امراته وهي مغضبة قد وضح بطلان رجائك وصدقاتك الان قد عرفت وبهذا الكلام ومثله كانت تعيره"}]},{"label":"سفر طوبيا 3","verses":[{"n":1,"text":"حينئذ ان طوبيا وطفق يصلي بدموع"},{"n":2,"text":"وقال عادل انت ايها الرب وجميع احكامك مستقيمة وطرقك كلها رحمة وحق وحكم"},{"n":3,"text":"فالان اذكرني يا رب ولا تنتقم عن خطاياي ولا تذكر ذنوبي ولا ذنوب ابائي"},{"n":4,"text":"لانا لم نطع اوامرك فلاجل ذلك اسلمنا الى النهب والجلاء والموت واصبحنا احدوثة وعارا في جميع الامم التي بددتنا بينها"},{"n":5,"text":"فالان يا رب عظيمة احكامك لانا لم نعمل بحسب وصاياك ولا سلكنا بخلوص امامك"},{"n":6,"text":"والان يا رب بحسب مشيئتك اصنع بي ومر ان تقبض روحي بسلام لان الموت لي خير من الحياة"},{"n":7,"text":"واتفق في ذلك اليوم عينه ان سارة بنة رعوئيل في راجيس مدينة الماديين سمعت هي ايضا تعييرا من احدى جواري ابيها"},{"n":8,"text":"لانه كان قد عقد لها على سبعة رجال وكان شيطان اسمه ازموداوس يقتلهم على اثر دخولهم عليها في الحال"},{"n":9,"text":"واذ كانت تنتهر الجارية لذنب اجابتها قائلة لا راينا لك ابنا ولا ابنة على الارض يا قاتلة ازواجها"},{"n":10,"text":"اتريدين ان تقتليني كما قتلت سبعة رجال فلما سمعت هذا الكلام صعدت الى علية بيتها فاقامت ثلاثة ايام وثلاث ليال لا \nتاكل ولا تشرب"},{"n":11,"text":"بل استمرت تصلي وتتضرع الى الله بدموع ان يكشف عنها هذا العار"},{"n":12,"text":"ولما اتمت صلاتها في اليوم الثالث وباركت الرب"},{"n":13,"text":"قالت تبارك اسمك يا اله ابائنا الذي بعد غضبه يصنع الرحمة وفي زمان البؤس يغفر الخطايا للذين يدعونه"},{"n":14,"text":"اليك يا رب اقبل بوجهي واليك اصرف ناظري"},{"n":15,"text":"اتوسل اليك يا رب ان تحلني من وثاق هذا العار او تاخذني عن الارض"},{"n":16,"text":"انك يا رب عالم باني لم اشته رجلا قط واني قد صنت نفسي منزهة عن كل شهوة"},{"n":17,"text":"ولم اكن قط امازج ارباب الملاهي ولا اعاشر السالكين بالطيش"},{"n":18,"text":"وانما رضيت بان اتخذ رجلا لخوفك لا لشهوتي"},{"n":19,"text":"ولعلي لم اكن مستاهلة لهم او لم يكونوا مستحقين لي فلعلك ابقيتني لبعل اخر"},{"n":20,"text":"لان مشورتك لا يدركها انسان"},{"n":21,"text":"على ان من يعبدك يوقن ان حياته ان انقضت بالمحن فستفوز باكليلها وان حلت به شدة فسينقذ وان عرض على التاديب فله ان يرجع الىرحمتك"},{"n":22,"text":"لانك لا تسر بهلاكنا فتلقي السكينة بعد العاصفة وبعد البكاء والنحيب تفيض التهلل"},{"n":23,"text":"فليكن اسمك يا اله اسرائيل مباركا مدى الدهور"},{"n":24,"text":"في ذلك الحين استجيبت صلوات الاثنين امام مجد الله العلي"},{"n":25,"text":"فارسل الرب ملاكه القديس رافائيل ليشفي كلا الاثنين اللذين رفعت صلواتهما في وقت واحد الى حضرة الرب"}]},{"label":"سفر طوبيا 4","verses":[{"n":1,"text":"واذ خال طوبيا ان قد استجيبت صلاته وتهيا له ان يموت استدعى اليه طوبيا ابنه"},{"n":2,"text":"وقال له اسمع يا بني كلمات في واجعلها في قلبك مثل الاساس"},{"n":3,"text":"اذا قبض الله نفسي فادفن جسدي واكرم والدتك جميع ايام حياتها"},{"n":4,"text":"واذكر ما المشقات التي عانتها لاجلك في جوفها وما كان اشدها"},{"n":5,"text":"ومتى استوفت هي ايضا زمان حياتها فادفنها الى جانبي"},{"n":6,"text":"وانت فليكن الله في قلبك جميع ايام حياتك واحذر ان ترضى بالخطيئة وتتعدى وصايا الرب الهنا"},{"n":7,"text":"تصدق من مالك ولا تحول وجهك عن فقير وحينئذ فوجه الرب لا يحول عنك"},{"n":8,"text":"كن رحيما على قدر طاقتك"},{"n":9,"text":"ان كان لك كثير فابذل كثيرا وان كان لك قليل فاجتهد ان تبذل القليل عن نفس طيبة"},{"n":10,"text":"فانك تدخر لك ثوابا جميلا الى يوم الضرورة"},{"n":11,"text":"لان الصدقة تنجي من كل خطيئة ومن الموت ولا تدع النفس تصير الى الظلمة"},{"n":12,"text":"ان الصدقة هي رجاء عظيم عند الله العلي لجميع صانعيها"},{"n":13,"text":"احذر لنفسك يا بني من كل زنى ولا تتجاوز امراتك مستبيحا معرفة الاثم ابدا"},{"n":14,"text":"ولا تدع الكبر يستولي على افكارك واقوالك لان الكبر مبدا كل هلاك"},{"n":15,"text":"وكل من خدمك بشيء فاوفه اجرته لساعته واجرة اجيرك لا تبق عندك ابدا"},{"n":16,"text":"كل ما تكره ان يفعله غيرك بك فاياك ان تفعله انت بغيرك"},{"n":17,"text":"كل خبزك مع الجياع والمساكين واكس العراة من ثيابك"},{"n":18,"text":"ضع خبزك وخمرك على مدفن البار ولا تاكل ولا تشرب منهما مع الخطاة"},{"n":19,"text":"التمس مشورة الحكيم دائما"},{"n":20,"text":"وبارك الله في كل حين واسترشده لتقويم سبلك واقرار كل مشوراتك فيه"},{"n":21,"text":"ثم اعلم يا بني اني قد اعطيت وانت صغير عشرة قناطير من الفضة لغابيلوس في راجيس مدينة الماديين ومعي بها صك"},{"n":22,"text":"وحيث ذلك فانظر كيف تتوصل اليه فتقبض منه الزنة المذكورة من الفضة وترد عليه صكه"},{"n":23,"text":"ولا تخف يا ولدي فانا نعيش عيشة الفقراء ولكن سيكون لنا خير كثير اذا اتقينا الله وابتعدنا عن كل خطيئة وفعلنا خيرا"}]},{"label":"سفر طوبيا 5","verses":[{"n":1,"text":"فاجاب طوبيا اباه وقال يا ابت كل ما امرتني به افعله"},{"n":2,"text":"واما هذا المال فما ادري كيف احصله فان الرجل لا يعرفني وانا لا اعرفه فما العلامة التي اعطيها له بل الطريق التي تؤدي الى هناك لا اعرفها ايضا"},{"n":3,"text":"فاجابه ابوه وقال ان عندي صكه فاذا عرضته عليه فانه يؤدي عاجلا"},{"n":4,"text":"والان هلم فالتمس لك رجلا ثقة يصحبك باجرته حتى تستوفي المال وانا حي"},{"n":5,"text":"فبينما خرج طوبيا اذا بفتى بهي قد وقف مشمرا كانه متاهب للمسير"},{"n":6,"text":"فسلم عليه وهو يجهل انه ملاك الله وقال من اين اقبلت يا فتى الخير"},{"n":7,"text":"قال انا من بني اسرائيل فقال له طوبيا هل تعرف الطريق الاخذة الى بلاد الماديين"},{"n":8,"text":"قال اعرفها وقد سلكت جميع طرقها مرارا كثيرة وكنت نازلا باخينا غابيلوس المقيم براجيس مدينة الماديين التي في جبل \nاحمتا"},{"n":9,"text":"فقال له طوبيا انتظرني حتى اخبر ابي بهذا"},{"n":10,"text":"ودخل طوبيا واخبر اباه بجميع ذلك فتعجب ابوه وطلب ان يدخل عليه"},{"n":11,"text":"فدخل وسلم عليه وقال ليكن لك فرح دائم"},{"n":12,"text":"فاجاب طوبيا واي فرح يكون لي انا المقيم في الظلام لا ابصر ضوء السماء"},{"n":13,"text":"فقال له الفتى كن طيب القلب فانك عن قليل تنال البرء من لدن الله"},{"n":14,"text":"فقال له طوبيا هل لك ان تبلغ ابني الى غابيلوس في راجيس مدينة الماديين وانا اوفيك اجرتك متى رجعت"},{"n":15,"text":"فقال له الملاك اخذه واعود به اليك"},{"n":16,"text":"فقال له طوبيا اخبرني من اي عشيرة ومن اي سبط انت"},{"n":17,"text":"فقال له رافائيل الملاك افي نسب الاجير حاجتك ام في الاجير الذي يذهب مع ابنك"},{"n":18,"text":"ولكن لكي لا اقلق بالك انا عزريا بن حننيا العظيم"},{"n":19,"text":"فقال له طوبيا انك من نسب كريم غير اني ارجو ان لا يسوءك كوني طلبت معرفة نسبك"},{"n":20,"text":"فقال له الملاك هاءنذا اخذ ابنك سالما وساعود به اليك سالما"},{"n":21,"text":"قال طوبيا انطلقا بسلام وليكن الله في طريقكما وملاكه يرافقكما"},{"n":22,"text":"حينئذ اخذا كل ما ارادا اخذه من اهبة الطريق وودع طوبيا اباه وامه وسارا كلاهما معا"},{"n":23,"text":"فلما فصلا جعلت امه تبكي وتقول قد اخذت عكازة شيخوختنا وابعدتها عنا"},{"n":24,"text":"لا كان هذا المال الذي ارسلته لاجله"},{"n":25,"text":"لقد كان في رزقنا القليل ما يكفي لان نعد النظر الى ولدنا غنى عظيما"},{"n":26,"text":"فقال لها طوبيا لا تبكي ان ولدنا سيصل سالما ويعود الينا سالما وعيناك تبصرانه"},{"n":27,"text":"فاني واثق بان ملاك الله الصالح يصحبه ويدبره في جميع احواله حتى يرجع الينا بفرح"},{"n":28,"text":"فكفت امه عن البكاء عند هذا الكلام وسكتت"}]},{"label":"سفر طوبيا 6","verses":[{"n":1,"text":"وسافر طوبيا والكلب يتبعه فبات اول منزلة بجانب نهر دجلة"},{"n":2,"text":"وخرج ليغسل رجليه فاذا بحوت عظيم قد خرج ليفترسه"},{"n":3,"text":"فارتاع طوبيا وصرخ بصوت عظيم قائلا يا مولاي قد اقتحمني"},{"n":4,"text":"فقال له الملاك امسك بخيشومه واجتذبه اليك ففعل كذلك واجتذبه الى اليبس فاخذ يختبط عند رجليه"},{"n":5,"text":"فقال له الملاك شق جوف الحوت واحتفظ بقلبه ومرارته وكبده فان لك بها منفعة لعلاج مفيد"},{"n":6,"text":"ففعل كذلك ثم شوى من لحمه فاخذا للطريق وملحا سائره حتى يكون لهما ما يكفيهما الى ان يبلغا راجيس مدينة الماديين"},{"n":7,"text":"ثم ان طوبيا سال الملاك وقال له نشدتك يا اخي عزريا ان تخبرني ما العلاج الذي يؤخذ من هذه الاشياء التي امرتني ان \nاذخرها من الحوت"},{"n":8,"text":"فاجابه الملاك قائلا اذا القيت شيئا من قلبه على الجمر فدخانه يطرد كل جنس من الشياطين في رجل كان او امراة بحيث لا \nيعود يقربهماابدا"},{"n":9,"text":"والمرارة تنفع لمسح العيون التي عليها غشاء فتبرا"},{"n":10,"text":"وقال طوبيا اين تريد ان ننزل"},{"n":11,"text":"فقال الملاك ان هنا رجلا اسمه رعوئيل من ذوي قرابتك من سبطك وله بنت اسمها سارة وليس له من ذكر ولا انثى سواها"},{"n":12,"text":"فجميع ماله مستحق لك ولا بد لك ان تتخذها زوجة"},{"n":13,"text":"فاخطبها الى ابيها فانه يزوجها منك"},{"n":14,"text":"فاجاب طوبيا وقال اني سمعت انه قد عقد لها على سبعة ازواج فماتوا وقد سمعت ايضا ان الشيطان قتلهم"},{"n":15,"text":"فلاجل هذا اخاف ان يصيبني مثل ذلك وانا وحيد لابوي فانزل شيخوختهما الى الجحيم بالحزن"},{"n":16,"text":"فقال له الملاك رافائيل استمع فاخبرك من هم الذين يستطيع الشيطان ان يقوى عليهم"},{"n":17,"text":"ان الذين يتزوجون فينفون الله من قلوبهم ويتفرغون لشهوتهم كالفرس والبغل اللذين لا فهم لهما اولئك للشيطان عليهم سلطان"},{"n":18,"text":"فانت اذا تزوجتها ودخلت المخدع فامسك عنها ثلاثة ايام ولا تتفرغ معها الا للصلوات"},{"n":19,"text":"وفي تلك الليلة اذا احرقت كبد الحوت ينهزم الشيطان"},{"n":20,"text":"وفي الليلة الثانية تكون مقبولا في شركة الاباء القديسين"},{"n":21,"text":"وفي الليلة الثالثة تنال البركة حتى يولد لكما بنون سالمون"},{"n":22,"text":"وبعد انقضاء الليلة الثالثة تتخذ البكر بخوف الرب وانت راغب في البنين اكثر من الشهوة لكي تنال بركة ذرية ابراهيم"}]},{"label":"سفر طوبيا 7","verses":[{"n":1,"text":"ثم دخلا على رعوئيل فتلقاهما رعوئيل بالمسرة"},{"n":2,"text":"واذ نظر رعوئيل الى طوبيا قال لحنة زوجته ما اشبه هذا الرجل بذي قرابتي"},{"n":3,"text":"وبعد هذا الكلام قال رعوئيل من اين انتما ايها الاخوان الفتيان فقالا له من سبط نفتالي من جلاء نينوى"},{"n":4,"text":"فقال لهما رعوئيل هل تعرفان طوبيا اخي فقالا نعرفه"},{"n":5,"text":"فلما اكثر من الثناء عليه قال الملاك لرعوئيل ان طوبيا الذي انت تسال عنه هو ابو هذا"},{"n":6,"text":"فالقى رعوئيل بنفسه وقبله بدموع وبكى على عنقه"},{"n":7,"text":"وقال بركة لك يا بني انك ابن رجل صالح فاضل"},{"n":8,"text":"وبكت حنة امراته وسارة ابنتهما ايضا"},{"n":9,"text":"وبعد ان تحادثوا امر رعوئيل ان يذبح كبش وتهيا مادبة ودعاهما ان يتكئا للغذاء"},{"n":10,"text":"فقال طوبيا اني لا اكل اليوم طعاما ههنا ولا اشرب ما لم تجيبني الى ما انا سائله وتعدني ان تعطيني سارة ابنتك"},{"n":11,"text":"فلما سمع رعوئيل هذا الكلام ارتعد لمعرفته بما اصاب السبعة الرجال الذين دخلوا عليها وخاف ان يصيب هذا ما اصابهم \nوفيما هو متردد ولم يردد عليه جوابا"},{"n":12,"text":"قال له الملاك لا تخف ان تعطيها لهذا فان ابنتك له ينبغي ان تكون زوجة لانه يخاف الله ولذلك لم يقدر غيره ان ياخذها"},{"n":13,"text":"حينئذ قال رعوئيل لا اشك ان الله قد تقبل صلواتي ودموعي امامه"},{"n":14,"text":"ولعله لاجل ذلك ساقكما الله الى حتى تتزوج هذه بذي قرابتها على حسب شريعة موسى والان لا تشك اني اعطيكها"},{"n":15,"text":"ثم اخذ بيمين ابنته سارة وسلمها الى يمين طوبيا قائلا اله ابراهيم واله اسحق واله يعقوب يكون معكما وهو يقرنكما \nويتم بركته عليكما"},{"n":16,"text":"ثم اخذوا صحيفة وكتبوا فيها عقد الزواج"},{"n":17,"text":"وبعد ذلك اكلوا وباركوا الله"},{"n":18,"text":"ودعا رعوئيل حنة زوجته وامرها ان تهيا مخدعا اخر"},{"n":19,"text":"وادخلته سارة ابنتها وهي باكية"},{"n":20,"text":"وقالت لها تشجعي يا بنية ورب السماء يؤتيك فرحا بدل الغم الذي قاسيته"}]},{"label":"سفر طوبيا 8","verses":[{"n":1,"text":"ولما فرغوا من العشاء ادخلوا عليها الفتى"},{"n":2,"text":"فذكر طوبيا كلام الملاك فاخرج من كيسه فلذة من الكبد والقاها على الجمر المشتعل"},{"n":3,"text":"حينئذ قبض الملاك رافائيل على الشيطان واوثقه في برية مصر العليا"},{"n":4,"text":"ووعظ طوبيا البكر وقال لها يا سارة قومي نصلي الى الله اليوم وغدا وبعد غد فانا في هذه الليالي الثلاث نتحد بالله وبعد \nانقضاء الليلة الثالثة نكون في زواجنا"},{"n":5,"text":"لانا بنو القديسين فلا ينبغي لنا ان نقترن اقتران الامم الذين لا يعرفون الله"},{"n":6,"text":"فقاما معا وصليا كلاهما بحرارة حتى يعافيهما"},{"n":7,"text":"وقال طوبيا ايها الرب اله ابائنا لتباركك السماوات والارض والبحر والينابيع والانهار وجميع خلائقك التي فيها"},{"n":8,"text":"انت جبلت ادم من تراب الارض واتيته حواء عونا"},{"n":9,"text":"والان يا رب انت تعلم اني لا لسبب الشهوة اتخذ اختي زوجة وانما رغبة في النسل الذي يبارك فيه اسمك الى دهر الدهور"},{"n":10,"text":"وقالت سارة ايضا ارحمنا يا رب ارحمنا حتى نشيخ كلانا معا في عافية"},{"n":11,"text":"وكان نحو وقت صياح الديك ان رعوئيل امر ان يجمع اليه غلمانه فانطلقوا معه واحتفروا قبرا"},{"n":12,"text":"لانه قال اخشى ان يصيبه ما اصاب غيره من الرجال السبعة الذين دخلوا عليها"},{"n":13,"text":"فلما اعدوا القبر رجع رعوئيل الى زوجته وقال لها"},{"n":14,"text":"ابعثي واحدة من جواريك لترى هل مات حتى اواريه قبل ضوء النهار"},{"n":15,"text":"فانفذت احدى جواريها فدخلت المخدع فاذا هما سالمان معافيان وهما نائمان معا"},{"n":16,"text":"فعادت واخبرت بهذه البشرى فبارك رعوئيل وحنة زوجته الرب"},{"n":17,"text":"قائلين نباركك ايها الرب اله اسرائيل من اجل انه لم يصبنا ما كنا نتوقعه"},{"n":18,"text":"فانك قد اتيتنا رحمتك وحبست عنا العدو الذي يضطهدنا"},{"n":19,"text":"ورحمت الوحيدين فاجعلهما يا رب يباركانك اتم بركة ويقدمان لك قربان تسبيحك وعافيتهما حتى تعلم الامم كافة انك انت \nالاله الواحد في الارض كلها"},{"n":20,"text":"وللحال امر رعوئيل غلمانه ان يردموا القبر الذي حفروه قبل ضوء الصباح"},{"n":21,"text":"ثم اوعز الى زوجته ان تعد وليمة وتصلح ما ينبغي للمسافرين من الزاد"},{"n":22,"text":"وامر بذبح بقرتين سمينتين واربعة اكبش وان تهيا وليمة لجميع جيرانه واصدقائه"},{"n":23,"text":"واستحلف رعوئيل طوبيا ان يقيم عنده اسبوعين"},{"n":24,"text":"واعطى رعوئيل لطوبيا نصف ماله كله وكتب لطوبيا صكا بالنصف الباقي ان يستولي عليه بعد موتهما"}]},{"label":"سفر طوبيا 9","verses":[{"n":1,"text":"ثم ان طوبيا استدعى الملاك الذي كان يحسبه انسانا وقال له يا اخي عزريا اسالك ان تسمع كلامي"},{"n":2,"text":"اني لو جعلت نفسي عبدا لك لما وفيت بعنايتك حق الوفاء"},{"n":3,"text":"ولكني مع ذلك اسالك ان تاخذ دواب وغلمانا وتنطلق الى غابيلوس في راجيس مدينة الماديين وترد عليه صكه وتقبض منه \nالفضة وتدعوه الى عرسي"},{"n":4,"text":"لانك تعلم ان ابي يحسب الايام فان زدت في ابطائي يوما واحدا حزنت نفسه"},{"n":5,"text":"وانت ترى ان رعوئيل قد استحلفني ولست استطيع ان استخف بحلفه"},{"n":6,"text":"حينئذ اخذ رافائيل اربعة من غلمان رعوئيل وجملين وسافر الى راجيس مدينة الماديين ولقي غابيلوس فدفع اليه صكه \nواستوفى منه المال كله"},{"n":7,"text":"وعرفه امر طوبيا بن طوبيا وكل ما وقع واتى به معه الى العرس"},{"n":8,"text":"فلما دخل بيت رعوئيل وجد طوبيا متكئا فنهض قائما وقبلا بعضهما بعضا وبكى غابيلوس وبارك الله"},{"n":9,"text":"وقال يباركك الرب اله اسرائيل لانك ابن رجل صالح جدا بار متقي الله صانع صدقات"},{"n":10,"text":"وتحل البركة على زوجتك وعلى والديكما"},{"n":11,"text":"وتريان بنيكما وبني بنيكما الى الجيل الثالث والرابع ويكون نسلكما مباركا من اله اسرائيل المالك الى دهر الدهور"},{"n":12,"text":"فقالوا كلهم امين ثم تقدموا الى الوليمة الا انهم اتخذوا وليمة العرس بخوف الله"}]},{"label":"سفر طوبيا 10","verses":[{"n":1,"text":"ولما ابطا طوبيا هناك لسبب العرس قلق ابوه طوبيا وقال لماذا ترى ابطا ابني وما الذي عاقه هناك"},{"n":2,"text":"العل غابيلوس قد مات وليس من يرد له المال"},{"n":3,"text":"واخذه حزن شديد هو وحنة امراته وطفق كلاهما يبكيان لتخلف ابنهما عن الرجوع في يوم الميعاد"},{"n":4,"text":"وكانت امه تبكي بدموع لا تنقطع وهي تقول اه اوه يا بني لماذا ارسلناك في الغربة يا نور ابصارنا وعكازة شيخوختنا وعزاء عيشتنا ورجاء عقبنا"},{"n":5,"text":"لقد كان لنا فيك وحدك كل شيء فلم يكن ينبغي لنا ان نرسلك عنا"},{"n":6,"text":"فكان طوبيا يقول لها اسكتي ولا تقلقي ان ابننا سالم والرجل الذي ارسلناه معه ثقة جدا"},{"n":7,"text":"فلم يكن ذلك يفيدها ادنى تعزية وكانت كل يوم تقوم مسرعة فتتشوف من كل جهة وتنظر في جميع الطرق التي كانت تظن ان \nابنها يرجع منها لعلها تراه عن بعد مقبلا"},{"n":8,"text":"واما رعوئيل فقال لصهره امكث ههنا وانا انفذ الى طوبيا ابيك من يخبره بسلامتك"},{"n":9,"text":"فقال له طوبيا اني لاعلم ان ابي وامي يحسبان الايام وارواحهما معذبة قلقا"},{"n":10,"text":"وبعد ان اكثر رعوئيل من الالحاح على طوبيا فابى ان يسمع بوجه من الوجوه اعطاه سارة ونصف امواله كلها من غلمان وجوار ومواش وابل وبقر وفضة كثيرة وصرفه من عنده بسلام فرحا"},{"n":11,"text":"قائلا ملاك الرب القدوس يكون في طريقكما ويبلغكما سالمين وتجدان كل شيء عند ابويكما بخير وترى عيناي بنيكما قبل موتي"},{"n":12,"text":"واقبل الوالدان على ابنتهما يقبلانها ثم صرفاها"},{"n":13,"text":"واوصياها ان تكرم حمويها وتحب بعلها وتدبر عيالها وتسوس بيتها وتحفظ نفسها غير ملومة"}]},{"label":"سفر طوبيا 11","verses":[{"n":1,"text":"وفيما هم راجعون وقد بلغوا الى حاران التي في وسط الطريق جهة نينوى في اليوم الحادي عشر"},{"n":2,"text":"قال الملاك يا اخي طوبيا انك تعلم كيف فارقت اباك"},{"n":3,"text":"فلنتقدم نحن ان احببت والعيال وزوجتك يلحقوننا على مهل مع المواشي"},{"n":4,"text":"واذ توافقا على المضي قال رافائيل لطوبيا خذ معك من مرارة الحوت فان لنا بها حاجة فاخذ طوبيا من المرارة وانطلقا"},{"n":5,"text":"واما حنة فكانت كل يوم تجلس عند الطريق على راس الجبل حيث كانت تستطيع ان تنظر على بعد"},{"n":6,"text":"فلما كانت تتشوف ذات يوم من ذلك الموضع نظرت على بعد وللوقت عرفت انه ابنها قادما فبادرت واخبرت بعلها قائلة هوذا \nابنك ات"},{"n":7,"text":"وقال رافائيل لطوبيا اذا دخلت بيتك فاسجد في الحال للرب الهك واشكر له ثم ادن من ابيك وقبله"},{"n":8,"text":"واطل لساعتك عينيه بمرارة الحوت هذه التي معك واعلم انه للحين تنفتح عيناه ويرى ابوك ضوء السماء ويفرح برؤيتك"},{"n":9,"text":"حينئذ سبق الكلب الذي كان معه في الطريق وكان كانه بشير يبدي مسرته ببصبصة ذنبه"},{"n":10,"text":"فقام ابوه وهو اعمى وجعل يجري وهو يتعثر برجليه فناول يده لغلام وخرج لملاقاة ابنه"},{"n":11,"text":"واستقبله وقبله هو وامراته وطفق كلاهما يبكيان من الفرح"},{"n":12,"text":"ثم سجدوا لله وشكروا له وجلسوا"},{"n":13,"text":"فاخذ طوبيا من مرارة الحوت وطلى عيني ابيه"},{"n":14,"text":"ومكث مقدار نصف ساعة فبدا يخرج من عينيه غشاوة كغرقئ البيض"},{"n":15,"text":"فامسكها طوبيا وسحبها من عينيه وللوقت عاد الى طوبيا بصره"},{"n":16,"text":"فمجد الله هو وامراته وكل من كان يعرفه"},{"n":17,"text":"وقال طوبيا اباركك ايها الرب اله اسرائيل لانك ادبتني وشفيتني وهاءنذا ارى طوبيا ولدي"},{"n":18,"text":"واما سارة كنته فوصلت بعد سبعة ايام هي وجميع العيال بسلام والغنم والابل ومال كثير مما للمراة مع المال الذي \nاستوفاه من غابيلوس"},{"n":19,"text":"واخبر ابويه بجميع احسانات الله التي انعم بها عليه على يد ذلك الرجل الذي ذهب معه"},{"n":20,"text":"ووفد على طوبيا احيور ونباط وهما ذوا قرابة له فرحين وهناه بجميع ما من الله به عليه من الخير"},{"n":21,"text":"وعملوا وليمة سبعة ايام وفرحوا كلهم فرحا عظيما"}]},{"label":"سفر طوبيا 12","verses":[{"n":1,"text":"حينئذ دعا طوبيا ابنه اليه وقال له ماذا ترى نعطي هذا الرجل القديس الذي ذهب معك"},{"n":2,"text":"فاجاب طوبيا وقال لابيه يا ابت اي اجرة نعطيه واي شيء يكون موازيا لاحسانه"},{"n":3,"text":"اخذني ورجع بي سالما والمال هو استوفاه من عند غابيلوس وبه حصلت على زوجتي وهو كف عنها الشيطان وفرح ابويها وخلصني \nمن افتراس الحوت واياك ايضا هو جعلك تبصر نور السماء وبه غمرنا بكل خير فماذا عسى ان نعطيه مما يكون موازيا لهذه"},{"n":4,"text":"لكني اسالك يا ابت ان نساله هل يرضى ان ياخذ النصف من كل ما جئنا به"},{"n":5,"text":"فدعاه الوالد وولده واخذاه ناحية وجعلا يسالانه ان يتنازل ويقبل النصف من جميع ما جاءا به"},{"n":6,"text":"حينئذ خاطبهما سرا وقال باركا اله السماء واعترفا له امام جميع الاحياء لما اتاكما من مراحمه"},{"n":7,"text":"اما سر الملك فخير ان يكتم واما اعمال الله فاذاعتها والاعتراف بها كرامة"},{"n":8,"text":"صالحة الصلاة مع الصوم والصدقة خير من ادخار كنوز الذهب"},{"n":9,"text":"لان الصدقة تنجي من الموت وتمحو الخطايا وتؤهل الانسان لنوال الرحمة والحياة الابدية"},{"n":10,"text":"واما الذين يعملون المعصية والاثم فهم اعداء لانفسهم"},{"n":11,"text":"اما انا فاعلن لكما الحق وما اكتم عنكما امرا مستورا"},{"n":12,"text":"انك حين كنت تصلي بدموع وتدفن الموتى وتترك طعامك وتخبا الموتى في بيتك نهارا وتدفنهم ليلا كنت انا ارفع صلاتك الى \nالرب"},{"n":13,"text":"واذ كنت مقبولا امام الله كان لا بد ان تمتحن بتجربة"},{"n":14,"text":"والان فان الرب قد ارسلني لاشفيك واخلص سارة كنتك من الشيطان"},{"n":15,"text":"فاني انا رافائيل الملاك احد السبعة الواقفين امام الرب"},{"n":16,"text":"فلما سمعا مقالته هذه ارتاعا وسقطا على اوجههما على الارض مرتعدين"},{"n":17,"text":"فقال لهما الملاك سلام لكم لا تخافوا"},{"n":18,"text":"لاني لما كنت معكم انما كنت بمشيئة الله فباركوه وسبحوه"},{"n":19,"text":"وكان يظهر لكم اني اكل واشرب معكم وانما انا اتخذ طعاما غير منظور وشرابا لا يبصره بشر"},{"n":20,"text":"والان قد حان ان ارجع الى من ارسلني وانتم فباركوا الله وحدثوا بجميع عجائبه"},{"n":21,"text":"وبعد ان قال هذا ارتفع عن ابصارهم فلم يعودوا يعاينونه بعد ذلك"},{"n":22,"text":"حينئذ لبثوا ثلاث ساعات منطرحين على وجوههم يباركون الله ثم نهضوا وحدثوا بجميع عجائبه"}]},{"label":"سفر طوبيا 13","verses":[{"n":1,"text":"حينئذ فتح طوبيا الشيخ فاه مباركا للرب وقال عظيم انت يا رب الى الابد وفي جميع الدهور ملكك"},{"n":2,"text":"لانك تجرح وتشفي وتحدر الى الجحيم وتصعد منه وليس من يفر من يدك"},{"n":3,"text":"اعترفوا للرب يا بني اسرائيل وسبحوه امام جميع الامم"},{"n":4,"text":"فانه فرقكم بين الامم الذين يجهلونه لكي تخبروا بمعجزاته وتعرفوهم ان لا اله قادرا على كل شيء سواه"},{"n":5,"text":"هو ادبنا لاجل اثامنا وهو يخلصنا لاجل رحمته"},{"n":6,"text":"انظروا الان ما صنع لنا واعترفوا له بخوف ورعدة ومجدوا ملك الدهور باعمالكم"},{"n":7,"text":"اما انا ففي ارض جلائي اعترف له لانه اظهر جلاله في امة خاطئة"},{"n":8,"text":"ارجعوا الان ايها الخطاة واصنعوا امام الله برا واثقين بانه يصنع لكم رحمة"},{"n":9,"text":"اما انا فنفسي تتهلل به"},{"n":10,"text":"باركوا الرب يا جميع مختاريه اقيموا ايام فرح واعترفوا له"},{"n":11,"text":"يا اورشليم مدينة الله ان الرب ادبك باعمال يديك"},{"n":12,"text":"اشكري لله نعمته عليك وباركي اله الدهور حتى يعود فيشيد مسكنه فيك ويرد اليك جميع اهل الجلاء وتبتهجي الى دهر الدهور"},{"n":13,"text":"تتلالئين بسنى بهيج وجميع شعوب الارض لك يسجدون"},{"n":14,"text":"يزورك الامم من الاقاصي بقرابينهم ويسجدون فيك للرب ويعتدون ارضك ارضا مقدسة"},{"n":15,"text":"لانهم فيك يدعون الاسم العظيم"},{"n":16,"text":"ملعونين يكونون الذين استهانوا بك والذين جدفوا عليك يدانون ويباركك الذين يبنونك"},{"n":17,"text":"اما انت فتفرحين ببنيك لانهم يباركون كافة والى الرب يحتشدون"},{"n":18,"text":"طوبى للذين يحبونك ويفرحون لك بالسلام"},{"n":19,"text":"باركي يا نفسي الرب لان الرب الهنا خلص اورشليم مدينته من جميع شدائدها"},{"n":20,"text":"طوبى لي ان بقي من ذريتي من يبصر بهاء اورشليم"},{"n":21,"text":"ابواب اورشليم من ياقوت وزمرد وكل محيط اسوارها من حجر كريم"},{"n":22,"text":"وجميع اسواقها مفروشة بحجر ابيض نقي وفي شوارعها ينشد هللويا"},{"n":23,"text":"مبارك الرب الذي عظمها وليكن ملكه فيها الى دهر الدهور امين"}]},{"label":"سفر طوبيا 14","verses":[{"n":1,"text":"وفرغ طوبيا من كلامه وعاش طوبيا بعدما عاد بصيرا اثنتين واربعين سنة وراى بني حفدته"},{"n":2,"text":"فتمت سنوه مئة واثنتين ودفن بكرامة في نينوى"},{"n":3,"text":"وكان حين ذهب بصره ابن ست وخمسين سنة وعاد يبصر وهو ابن ستين سنة"},{"n":4,"text":"وقضى بقية حياته مسرورا واذ بلغ من تقوى الله غاية حسنة انتقل بسلام"},{"n":5,"text":"ولما حضرته الوفاة دعا ابنه طوبيا وبني ابنه السبعة الفتيان وقال لهم"},{"n":6,"text":"قد دنا دمار نينوى لان كلام الرب لا يذهب باطلا واخوتنا الذين تفرقوا من ارض اسرائيل يرجعون اليها"},{"n":7,"text":"وكل ارضها المقفرة ستمتلئ وبيت الله الذي احرق فيها سيستانف بناؤه وسيرجع الى هناك جميع خائفي الله"},{"n":8,"text":"وستترك الامم اصنامها وترحل الى اورشليم فتقيم بها"},{"n":9,"text":"وتفرح فيها ملوك الارض كافة ساجدة لملك اسرائيل"},{"n":10,"text":"اسمعوا يا بني لابيكم اعبدوا الرب بحق وابتغوا عمل مرضاته"},{"n":11,"text":"واوصوا بنيكم بعمل العدل والصدقات وان يذكروا الله ويباركوه كل حين بالحق وبكل طاقاتهم"},{"n":12,"text":"اسمعوا لي يا بني لا تقيموا ههنا بل اي يوم دفنتم والدتكم معي في قبر واحد ففي ذلك اليوم وجهوا خطواتكم للخروج من \nهذا الموضع"},{"n":13,"text":"فاني ارى ان اثمه سيهلكه"},{"n":14,"text":"فكان ان طوبيا بعد موت امه ارتحل عن نينوى بزوجته وبنيه وبني بنيه ورجع الى حمويه"},{"n":15,"text":"فوجدهما سالمين بشيخوخة صالحة فاهتم بهما وهو اغمض اعينهما واحرز كل ميراث بيت رعوئيل وراى بني بنيه الى الجيل \nالخامس"},{"n":16,"text":"وبعد ان استوفى تسعا وتسعين سنة في مخافة الرب دفن بفرح"},{"n":17,"text":"ولبث كل ذوي قرابته وجميع اعقابه في عيشة صالحة وسيرة مقدسة وكانوا مرضيين لدى الله والناس وجميع سكان الارض"}]}],"sources":["https://ar.wikisource.org/wiki/سفر_طوبيا"]},{"name":"يهوديت","chapters":[{"label":"سفر يهوديت 1","verses":[{"n":1,"text":"كان ارفكشاد ملك الماديين قد اخضع امما كثيرة لسلطانه وبنى مدينة منيعة جدا سماها احمتا"},{"n":2,"text":"بناها من حجارة مربعة منحوتة وابتنى اسوارها على ارتفاع سبعين ذراعا في عرض ثلاثين ذراعا وشيد بروجها على ارتفاع مئة \nذراع"},{"n":3,"text":"مساحة كل جانب من مربعها عشرون قدما وجعل ابوابها في علو الابراج"},{"n":4,"text":"وكان يفتخر بقدرته وسطوة جيشه وعزة مراكبه"},{"n":5,"text":"وان نبوكد نصر ملك اشور الذي كان مالكا على نينوى المدينة العظيمة في السنة الثانية عشرة من ملكه حارب ارفشكاد فظفر \nبه"},{"n":6,"text":"في الصحراء العظيمة التي يقال لها رعاوى عند الفرات ودجلة ويادسون في صحراء اريوك ملك عليم"},{"n":7,"text":"فعظم اذ ذاك ملك نبوكد نصر وسمت نفسه فراسل جميع سكان قيليقية ودمشق ولبنان"},{"n":8,"text":"والامم التي في الكرمل وقيدار وسكان الجليل في صحراء يزرعيل الواسعة"},{"n":9,"text":"وجميع من في السامرة وعبر الاردن الى اورشليم وفي جميع ارض يسى الى حدود الحبشة"},{"n":10,"text":"الى جميع اولئك بعث نبوكد نصر ملك اشور رسلا"},{"n":11,"text":"فابى جميعهم اتفاقا وردوا الرسل خائبين وطردوهم بلا كرامة"},{"n":12,"text":"فاستشاط حينئذ نبوكد نصر الملك غضبا على تلك الارض باسرها وحلف بعرشه وملكه لينتقمن من جميع تلك البلاد"}]},{"label":"سفر يهوديت 2","verses":[{"n":1,"text":"وفي السنة الثالثة عشرة لنبوكد نصر وفي اليوم الثاني والعشرين من الشهر الاول تمت الكلمة في بيت نبوكد نصر ملك اشور بالانتقام"},{"n":2,"text":"فدعا جميع الشيوخ وكل قواده ورجال حربه وواضعهم مشورة سرية"},{"n":3,"text":"وقال لهم ان في نفسه ان يخضع كل الارض لملكه"},{"n":4,"text":"واذ حسن ذلك لدى الجميع استدعى نبوكد نصر الملك اليفانا قائد جيشه"},{"n":5,"text":"وقال له اخرج على جميع ممالك الغرب وخصوصا الذين استهانوا باوامري"},{"n":6,"text":"ولا تشفق عينك على مملكة ما واخضع لي جميع المدن المحصنة"},{"n":7,"text":"فدعا اليفانا القواد وعظماء جيش اشور واحصى عدد رجال الحرب كما امره الملك مئة وعشرين الف راجل مقاتلين واثني عشر \nالف فارس ارباب قسي"},{"n":8,"text":"وسير امام جيوشه عددا لا يحصى من الجمال بما يكفي الجيش بكثرة ومن اصورة البقر وقطعان الغنم ما لا يحصى"},{"n":9,"text":"وامر ان تجمع الحنطة من كل سورية عند عبوره"},{"n":10,"text":"واخذ من بيت الملك من الذهب والفضة شيئا كثيرا جدا"},{"n":11,"text":"ثم ارتحل بجميع جيشه ومراكبه وفرسانه وارباب القسي وكانوا يغطون وجه الارض كالجراد"},{"n":12,"text":"فلما جاوز تخوم اشور انتهى الى جبال انجة العظيمة التي الى يسار قيليقية وزحف على جميع قلاعهم وتسلم كل الحصون"},{"n":13,"text":"وفتح مدينة ملوطة المشهورة ونهب جميع بني ترشيش وبني اسماعيل الذين حيال البرية وجهة جنوب ارض كلون"},{"n":14,"text":"ثم عبر الفرات واتى الى ما بين النهرين وقهر جميع ما هناك من المدن المشيدة من وادي ممرا الى حد البحر"},{"n":15,"text":"واستولى على حدودها من قيليقية الى تخوم يافث التي الى الجنوب"},{"n":16,"text":"واسر جميع بني مدين وغنم كل ثروتهم وكل من قاومهم قتله بحد السيف"},{"n":17,"text":"وبعد ذلك انحدر الى صحاري دمشق في ايام الحصاد واحرق جميع حقولهم وقطع كل اشجارهم وكرومهم"},{"n":18,"text":"فوقع رعبه على جميع سكان الارض"}]},{"label":"سفر يهوديت 3","verses":[{"n":1,"text":"حينئذ انفذ اليه جميع ملوك ورؤساء المدن والاقاليم رسلهم من سورية التي بين النهرين وسورية صوبال ولوبية وقيليقية فاتوا اليفانا وقالوا له"},{"n":2,"text":"ليكف غضبك عنا فخير ان نحيا عبيدا لنبوكد نصر الملك العظيم وندين لك من ان نموت ونخرب ونتحمل خسف العبودية"},{"n":3,"text":"وهذه مدائننا باسرها وجميع ما نملكه وجبالنا وهضابنا وحقولنا ومواشينا من اصورة البقر وقطعان الغنم والمعز والخيل \nوالابل وجميع مقتنانا وعيالنا بين يديك"},{"n":4,"text":"جميع ما هو لنا تحت امرك"},{"n":5,"text":"ونحن وبنونا عبيد لك"},{"n":6,"text":"فكن في قدومك علينا مولى سلام واستخدمنا بما يحسن عندك"},{"n":7,"text":"حينئذ انحدر من الجبال مع الفرسان بقوة عظيمة واستولى على جميع المدن وكل سكان الارض"},{"n":8,"text":"واخذ من جميع المدن انصارا له من ذوي الباس ومختارين للحرب"},{"n":9,"text":"فحل على جميع تلك البلدان خوف عظيم حتى خرج للقائه سكان جميع المدن الرؤساء والاشراف مع شعوبهم"},{"n":10,"text":"واستقبلوه بالاكاليل والمصابيح راقصين بالطبول والنايات"},{"n":11,"text":"ولا بصنعهم هذا امكنهم ان يلينوا قساوة قلبه"},{"n":12,"text":"فانه دمر مدنهم وقطع غاباتهم"},{"n":13,"text":"لان نبوكد نصر الملك كان قد امره ان يبيد جميع الهة الارض حتى يدعى هو وحده الها بين جميع تلك الامم التي تدين له \nبسطوة اليفانا"},{"n":14,"text":"ثم عبر سورية صوبال وبامية كلها وجميع ما بين النهرين واتى الادوميين في ارض جبع"},{"n":15,"text":"واخذ مدائنهم واقام هناك ثلاثين يوما امر فيها ان تجمع كل قوة جيشه"}]},{"label":"سفر يهوديت 4","verses":[{"n":1,"text":"وسمع بنو اسرائيل المقيمون بارض يهوذا فخافوا جدا من وجهه"},{"n":2,"text":"واخذ الارتعاد بفرائصهم مخافة ان يفعل باورشليم وبهيكل الرب كما فعل بسائر المدن وهياكلها"},{"n":3,"text":"فارسلوا الى جميع السامرة في كل وجه الى حد اريحا وضبطوا رؤوس الجبال كلها"},{"n":4,"text":"وسوروا قراهم وجمعوا الحنطة استعدادا للقتال"},{"n":5,"text":"وكتب الياقيم الكاهن الى جميع الساكنين قبالة يزرعيل التي حيال الصحراء الكبيرة الى جانب دوتان والى جميع الذين \nيمكن ان يجاز في اراضيهم"},{"n":6,"text":"ان يضبطوا مراقي الجبال التي يمكن ان تسلك الى اورشليم ويحفظوا المضايق التي يمكن ان يجاز منها بين الجبال"},{"n":7,"text":"ففعل بنو اسرائيل كما رسم كاهن الرب الياقيم"},{"n":8,"text":"وصرخ كل الشعب الى الرب بابتهال عظيم وذللوا نفوسهم بالصوم والصلاة هم ونساؤهم"},{"n":9,"text":"ولبس الكهنة المسوح وطرحوا الاطفال امام هيكل الرب وغطوا مذبح الرب بمسح"},{"n":10,"text":"وصرخوا جملة الى الرب اله اسرائيل ان لا يجعل اطفالهم غنيمة ونساءهم مقتسما للاعداء ومدنهم خرابا واقداسهم نجاسة \nواياهم عارا بين الامم"},{"n":11,"text":"وجال الياقيم كاهن الرب العظيم في جميع اسرائيل وكلمهم قائلا"},{"n":12,"text":"اعلموا ان الرب يستجيب لصلواتكم ان واظبتم على الصوم والصلوات امام الرب"},{"n":13,"text":"اذكروا موسى عبد الرب كيف قهر العمالقة الذين كانوا متكلين على باسهم وقدرتهم وجيشهم وتروسهم ومراكبهم وفرسانهم \nفقهرهم مقاتلا لا بالسيف بل بالصلوات الطاهرة"},{"n":14,"text":"هكذا يكون جميع اعداء اسرائيل اذا واظبتم على العمل الذي بداتم به"},{"n":15,"text":"واذ خاطبهم بهذا الكلام تضرعوا الى الرب وكانوا لا يبرحون من امام الرب"},{"n":16,"text":"وكان الذين يقدمون المحرقات الى الرب لابسين المسوح يقربون ذبائح للرب والرماد على رؤوسهم"},{"n":17,"text":"وكانوا بجملتهم يصلون الى الله من كل قلوبهم ان يفتقد شعب اسرائيل"}]},{"label":"سفر يهوديت 5","verses":[{"n":1,"text":"واخبر اليفانا رئيس جيش الاشوريين ان بني اسرائيل قد تاهبوا للمدافعة وانهم قد سدوا طرق الجبال"},{"n":2,"text":"فاستشاط اليفانا غضبا في شدة حنقه ودعا جميع رؤساء مواب وقواد عمون"},{"n":3,"text":"وقال لهم قولوا لي من اولئك الشعب الذين ضبطوا الجبال وما مدنهم وكيف هي وما قوتها وما قدرتهم وكثرتهم ومن قائد \nجيشهم"},{"n":4,"text":"وكيف استخفوا بنا دون جميع سكان المشرق ولم يخرجوا لاستقبالنا ليتلقونا بالسلم"},{"n":5,"text":"فاجابه احيور قائد جميع بني عمون قائلا ان تنازلت فسمعت لي يا سيدي اقول الحق بين يديك في امر اولئك الشعب المقيمين \nبالجبال ولا تخرج لفظة كاذبة من فمي"},{"n":6,"text":"ان اولئك الشعب هم من نسل الكلدانيين"},{"n":7,"text":"وكان اول مقامهم فيما بين النهرين لانهم ابوا اتباع الهة ابائهم المقيمين بارض الكلدانيين"},{"n":8,"text":"فتركوا سنن ابائهم التي كانت لالهة كثيرة"},{"n":9,"text":"وسجدوا لاله السماء الواحد وهو امرهم ان يخرجوا من هناك ويسكنوا في حاران فلما عم الجوع الارض كلها هبطوا الى مصر \nوتكاثروا هناك مدة اربع مئة سنة حتى كان جيشهم لا يحصى"},{"n":10,"text":"واذ كان ملك مصر يعنتهم بالاثقال ويستعبدهم في بناء مدنه بالطين واللبن صرخوا الى ربهم فضرب جميع ارض مصر ضربات مختلفة"},{"n":11,"text":"وبعد ان طردهم المصريون من ارضهم وكفت الضربة عنهم ارادوا امساكهم ليردوهم الى عبوديتهم"},{"n":12,"text":"وفيما هم هاربون فلق لهم اله السماء البحر وجمدت المياه من الجانبين فعبروا على حضيض البحر على اليبس"},{"n":13,"text":"وتعقبهم هناك جيش المصريين بلا عدد فغمرتهم المياه حتى لم يبق منهم احد يخبر اعقابهم"},{"n":14,"text":"فخرجوا من البحر الاحمر ونزلوا برية جبل سيناء حيث لم يكن يقدر ان يسكن انسان ولا يستريح ابن بشر"},{"n":15,"text":"وهناك حولت لهم ينابيع المياه المرة عذبة ليشربوا ورزقوا طعاما من السماء مدة اربعين سنة"},{"n":16,"text":"وحيثما دخلوا بلا قوس ولا سهم ولا ترس ولا سيف قاتل الههم عنهم وظفر"},{"n":17,"text":"ولم يكن من يستهين بهؤلاء الشعب الا اذا تركوا عبادة الرب الههم"},{"n":18,"text":"فكانوا كلما عبدوا غير الههم اسلموا للغنيمة والسيف والعار"},{"n":19,"text":"وكلما تابوا عن تركهم عبادة الههم اتاهم اله السماء قوة للمدافعة"},{"n":20,"text":"فكسروا امامهم ملوك الكنعانيين واليبوسيين والفرزيين والحثيين والحويين والاموريين وجميع الجبابرة الذين في حشبون \nواستحوذوا على اراضيهم ومدائنهم"},{"n":21,"text":"وكانوا ما داموا لا يخطاون امام الههم يصيبهم خير لان الههم يبغض الاثم"},{"n":22,"text":"فلما ان حادوا قبل هذه السنين عن الطريق التي امرهم الله ان يسلكوها انكسروا في الحروب امام شعوب كثيرة وجلي كثيرون \nمنهم الى ارض غير ارضهم"},{"n":23,"text":"غير انهم من عهد قريب قد تابوا الى الرب الههم واجتمعوا من شتاتهم حيث تبددوا وصعدوا الى هذه الجبال كلها وعادوا \nفتملكوا في اورشليم حيث اقداسهم"},{"n":24,"text":"والان يا سيدي انظر فان كان لاولئك الشعب اثم امام الههم فلنصعد اليهم لان الههم يسلمهم اليك ويستعبدون تحت نير \nسلطانك"},{"n":25,"text":"وان لم يكن لاولئك الشعب اثم امام الههم فلا طاقة لنا بهم لان الههم يدافع عنهم فنكون عارا على جميع وجه الارض"},{"n":26,"text":"فلما فرغ احيور من هذا الكلام غضب جميع عظماء اليفانا وهموا بقتله قائلين بعضهم لبعض"},{"n":27,"text":"من يقول ان لبني اسرائيل طاقة بمقاومة الملك نبوكد نصر وجيوشه وهم قوم لا سلاح لهم ولا قوة ولا لهم خبرة في امر الحرب"},{"n":28,"text":"فلكي يعلم احيور انه انما يخادعنا نصعد الان الى الجبال واذا اخذ جبابرتهم فحينئذ نجعله موردا للسيف ايضا معهم"},{"n":29,"text":"حتى تعلم كل امة ان نبوكد نصر هو اله الارض ولا اله غيره"}]},{"label":"سفر يهوديت 6","verses":[{"n":1,"text":"فلما فرغوا من كلامهم اشتد غضب اليفانا جدا وقال لاحيور"},{"n":2,"text":"بما انك تنبات لنا قائلا ان شعب اسرائيل يدافع عنه الهه فلكي اريك ان لا اله الا نبوكد نصر"},{"n":3,"text":"فانا اذا ضربناهم كلهم كرجل واحد فحينئذ انت ايضا تهلك بسيف الاشوريين وجميع اسرائيل يهلكون معك"},{"n":4,"text":"فتعلم عن خبرة ان نبوكد نصر هو رب الارض كلها وحينئذ سيف جيشي يخترق جنبيك فتسقط طعينا بين جرحى اسرائيل ولا يبقى فيك \nنسمة الا ريثما تستاصل معهم"},{"n":5,"text":"وان كنت تخال ان نبوتك صادقة فلا يسقط وجهك وليفارقك الاصفرار الذي علا وجهك ان كنت تظن ان كلامي هذا لا يمكن ان يتم"},{"n":6,"text":"ولكي تعلم انك تختبر هذا معهم فها انك من هذه الساعة تنضم الى شعبهم واذا نالهم من سيفي عقوبة ما استحقوه فانك تكون \nمعهم تحت طائلة الانتقام"},{"n":7,"text":"ثم امر اليفانا عبيده ان يقبضوا على احيور وياخذوه الى بيت فلوى ويسلموه الى ايدي بني اسرائيل"},{"n":8,"text":"فاخذه عبيد اليفانا وساروا في الصحراء ولما دنوا من الجبال خرج عليهم الرماة بالمقاليع"},{"n":9,"text":"فانحازوا الى جانب الجبل وربطوا احيور الى شجرة بيديه ورجليه وبعد ان ربطوه هكذا بالحبال تركوه ورجعوا الى سيدهم"},{"n":10,"text":"فنزل بنو اسرائيل من بيت فلوى واتوه فحلوه واخذوه الى بيت فلوى واقاموه في وسط الشعب وسالوه لم تركه الاشوريون \nمربوطا"},{"n":11,"text":"وكان في تلك عزيا بن ميخا من سبط شمعون وكرمي الذي هو عتنيئيل اميرين هناك"},{"n":12,"text":"فتكلم احيور بين ايدي الشيوخ وبحضرة الجميع بكل ما ذكره عن سؤال اليفانا وكيف هم قوم اليفانا ان يقتلوه بسبب هذا \nالكلام"},{"n":13,"text":"وكيف امرهم اليفانا وهو مغضب ان يدفعوه الى ايدي الاسرائيليين وفي قصده انه انه متى ظفر ببني اسرائيل يامر بقتل \nاحيور بضروب مختلفة من العذاب لاجل انه قال ان اله السماء هو المدافع عنهم"},{"n":14,"text":"فلما قص عليهم احيور جميع ذلك خر الشعب كلهم على وجوههم ساجدين للرب ورفعوا صلواتهم الى الرب بالبكاء والعويل عامة \nبقلب واحد"},{"n":15,"text":"قائلين ايها الرب اله السماء والارض انظر الى عتوهم والتفت الى تذللنا ولا تغفل وجوه قديسيك واعلن انك لم تترك \nالمتوكلين عليك وانك تذل المتوكلين على انفسهم والمفتخرين بقوتهم"},{"n":16,"text":"وبعد هذا البكاء وانقضاء صلاة الشعب ذلك اليوم كله عزوا احيور"},{"n":17,"text":"قائلين اله ابائنا الذي انذرت بقوته يمن عليك بهذه المنية ان تنظر انت هلاكهم"},{"n":18,"text":"واذا اتى الرب الهنا عبيده هذا الخلاص فليكن هو الها لك فيما بيننا ان احببت ان تكون معنا باهلك كلهم"},{"n":19,"text":"ولما انتهت المشورة اخذوا عزيا الى بيته وصنع له عشاء عظيما"},{"n":20,"text":"ودعا الشيوخ كلهم فاكلوا بعد انقضاء الصوم"},{"n":21,"text":"ثم دعوا كل الشعب وباتوا في موضع الاجتماع يصلون ويستغيثون باله اسرائيل ذلك الليل كله"}]},{"label":"سفر يهوديت 7","verses":[{"n":1,"text":"وفي اليوم الثاني امر اليفانا جميع عسكره ان يزحفوا على بيت فلوى"},{"n":2,"text":"وكان رجالة الحرب مئة وعشرين الفا والفرسان اثنين وعشرين الفا ما خلا الرجال المجلوين وجميع الفتيان الذين استصحبهم \nمن الاقاليم والمدن"},{"n":3,"text":"فتاهب جميعهم لمقاتلة بني اسرائيل وجاءوا من جانب الجبل الى القمة التي تنظر الى دوتان من الموضع الذي يقال له بلما \nالى قليمون التي قبالة يزرعيل"},{"n":4,"text":"فلما راى بنو اسرائيل كثرتهم خروا على الارض وحثوا الرماد على رؤوسهم وصلوا بقلب واحد الى اله اسرائيل ليظهر رحمته \nعلى شعبه"},{"n":5,"text":"ثم اخذ كل رجل سلاحه واقاموا في الاماكن المفضية الى المضيق بين الجبال ولم يزالوا حارسين كل النهار والليل"},{"n":6,"text":"ولما كان اليفانا يطوف في الارض وجد العين التي كانت تجري الى داخل المدينة من ناحية الجنوب لها قناة خارج المدينة \nفامر ان يقطعوا القناة"},{"n":7,"text":"وكانت عيون اخر على قرب من السور كانوا يخرجون فيستقون منها خفية لكي يكسروا حدة عطشهم وان كانوا لا يرتوون"},{"n":8,"text":"فتقدم بنو عمون ومواب الى اليفانا وقالوا له ان بني اسرائيل لا يتكلون على الرمح والسهم ولكن الجبال تزرهم والتلال \nالتي بين الهوى تحصنهم"},{"n":9,"text":"فالان حتى تظفر بهم بلا قتال اقم ارصادا على الينابيع لئلا يستقوا منها ماء فتقتلهم بغير سيف او يلجئهم ما يصيرون اليه \nمن الضنك ان يسلموا مدينتهم التي يعدونها منيعة من اجل انها على الجبال"},{"n":10,"text":"فاعجب اليفانا وسائر عبيده بهذا الكلام فجعل ارصادا على العيون من اصحاب المئة على كل عين من جميع الجهات"},{"n":11,"text":"فاقاموا على هذه المحافظة عشرين يوما حتى جفت مياه ابار بيت فلوى وحياضها باسرها حتى لم يكن في داخل المدينة ما \nيرويهم يوما واحدا لان الماء كان يعطى للشعب كل يوم بمقدار"},{"n":12,"text":"حينئذ اجتمع على عزيا جميع الرجال والنساء والشبان والاطفال وكلهم بصوت واحد"},{"n":13,"text":"وقالوا يحكم الله بيننا وبينك فانك قد جنيت علينا شرورا اذ ابيت ان تخاطب الاشوريين بالمسالمة ولذلك باعنا الله الى \nايديهم"},{"n":14,"text":"والان فانه ليس لنا من نصير ولكنا نصرع امام عيونهم من قبل العطش والدمار العظيم"},{"n":15,"text":"فالان ادعوا جميع من في المدينة ولنستسلم باجمعنا الى اصحاب اليفانا من تلقاء انفسنا"},{"n":16,"text":"فخير لنا ان نبارك الرب ونحن احياء في الجلاء من ان نموت ونكون عارا عند جميع البشر بعد ان نكون عاينا نساءنا \nواطفالنا يموتون امامنا"},{"n":17,"text":"ونستحلفكم اليوم بالسماء والارض وباله ابائنا الذي ينتقم منا بحسب خطايانا ان تسلموا المدينة الى ايدي جيش اليفانا \nفيقضى اجلنا سريعا بحد السيف ولا يتمادى في اوار العطش"},{"n":18,"text":"فلما قالوا هذا حدث بكاء وعويل عظيم في الجماعة كلها وصرخوا الى الله بصوت واحد ساعات كثيرة قائلين"},{"n":19,"text":"قد خطئنا نحن واباؤنا وصنعنا الظلم والاثم"},{"n":20,"text":"ارحمنا لانك رحيم او فانتقم عن اثامنا بان تعاقبنا انت ولا تسلم المعترفين بك الى شعب لا يعرفك"},{"n":21,"text":"لئلا يقال في الامم اين الههم"},{"n":22,"text":"ثم انهم كلوا من الصراخ وخاروا من البكاء فسكتوا"},{"n":23,"text":"فقام عزيا ودموعه سائلة وقال لهم كونوا طيبي القلوب يا اخوتي ولننتظر رحمة من لدن الرب هذه الخمسة الايام"},{"n":24,"text":"فلعله يكف غضبه ويقيم مجدا لاسمه"},{"n":25,"text":"فاذا انقضت خمسة ايام ولم تاتنا معونة فعلنا ما تقولون"}]},{"label":"سفر يهوديت 8","verses":[{"n":1,"text":"ولما سمعت هذا الكلام يهوديت الارملة وهي بنت مراري بن ايدوس ابن يوسف بن عزيا بن الاي ابن يمنور بن جدعون بن رفائيم بن احيطوب بن ملكيا ابن عانان بن نتنيا بن شالتيئيل بن شمعون بن راوبين"},{"n":2,"text":"وكان بعلها منسى وقد مات في ايام حصاد الشعير"},{"n":3,"text":"لانه كان يحث رابطي الحزم في الحقل فصخد الحر راسه فمات في بيت فلوى مدينته وقبر هناك مع ابائه"},{"n":4,"text":"وكانت يهوديت قد بقيت ارملة منذ ثلاث سنين وستة اشهر"},{"n":5,"text":"وكانت قد هيات لها في اعلى بيتها غرفة سرية وكانت تقيم فيها مع جواريها وتغلقها"},{"n":6,"text":"وكان على حقويها مسح وكانت تصوم جميع ايام حياتها ما خلا السبوت ورؤوس الشهور واعياد ال اسرائيل"},{"n":7,"text":"وكانت جميلة المنظر جدا وقد ترك لها بعلها ثروة واسعة وحشما كثيرين واملاكا مملوءة باصورة البقر وقطعان الغنم"},{"n":8,"text":"وكانت لها شهرة بين جميع الناس من اجل انها كانت تتقي الرب جدا ولم يكن احد يقول عليها كلمة سوء"},{"n":9,"text":"فهذه لما سمعت ان عزيا وعد بان يسلم المدينة بعد خمسة ايام انفذت الى الشيخين كبري وكرمي"},{"n":10,"text":"فوافياها فقالت لهما ما هذا الامر الذي وافق عليه عزيا ان يسلم المدينة الى الاشوريين اذا لم تاتنا معونة الى خمسة \nايام"},{"n":11,"text":"من انتم حتى تجربوا الرب"},{"n":12,"text":"ليس هذا بكلام يستعطف الرحمة ولكنه بالاحرى يهيج الغضب ويضرم السخط"},{"n":13,"text":"فانكم قد ضربتم اجلا لرحمة الرب وعينتم له يوما كما شئتم"},{"n":14,"text":"ولكن بما ان الرب طويل الاناة فلنندم على هذا ونلتمس غفرانه بالدموع المسكوبة"},{"n":15,"text":"انه ليس وعيد الله كوعيد الانسان ولا هو يستشيط حنقا كابن البشر"},{"n":16,"text":"لذلك فلنذلل له انفسنا ونعبده بروح متواضع"},{"n":17,"text":"ولنسال الرب باكين ان يؤتينا رحمته بحسب مشيئته لنفتخر بتواضعنا مثلما اضطربت قلوبنا بتكبرهم"},{"n":18,"text":"فانا لم نجر على خطايا ابائنا الذين تركوا الههم وعبدوا الهة غريبة"},{"n":19,"text":"فاسلموا من اجل ذلك الاثم الى السيف والنهب والخزي بين اعدائهم لكنا نحن لا نعرف الها غيره"},{"n":20,"text":"فنترجى بالتواضع تعزيته وهو ينتقم لدمنا عن اعنات اعدائنا لنا ويذل جميع الامم الواثبين علينا ويخزيهم الرب الهنا"},{"n":21,"text":"والان يا اخوتي بما انكم انتم شيوخ في شعب الله وبكم نفوسهم منوطة فانهضوا قلوبهم بكلامكم حتى يذكروا ان اباءنا انما \nورد عليهم البلاء ليمتحنوا هل يعبدون الههم بالحق"},{"n":22,"text":"فينبغي لهم ان يذكروا كيف امتحن ابونا ابراهيم وبعد ان جرب بشدائد كثيرة صار خليلا لله"},{"n":23,"text":"وهكذا اسحق وهكذا يعقوب وهكذا موسى وجميع الذين رضي الله منهم جازوا في شدائد كثيرة وبقوا على امانتهم"},{"n":24,"text":"فاما الذين لم يقبلوا البلايا بخشية الرب بل ابدوا جزعهم وعاد تذمرهم على الرب"},{"n":25,"text":"فاستاصلهم المستاصل وهلكوا بالحيات"},{"n":26,"text":"واما نحن الان فلا نجزع لما نقاسيه"},{"n":27,"text":"بل لنحسب ان هذه العقوبات هي دون خطايانا ونعتقد ان ضربات الرب التي نؤدب بها كالعبيد انما هي للاصلاح لا للاهلاك"},{"n":28,"text":"فقال لها عزيا والشيوخ جميع مقالك حق ولا عيب في كلماتك"},{"n":29,"text":"فالان صلي عنا لانك امراة قديسة متقية لله"},{"n":30,"text":"فقالت لهم يهوديت كما انكم عرفتم ان ما تكلمت به هو من قبل الله"},{"n":31,"text":"فاعلموا عن خبرة ان ما عزمت عليه هو من قبل الله وصلوا حتى يؤيد الله مشورتي"},{"n":32,"text":"ففي هذه الليلة تقفون انتم على الباب وانا اخرج مع وصيفتي وصلوا ان ينظر الرب الى شعبه اسرائيل خمسة ايام كما قلتم"},{"n":33,"text":"وانا لا احب ان تفحصوا عن قصدي ومن الان حتى اعلمكم به لا تصنعوا شيئا غير الصلاة عني الى الرب الهنا"},{"n":34,"text":"فقال لها عزيا امير يهوذا اذهبي بسلام وليكن الرب معك في الانتقام من اعدائنا وانصرفوا راجعين"}]},{"label":"سفر يهوديت 9","verses":[{"n":1,"text":"وبينما هم ذاهبون دخلت يهوديت معبدها ولبست مسحا والقت رمادا على راسها وخرت امام الرب وصرخت الى الرب قائلة"},{"n":2,"text":"ايها الرب اله ابي شمعون الذي اعطاه سيفا لينتقم من الغرباء الذين بنجاستهم فضحوا وكشفوا عذراء للخزي"},{"n":3,"text":"فجعلت نساءهم غنيمة وبناتهم سبيا وكل سلبهم مقتسما بين عبيدك الذين غاروا غيرتك اتوسل اليك ايها الرب الهي ان \nتعينني انا الارملة"},{"n":4,"text":"فان لك الافعال الاولى وانت قدرت بعضها في عقب بعض وما اردته كان"},{"n":5,"text":"فان طرائقك جميعها مهياة وقد اقمت احكامك بعنايتك"},{"n":6,"text":"فانظر الان الى معسكر الاشوريين كما تنازلت فنظرت الى معسكر المصريين حين كانوا يسعون في اثر عبيدك بسلاحهم متوكلين \nعلى مراكبهم وفرسانهم وعلى كثرة رجال حربهم"},{"n":7,"text":"حينئذ نظرت الى معسكرهم فزعجتهم الظلمة"},{"n":8,"text":"التزقت اقدامهم بالعمق وغطتهم المياه"},{"n":9,"text":"يا رب فليكن مثلهم هؤلاء المتوكلون على كثرة عددهم ومراكبهم وحرابهم وتروسهم وسهامهم المفتخرون برماحهم"},{"n":10,"text":"وهم لا يعلمون انك انت الهنا الذي يمحق الحروب منذ البدء وان اسمك الرب"},{"n":11,"text":"فارفع ذراعك كما فعلت من البدء واحطم قوتهم بقوتك ولتسقط بغضبك قوة الذين يطمعون انفسهم في ابتذال اقداسك وتنجيس \nمسكن اسمك وهدم قرن مذبحك بسيفهم"},{"n":12,"text":"اجعل يا رب كبرياءه تقطع بنفس سيفه"},{"n":13,"text":"ليصد بفخ نظره الي واضربه بعذوبة الكلام الخارج من شفتي"},{"n":14,"text":"وهبني ثباتا في قلبي حتى ازدريه وقوة حتى اهلكه"},{"n":15,"text":"فيكون هذا ذكرا لاسمك اذا اهلكته يد امراة"},{"n":16,"text":"لانها ليست قوتك بالكثرة يا رب ولا مرضاتك بقدرة الخيل ومنذ البدء لا ترضى من المتكبرين بل يسرك دائما تضرع \nالمتواضعين الودعاء"},{"n":17,"text":"يا اله السماوات خالق المياه ورب كل خليقة استجبني انا المسكينة المتضرعة والمتوكلة على رحمتك"},{"n":18,"text":"واذكر يا رب ميثاقك واجعل الكلام في في وثبت مشورة قلبي ليثبت بيتك في قدسك"},{"n":19,"text":"فيعرف جميع الامم انك انت الاله وليس اخر سواك"}]},{"label":"سفر يهوديت 10","verses":[{"n":1,"text":"وكان لما فرغت من صراخها الى الرب انها قامت من المكان الذي كانت فيه منطرحة امام الرب"},{"n":2,"text":"ودعت وصيفتها ونزلت الى بيتها والقت عنها المسح ونزعت عنها ثياب ارمالها"},{"n":3,"text":"واستحمت وادهنت باطياب نفيسة وفرقت شعرها وجعلت تاجا على راسها ولبست ثياب فرحها واحتذت بحذاء ولبست الدمالج \nوالسواسن والقرطة والخواتم وتزينت بكل زينتها"},{"n":4,"text":"وزادها الرب ايضا بهاء من اجل ان تزينها هذا لم يكن عن شهوة بل عن فضيلة ولذلك زاد الرب في جمالها حتى ظهرت في عيون \nالجميع ببهاء لا يمثل"},{"n":5,"text":"وحملت وصيفتها زق خمر واناء زيت ودقيقا وتينا يابسا وخبزا وجبنا وانطلقت"},{"n":6,"text":"فلما بلغتا باب المدينة وجدتا عزيا وشيوخ المدينة منتظرين"},{"n":7,"text":"فلما راوها اندهشوا وتعجبوا جدا من جمالها"},{"n":8,"text":"غير انهم لم يسالوها عن شيء بل تركوها تجوز قائلين اله ابائنا يمنحك نعمة ويؤيد كل مشورة قلبك بقوته حتى تفتخر بك \nاورشليم ويكون اسمك محصى في عداد القديسين والابرار"},{"n":9,"text":"فقال كل من هناك بصوت واحد امين امين"},{"n":10,"text":"فخرجت يهوديت من الباب هي وامتها وكانت تصلي الى الرب"},{"n":11,"text":"وكان انها لما نزلت من الجبل عند تبلج النهار لقيتها طلائع الاشوريين فامسكوها قائلين من اين جئت والى اين تذهبين"},{"n":12,"text":"فاجابت اني بنت للعبرانيين وقد هربت من بينهم لاني ايقنت انهم سيكونون غنيمة لكم لانهم استخفوا بكم وابوا ان \nيستسلموا لكم طوعا حتى يظفروا منكم برحمة"},{"n":13,"text":"فلاجل هذا فكرت في نفسي وقلت انطلق الى امام الامير اليفانا لاخبره باسرارهم واعلمه من اي مدخل يستطيع ان يظفر بهم ولا \nيقتل رجلا من جيشه"},{"n":14,"text":"فلما سمع اولئك الرجال كلامها وهم ينظرون الى وجهها اندهشت ابصارهم لشدة تعجبهم من حسنها"},{"n":15,"text":"فقالوا لها قد وقيت نفسك باتخاذك هذه المشورة ان تنزلي الى سيدنا"},{"n":16,"text":"فاعلمي انك اذا وقفت بحضرته يحسن اليك وتقعين من قلبه احسن موقع ثم اخذوها الى خيمة اليفانا واخبروه بها"},{"n":17,"text":"فلما دخلت عليه اصطيد اليفانا لساعته بعينيها"},{"n":18,"text":"فقال له اشراطه من يزدري بشعب العبرانيين ولهم نسوة مثل هذه جميلات السن اهلا لان نقاتلهم لاجلهن"},{"n":19,"text":"واذ رات يهوديت اليفانا جالسا في الخيمة المنسوجة من ارجوان وذهب وزمرد وجواهر"},{"n":20,"text":"ونظرت الى وجهه خرت له ساجدة على الارض فانهضها عبيد اليفانا بامر سيدهم"}]},{"label":"سفر يهوديت 11","verses":[{"n":1,"text":"حينئذ قال لها اليفانا لتطب نفسك ولا يكن في قلبك روع لاني لم اضر قط برجل اثر الخضوع لنبوكد نصر الملك"},{"n":2,"text":"واما شعبك فلو لم يزدروا بي لما اشرعت رمحي عليهم"},{"n":3,"text":"والان فقولي لي لاي سبب فارقتهم واثرت المجيء الينا"},{"n":4,"text":"فقالت له يهوديت اسمع كلام امتك فانك اذا اتبعت قول امتك يتم الرب الامر لك"},{"n":5,"text":"ليحي نبوكد نصر ملك الارض ولتحي قوته التي فيك لتاديب جميع الانفس الغاوية لانه لا الناس فقط يخضعون له بك بل وحوش البر \nايضا تنقاد له"},{"n":6,"text":"لان ذكاء عقلك قد شاع في جميع الامم واهل العصر كلهم يعلمون انك انت وحدك صالح وجبار في جميع مملكته وحسن سياستك \nمشهور في جميع الاقاليم"},{"n":7,"text":"وليس بخاف ما تكلم به احيور ولم يجهل ما امرت ان يصيبه"},{"n":8,"text":"ومن المحقق ان الهنا قد بلغ من غضبه من الخطايا انه ارسل انبياءه الى شعبه بانه سيسلمهم لاجل خطاياهم"},{"n":9,"text":"ولعلم بني اسرائيل بانهم قد اهانوا الههم قد حل رعبك عليهم"},{"n":10,"text":"وفضلا عن ذلك فان الجوع قد اخذ منهم وهم معدودون في الموتى من عوز الماء"},{"n":11,"text":"حتى عزموا ان يذبحوا بهائمهم ليشربوا دماءها"},{"n":12,"text":"واقداس الرب الههم التي امر الله ان لا تلمس من الحنطة والخمر والزيت قد هموا ان ينفقوها وهم يريدون ان ياكلوا ما لا \nيحل حتى لمسه بالايدي فحيث انهم يفعلون هذا فقد ثبت انهم سيسلمون للهلاك"},{"n":13,"text":"وبما ان امتك قد علمت بهذا هربت من عندهم وقد بعثني الرب لاخبرك بهذا"},{"n":14,"text":"وانا امتك اعبد الله حتى الان عندك ايضا وامتك تخرج وتصلي الى الله"},{"n":15,"text":"فيقول لي متى يرد عليهم خطيئتهم فاجيء واخبرك بذلك حتى اخذك الى وسط اورشليم ويكون لك جميع شعب اسرائيل مثل الغنم \nالتي لا راعيلها ولا ينبح عليك كلب"},{"n":16,"text":"وهذه كلها قد لقنتها من عناية الله"},{"n":17,"text":"وحيث ان الله قد غضب عليهم فانا مرسلة لاخبرك بهذه الامور"},{"n":18,"text":"فحسن هذا الكلام كله لدى اليفانا وعبيده وكانوا يتعجبون من حكمتها ويقولون بعضهم لبعض"},{"n":19,"text":"ليس مثل هذه المراة على الارض في المنظر والجمال والحكمة في الكلام"},{"n":20,"text":"فقال لها اليفانا قد احسن الله اليك اذ ارسلك امام الشعب لتسلميه انت الى ايدينا"},{"n":21,"text":"وبما ان وعدك حسن ان فعل الهك لي ذلك فهو يكون الها لي وانت تكونين عظيمة في بيت نبوكد نصر وينوه باسمك في كل الارض"}]},{"label":"سفر يهوديت 12","verses":[{"n":1,"text":"حينئذ امرهم ان يدخلوها موضع خزائنه وامر ان تمكث هناك واوصى بما يعطى لها من مائدته"},{"n":2,"text":"فاجابته يهوديت وقالت اني لا استطيع ان اكل مما امرت ان يعطى لي لئلا تكون علي خطيئة ولكني اكل مما اتيت به"},{"n":3,"text":"فقال لها اليفانا اذا فرغ هذا الذي اتيت به فما نصنع بك"},{"n":4,"text":"فقالت يهوديت تحيا نفسك يا سيدي ان امتك لا تنفق هذه جميعها حتى يصنع الله بيدي ما في خاطري فادخلها عبيده الخيمة التي \nامر بها"},{"n":5,"text":"فلما صارت في داخلها سالت ان يرخص لها ان تخرج في الليل قبل الصباح لتصلي وتتضرع الى الرب"},{"n":6,"text":"فاوصى اصحاب مخدعه ان ياذنوا لها كما تحب في ان تخرج وتدخل لتعبد الهها ثلاثة ايام"},{"n":7,"text":"فكانت تخرج ليلا الى وادي بيت فلوى وتغتسل في عين الماء"},{"n":8,"text":"وبعد صعودها كانت تتضرع الى اله اسرائيل ان يرشد طريقها لتخلص شعبها"},{"n":9,"text":"ثم تدخل وتقيم في خيمتها طاهرة الى ان تاخذ طعامها في المساء"},{"n":10,"text":"وكان في اليوم الرابع ان اليفانا صنع عشاء لعبيده وقال لبوغا خصيه انطلق الان واقنع تلك العبرانية ان ترضى بالاقامة \nمعي طوعا"},{"n":11,"text":"فانه عار عند الاشوريين ان تسخر المراة من الرجل وتمضي عنه نقية"},{"n":12,"text":"فدخل حينئذ بوغا على يهوديت وقال لا تحتشمي ايتها الفتاة الصالحة ان تدخلي على سيدي وتكرمي امام وجهه وتاكلي معه \nوتشربي خمرا بفرح"},{"n":13,"text":"فاجابته يهوديت من انا حتى اخالف سيدي"},{"n":14,"text":"كل ما حسن وجاد في عينيه فانا اصنعه وكل ما يرضى به فهو عندي حسن جدا كل ايام حياتي"},{"n":15,"text":"ثم قامت وتزينت بملابسها ودخلت فوقفت امامه"},{"n":16,"text":"فاضطرب قلب اليفانا لانه كان قد اشتدت شهوته"},{"n":17,"text":"وقال لها اليفانا اشربي الان واتكئي بفرح فانك قد ظفرت امامي بحظوة"},{"n":18,"text":"فقالت يهوديت اشرب يا سيدي من اجل انها قد عظمت نفسي اليوم اكثر من جميع ايام حياتي"},{"n":19,"text":"ثم اخذت واكلت وشربت بحضرته مما كانت قد هياته لها جاريتها"},{"n":20,"text":"ففرح اليفانا بازائها وشرب من الخمر شيئا كثيرا جدا اكثر مما شرب في جميع حياته"}]},{"label":"سفر يهوديت 13","verses":[{"n":1,"text":"ولما امسوا اسرع عبيده الى منازلهم واغلق بوغا ابواب المخدع ومضى"},{"n":2,"text":"وكانوا جميعهم قد ثقلوا من الخمر"},{"n":3,"text":"وكانت يهوديت وحدها في المخدع"},{"n":4,"text":"واليفانا مضطجع على السرير نائما لشدة سكره"},{"n":5,"text":"فامرت يهوديت جاريتها ان تقف خارجا امام المخدع وتترصد"},{"n":6,"text":"ووقفت يهوديت امام السرير وكانت تصلي بالدموع وتحرك شفتيها وهي ساكتة"},{"n":7,"text":"وتقول ايدني ايها الرب اله اسرائيل وانظر في هذه الساعة الى عمل يدي حتى تنهض اورشليم مدينتك كما وعدت وانا اتم ما \nعزمت عليه واثقة باني اقدر عليه بمعونتك"},{"n":8,"text":"وبعد ان قالت هذا دنت من العمود الذي في راس سريره فحلت خنجره المعلق به مربوطا"},{"n":9,"text":"واستلته ثم اخذت بشعر راسه وقالت ايدني ايها الرب الاله في هذه الساعة"},{"n":10,"text":"ثم ضربت مرتين على عنقه فقطعت راسه ونزعت خيمة سريره عن العمد ودحرجت جثته عن السرير"},{"n":11,"text":"وبعد هنيهة خرجت وناولت وصيفتها راس اليفانا وامرتها ان تضعه في مزودها"},{"n":12,"text":"وخرجتا كلتاهما على عادتهما كانهما خارجتان للصلاة واجتازتا المعسكر ودارتا في الوادي حتى انتهتا الى باب المدينة"},{"n":13,"text":"فنادت يهوديت من بعد حراس السور افتحوا الابواب فان الله معنا وقد اجرى قوة في اسرائيل"},{"n":14,"text":"فكان انه لما سمع الرجال صوتها دعوا شيوخ المدينة"},{"n":15,"text":"وبادروا اليها جميعهم من اصغرهم الى اكبرهم لانه لم يكن في امالهم انها ترجع بعد"},{"n":16,"text":"ثم اوقدوا مصابيح واجتمعوا حولها باسرهم فصعدت الى اعلى موضع وامرت بالسكوت فلما سكتوا كلهم"},{"n":17,"text":"قالت يهوديت سبحوا الرب الهنا الذي لم يخذل المتوكلين عليه"},{"n":18,"text":"وبي انا امته اتم رحمته التي وعد بها ال اسرائيل وقتل بيدي عدو شعبه هذه الليلة"},{"n":19,"text":"ثم اخرجت راس اليفانا من المزود وارتهم اياه قائلة ها هوذا راس اليفانا رئيس جيش الاشوريين وهذه خيمة سريره التي \nكان مضطجعا فيها في سكره حيث ضربه الرب الهنا بيد امراة"},{"n":20,"text":"حي الرب انه حفظني ملاكه في مسيري من ههنا وفي اقامتي هناك وفي ايابي الى هنا ولم ياذن الرب ان تتدنس امته ولكن \nارجعني اليكم بغير نجاسة خطيئة فرحة بغلبته وخلاصي وخلاصكم"},{"n":21,"text":"فاشكروا له كلكم لانه صالح لان رحمته الى الابد"},{"n":22,"text":"فسجدوا باجمعهم للرب وقالوا لها قد باركك الرب بقوته لانه بك افنى اعداءنا"},{"n":23,"text":"وقال لها عزيا رئيس شعب اسرائيل مباركة انت يا بنية من الرب الاله العلي فوق جميع نساء الارض"},{"n":24,"text":"تبارك الرب الذي خلق السماء والارض الذي سدد يدك لضرب راس قائد اعدائنا"},{"n":25,"text":"فانه عظم اليوم اسمك هكذا حتى لا يبرح مدحك من افواه الناس الذين يذكرون قوة الرب الى الابد الذين لاجلهم لم تشفقي \nعلى نفسك لاجل ضيقة وشدة جنسك بل رددت الهلاك امام الهنا"},{"n":26,"text":"فقال كل الشعب امين امين"},{"n":27,"text":"ثم دعوا احيور فجاء فقالت له يهوديت ان اله اسرائيل الذي شهدت له بانه ينتقم من اعدائه هو قطع في هذه الليلة بيدي \nراس جميع الكفار"},{"n":28,"text":"وحتى تعلم ان الامر هكذا فهوذا راس اليفانا الذي اهان اله اسرائيل باستخفاف كبريائه وتهددك بالموت اذ قال لك اذا \nاسرشعب اسرائيل امر ان يخترقوا جنبيك بالسيف"},{"n":29,"text":"فلما راى احيور راس اليفانا ارتاع خوفا وسقط بوجهه على الارض وهلعت نفسه"},{"n":30,"text":"وبعدما ثابت اليه روحه وانتعش خر قدامها ساجدا لها وقال"},{"n":31,"text":"مباركة انت من الهك في كل خيام يعقوب وفي كل امة يسمع فيها باسمك يعظم لاجلك اله اسرائيل"}]},{"label":"سفر يهوديت 14","verses":[{"n":1,"text":"وقالت يهوديت لجميع الشعب اسمعوا لي يا اخوتي علقوا هذا الراس على اسوارنا"},{"n":2,"text":"ومتى طلعت الشمس فلياخذ كل واحد سلاحه واخرجوا بهجمة لا لتنحدروا الى اسفل ولكن كانكم تقصدون المهاجمة"},{"n":3,"text":"فعند ذلك يضطر الجواسيس ان يهربوا الى رئيسهم لينبهوه للقتال"},{"n":4,"text":"فاذا جرى قوادهم الى خيمة اليفانا يجدونه بلا راس متمرغا في دمه فيقع عليهم الذعر"},{"n":5,"text":"فاذا علمتم انهم هاربون فاسعوا على اعقابهم امنين فان الرب يسحقهم تحت ارجلكم"},{"n":6,"text":"ولما راى احيور القوة التي اجراها اله اسرائيل ترك سنة الامم وامن بالله وختن لحم قلفته وضم الى شعب اسرائيل هو وكل \nذريته الى اليوم"},{"n":7,"text":"وعندما تبلج النهار علقوا راس اليفانا على الاسوار واخذ كل رجل سلاحه ثم خرجوا بجلبة عظيمة وصراخ"},{"n":8,"text":"فلما راى الجواسيس ذلك بادروا الى خيمة اليفانا"},{"n":9,"text":"فجاء من في الخيمة وضجوا امام مدخل المخدع لينبهوه واحدثوا ضوضاء حتى يستيقظ اليفانا بضوضائهم من غير ان يوقظه احد"},{"n":10,"text":"ولم يكن احد يجسر ان يقرع او يدخل باب مخدع قائد الاشوريين"},{"n":11,"text":"فلما جاء قواده ورؤساء الالوف وجميع عظماء جيش ملك اشور قالوا للحجاب"},{"n":12,"text":"ادخلوا وايقظوه لان الفئران قد خرجت من حجرتها واجترات على مهايجتنا للقتال"},{"n":13,"text":"فحينئذ دخل بوغا مخدعه فوقف عند السجف ثم صفق بكفيه لانه كان يظن انه نائم مع يهوديت"},{"n":14,"text":"فلما لم يشعر بحركة يسمعها دنا من السجف ورفعه فلما راى جثة اليفانا بلا راس وهي مضرجة بدمه مطروحة على الارض اعول \nبصوت عظيم ومزق ثيابه"},{"n":15,"text":"ثم دخل خيمة يهوديت فلم يجدها فخرج الى الشعب خارجا"},{"n":16,"text":"وقال امراة عبرانية بلبلت بيت الملك نبوكد نصر هوذا اليفانا مطروح على الارض بلا راس"},{"n":17,"text":"فلما سمع رؤساء جيش الاشوريين مزقوا ثيابهم جميعا ووقع عليهم من الخوف والرعب ما لا يطاق واضطربت قلوبهم جدا"},{"n":18,"text":"وحدث بين معسكرهم عويل لا نظير له"}]},{"label":"سفر يهوديت 15","verses":[{"n":1,"text":"ولما سمع كل الجيش ان اليفانا قد قطع راسه طارت عقولهم ومشورتهم ولم يعودوا يبالون الا بالخوف والرعب فاستنجدوا بالهزيمة"},{"n":2,"text":"ولم يكلم احد صاحبه بل طاطا كل منهم راسه وتركوا كل شيء وكانوا يسارعون لينجوا من العبرانيين الذين سمعوهم اتين \nعليهم بسلاحهم فهربوا في طرق الصحراء وشعاب التلال"},{"n":3,"text":"فلما راهم بنو اسرائيل هاربين سعوا على اعقابهم ونزلوا وهم يهتفون بالابواق مجلبين وراءهم"},{"n":4,"text":"وكان الاشوريون متبددين وهم مندفعون في هزيمتهم وبنو اسرائيل صبة واحدة في اثارهم فاهلكوا كل من ادركوه"},{"n":5,"text":"وارسل عزيا رسلا الى جميع مدن ونواحي اسرائيل"},{"n":6,"text":"فكل بلدة ومدينة ارسلت في اثرهم شبانا منتخبين مدججين في السلاح فطردوهم بحد السيف الى ان بلغوا الى اخر تخمهم"},{"n":7,"text":"ودخل بقية سكان بيت فلوى محلة اشور فاخذوا كل ما تركه الاشوريون عندما هربوا وكان شيئا كثيرا"},{"n":8,"text":"والذين رجعوا الى بيت فلوى منصورين جاءوا بجميع اموالهم حتى كانت المواشي والبهائم وجميع اثاثهم بلا عدد فاثروا \nجميعهم من صغيرهم الى كبيرهم من غنيمتهم"},{"n":9,"text":"واتى يوياقيم الكاهن العظيم من اورشليم الى بيت فلوى مع جميع شيوخه ليرى يهوديت"},{"n":10,"text":"فلما خرجت اليه باركوها كلهم بصوت واحد قائلين انت مجد اورشليم وفرح اسرائيل وفخر شعبنا"},{"n":11,"text":"فانك قد صنعت بباس وثبت قلبك فاحببت العفاف ولم تعرفي رجلا بعد رجلك فلهذا ايدتك يد الرب فكوني مباركة الى الابد"},{"n":12,"text":"فقال جميع الشعب امين امين"},{"n":13,"text":"ولم يكد شعب اسرائيل في ثلاثين يوما يجمعون غنيمة الاشوريين"},{"n":14,"text":"وكل ما تبين انه كان من خواص اليفانا دفعوه الى يهوديت من ذهب وفضة وثياب وجواهر وامتعة كل هذه اعطاها لها الشعب"},{"n":15,"text":"وكان جميع الشعب يفرحون مع النساء والعذارى والشبان بالاعواد والقياثير"}]},{"label":"سفر يهوديت 16","verses":[{"n":1,"text":"حينئذ انشدت يهوديت هذا النشيد للرب فقالت"},{"n":2,"text":"سبحوا الرب بالدفوف رنموا للرب على الصنوج انشدوا له انشادا جديدا عظموه وادعوا باسمه"},{"n":3,"text":"الرب يمحق الحروب الرب اسمه"},{"n":4,"text":"جعل معسكره في وسط شعبه لينقذنا من ايدي جميع اعدائنا"},{"n":5,"text":"اتى اشور من الجبال الشمالية اتى في كثرة قوته فسدت كثرته الاودية وخيوله غطت الوهاد"},{"n":6,"text":"قال انه سيحرق تخومي ويقتل فتياني بالسيف ويجعل اطفالي غنيمة وابكاري سبيا"},{"n":7,"text":"الرب القدير ضربه واسلمه الى يد امراة فطعنته"},{"n":8,"text":"ان جبارهم لم يسقط بايدي الشبان ولم يبطش به بنو طيطان ولا جبابرة طوال تعرضوا له بل يهوديت ابنة مراري بجمال وجهها \nاهلكته"},{"n":9,"text":"نزعت ثياب ارمالها وتردت بثياب فرحها لابتهاج بني اسرائيل"},{"n":10,"text":"دهنت وجهها بالطيب وضمت ضفائرها بالتاج ولبست حللها الفاخرة لتفتنه"},{"n":11,"text":"بهاء حذائها خطف ابصاره وجمالها اسر نفسه فقطعت بالخنجر عنقه"},{"n":12,"text":"ارتاعت فارس من ثباتها والماديون من جراتها"},{"n":13,"text":"حينئذ اعولت محلة الاشوريين عندما ظهر متواضعي ملتهبين من العطش"},{"n":14,"text":"بنو الجواري اثخنوهم وقتلوهم كانهم صبية منهزمون فهلكوا في القتال بين يدي الرب الهي"},{"n":15,"text":"فلنسبح الرب تسبيحا ونرنم نشيدا جديدا لالهنا"},{"n":16,"text":"ايها الرب ادوناي انك عظيم شهير بجبروتك ولا يقوى عليك احد"},{"n":17,"text":"اياك فلتعبد خليقتك باسرها لانك انت قلت فكانوا ارسلت روحك فخلقوا وليس من يقاوم كلمتك"},{"n":18,"text":"تهتز الجبال من اساسها مع المياه والصخور كالشمع تذوب امام وجهك"},{"n":19,"text":"والذين يتقونك يكونون اعزة عندك في كل شيء"},{"n":20,"text":"الويل للامة القائمة على شعبي الرب القدير ينتقم منهم وفي يوم الدينونة يفتقدهم"},{"n":21,"text":"يجعل لحومهم للنار والدود لكي يحترقوا ويتالموا الى الابد"},{"n":22,"text":"وكان بعد هذا ان جميع الشعب بعد غلبتهم جاءوا الى اورشليم ليسجدوا للرب ولما تطهروا قدموا جميعهم محرقاتهم ونذورهم \nواوعادهم"},{"n":23,"text":"ويهوديت ايضا قدمت جميع ادوات حرب اليفانا التي اعطاها لها الشعب والخيمة التي اخذتها من سريره ابسال نسيان"},{"n":24,"text":"وكان الشعب مسرورين بمشاهدة المقدسات وعيدوا لفرح هذه الغلبة مع يهوديت ثلاثة اشهر"},{"n":25,"text":"وبعد تلك الايام رجع كل واحد الى بيته وعظمت يهوديت في بيت فلوى جدا وكانت اجل من في جميع ارض اسرائيل"},{"n":26,"text":"وكان فيها العفاف مقرونا بالشجاعة ولم تعد تعرف رجلا كل ايام حياتها منذ وفاة منسى بعلها"},{"n":27,"text":"وكانت في الاعياد تظهر بمجد عظيم"},{"n":28,"text":"وبقيت في بيت بعلها مئة وخمس سنين واعتقت وصيفتها وتوفيت ودفنت مع بعلها في بيت فلوى"},{"n":29,"text":"فناح عليها جميع الشعب سبعة ايام"},{"n":30,"text":"ولم يكن مدة حياتها كلها من يقلق اسرائيل ولا بعد موتها سنين كثيرة"},{"n":31,"text":"واحصي يوم هذه الغلبة عند العبرانيين في عداد الايام المقدسة واليهود يعيدونه منذ ذلك الوقت الى يومنا هذا"}]}],"sources":["https://ar.wikisource.org/wiki/سفر_يهوديت"]},{"name":"تتمة استير","chapters":[{"label":"سفر أستير 10","verses":[{"n":4,"text":"وقال مردكاي ان هذا كله انما كان من قبل الله"},{"n":5,"text":"وقد ذكرت حلما رايته يشير الى ذلك فلم يسقط منه شيء"},{"n":6,"text":"ينبوع صغير ازداد فصار نهرا ثم انقلب فصار نورا وشمسا وفاض بمياه كثيرة فهذا هو استير التي اتخذها الملك زوجة وشاء \nان تكون ملكة"},{"n":7,"text":"والتنينان انا وهامان"},{"n":8,"text":"والامم المجتمعون هم الذين طلبوا ان يمحوا اسم اليهود"},{"n":9,"text":"وشعبي هو اسرائيل الذي صرخ الى الرب فانقذ الرب شعبه وخلصنا من جميع الشرور وصنع ايات عظيمة ومعجزات في الامم"},{"n":10,"text":"وامر ان يكون سهمان احدهما لشعب الله والاخر لجميع الامم"},{"n":11,"text":"فبرز السهمان امام الله في اليوم المسمى منذ ذلك الزمان لجميع الامم"},{"n":12,"text":"وذكر الرب شعبه ورحم ميراثه"},{"n":13,"text":"لذلك يحفظ هذان اليومان من شهر اذار اليوم الرابع عشر والخامس عشر من هذا الشهر بكل غيرة وفرح فيجتمع الشعب جماعة واحدة في كل اجيال شعب اسرائيل فيما بعد"}]},{"label":"سفر أستير 11","verses":[{"n":1,"text":"كان في السنة الرابعة من ملك تلماي وكلوبطرا ان دوسيتاوس الذي كان يقول عن نفسه انه كاهن ومن نسل لاوي وابنه تلماي اتيا برسالة فوريم هذه قائلين انها قد ترجمت في اورشليم بيد لوسيماكوس بن تلماي"},{"n":2,"text":"وكان في السنة الثانية من ملك ارتحششتا الاكبر في اليوم الاول من شهر نيسان ان مردكاي بن يائير بن شمعي بن قيش من سبط بنيامين راى حلما"},{"n":3,"text":"وهو رجل يهودي مقيم بمدينة شوشن رجل عظيم من عظماء بلاط الملك"},{"n":4,"text":"وكان من جملة اهل الجلاء الذين اخذهم نبوكد نصر ملك بابل من اورشليم مع يكنيا ملك يهوذا"},{"n":5,"text":"وهذا حلمه راى كان اصواتا وضوضاء ورعودا وزلازل واضطرابا في الارض"},{"n":6,"text":"ثم اذا بتنينين عظيمين متهيئان للاقتتال"},{"n":7,"text":"وقد تهيجت كل الامم باصواتهما لتقاتل شعب الابرار"},{"n":8,"text":"وكان ذلك اليوم يوم ظلمة وهول وشدة وضنك ورعب عظيم على الارض"},{"n":9,"text":"فاضطرب شعب الابرار خوفا من شرورهم متوقعين الموت"},{"n":10,"text":"وصرخوا الى الله وفيما هم يصرخون اذا بينبوع صغير قد تكاثر حتى صار نهرا عظيما وفاض بمياه كثيرة"},{"n":11,"text":"ثم اشرق النور والشمس فارتفع المتواضعون وافترسوا المتجبرين"},{"n":12,"text":"فلما راى مردكاي ذلك ونهض من مضجعه كان يفكر في ماذا يريد الله ان يفعل وكان ذلك لا يبرح من نفسه وهو يرغب ان يعرف ما \nمعنى الحلم"}]},{"label":"تتمة سفر أستير 12","verses":[{"n":1,"text":"وكان حينئذ يقف بباب الملك مع بجتان وتارش خصيي الملك وهما حاجبا البلاط"},{"n":2,"text":"فبعد ان وقف على نواياهما وتقصى مدققا علم انهما يحاولان ان يلقيا ايديهما على الملك ارتحششتا فاطلع الملك على ذلك"},{"n":3,"text":"فالقاهما تحت العذاب فاقرا فامر بان يساقا الى الموت"},{"n":4,"text":"وكتب الملك ما وقع في سفر اخبار الايام وكذلك مردكاي كتب ذكر الامر"},{"n":5,"text":"ثم امره الملك ان يقيم ببيت الملك وامر له بهبات لانه اطلعه على ذلك"},{"n":6,"text":"وكان هامان بن همداتا الاجاجي له عند الملك كرامة عظيمة فاراد ان يؤذي مردكاي وشعبه بسبب خصيي الملك المقتولين"}]},{"label":"سفر أستير 13","verses":[{"n":1,"text":"من ارتحششتا الاكبر المالك من الهند الى الحبشة على المئة والسبعة والعشرين اقليما الى الرؤساء والقواد الذين في طاعته سلام"},{"n":2,"text":"اني مع كوني متسلطا على شعوب كثيرين وقد اخضعت المسكونة باسرها تحت يدي لم احب ان اسيء انفاذ مقدرتي العظيمة ولكني \nحكمت بالرحمة والحلم حتى يقضوا حياتهم بلا خوف وبسكينة ويتمتعوا بالسلام الذي يصبو اليه كل بشر"},{"n":3,"text":"فسالت اصحاب مشورتي كيف يتم ذلك فكان ان واحدا منهم يفوق من سواه في الحكمة والامانة وهو ثنيان الملك اسمه هامان"},{"n":4,"text":"قال لي ان في المسكونة شعبا متشتتا له شرائع جديدة يتصرف بخلاف عادة جميع الامم ويحتقر اوامر الملوك ويفسد نظام جميع \nالامم بفتنته"},{"n":5,"text":"فلما وقفنا على هذا وراينا ان شعبا واحدا متمرد على الناس طائفة تتبع شرائع فاسدة وتخالف اوامرنا وتقلق سلام واتفاق \nجميع الاقاليم الخاضعة لنا"},{"n":6,"text":"امرنا ان كل من يشير اليهم هامان المولى على جميع الاقاليم وثنيان الملك الذي نكرمه بمنزلة اب يبادون بايدي اعدائهم \nهم ونساؤهم واولادهم ولا يرحمهم احد في اليوم الرابع عشر من الشهر الثاني عشر شهر اذار من هذه السنة"},{"n":7,"text":"حتى اذا هبط اولئك الناس الخبثاء الى الجحيم في يوم واحد يرد الى مملكتنا السلام الذي اقلقوه"},{"n":8,"text":"فاما مردكاي فتضرع الى الرب متذكرا جميع اعماله"},{"n":9,"text":"وقال اللهم ايها الرب الملك القادر على الكل اذ كل شيء في طاعتك وليس من يقاوم مشيئتك اذا هممت بنجاة اسرائيل"},{"n":10,"text":"انت صنعت السماء والارض وكل ما تحت السماوات"},{"n":11,"text":"انت رب الجميع وليس من يقاوم عزتك"},{"n":12,"text":"انك تعرف كل شيء وتعلم اني لا تكبرا ولا احتقارا ولا رغبة في شيء من الكرامة فعلت هذا اني لم اسجد لهامان العاتي"},{"n":13,"text":"فاني مستعد ان اقبل حتى اثار قدميه عن طيب نفس لاجل نجاة اسرائيل"},{"n":14,"text":"ولكن خفت ان احول كرامة الهي الى انسان واعبد احدا سوى الهي"},{"n":15,"text":"فالان ايها الرب الملك اله ابراهيم ارحم شعبك لان اعداءنا يطلبون ان يهلكونا ويستاصلوا ميراثك"},{"n":16,"text":"لا تهمل نصيبك الذي افتديته لك من مصر"},{"n":17,"text":"واستجب لتضرعي واعطف على نصيبك وميراثك وحول حزننا فرحا لنحيا ونسبح اسمك ايها الرب ولا تسدد افواه المرنمين لك"},{"n":18,"text":"وكذلك جميع اسرائيل بروح واحد وتضرع واحد صرخوا الى الرب من اجل ان الموت اشرف عليهم يقينا"}]},{"label":"سفر أستير 14","verses":[{"n":1,"text":"وان استير الملكة ايضا التجئت الى الرب خوفا من الخطر المشرف"},{"n":2,"text":"فخلعت ثياب الملك ولبست ثيابا للحزن والبكاء وعوض الاطياب المختلفة القت على راسها رمادا وزبلا وذللت جسدها بالصوم \nوجميع المواضع التي كانت تفرح فيها من قبل ملاتها من نتاف شعر راسها"},{"n":3,"text":"وكانت تتضرع الى الرب اله اسرائيل قائلة ايها الرب الذي هو وحده ملكنا اعني انا المنقطعة التي ليس لها معين سواك"},{"n":4,"text":"فان خطري بين يدي"},{"n":5,"text":"لقد سمعت من ابي انك ايها الرب اتخذت اسرائيل من جميع الامم واباءنا من جميع اسلافهم الاقدمين لتحوزهم ميراثا ابديا \nوصنعت معهم كما قلت"},{"n":6,"text":"انا قد خطئنا امامك ولذلك اسلمتنا الى ايدي اعدائنا"},{"n":7,"text":"لانا عبدنا الهتهم وانت عادل ايها الرب"},{"n":8,"text":"والان لم يكفهم انهم استعبدونا عبودية شاقة جدا بل بما انهم يعزون قوة ايديهم الى اوثانهم"},{"n":9,"text":"يحاولون ان ينقضوا مواعيدك ويمحوا ميراثك ويسدوا افواه المسبحين لك ويطفئوا مجد هيكلك ومذبحك"},{"n":10,"text":"ليفتحوا افواه الامم فيسبحوا لقوة الاوثان ويمجدوا ملكا بشريا الى الابد"},{"n":11,"text":"لا تسلم ايها الرب صولجانك الى من ليسوا بشيء لئلا يضحكوا من هلاكنا ولكن اردد مشورتهم عليهم واهلك الذي ابتدا يشدد \nعلينا"},{"n":12,"text":"اذكرنا يا رب واستعلن لنا في وقت ضنكنا وهبني ثقة ايها الرب ملك الالهة وملك كل قدرة"},{"n":13,"text":"الق في فمي كلاما مرصفا بحضرة ذاك الاسد وحول قلبه الى بغض عدونا لكي يهلك هو وسائر المتواطئين معه"},{"n":14,"text":"وايانا فانقذنا بيدك واعني انا التي لا معونة لها سواك ايها الرب العالم بكل شيء"},{"n":15,"text":"انك تعلم اني ابغض مجد الظالمين واكره مضجع القلف وجميع الغرباء"},{"n":16,"text":"وانت عالم بضرورتي واني اكره سمة ابهتي ومجدي التي احملها على راسي ايام بروزي وامقتها كفرصة الطامث ولا احملها في \nايام قراري"},{"n":17,"text":"واني لم اكل على مائدة هامان ولا لذذت بوليمة الملك ولم اشرب خمر السكب"},{"n":18,"text":"ولم افرح انا امتك منذ نقلت الى ههنا الى اليوم الا بك ايها الرب اله ابراهيم"},{"n":19,"text":"الاله القدير على الجميع فاستجب لاصوات الذين ليس لهم رجاء غيرك ونجنا من ايدي الاثماء وانقذني من مخافتي"}]},{"label":"سفر أستير 15","verses":[{"n":1,"text":"وامرها ان تدخل على الملك وتتوسل اليه لاجل شعبها وارضها"},{"n":2,"text":"وقال اذكري ايام مذلتك حيث نشات على يدي فان هامان ثنيان الملك قد تكلم في اهلاكنا"},{"n":3,"text":"فادعي الرب وكلمي الملك في امرنا وخلصينا من الموت"},{"n":4,"text":"ثم انها في اليوم الثالث نزعت ثياب حدادها ولبست ملابس مجدها"},{"n":5,"text":"ولما تبرجت ببزة الملك ودعت مدبر ومخلص الجميع الله اتخذت لها جاريتين"},{"n":6,"text":"فكانت تستند الى احداهما كانها لم تكن تستطيع ان تستقل لكثرة ترفها ورخوصتها"},{"n":7,"text":"والجارية الاخرى كانت تتبع مولاتها رافعا اذيالها المنسحبة على الارض"},{"n":8,"text":"وكان احمرار وجهها وجمال عينيها ولمعانهما يخفي كابة نفسها المنقبضة بشدة خوفها"},{"n":9,"text":"فدخلت كل الابواب بابا بابا ثم وقفت قبالة الملك حيث كان جالسا على عرش ملكه بلباس الملك مزينا بالذهب والجواهر \nومنظره رهيب"},{"n":10,"text":"فلما رفع وجهه ولاح من اتقاد عينيه غضب صدره سقطت الملكة واستحال لون وجهها الى صفرة واتكات راسها على الجارية \nاسترخاء"},{"n":11,"text":"فحول الله روح الملك الى الحلم فاسرع ونهض عن العرش مشفقا وضمها بذراعيه حتى ثابت الى نفسها وكان يلاطفها بهذاالكلام"},{"n":12,"text":"ما لك يا استر انا اخوك لا تخافي"},{"n":13,"text":"انك لا تموتين انما الشريعة ليست عليك ولكن على العامة"},{"n":14,"text":"هلمي والمسي الصولجان"},{"n":15,"text":"واذ لم تزل ساكتة اخذ صولجان الذهب وجعله على عنقها وقبلها وقال لماذا لا تكلمينني"},{"n":16,"text":"فاجابت وقالت اني رايتك يا سيدي كانك ملاك الله فاضطرب قلبي هيبة من مجدك"},{"n":17,"text":"لانك عجيب جدا يا سيدي ووجهك مملوء نعمة"},{"n":18,"text":"وفيما هي تتكلم سقطت ثانية وكاد يغشى عليها"},{"n":19,"text":"فاضطرب الملك وكان جميع اعوانه يلاطفونها"}]},{"label":"سفر أستير 16","verses":[{"n":1,"text":"من ارتحششتا العظيم المالك من الهند الى الحبشة الى القواد والرؤساء في المئة والسبعة والعشرين اقليما التي في طاعتنا سلام"},{"n":2,"text":"ان كثيرين يسيئون اتخاذ المجد الممنوح لهم فيتكبرون"},{"n":3,"text":"ويجتهدون لا ان يظلموا رعية الملوك فقط ولكن اذ لا يحسنون تحمل المجد الممنوح لهم يتامرون على الذين منحوه لهم"},{"n":4,"text":"ولا يكتفون بان لا يشكروا على الانعام وان ينابذوا الحقوق الانسانية بل يتوهمون انهم يستطيعون ان يفروا من قضاء الله \nالمطلع على كل شيء"},{"n":5,"text":"وقد بلغ من حماقتهم انهم يحاولون بمكايد اكاذيبهم ان يسقطوا الذين سلمت اليهم المناصب وهم يجرونها بالتحري ويفعلون \nكل مايستاهلون به شكر الجميع"},{"n":6,"text":"ويخدعوا باحتيال مكرهم مسامع الرؤساء السليمة الذين يقيسون طباع غيرهم على طباعهم"},{"n":7,"text":"وهذا امر مختبر من التواريخ القديمة ومما يحدث كل يوم ان دسائس البعض تفسد خواطر الملوك الصالحة"},{"n":8,"text":"فلذلك ينبغي ان ينظر في سلم جميع الاقاليم"},{"n":9,"text":"فلا ينبغي ان يظن اننا نامر باشياء متباينة عن خفة عقل بل ذلك ناشئ عن اختلاف الازمنة وضروراتها التي حملتنا على ابراز \nالحكم بحسب مقتضى نفع الجميع"},{"n":10,"text":"ولكي تفهموا كلامنا باوضح بيانا فان هامان بن همداتا الذي هو مكدوني جنسا ومشربا وهو غريب عن دم الفرس وقد فضح \nرحمتنا بقساوته بعد ان اويناه غريبا"},{"n":11,"text":"وبعدما احسنا اليه حتى كان يدعى ابا لنا وكان الجميع يسجدون له سجودهم لثنيان الملك"},{"n":12,"text":"قد بلغ من شدة عتوه انه اجتهد ان يسلبنا الملك والحياة"},{"n":13,"text":"لانه سعى بدسائس جديدة لم تسمع باهلاك مردكاي الذي انما نحن في الحياة من امانته واحسانه وباهلاك قرينة ملكنا استير \nوسائر شعبها"},{"n":14,"text":"وكان في نفسه انه بعد قتلهم يترصد لنا في خلوتنا ويحول مملكة الفرس الى المكدونيين"},{"n":15,"text":"ونحن لم نجد قط ذنبا في اليهود المقضي عليهم بالموت بقضاء اخبث البشر بل بعكس ذلك وجدنا ان لهم سننا عادلة"},{"n":16,"text":"وهم بنو الله العلي العظيم الحي الى الابد الذي باحسانه سلم الملك الى ابائنا والينا وما برح محفوظا الى اليوم"},{"n":17,"text":"وحيث ذلك فاعلموا ان الرسائل التي وجهها باسمنا هي باطلة"},{"n":18,"text":"وبسبب تلك الجريمة قد علق امام ابواب هذه المدينة شوشن هو صاحب تلك المؤامرة وجميع انسبائه على خشبات فنال بذلك \nجزاء ما استحق من قبل الله لا من قبلنا"},{"n":19,"text":"فليعلن هذا الامر الذي نحن منفذوه الان في جميع المدن ليباح لليهود ان يعملوا بسننهم"},{"n":20,"text":"وينبغي لكم ان تعضدوهم حتى يستمكنوا من قتل الذين كانوا متاهبين لقتلهم في اليوم الثالث عشر من الشهر الثاني عشر الذي يدعى اذار"},{"n":21,"text":"فان ذلك اليوم الذي كان لهم يوم حزن ونحيب قد حوله لهم الله القدير الى فرح"},{"n":22,"text":"وانتم ايضا فانظموا هذا اليوم بين سائر ايام الاعياد الاخرى وعيدوه بكل فرح حتى يعلم فيما بعد"},{"n":23,"text":"ان كل من يطيع الفرس بامانة يثاب على امانته ثوابا وافيا ومن يرصد لملكهم يهلك بجنايته"},{"n":24,"text":"وكل اقليم او مدينة يابى ان يشترك في هذا العيد فليهلك بالسيف والنار لا الناس فقط بل البهائم ايضا ليكون الى الابد \nعبرة للاستخفاف والعصيان"}]}],"sources":["https://ar.wikisource.org/wiki/تتمة_سفر_أستير"]},{"name":"الحكمة","chapters":[{"label":"سفر الحكمة 1","verses":[{"n":1,"text":"احبوا العدل يا قضاة الارض واعتقدوا في الرب خيرا والتمسوه بقلب سليم"},{"n":2,"text":"فانما يجده الذين لا يجربونه ويتجلى للذين لا يكفرون به"},{"n":3,"text":"لان الافكار الزائغة تقصي من الله واختبار قدرته يثقف الجهال"},{"n":4,"text":"ان الحكمة لا تلج النفس الساعية بالمكر ولا تحل في الجسد المسترق للخطية"},{"n":5,"text":"لان روح التاديب القدوس يهرب من الغش ويتحول عن الافكار السفيهة وينهزم اذا حضر الاثم"},{"n":6,"text":"ان روح الحكمة محب للانسان فلا يبرئ المجدف مما نطق لان الله ناظر لكليتيه ورقيب لقلبه لا يغفل وسامع لفمه"},{"n":7,"text":"لان روح الرب ملا المسكونة وواسع الكل عنده علم كل كلمة"},{"n":8,"text":"فلذلك لا يخفى عليه ناطق بسوء ولا ينجو من القضاء المفحم"},{"n":9,"text":"لكن سيفحص عن افكار المنافق وكل ما سمع من اقواله يبلغ الى الرب فيحكم على اثامه"},{"n":10,"text":"لان الاذن الغيرى تسمع كل شيء وصياح المتذمرين لا يخفى عليها"},{"n":11,"text":"فاحترزوا من التذمر الذي لا خير فيه وكفوا السنتكم عن الثلب فان المنطوق به في الخفية لا يذهب سدى والفم الكاذب يقتل \nالنفس"},{"n":12,"text":"لا تغاروا على الموت في ضلال حياتكم ولا تجلبوا عليكم الهلاك باعمال ايديكم"},{"n":13,"text":"اذ ليس الموت من صنع الله ولا هلاك الاحياء يسره"},{"n":14,"text":"لانه انما خلق الجميع للبقاء فمواليد العالم انما كونت معافاة وليس فيها سم مهلك ولا ولاية للجحيم على الارض"},{"n":15,"text":"لان البر خالد"},{"n":16,"text":"لكن المنافقين هم استدعوا الموت بايديهم واقوالهم ظنوه حليفا لهم فاضمحلوا وانما عاهدوه لانهم اهل ان يكونوا من حزبه"}]},{"label":"سفر الحكمة 2","verses":[{"n":1,"text":"فانهم بزيغ افكارهم قالوا في انفسهم ان حياتنا قصيرة شقية وليس لممات الانسان من دواء ولم يعلم قط ان احدا رجع من الجحيم"},{"n":2,"text":"انا ولدنا اتفاقا وسنكون من بعد كانا لم نكن قط لان النسمة في انافنا دخان والنطق شرارة من حركة قلوبنا"},{"n":3,"text":"فاذا انطفات عاد الجسم رمادا وانحل الروح كنسيم رقيق وزالت حياتنا كاثر غمامة واضمحلت مثل ضباب يسوقه شعاع الشمس \nويسقط بحرها"},{"n":4,"text":"وبعد حين ينسى اسمنا ولا يذكر احد اعمالنا"},{"n":5,"text":"انما حياتنا ظل يمضي ولا مرجع لنا بعد الموت لانه يختم علينا فلا يعود احد"},{"n":6,"text":"فتعالوا نتمتع بالطيبات الحاضرة ونبتدر منافع الوجود ما دمنا في الشبيبة"},{"n":7,"text":"ونترو من الخمر الفاخرة ونتضمخ بالادهان ولا تفتنا زهرة الاوان"},{"n":8,"text":"ونتكلل بالورد قبل ذبوله ولا يكن مرج الا تمر لنا فيه لذة"},{"n":9,"text":"ولا يكن فينا من لا يشترك في لذاتنا ولنترك في كل مكان اثار الفرح فان هذا حظنا ونصيبنا"},{"n":10,"text":"لنجر على الفقير الصديق ولا نشفق على الارملة ولا نهب شيبة الشيخ الكثير الايام"},{"n":11,"text":"ولتكن قوتنا هي شريعة العدل فانه من الثابت ان الضعف لا يغني شيئا"},{"n":12,"text":"ولنكمن للصديق فانه ثقيل علينا يقاوم اعمالنا ويقرعنا على مخالفتنا للناموس ويفضح ذنوب سيرتنا"},{"n":13,"text":"يزعم ان عنده علم الله ويسمي نفسه ابن الرب"},{"n":14,"text":"وقد صار لنا عذولا حتى على افكارنا"},{"n":15,"text":"بل منظره ثقيل علينا لان سيرته تخالف سيرة الناس وسبله تباين سبلهم"},{"n":16,"text":"قد حسبنا كزيوف فهو يجانب طرقنا مجانبة الرجس ويغبط موت الصديقين ويتباهى بان الله ابوه"},{"n":17,"text":"فلننظر هل اقواله حق ولنختبر كيف تكون عاقبته"},{"n":18,"text":"فانه ان كان الصديق ابن الله فهو ينصره وينقذه من ايدي مقاوميه"},{"n":19,"text":"فلنمتحنه بالشتم والعذاب حتى نعلم حلمه ونختبر صبره"},{"n":20,"text":"ولنقض عليه باقبح ميتة فانه سيفتقد كما يزعم"},{"n":21,"text":"هذا ما ارتاوه فضلوا لان شرهم اعماهم"},{"n":22,"text":"فلم يدركوا اسرار الله ولم يرجوا جزاء القداسة ولم يعتبروا ثواب النفوس الطاهرة"},{"n":23,"text":"فان الله خلق الانسان خالدا وصنعه على صورة ذاته"},{"n":24,"text":"لكن بحسد ابليس دخل الموت الى العالم"},{"n":25,"text":"فيذوقه الذين هم من حزبه"}]},{"label":"سفر الحكمة 3","verses":[{"n":1,"text":"اما نفوس الصديقين فهي بيد الله فلا يمسها العذاب"},{"n":2,"text":"وفي ظن الجهال انهم ماتوا وقد حسب خروجهم شقاء"},{"n":3,"text":"وذهابهم عنا عطبا اما هم ففي السلام"},{"n":4,"text":"ومع انهم قد عوقبوا في عيون الناس فرجاؤهم مملوء خلودا"},{"n":5,"text":"وبعد تاديب يسير لهم ثواب عظيم لان الله امتحنهم فوجدهم اهلا له"},{"n":6,"text":"محصهم كالذهب في البودقة وقبلهم كذبيحة محرقة"},{"n":7,"text":"فهم في وقت افتقادهم يتلالاون ويسعون سعي الشرار بين القصب"},{"n":8,"text":"ويدينون الامم ويتسلطون على الشعوب ويملك ربهم الى الابد"},{"n":9,"text":"المتوكلون عليه سيفهمون الحق والامناء في المحبة سيلازمونه لان النعمة والرحمة لمختاريه"},{"n":10,"text":"اما المنافقون فسينالهم العقاب الخليق بمشوراتهم اذ استهانوا بالصديق وارتدوا عن الرب"},{"n":11,"text":"لان مزدري الحكمة والتاديب شقي انما رجاؤهم باطل واتعابهم بلا ثمرة واعمالهم لا فائدة فيها"},{"n":12,"text":"نساوهم سفيهات واولادهم اشرار"},{"n":13,"text":"ونسلهم ملعون اما العاقر الطاهرة التي لم تعرف المضجع الفاحش فطوبى لها انها ستحوز ثمرتها في افتقاد النفوس"},{"n":14,"text":"وطوبى للخصي الذي لم تباشر يده ماثما ولا افتكر قلبه بشر على الرب فانه سيعطى نعمة سامية لامانته وحظا شهيا في هيكل \nالرب"},{"n":15,"text":"لان ثمرة الاتعاب الصالحة فاخرة وجرثومة الفطنة راسخة"},{"n":16,"text":"اما اولاد الزناة فلا يبلغون اشدهم وذرية المضجع الاثيم تنقرض"},{"n":17,"text":"ان طالت حياتهم فانهم يحسبون كلا شيء وفي اواخرهم تكون شيخوختهم بلا كرامة"},{"n":18,"text":"وان ماتوا سريعا فلا يكون لهم رجاء ولا عزاء في يوم الحساب"},{"n":19,"text":"لان عاقبة الجيل الاثيم هائلة"}]},{"label":"سفر الحكمة 4","verses":[{"n":1,"text":"ان البتولية مع الفضيلة اجمل فان معها ذكرا خالدا لانها تبقى معلومة عند الله والناس"},{"n":2,"text":"اذا حضرت يقتدى بها واذا غابت يشتاق اليها ومدى الدهور تفتخر باكليل الظفر بعد انتصارها في ساحة المعارك الطاهرة"},{"n":3,"text":"اما لفيف المنافقين الكثير التوالد فلا ينجح وفراخهم النغلة لا تتعمق اصولها ولا تقوم على ساق راسخة"},{"n":4,"text":"وان اخرجت فروعا الى حين فانها لعدم رسوخها تزعزعها الريح وتقتلعها الزوبعة"},{"n":5,"text":"فتنقصف فروعها قبل اناها وتكون ثمرتها خبيثة غير ناضجة للاكل ولا تصلح لشيء"},{"n":6,"text":"والمولودون من المضجع الاثيم يشهدون بفاحشة والديهم عند استنطاق حالهم"},{"n":7,"text":"اما الصديق فانه وان تعجله الموت يستقر في الراحة"},{"n":8,"text":"لان الشيخوخة المكرمة ليست هي القديمة الايام ولا هي تقدر بعدد السنين"},{"n":9,"text":"ولكن شيب الانسان هو الفطنة وسن الشيخوخة هي الحياة المنزهة عن العيب"},{"n":10,"text":"انه كان مرضيا لله فاحبه وكان يعيش بين الخطاة فنقله"},{"n":11,"text":"خطفه لكي لا يغير الشر عقله ولا يطغي الغش نفسه"},{"n":12,"text":"لان سحر الاباطيل يغشي الخير ودوار الشهوة يطيش العقل السليم"},{"n":13,"text":"قد بلغ الكمال في ايام قليلة فكان مستوفيا سنين كثيرة"},{"n":14,"text":"واذ كانت نفسه مرضية للرب فقد اخرج سريعا من بين الشرور اما الشعوب فابصروا ولم يفقهوا ولم يجعلوا هذا فيقلوبهم"},{"n":15,"text":"ان نعمته ورحمته لمختاريه وافتقاده لقديسيه"},{"n":16,"text":"لكن الصديق الذي قد مات يحكم على المنافقين الباقين بعده الشبيبة السريعة الكمال تحكم على شيخوخة الاثيم الكثيرة \nالسنين"},{"n":17,"text":"فانهم يبصرون موت الحكيم ولا يفقهون ماذا اراد الرب به ولماذا نقله الى عصمته"},{"n":18,"text":"يبصرون ويزدرون والرب يستهزئ بهم"},{"n":19,"text":"سيسقطون من بعد سقوطا مهينا ويكونون عارا بين الاموات مدى الدهور فانه يحطمهم وهم مبلسون مطرقون ويقتلعهم من الاسس \nويتم خرابهم فيكونون في العذاب وذكرهم يهلك"},{"n":20,"text":"يتقدمون فزعين من تذكر خطاياهم واثامهم تحجهم في وجوههم"}]},{"label":"سفر الحكمة 5","verses":[{"n":1,"text":"حينئذ يقوم الصديق بجراة عظيمة في وجوه الذين ضايقوه وجعلوا اتعابه باطلة"},{"n":2,"text":"فاذا راوه يضطربون من شدة الجزع وينذهلون من خلاص لم يكونوا يظنونه"},{"n":3,"text":"ويقولون في انفسهم نادمين وهم ينوحون من ضيق صدرهم هذا الذي كنا حينا نتخذه سخرة ومثلا للعار"},{"n":4,"text":"وكنا نحن الجهال نحسب حياته جنونا وموته هوانا"},{"n":5,"text":"فكيف اصبح معدودا في بني الله وحظه بين القديسين"},{"n":6,"text":"لقد ضللنا عن طريق الحق ولم يضئ لنا نور البر ولم تشرق علينا الشمس"},{"n":7,"text":"اعيينا في سبل الاثم والهلاك وهمنا في متايه لا طريق فيها ولم نعلم طريق الرب"},{"n":8,"text":"فماذا نفعتنا الكبرياء وماذا افادنا افتخارنا بالاموال"},{"n":9,"text":"قد مضى ذلك كله كالظل وكالخبر السائر"},{"n":10,"text":"او كالسفينة الجارية على الماء المتموج التي بعد مرورها لا تجد اثرها ولا خط حيزومها في الامواج"},{"n":11,"text":"او كطائر يطير في الجو فلا يبقى دليل على مسيره يضرب الريح الخفيفة بقوادمه ويشق الهواء بشدة سرعته وبرفرفة جناحيه \nيعبر ثم لا تجد لمروره من علامة"},{"n":12,"text":"او كسهم يرمى الى الهدف فيخرق به الهواء ولوقته يعود الى حاله حتى لا يعرف ممر السهم"},{"n":13,"text":"كذلك نحن ولدنا ثم اضمحللنا ولم يكن لنا ان نبدي علامة فضيلة بل فنينا في رذيلتنا"},{"n":14,"text":"كذا قال الخطاة في الجحيم"},{"n":15,"text":"لان رجاء المنافق كغبار تذهب به الريح وكزبد رقيق تطارده الزوبعة وكدخان تبدده الريح وكذكر ضيف نزل يوما ثم ارتحل"},{"n":16,"text":"اما الصديقون فسيحيون الى الابد وعند الرب ثوابهم ولهم عناية من لدن العلي"},{"n":17,"text":"فلذلك سينالون ملك الكرامة وتاج الجمال من يد الرب لانه يسترهم بيمينه وبذراعه يقيهم"},{"n":18,"text":"يتسلح بغيرته ويسلح الخلق للانتقام من الاعداء"},{"n":19,"text":"يلبس البر درعا وحكم الحق خوذة"},{"n":20,"text":"ويتخذ القداسة ترسا لا يقهر"},{"n":21,"text":"ويحدد غضبه سيفا ماضيا والعالم يحارب معه الجهال"},{"n":22,"text":"فتنطلق صواعق البروق انطلاقا لا يخطئ وعن قوس الغيوم المحكمة التوتير تطير الى الهدف"},{"n":23,"text":"وسخطه يرجمهم ببرد ضخم ومياه البحار تستشيط عليهم والانهار تلتقي بطغيان شديد"},{"n":24,"text":"وتثور عليهم ريح شديدة زوبعة تذريهم والاثم يدمر جميع الارض والفجور يقلب عروش المقتدرين"}]},{"label":"سفر الحكمة 6","verses":[{"n":1,"text":"الحكمة خير من القوة والحكيم افضل من الجبار"},{"n":2,"text":"وانتم ايها الملوك فاسمعوا وتعقلوا ويا قضاة اقاصي الارض اتعظوا"},{"n":3,"text":"اصغوا ايها المتسلطون على الجماهير المفتخرون بجموع الامم"},{"n":4,"text":"فان سلطانكم من الرب وقدرتكم من العلي الذي سيفحص اعمالكم ويستقصي نياتكم"},{"n":5,"text":"فانكم انتم الخادمين لملكه لم تحكموا حكم الحق ولم تحفظوا الشريعة ولم تسيروا بحسب مشيئة الله"},{"n":6,"text":"فسيطلع عليكم بغتة مطلعا مخيفا لانه سيمضى على الحكام قضاء شديد"},{"n":7,"text":"فان الصغير اهل للرحمة اما ارباب القوة فبقوة يفحصون"},{"n":8,"text":"ورب الجميع لا يستثني احد ولا يهاب العظمة لان الصغير والعظيم كليهما صنعه على السواء وعنايته تعم الجميع"},{"n":9,"text":"لكن على الاشداء امتحانا شديدا"},{"n":10,"text":"اليكم ايها الملوك توجيه كلامي لكي تتعلموا الحكمة ولا تسقطوا"},{"n":11,"text":"فان الذين يحفظون بقداسة ما هو مقدس يقدسون والذين يتعلمون هذه يجدون ما يحتجون به"},{"n":12,"text":"فابتغوا كلامي واحرصوا عليه فتتادبوا"},{"n":13,"text":"فان الحكمة ذات بهاء ونضرة لا تذبل ومشاهدتها متيسرة للذين يحبونها ووجدانها سهل على الذين يلتمسونها"},{"n":14,"text":"فهي تسبق فتتجلى للذين يبتغونها"},{"n":15,"text":"ومن ابتكر في طلبها لا يتعب لانه يجدها جالسة عند ابوابه"},{"n":16,"text":"فالتامل فيها كمال الفطنة ومن سهر لاجلها فلا يلبث له هم"},{"n":17,"text":"لانها تجول في طلب الذين هم اهل لها وتتمثل لهم في الطرق باسمة وتتلقاهم كلما تاملوا فيها"},{"n":18,"text":"فاولها الخلوص في ابتغاء التاديب"},{"n":19,"text":"وتطلب التاديب هو المحبة والمحبة حفظ الشرائع ومراعاة الشرائع ثبات الطهارة"},{"n":20,"text":"والطهارة تقرب الى الله"},{"n":21,"text":"فابتغاء الحكمة يبلغ الى الملكوت"},{"n":22,"text":"فان كنتم تلتذون بالعرش والصولجان يا ملوك الشعوب فاكرموا الحكمة لكي تملكوا الى الابد"},{"n":23,"text":"واحبوا نور الحكمة يا حكام الشعوب"},{"n":24,"text":"وانا اخبركم ما الحكمة وكيف صدرت ولا اكتم عنكم الاسرار لكن ابحث عنها من اول كونها واجعل معرفتها بينه ولا اتجاوز من \nالحق شيئا"},{"n":25,"text":"ولا اسير مع من يذوب حسدا لان مثل هذا لا حظ له في الحكمة"},{"n":26,"text":"ان كثرة الحكماء خلاص العالم والملك الفطن ثبات الشعب"},{"n":27,"text":"فتادبوا باقوالي واستفيدوا بها"}]},{"label":"سفر الحكمة 7","verses":[{"n":1,"text":"انما انا انسان يموت مشاكل لسائر الناس من جنس اول من جبل وقد صورت جسدا في جوف امي"},{"n":2,"text":"وفي مدة عشرة اشهر صنعت من الدم بزرع الرجل واللذة التي تصاحب النوم"},{"n":3,"text":"ولما ولدت انتشيت هذا الهواء الشائع وسقطت على هذه الارض المشتركة واول ما استهللت بالبكاء على حد الجميع"},{"n":4,"text":"وربيت في القمط وباهتمام كثير"},{"n":5,"text":"فانه ليس لملك بدء مولد غير هذا"},{"n":6,"text":"بل دخول الجميع الى الحياة واحد وخروجهم سواء"},{"n":7,"text":"حينئذ تمنيت فاوتيت الفطنة ودعوت فحل علي روح الحكمة"},{"n":8,"text":"ففضلتها على الصوالجة والعروش ولم احسب الغنى شيئا بالقياس اليها"},{"n":9,"text":"ولم اعدل بها الحجر الكريم لان جميع الذهب بازائها قليل من الرمل والفضة عندها تحسب طينا"},{"n":10,"text":"واحببتها فوق العافية والجمال واتخذتها لي نورا لان ضوءها لا يغرب"},{"n":11,"text":"فاوتيت معها كل صنف من الخير ونلت من يديها غنى لا يحصى"},{"n":12,"text":"فتمتعت بهذه كلها لان الحكمة قائدة لها ولم اعلم انها ام جميعها"},{"n":13,"text":"تعلمتها بغير مكر واشرك فيها بغير حسد وغناها لا استره"},{"n":14,"text":"فانه كنز للناس لا ينقص والذين استفادوا منه اشركوا في محبة الله لان مواهب التاديب قربتهم اليه"},{"n":15,"text":"وقد وهبني الله ان ابدي عما في نفسي وان اجري في خاطري ما يليق بمواهبه فانه هو المرشد الى الحكمة ومثقف الحكماء"},{"n":16,"text":"وفي يده نحن واقوالنا والفطنة كلها ومعرفة ما يصنع"},{"n":17,"text":"ووهبني علما يقينا بالاكوان حتى اعرف نظام العالم وقوات العناصر"},{"n":18,"text":"ومبدا الازمنة ومنتهاها وما بينهما وتغير الاحوال وتحول الاوقات"},{"n":19,"text":"ومداور السنين ومراكز النجوم"},{"n":20,"text":"وطبائع الحيوان واخلاق الوحوش وعصوف الرياح وخواطر الناس وتباين الانبتة وقوى العقاقير"},{"n":21,"text":"فعلمت جميع المكنونات والظواهر لان الحكمة مهندسة كل شيء هي علمتني"},{"n":22,"text":"فان فيها الروح الفهم القدوس المولود الوحيد ذا المزايا الكثيرة اللطيف السريع الحركة الفصيح الطاهر النير السليم \nالمحب للخير الحديد الحر المحسن"},{"n":23,"text":"المحب للبشر الثابت الراسخ المطمئن القدير الرقيب الذي ينفذ جميع الارواح الفهمة الطاهرة اللطيفة"},{"n":24,"text":"لان الحكمة اسرع حركة من كل متحرك فهي لطهارتها تلج وتنفذ في كل شيء"},{"n":25,"text":"فانها بخار قوة الله وصدور مجد القدير الخالص فلذلك لا يشوبها شيء نجس"},{"n":26,"text":"لانها ضياء النور الازلي ومراة عمل الله النقية وصورة جودته"},{"n":27,"text":"تقدر على كل شيء وهي واحدة وتجدد كل شيء وهي ثابتة في ذاتها وفي كل جيل تحل في النفوس القديسة فتنشئ احباء لله \nوانبياء"},{"n":28,"text":"لان الله لا يحب احدا الا من يساكن الحكمة"},{"n":29,"text":"انها ابهى من الشمس واسمى من كل مركز للنجوم واذا قيست بالنور تقدمت عليه"},{"n":30,"text":"لان النور يعقبه الليل اما الحكمة فلا يغلبها الشر"}]},{"label":"سفر الحكمة 8","verses":[{"n":1,"text":"انها تبلغ من غاية الى غاية بالقوة وتدبر كل شيء بالرفق"},{"n":2,"text":"لقد احببتها والتمستها منذ صبائي وابتغيت ان اتخذها لي عروسا وصرت لجمالها عاشقا"},{"n":3,"text":"فان في نسبها مجدا لانها تحيا عند الله ورب الجميع قد احبها"},{"n":4,"text":"فهي صاحبة اسرار علم الله والمتخيرة لاعماله"},{"n":5,"text":"اذا كان الغنى ملكا نفيسا في الحياة فاي شيء اغنى من الحكمة صانعة الجميع"},{"n":6,"text":"وان كانت الفطنة هي التي تعمل فمن احكم منها في هندسة الاكوان"},{"n":7,"text":"واذا كان احد يحب البر فالفضائل هي اتعابها لانها تعلم العفة والفطنة والعدل والقوة التي لا شيء للناس في الحياة انفع \nمنها"},{"n":8,"text":"واذا كان احد يؤثر انواع العلم فهي تعرف القديم وتتمثل المستقبل وتفقه فنون الكلام وحل الاحاجي وتعلم الايات والعجائب \nقبل ان تكون وحوادث الاوقات والازمنة"},{"n":9,"text":"لذلك عزمت ان اتخذها قرينة لحياتي علما بانها تكون لي مشيرة بالصالحات ومفرجة لهمومي وكربي"},{"n":10,"text":"فيكون لي بها مجد عند الجموع وكرامة لدى الشيوخ على ما انا فيه من الفتاء"},{"n":11,"text":"واعد حاذقا في القضاء وعجيبا امام المقتدرين"},{"n":12,"text":"اذا صمت ينتظرون واذا نطقت يصغون واذا افضت في الكلام يضعون ايديهم على افواههم"},{"n":13,"text":"وانال بها الخلود واخلف عند الذين بعدي ذكرا مؤبدا"},{"n":14,"text":"ادبر الشعوب وتخضع لي الامم"},{"n":15,"text":"يسمع الملوك المرهوبون فيخافونني ويظهر في الجمع صلاحي وفي الحرب باسي"},{"n":16,"text":"واذا دخلت بيتي سكنت اليها لانه ليس في معاشرتها مرارة ولا في الحياة معها غمة بل سرور وفرح"},{"n":17,"text":"فلما تفكرت في نفسي بهذه وتاملت في قلبي ان في قربى الحكمة خلودا"},{"n":18,"text":"وفي مصافاتها لذة صالحة وفي اتعاب يديها غنى لا ينقص وفي الترشح لمؤانستها فطنة وفي الاشتراك في حديثها فخرا طفقت \nاطوف طالبا ان اتخذها لنفسي"},{"n":19,"text":"وقد كنت صبيا حسن الطباع ورزقت نفسا صالحة"},{"n":20,"text":"ثم بازديادي صلاحا حصلت على جسد غير مدنس"},{"n":21,"text":"ولما علمت باني لا اكون عفيفا ما لم يهبني الله العفة وقد كان من الفطنة ان اعلم ممن هذه الموهبة توجهت الى الرب \nوسالته من كل قلبي قائلا"}]},{"label":"سفر الحكمة 9","verses":[{"n":1,"text":"يا اله الاباء يا رب الرحمة يا صانع الجميع بكلمتك"},{"n":2,"text":"وفاطر الانسان بحكمتك لكي يسود على الخلائق التي كونتها"},{"n":3,"text":"ويسوس العالم بالقداسة والبر ويجري الحكم باستقامة النفس"},{"n":4,"text":"هب لي الحكمة الجالسة الى عرشك ولا ترذلني من بين بنيك"},{"n":5,"text":"فاني انا عبدك وابن امتك انسان ضعيف قليل البقاء وناقص الفهم في القضاء والشرائع"},{"n":6,"text":"على انه ان كان في بني البشر احد كامل فما لم تكن معه الحكمة التي منك لا يحسب شيئا"},{"n":7,"text":"انك قد اخترتني لشعبك ملكا ولبنيك وبناتك قاضيا"},{"n":8,"text":"وامرتني ان ابني هيكلا في جبل قدسك ومذبحا في مدينة سكناك على مثال المسكن المقدس الذي هياته منذ البدء"},{"n":9,"text":"ان معك الحكمة العليمة باعمالك والتي كانت حاضرة اذ صنعت العالم وهي عارفة ما المرضي في عينيك والمستقيم في وصاياك"},{"n":10,"text":"فارسلها من السماوات المقدسة وابعثها من عرش مجدك حتى اذا حضرت تجد معي واعلم ما المرضي لديك"},{"n":11,"text":"فانها تعلم وتفهم كل شيء فتكون لي في افعالي مرشدا فطينا وبعزها تحفظني"},{"n":12,"text":"فتغدو اعمالي مقبولة واحكم لشعبك بالعدل واكون اهلا لعرش ابي"},{"n":13,"text":"فاي انسان يعلم مشورة الله او يفطن لما يريد الرب"},{"n":14,"text":"ان افكار البشر ذات احجام وبصائرنا غير راسخة"},{"n":15,"text":"اذ الجسد الفاسد يثقل النفس والمسكن الارضي يخفض العقل الكثير الهموم"},{"n":16,"text":"ونحن بالجهد نتمثل ما على الارض وبالكد ندرك ما بين ايدينا فما في السماوات من اطلع عليه"},{"n":17,"text":"ومن علم مشورتك لو لم تؤت الحكمة وتبعث روحك القدوس من الاعالي"},{"n":18,"text":"فانه كذلك قومت سبل الذين على الارض وتعلم الناس مرضاتك"},{"n":19,"text":"والحكمة هي التي خلصت كل من ارضاك يا رب منذ البدء"}]},{"label":"سفر الحكمة 10","verses":[{"n":1,"text":"هي التي حفظت اول من جبل ابا للعالم لما خلق وحده"},{"n":2,"text":"وانقذته من زلته واتته قوة ليتسلط على الجميع"},{"n":3,"text":"ولما ارتد عنها الظالم في غضبه هلك في حنقه الذي كان به قاتل اخيه"},{"n":4,"text":"ولما غمر الطوفان الارض بسببه عادت الحكمة فخلصتها بهدايتها للصديق في آلة خشب حقيرة"},{"n":5,"text":"وهي التي عند اتفاق لفيف الامم على الشر لقيت الصديق وصانته لله بغير وصمة وحفظت احشائه صماء عن ولده"},{"n":6,"text":"وهي التي انقذت الصديق من المنافقين الهالكين فهرب من النار الهابطة على المدن الخمس"},{"n":7,"text":"والى الان يشهد بشرهم قفر يسطع منه الدخان ونبات يثمر ثمرا لا ينضج وعمود من ملح قائم تذكارا لنفس لم تؤمن"},{"n":8,"text":"والذين اهملوا الحكمة لم ينحصر ظلمهم لانفسهم بجهلهم الصلاح ولكنهم خلفوا للناس ذكر حماقتهم بحيث لم يستطيعوا كتمان \nما زلوا فيه"},{"n":9,"text":"واما الذين خدموا الحكمة فانقذتهم من كل نصب"},{"n":10,"text":"وهي التي قادت الصديق الهارب من غضب اخيه في سبل مستقيمة وارته ملكوت الله واتته علم القديسين وانجحته في اتعابه \nواكثرت ثمرات اعماله"},{"n":11,"text":"وعند طماعة المستطيلين عليه انتصبت لمعونته واغنته"},{"n":12,"text":"ووقته من اعدائه وحمته من الكامنين له واظفرته في القتال الشديد لكي يعلم ان التقوى اقدر من كل شيء"},{"n":13,"text":"وهي التي لم تخذل الصديق المبيع بل صانته من الخطيئة ونزلت معه في الجب"},{"n":14,"text":"وفي القيود لم تفارقه حتى ناولته صوالجة الملك وسلطانا على الذين قسروه وكذبت الذين عابوه واتته مجدا ابديا"},{"n":15,"text":"وهي التي انقذت شعبا مقدسا وزرية لا وصمة فيها من امة مضايقيهم"},{"n":16,"text":"وحلت نفس عبد للرب وقاومت ملوكا مرهوبين بعجائب وايات"},{"n":17,"text":"وجزت القديسين ثواب اتعابهم وقادتهم في طريق عجيب وكانت لهم ظلا في النهار وضياء نجوم في الليل"},{"n":18,"text":"وعبرت بهم البحر الاحمر واجازتهم المياه الغزيرة"},{"n":19,"text":"اما اعداؤهم فاغرقتهم ثم قذفتهم من عمق الغمار على الشاطئ فسلب الصديقون المنافقين"},{"n":20,"text":"ورنموا لاسمك القدوس ايها الرب وحمدوا بقلب واحد يدك الناصرة"},{"n":21,"text":"لان الحكمة فتحت افواه البكم وجعلت السنة الاطفال تفصح"}]},{"label":"سفر الحكمة 11","verses":[{"n":1,"text":"ثم سددت مساعيهم بارشاد نبي قديس"},{"n":2,"text":"فساروا في برية لا ساكن بها وضربوا اخبيتهم في ارض قفرة"},{"n":3,"text":"وقاوموا محاربيهم ودافعوا اعداءهم"},{"n":4,"text":"وفي عطشهم دعوا اليك فاعطوا ماء من صخرة الصوان وشفاء لغليلهم من الحجر الجلمود"},{"n":5,"text":"فكان الذي عذب به اعداؤهم اذ اعوزهم ما يشربون وبنو اسرائيل متهللون بكثرته"},{"n":6,"text":"هو الذي احسن به اليهم في عوزهم"},{"n":7,"text":"فانك بلبلت اولئك اذ بدلتهم بمعين النهر الدائم دما صديدا"},{"n":8,"text":"عقابا لهم على قضائهم بقتل الاطفال وهؤلاء اعطيتهم ماء غزيرا عند الياس منه"},{"n":9,"text":"لكي تريهم بعطشهم هذا كيف عاقبت اضدادهم"},{"n":10,"text":"فانهم بامتحانك لهم وان كان تاديب رحمة فهموا كيف كان عذاب المنافقين المقضي عليهم بالغضب"},{"n":11,"text":"لانك جربت هؤلاء كاب انذارا لهم واولئك ابتليتهم كملك قاس قضاء عليهم"},{"n":12,"text":"وقد مسهم في الغيب من الضر ما مسهم في المشهد"},{"n":13,"text":"اذ اخذهم ضعفان من الحزن والنحيب بتذكر الضربات السالفة"},{"n":14,"text":"لانهم لما سمعوا ان ما كان لهم عقابا صار لاعدائهم احسانا شعروا بيد الرب"},{"n":15,"text":"والذي قضوا من قبل بطرحه في النهر واستخفوا به ورذلوه استعظموه في اخر الامر اذا كان عطش الصديقين على خلاف عطشهم"},{"n":16,"text":"واذ كانوا قد سفهوا في افكارهم الاثيمة وضلوا حتى عبدوا زحافات حقيرة ووحوشا لا نطق لها انتقمت منهم بان ارسلت عليهم \nجما من الحيوانات التي لا نطق لها"},{"n":17,"text":"لكي يعلموا ان ما خطئ به احد به يعاقب"},{"n":18,"text":"ولم يكن صعبا على يدك القادرة على كل شيء التي صنعت العالم من مادة غير مصورة ان تبعث عليهم جما من الادباب او \nالاسود الباسلة"},{"n":19,"text":"او من اصناف جديدة لم تعرف من الوحوش الضارية التي تنفخ نارا او تبعث دخانا قاتما او ترسل من عيونها شرارا مخيفا"},{"n":20,"text":"اذا لكانت تهلكهم خوفا من منظرها فضلا عن ان تهشمهم باصابتها"},{"n":21,"text":"بل قد كان نفس كافيا لاسقاطهم فيتعقبهم القضاء وروح قدرتك يذريهم لكنك رتبت كل شيء بمقدار وعدد ووزن"},{"n":22,"text":"وعندك قدرة عظيمة في كل حين فمن يقاوم قوة ذراعك"},{"n":23,"text":"ان العالم كله امامك مثل ما ترجح به كفة الميزان وكنقطة ندى تسقط على الارض عند السحر"},{"n":24,"text":"لكنك ترحم الجميع لانك قادر على كل شيء وتتغاضى عن خطايا الناس لكي يتوبوا"},{"n":25,"text":"لانك تحب جميع الاكوان ولا تمقت شيئا مما صنعت فانك لو ابغضت شيئا لم تكونه"},{"n":26,"text":"وكيف يبقى شيء لم ترده ام كيف يحفظ ما لست انت داعيا له"},{"n":27,"text":"انك تشفق على جميع الاكوان لانها لك ايها الرب المحب النفوس"}]},{"label":"سفر الحكمة 12","verses":[{"n":1,"text":"ان في كل شيء روحك الذي لا فساد فيه"},{"n":2,"text":"فبه توبخ الخطاة شيئا فشيئا وفيما يخطاون به تذكرهم وتنذرهم لكي يقلعوا عن الشر ويؤمنوا بك ايها الرب"},{"n":3,"text":"فانك ابغضت الذين كانوا قديما سكان ارضك المقدسة"},{"n":4,"text":"لاجل اعمالهم الممقوتة لديك من السحر وذبائح الفجور"},{"n":5,"text":"اذ كانوا يقتلون اولادهم بغير رحمة وياكلون احشاء الناس ويشربون دماءهم في شعائر عبادتك"},{"n":6,"text":"فاثرت ان تهلك بايدي ابائنا اولئك الوالدين قتلة النفوس التي لا نصرة لها"},{"n":7,"text":"لكي تكون الارض التي هي اكرم عندك من كل ارض عامرة بابناء الله كما يليق بها"},{"n":8,"text":"على انك اشفقت على اولئك ايضا لانهم بشر فبعثت بالزنابير تتقدم عسكرك وتبيدهم شيئا بعد شيء"},{"n":9,"text":"لا لانك عجزت عن اخضاع المنافقين للصديقين بالقتال او تدميرهم بمرة بالوحوش الضارية او بامر جازم من عندك"},{"n":10,"text":"لكن بعقابهم شيئا فشيئا منحتهم مهلة للتوبة وان لم يخف عليك ان جيلهم شرير وان خبثهم غريزي وافكارهم لا تتغير الى \nالابد"},{"n":11,"text":"لانهم كانوا ذرية ملعونة منذ البدء ولم يكن عفوك عن خطاياهم خوفا من احد"},{"n":12,"text":"فانه من يقول ماذا صنعت او يعترض قضاءك ومن يشكوك بهلاك الامم التي خلقتها او يقف بين يديك مخاصما عن اناس مجرمين"},{"n":13,"text":"اذ ليس اله الا انت المعتني بالجميع حتى تري انك لا تقضي قضاء الظلم"},{"n":14,"text":"وليس لملك او سلطان ان يطالبك بالذين اهلكتهم"},{"n":15,"text":"واذ انت عادل تدبر الجميع بالعدل وتحسب القضاء على من لا يستوجب العقاب منافيا لقدرتك"},{"n":16,"text":"لان قوتك هي مبدا عدلك وبما انك رب الجميع فانت تشفق على الجميع"},{"n":17,"text":"وانما تبدي قوتك للذين لا يؤمنون انك على كمال القدرة وتعاقب العلماء على جسارتهم"},{"n":18,"text":"لكنك ايها السلطان القدير تحكم بالرفق وتدبرنا باشفاق كثير لان في يدك ان تعمل بقدرة متى شئت"},{"n":19,"text":"فعلمت شعبك باعمالك هذه ان الصديق ينبغي ان يكون محبا للناس وجعلت لبنيك رجاء حسنا لانك تمنحهم في خطاياهم مهلة \nللتوبة"},{"n":20,"text":"لانك ان كنت عاقبت اعداء بنيك المستوجبين للموت بمثل هذا التحرز والترفق وجعلت لهم زمانا ومكانا للاقلاع عن الشر"},{"n":21,"text":"فباي اعتناء دبرت بنيك الذين واثقت اباءهم بالاقسام والعهود على مواعيدك الصالحة"},{"n":22,"text":"فتؤدبنا نحن وتجلد اعداءنا جلدا كثيرا لكي نتذكر حلمك اذا حكمنا وننتظر رحمتك اذا حكم علينا"},{"n":23,"text":"لاجل ذلك فالمنافقون الذين عاشوا بالسفه عذبتهم بارجاسهم عينها"},{"n":24,"text":"فانهم في ضلالهم تجاوزوا طرق الضلال اذ اتخذوا ما يستحقره اعداؤهم من الحيوان الهة مغترين كاطفال لا يفقهون"},{"n":25,"text":"لذلك بعثت عليهم عقاب اولاد لا عقل لهم للسخرية"},{"n":26,"text":"ولما لم يتعظوا بتاديب السخرية ذاقوا العقاب اللائق بالله"},{"n":27,"text":"وفيما تحملوه بغيظهم وقد راوا ان ما اتخذوه الها كانوا به يعذبون عرفوا الاله الحق الذي كانوا يكفرون به ولذلك حلت \nبهم خاتمة العقاب"}]},{"label":"سفر الحكمة 13","verses":[{"n":1,"text":"ان جميع الذين لم يعرفوا الله هم حمقى من طبعهم لم يقدروا ان يعلموا الكائن من الخيرات المنظورة ولم يتاملوا المصنوعات حتى يعرفوا صانعها"},{"n":2,"text":"لكنهم حسبوا النار او الريح او الهواء اللطيف او مدار النجوم او لجة المياه او نيري السماء الهة تسود العالم"},{"n":3,"text":"فان كانوا انما اعتقدوا هذه الهة لانهم خلبوا بجمالها فليتعرفوا كم ربها احسن منها اذ الذي خلقها هو مبدا كل جمال"},{"n":4,"text":"او لانهم دهشوا من قوتها وفعلها فليتفهموا بها كم منشئها اقوى منها"},{"n":5,"text":"فانه بعظم جمال المبروءات يبصر فاطرها على طريق المقايسة"},{"n":6,"text":"غير ان لهؤلاء وجها من العذر لعلهم ضلوا في طلبهم لله ورغبتهم في وجدانهم"},{"n":7,"text":"اذ هم يبحثون عنه مترددين بين مصنوعاته فيغرهم منظرها لان المنظورات ذات جمال"},{"n":8,"text":"مع ذلك ليس لهم من مغفرة"},{"n":9,"text":"لانهم ان كانوا قد بلغوا من العلم ان استطاعوا ادراك كنه الدهر فكيف لم يكونوا اسرع ادراكا لرب الدهر"},{"n":10,"text":"اما الذين سموا اعمال ايدي الناس الهة الذهب والفضة وما اخترعته الصناعة وتماثيل الحيوان والحجر الحقير مما صنعته \nيد قديمة فهم اشقياء ورجاؤهم في الاموات"},{"n":11,"text":"يقطع نجار شجرة من الغابة طوع العمل ويجردها بحذقه من قشرها كله ثم بحسن صناعته يصنعها الة تصلح لخدمة العيش"},{"n":12,"text":"ويستعمل نفايتها وقودا لاعداد طعامه"},{"n":13,"text":"ثم ياخذ قطعة من نفايتها لا تصلح لشيء خشبة ذات اعوجاج وعقد ويعتني بنقشها في اوان فراغه ويصورها بخبرة صناعته على \nشكل انسان"},{"n":14,"text":"او يمثل بها حيوان خسيسا ويدهنها بالاسفيداج ويحمر لونها بالزنجفر ويطلي كل لطخة بها"},{"n":15,"text":"ويجعل لها مقاما يليق بها ويضعها في الحائط ويوثقها بالحديد"},{"n":16,"text":"ويتحفظ عليها ان لا تسقط لعلمه بانها لا تقوم بمعونة نفسها اذ هي تمثال يفتقر الى من يعينه"},{"n":17,"text":"ثم يتضرع اليها عن امواله وازواجه وبنيه ولا يخجل ان يخاطب من لا روح له"},{"n":18,"text":"فيطلب العافية من السقيم ويسال الميت الحياة ويستغيث بمن هو اعجز شيء عن الاغاثة"},{"n":19,"text":"ويتوسل من اجل السفر الى من لا يستطيع المشي ويلتمس النصرة في الكسب والتجارة ونجح المساعي ممن هو اقصر موجود باعا"}]},{"label":"سفر الحكمة 14","verses":[{"n":1,"text":"واخر قبل ان يركب البحر ويسير على الامواج المعربدة يستغيث بخشب هو اقصف من المركب الذي يحمله"},{"n":2,"text":"لان المركب اخترعه حب الكسب وصنعته الحكمة المهندسة"},{"n":3,"text":"لكن عنايتك ايها الاب هي التي تدبره لانك انت الذي فتحت في البحر طريقا وفي الامواج مسلكا امنا"},{"n":4,"text":"وبينت انك قادر ان تخلص من كل خطر ولو ركب البحر من يجهل صناعته"},{"n":5,"text":"وانت تحب ان لا تكون اعمال حكمتك باطلة فلذلك يودع الناس انفسهم خشبا صغيرا ويقطعون اللجة في سفينة ويخلصون"},{"n":6,"text":"وفي البدء ايضا حين هلك الجبابرة المتكبرون التجا رجاء العالم الى سفينة وارشدته يديك فابقى للدهر ذرية تتوالد"},{"n":7,"text":"فالخشب الذي به يحصل البر هو مبارك"},{"n":8,"text":"اما الخشب المصنوع صنما فملعون هو وصانعه اما هذا فلانه عمله واما ذاك فلانه مع كونه فاسدا سمي الها"},{"n":9,"text":"فان الله يبغض المنافق ونفاقه على السواء"},{"n":10,"text":"فيصيب العقاب المصنوع والصانع"},{"n":11,"text":"لذلك ستفتقد اصنام الامم ايضا لانها صارت في خلق الله رجسا ومعثرة لنفوس الناس وفخا لاقدام الجهال"},{"n":12,"text":"لان اختراع الاصنام هو اصل الفسق ووجدانها فساد الحياة"},{"n":13,"text":"وهي لم تكن في البدء وليست تدوم الى الابد"},{"n":14,"text":"لانها انما دخلت العالم بحب الناس للمجد الفارغ ولذلك قد عزم على الغائها عن قريب"},{"n":15,"text":"وذلك ان والدا قد فجع بثكل معجل فصنع تمثالا لابنه الذي خطف سريعا وجعل يعبد ذلك الانسان الميت بمنزلة اله ورسم للذين \nتحت يده شعائر وذبائح"},{"n":16,"text":"ثم على ممر الزمان تاصلت تلك العادة الكفرية فحفظت كشريعة وباوامر الملوك عبدت المنحوتات"},{"n":17,"text":"والذين لم يستطع الناس اكرامهم بمحضرهم لبعد مقامهم صوروا هيئاتهم الغائبة وجعلوا صورة الملك المكرم نصب العيون \nحرصا على تملقه في الغيبة كانه حاضر"},{"n":18,"text":"ثم ان حب الصناع للمباهاة كان داعية للجاهلين الى المبالغة في هذه العبادة"},{"n":19,"text":"فانهم رغبة في ارضاء الامر قد افرغوا وسعهم في الصناعة لاخراج الصورة على غاية الكمال"},{"n":20,"text":"فاستميل الجمهور ببهجة ذلك المصنوع حتى ان الذي كانوا قبل قليل يكرمونه كانسان عدوه الها"},{"n":21,"text":"وبهذا كان اقتناص الخلق فان رزيئة بعض الناس او اقتسار الملوك استعبدهم حتى جعلوا على الحجر والخشب الاسم الذي لا \nيشرك فيه احد"},{"n":22,"text":"ثم لم يكتفوا بضلالهم في معرفة الله لكنهم غاصوا في حرب الجهل الشديدة وهم يسمون مثل هذه الشرور سلاما"},{"n":23,"text":"فانهم يمارسون ذبائح من بنيهم وشعائر خفية ومادب جنون على اساليب اخر"},{"n":24,"text":"لا يرعون حسن السيرة ولا طهارة الزواج فيقتل الرجل صاحبه بالاغتيال ويمضه بالفاحشة"},{"n":25,"text":"شر متفاقم في كل موضع الدم والقتل والسرقة والمكر والفساد والخيانة والفتنة والحنث وقلق الابرار"},{"n":26,"text":"وكفران النعمة وتدنس النفوس والتباس المواليد وتشوش الزواج والفسق والعهر"},{"n":27,"text":"لان عبادة الاصنام المكروهة هي علة كل شر وابتداؤه وغايته"},{"n":28,"text":"فانهم اذا فرحوا جنوا او تنباوا كذبوا او عاملوا ظلموا او حالفوا اسرعوا الى الحنث"},{"n":29,"text":"ولتوكلهم على اصنام لا ارواح له لا يتوقعون اذا اقسموا بالزور ان ينالهم الخسران"},{"n":30,"text":"فهناك امران يستحقون بهما حلول اعقاب سوء اعتقادهم في الله اذ اتبعوا الاصنام وقسمهم بالظلم والمكر اذا ستخفوا \nبالقداسة"},{"n":31,"text":"لان معصية الظالمين انما يتعقبها القضاء على الخطاة لا قدرة المقسم بهم"}]},{"label":"سفر الحكمة 15","verses":[{"n":1,"text":"وانت يا الهنا ذو صلاح وصدق طويل الاناة ومدبر الجميع بالرحمة"},{"n":2,"text":"فاذا خطئنا فنحن في يدك وقد علمنا قدرتك لكنا لا نختار الخطا لعلمنا بانا من خاصتك"},{"n":3,"text":"فان معرفتك هي البر الكامل والعلم بقدرتك هو اصل الحياة الدائمة"},{"n":4,"text":"لذلك لم يغونا ما اخترعته صناعة الناس الممقوتة ولا عمل المصورين العقيم من الصور الملطخة بالالوان"},{"n":5,"text":"التي في النظر اليها فضيحة للسفهاء بعشقهم صورة تمثال ميت لا روح فيه"},{"n":6,"text":"لا جرم ان الذين يصنعونها والذين يعشقونها والذين يعبدونها هم كلفون بالمنكرات وهم اهل لان تكون امالهم في امثال هذه"},{"n":7,"text":"ان الخزاف يعني بعجن الطين اللين ويصنع منه كل اناء مما نستخدمه فيصنع من الطين الواحد الانية المستخدمة في الاعمال \nالطاهرة والمستخدمة في عكس ذلك واما تخصيص كل اناء بواحدة من الخدمتين فانما يرجع الى حكم صانع الطين"},{"n":8,"text":"وبعنائه الممقوت يصنع من هذا الطين الها باطلا وهو انما ولد من الطين من حين يسير وعن قليل سيعود الى ما اخذ منه حين \nيطالب بدين نفسه"},{"n":9,"text":"غير ان همه ليس بانه يتعب ولا بانه قريب الاجل لكنه يباري صاغة الذهب والفضة ويعارض النحاسين ويعتد ما يصنعه من \nالخسائس فخرا"},{"n":10,"text":"فقلبه رماد ورجاؤه اخس من التراب وحياته احقر من الطين"},{"n":11,"text":"لانه جهل من جبله ونفخ فيه نفسا عاملة وروحا محييا"},{"n":12,"text":"بل حسب حياتنا عبثا وعمرنا موسما للاكتساب وزعم انه لا بد من الربح بكل حيلة ولو بالظلم"},{"n":13,"text":"فانه عالم بانه اعظم جرما من الجميع لانه يصنع من طين الارض انية قصمة ومنحوتات"},{"n":14,"text":"ان جميع اعداء شعبك المتسلطين عليهم هم اجهل الناس واشقى من نفوس الاطفال"},{"n":15,"text":"لانهم حسبوا جميع اصنام الامم الهة تلك التي لا تبصر بعيونها ولا تنشق الهواء بانوفها ولا تسمع باذانها ولا تلمس باصابع \nايديها وارجلها عاجزة عن الخطو"},{"n":16,"text":"لانها انما عملها انسان والذي اعير روحا صنعها وليس في طاقة انسان ان يصنع الها مثله"},{"n":17,"text":"وانما هو فان فيصنع بيديه الاثيمتين ما لا حياة فيه فهو افضل من معبوداته اذ هو قد كان حيا واما هي فلم تكن حية \nالبتة"},{"n":18,"text":"وهم يعبدون اعدى الحيوان مما هو اشد البهائم عجمة"},{"n":19,"text":"وليس فيه ما في منظر الحيوانات الاخر من الحسن الشائق اذ فاته مدح الله وبركته"}]},{"label":"سفر الحكمة 16","verses":[{"n":1,"text":"لذلك كانوا احقاء بان يعاقبوا بامثال هذه ويعذبوا بجم من الحشرات"},{"n":2,"text":"اما شعبك فبدلا من ذلك العقاب احسنت اليهم باعداد السلوى ماكلا غريب الطعم اشبعت به شهوتهم"},{"n":3,"text":"حتى انه بينما كان اولئك مع جوعهم فاقدي كل شهوة للطعام من كراهة ما بعثت عليهم كان هؤلاء بعد عوز يسير يتناولون \nماكلا غريب الطعم"},{"n":4,"text":"فانه كان ينبغي لاولئك المقتسرين ان تنزل بهم فاقة لا مناص منها ولهؤلاء ان يروا كيف يعذب اعداؤهم لا غير"},{"n":5,"text":"ولما اقتحم هؤلاء حنق الوحوش الهائل واهلكهم لدغ الحيات الخبيثة"},{"n":6,"text":"لم يستمر غضبك الى المنتهى بل انما اقلقوا الى حين انذارا لهم ونصبت لهم علامة للخلاص تذكرهم وصية شريعتك"},{"n":7,"text":"فكان الملتفت اليها يخلص لا بذلك المنظور بل بك يا مخلص الجميع"},{"n":8,"text":"وبذلك اثبت لاعدائنا انك انت المنقذ من كل سوء"},{"n":9,"text":"لان اولئك قتلهم لسع الجراد والذباب ولم يوجد لنفوسهم شفاء اذ هم اهل لان يعاقبوا بمثل ذلك"},{"n":10,"text":"اما بنوك فلم تقو عليهم انياب التنانين السامة لان رحمتك اقبلت وشفتهم"},{"n":11,"text":"وانما نخسوا ليتذكروا اقوالك ثم خلصوا سريعا لئلا يسقطوا في نسيان عميق فيحرموا احسانك"},{"n":12,"text":"وما شفاهم نبت ولا مرهم بل كلمتك يا رب التي تشفي الجميع"},{"n":13,"text":"لان لك سلطان الحياة والموت فتحدر الى ابواب الجحيم وتصعد"},{"n":14,"text":"اما الانسان فيقتل بخبثه لكنه لا يعيد الروح الذي قد خرج ولا يسترجع النفس المقبوضة"},{"n":15,"text":"انه ليس احد يستطيع ان يهرب من يدك"},{"n":16,"text":"فانك قد جلدت بقوة ذراعك المنافقين الذين جحدوا معرفتك واطلقت في اثرهم سيولا وبردا وامطارا غريبة ونارا اكلة"},{"n":17,"text":"واغرب شيء ان النار كانت في الماء الذي يطفئ كل شيء تزداد حدة لان عناصر العالم تقاتل عن الصديقين"},{"n":18,"text":"وكان اللهيب تارة يسكن لئلا يحرق ما ارسل على المنافقين من الحيوان ولكي يبصروا فيعلموا ان قضاء الله على اعقابهم"},{"n":19,"text":"وتارة يخرج عن طبع النار فيتاجج في الماء لكي يستاصل انبتة الارض الاثيمة"},{"n":20,"text":"اما شعبك فبدلا من ذلك اطعمتهم طعام الملائكة وارسلت لهم من السماء خبزا معدا لا تعب فيه يتضمن كل لذة ويلائم كل ذوق"},{"n":21,"text":"لان جوهرك ابدى عذوبتك لبنيك فكان يخدم شهوة المتناول ويتحول الى ما شاء كل واحد"},{"n":22,"text":"وكان الثلج والجليد يثبتان في النار ولا يذوبان لكي يعلم كيف اكلت ثمار الاعداء نار تلتهب في البرد وتبرق في المطر"},{"n":23,"text":"اما عند هؤلاء فقد تناست القوة التي لها لكي يغتذي القديسون"},{"n":24,"text":"اذ الخليقة الخادمة لك انت صانعها تتشدد لتعاقب المجرمين وتتراخى لتحسن الى المتوكلين عليك"},{"n":25,"text":"لذلك كانت حينئذ تتحول الى كل شيء لتخدم نعمتك الغاذية الجميع على ما يشاء كل محتاج"},{"n":26,"text":"لكي يعلم بنوك الذين احببتهم ايها الرب ان ليس ما تخرج الارض من الثمار هو يغذو الانسان لكن كلمتك هي التي تحفظ المؤمنين بك"},{"n":27,"text":"اذ ما لم تكن النار تحله كانت شعاعة يسيرة من الشمس تحميه فيذوب"},{"n":28,"text":"حتى يعلم انه يجب ان نسبق الشمس الى شكرك ونحضر امامك عند شروق النور"},{"n":29,"text":"لان رجاء من لا شكر له يذوب كجليد شتوي ويذهب كماء لا منفعة فيه"}]},{"label":"سفر الحكمة 17","verses":[{"n":1,"text":"ان احكامك عظيمة لا يعبر عنها ولذلك ضلت النفوس التي لا تاديب لها"},{"n":2,"text":"فانه لما توهم المجرمون انهم يتسلطون على الامة القديسة اذا هم ملقون في اسر الظلمة وقيود الليل الطويل محبوسون تحت \nسقوفهم منفيون عن العناية الابدية"},{"n":3,"text":"واذ حسبوا انهم مستترون في خطاياهم الخفية فرق بينهم ستر النسيان المظلم وهم في رعب شديد تقلقهم الاخيلة"},{"n":4,"text":"ولم تكن الاكنة التي لبثوا فيها لتقيهم من الذعر فقد كانت اصوات قاصفة تدوي من حولهم واشباح مكفهرة تتراى امام \nوجوههم الكاسفة"},{"n":5,"text":"ولم يكن في قوة النار مهما اشتدت ان تاتي بضياء ولا في بريق النجوم ان ينير ذلك الليل المدلهم"},{"n":6,"text":"وانما كانت تلمع لهم بغتة نيران مخيفة فيرتعدون من ذلك المنظر المبهم ويتوهمون ما يظهر لهم اهول مما هو"},{"n":7,"text":"حينئذ بطلت صناعة السحر وشعوذته وبرز على افتخارهم بالحكمة حجة مخزية"},{"n":8,"text":"اذ الذين وعدوا بنفي الجزع والبلبال عن النفس الدنفة هؤلاء ادنفهم خوف مضحك"},{"n":9,"text":"فانهم وان لم يصبهم شيء هائل كان مرور الوحوش وفحيح الافاعي يدحرهم فيهلكون من الخوف ويتوقون حتى الهواء الذي لا محيد \nعنه"},{"n":10,"text":"لان الخبث ملازم للجبن فهو يقضي على نفسه بشهادته ولقلق الضمير لا يزال متخيلا الضربات"},{"n":11,"text":"فان الخوف انما هو ترك المدد الذي من العقل"},{"n":12,"text":"وانتظار المدد من الداخل اضعف ولذلك تحسب مجلبة العذاب المجهولة اشد"},{"n":13,"text":"فالذين ناموا تلك النومة في ذلك الليل الذي لا يطاق الوارد من اخادير الجحيم الفظيعة"},{"n":14,"text":"كانوا تارة تقتحمهم الاخيلة وتارة تنحل قواهم من انخلاع قلوبهم لما غشيهم من مفاجاة الخوف الغير المتوقع"},{"n":15,"text":"ثم حيثما سقط احد بقى محبوسا في سجن لا حديد فيه"},{"n":16,"text":"فان كان فلاحا او راعيا او صاحب عمل من اعمال الصحراء اخذ بغتة فوقع في قسر لا انفكاك عنه"},{"n":17,"text":"اذ جميعهم كانوا مقيدين بسلسلة واحدة من الظلام فدوي الريح واغاريد الطيور على الاغصان الملتفة وصوت المياه المندفعة \nبقوة"},{"n":18,"text":"وقعقعة الحجارة المتدحرجة وركض الحيوانات الذي لا يرى وزئير الوحوش الضارية والصدى المتردد في بطون الجبال كل ذلك \nكان يذيبهم من الخوف"},{"n":19,"text":"وبينما كان سائر العالم يضيئه نور ساطع ويتعاطى اعماله بغير مانع"},{"n":20,"text":"كان اولئك منفردين في ظل ليل مدلهم مشاكل لما سيغشاهم من الظلمة لكنهم كانوا على انفسهم اثقل من الظلمة"}]},{"label":"سفر الحكمة 18","verses":[{"n":1,"text":"اما قديسوك فكان عندهم نور عظيم وكان اولئك يسمعون اصواتهم بغير ان يبصروا اشخاصهم ويغبطونهم على انهم لا يقاسون مثل حالهم"},{"n":2,"text":"ويشكرونهم على انهم لا يؤذون الذين قد ظلموهم ويستغفرونهم من معاداتهم لهم"},{"n":3,"text":"وبازاء ذلك جعلت لهؤلاء عمود نار دليلا في طريق لم يعرفوه شمسا لتلك الضيافة الكريمة لا اذى بها"},{"n":4,"text":"اما اولئك فكان جديرا بهم ان يفقدوا النور ويحبسوا في الظلمة لانهم حبسوا بنيك الذين بهم سيمنح الدهر نور شريعتك \nالغير الفاني"},{"n":5,"text":"ولما ائتمروا ان يقتلوا اطفال القديسين وعرض واحد منهم لذلك ثم خلص عاقبتهم انت باهلاك جمهور اولادهم ثم دمرتهم جميعا \nفي الماء الغامر"},{"n":6,"text":"وتلك الليلة قد اخبر بها اباؤنا من قبل لكي تطيب نفوسهم لعلمهم اليقين ما الاقسام التي يثقون بها"},{"n":7,"text":"ففاز شعبك بخلاص الصديقين وهلاك الاعداء"},{"n":8,"text":"فان الذي عاقبت به المقاومين هو الذي جذبتنا به اليك ومجدتنا"},{"n":9,"text":"فان القديسين بني الصالحين كانوا يذبحون خفية ويوجبون على انفسهم شريعة الله هذه ان يشترك القديسون في السراء والضراء \nعلى السواء وكانوا يرنمون بتسابيح الاباء"},{"n":10,"text":"وقد رفع الاعداء جلبة اصواتهم بالبكاء والنحيب على اطفالهم"},{"n":11,"text":"وكان قضاء واحد على العبد والمولى وضربة واحدة نالت الشعب والملك"},{"n":12,"text":"وكان لكلهم اجمعين اموات لا يحصون قد ماتوا ميتة واحدة حتى ان الاحياء لم يكفوا لدفن الموتى اذ في لحظة ابيد نسلهم \nالاعز"},{"n":13,"text":"وبعد ان ابوا بسبب السحر ان يؤمنوا بشيء اعترفوا عند هلاك الابكار بان الشعب هو ابن لله"},{"n":14,"text":"وحين شمل كل شيء هدوء السكوت وانتصف مسير الليل"},{"n":15,"text":"هجمت كلمتك القديرة من السماء من العروش الملكية على ارض الخراب بمنزلة مبارز عنيف"},{"n":16,"text":"وسيف صارم يمضي قضاءك المحتوم فوقف وملا كل مكان قتلى وكان راسه في السماء وقدماه على الارض"},{"n":17,"text":"حينئذ بلبلتهم بغتة اخيلة الاحلام بلبلة شديدة وغشيتهم اهوال مفاجئة"},{"n":18,"text":"وكان كل واحد عند صرعه بين حي وميت يعلن لاي سبب يموت"},{"n":19,"text":"لان الاحلام التي اقلقتهم انباتهم بذلك لئلا يهلكوا وهم يجهلون مجلبة هلاكهم"},{"n":20,"text":"والصديقون ايضا مستهم محنة الموت ووقعت الضربة على جم منهم في البرية لكن الغضب لم يلبث طويلا"},{"n":21,"text":"لان رجلا لا عيب فيه بادر لحمايتهم فبرز بسلاح خدمته الذي هو الصلاة والتكفير بالبخور وقاوم الغضب وازال النازلة فتبين \nانه خادمك"},{"n":22,"text":"فانتصر على الجمع لا بقوة الجسد ولا باعمال السلاح ولكنه بالكلام كف المعاقب مذكرا الاقسام والعهود للاباء"},{"n":23,"text":"فانه اذ كان القتلى يتساقطون جماعات وقف في الوسط فحسم السخط وقطع المسلك الى الاحياء"},{"n":24,"text":"لانه كان على ثوبه السابغ العالم كله واسماء الاباء المجيدة منقوشة في اربعة اسطر من الحجارة الكريمة وعظمتك على تاج \nراسه"},{"n":25,"text":"فهذه خضع المهلك لها وهابها وكان مجرد اختبار الغضب قد كفى"}]},{"label":"سفر الحكمة 19","verses":[{"n":1,"text":"اما المنافقون فاستمر عليهم الى الانقضاء غضب لا رحمة معه لانه كان يعلم من قبل ماذا سيكون من امرهم"},{"n":2,"text":"وانهم بعد ترخيصهم لهم في الذهاب ومبادرتهم لاطلاقهم يندمون فيجدون في اثرهم"},{"n":3,"text":"فانهم قبل ان تنقضي مناحتهم وهم منتحبون على قبور امواتهم عادوا فاتخذوا مشورة جهل اخرى وسعوا في اثار الذين حثوهم \nعلى الرحيل سعيهم وراء قوم فارين"},{"n":4,"text":"وانما ساقهم الى هذا الاجل امر لا بد منه انساهم ما سبق من الحوادث لكي يستتموا ما بقي من الام عقابهم"},{"n":5,"text":"ويعبر شعبك اعجب عبور ويموت اولئك اغرب ميتة"},{"n":6,"text":"وكانت جميع الخلائق كل واحدة في جنسها تستبدل طبعها وتخدمك بحسب ما رسم لها لكي يحفظ بنوك بغير ضر"},{"n":7,"text":"فالغمام ظلل المحلة ومما كان قبلا يغمر بالمياه برزت ارض يابسة طريق ممهد في البحر الاحمر ومرج اخضر في قعر لجة \nعظيمة"},{"n":8,"text":"هناك عبرت الامة كلها وهم في ستر يدك يرون عجائب الايات"},{"n":9,"text":"ورتعوا كالخيل ووثبوا كالحملان مسبحين لك ايها الرب مخلصهم"},{"n":10,"text":"متذكرين ما وقع في غربتهم كيف اخرجت الارض الذباب بدلا من نتاج الحيوان وفاض النهر بجم من الضفادع عوض الاسماك"},{"n":11,"text":"واخيرا راوا صنفا جديدا من الطير حين حثتهم شهوتهم ان يتطلبوا طعاما لذيذا"},{"n":12,"text":"فصعدت السلوى من البحر تسلية لهم اما الخطاة فنزل عليهم الانتقام مع ما له من العلائم القديمة التي هي شدة الصواعق \nوانما اصابهم ما استحقت فواحشهم"},{"n":13,"text":"اذ كانت معاملتهم للاضياف اشد كراهية فان اولئك ابوا ان يقبلوا غرباء لم يعرفوهم اما هؤلاء فاستعبدوا اضيافا قد \nاحسنوا اليهم"},{"n":14,"text":"وفضلا عن ذلك فان عليهم افتقادا اخر اذ ان اولئك انما قبلوا قوما اجنبيين كرها"},{"n":15,"text":"اما هؤلاء فانهم قبلوا اضيافا باحتفال وفرح واشركوهم في حقوقهم ثم اساءوا اليهم بصنوف العذاب الشديد"},{"n":16,"text":"فضربوا بالعمى مثل اولئك الواقفين على باب الصديق الذين شملتهم ظلمة هائلة فجعل كل منهم يتلمس طالبا مدخل بابه"},{"n":17,"text":"اذ تغيرت نسب العناصر بعضها الى بعض كما يتغير في العود اسم صوت من اللحن والصوت باق وذلك بين لمن تامل تلك \nالحوادث"},{"n":18,"text":"فالارضيات تحولت الى مائيات والسابحات سعت على الارض"},{"n":19,"text":"والنار كانت لها قوة في الماء اشد من قوتها الغريزية والماء نسي قوته المطفئة"},{"n":20,"text":"وبالعكس اللهيب لم يؤذ جسم السريع الفاسد من الحيوان اذ كان يمشي فيه ولم يذب الطعام السماوي السريع الذوبان \nكالجليد لانك يا رب عظمت شعبك في كل شيء ومجدته ولم تهمله بل كنت مؤازرا له في كل زمان ومكان"}]}],"sources":["https://ar.wikisource.org/wiki/سفر_الحكمة"]},{"name":"يشوع بن سيراخ","chapters":[{"label":"سفر يشوع بن سيراخ 1","verses":[{"n":1,"text":"كل حكمة فهي من الرب ولا تزال معه الى الابد"},{"n":2,"text":"من يحصي رمل البحار وقطار المطر وايام الدهر ومن يمسح سمك السماء ورحب الارض والغمر"},{"n":3,"text":"ومن يستقصي الحكمة التي هي سابقة كل شيء"},{"n":4,"text":"قبل كل شيء حيزت الحكمة ومنذ الازل فهم الفطنة"},{"n":5,"text":"ينبوع الحكمة كلمة الله في العلى ومسالكها الوصايا الازلية"},{"n":6,"text":"لمن انكشف اصل الحكمة ومن علم دهائها"},{"n":7,"text":"لمن تجلب معرفة الحكمة ومن ادرك كثرة خبرتها"},{"n":8,"text":"واحد هو حكيم عظيم المهابة جالس على عرشه"},{"n":9,"text":"الرب هو حازها وراها واحصاها"},{"n":10,"text":"وافاضها على جميع مصنوعاته فهي مع كل ذي جسد على حسب عطيته وقد منحها لمحبيه"},{"n":11,"text":"مخافة الرب مجد وفخر وسرور واكليل ابتهاج"},{"n":12,"text":"مخافة الرب تلذ للقلب وتعطي السرور والفرح وطول الايام"},{"n":13,"text":"المتقي للرب يطيب نفسا في اواخره وينال حظوة يوم موته"},{"n":14,"text":"محبة الرب هي الحكمة المجيدة"},{"n":15,"text":"والذين تتراءى لهم يحبونها عند رؤيتهم لها وتاملهم لعظائمها"},{"n":16,"text":"راس الحكمة مخافة الله انها تولدت في الرحم مع المؤمنين وجعلت عشها بين الناس مدى الدهر وستسلم نفسها الى ذريتهم"},{"n":17,"text":"مخافة الرب هي عبادته عن معرفة"},{"n":18,"text":"العبادة تحفظ القلب وتبرره وتمنح السرور والفرح"},{"n":19,"text":"المتقي للرب يطيب نفسا وينال حظوة في يوم وفاته"},{"n":20,"text":"كمال الحكمة مخافة الرب انها تسكر بثمارها"},{"n":21,"text":"تملا كل بيتها رغائب ومخازنها غلالا"},{"n":22,"text":"اكليل الحكمة مخافة الرب انها تنشئ السلام والشفاء والعافية"},{"n":23,"text":"وقد رات الحكمة واحصتها وكلتاهما عطية من الله"},{"n":24,"text":"الحكمة تسكب المعرفة وعلم الفطنة وتعلي مجد الذين يملكونها"},{"n":25,"text":"اصل الحكمة مخافة الرب وفروعها طول الايام"},{"n":26,"text":"في زخائر الحكمة العقل والعبادة عن معرفة اما عند الخطاة فالحكمة رجس"},{"n":27,"text":"مخافة الرب تنفي الخطيئة"},{"n":28,"text":"غضب الاثيم لا يمكن ان يبرر لان وقر غضبه يسقطه"},{"n":29,"text":"الطويل الاناة يصبر الى حين ثم يعاوده السرور"},{"n":30,"text":"العاقل يكتم كلامه الى حين وشفاه المؤمنين تثني على عقله"},{"n":31,"text":"في زخائر الحكمة امثال المعرفة"},{"n":32,"text":"اما عند الخاطئ فعبادة الله رجس"},{"n":33,"text":"يا بني ان رغبت في الحكمة فاحفظ الوصايا فيهبها لك الرب"},{"n":34,"text":"فان الحكمة والتاديب هما مخافة الرب والذي يرضيه"},{"n":35,"text":"هو الايمان والوداعة فيغمر صاحبهما بالكنوز"},{"n":36,"text":"لا تعاص مخافة الرب ولا تتقدم اليه بقلب وقلب"},{"n":37,"text":"لا تكن مرائيا في وجوه الناس وكن محترسا لشفتيك"},{"n":38,"text":"لا تترفع لئلا تسقط فتجلب على نفسك الهوان"},{"n":39,"text":"ويكشف الرب خفاياك ويصرعك في المجمع"},{"n":40,"text":"لانك لم تتوجه الى مخافة الرب لكن قلبك مملوء مكرا"}]},{"label":"سفر يشوع بن سيراخ 2","verses":[{"n":1,"text":"يا بني ان اقبلت لخدمة الرب الاله فاثبت على البر والتقوى واعدد نفسك للتجربة"},{"n":2,"text":"ارشد قلبك واحتمل امل اذنك واقبل اقوال العقل ولا تعجل وقت النوائب"},{"n":3,"text":"انتظر بصبر ما تنتظره من الله لازمه ولا ترتدد لكي تزداد حياة في اواخرك"},{"n":4,"text":"مهما نابك فاقبله وكن صابرا على صروف اتضاعك"},{"n":5,"text":"فان الذهب يمحص في النار والمرضيين من الناس يمحصون في اتون الاتضاع"},{"n":6,"text":"امن به فينصرك قوم طرقك وامله احفظ مخافته وابق عليها في شيخوختك"},{"n":7,"text":"ايها المتقون للرب انتظروا رحمته ولا تحيدوا لئلا تسقطوا"},{"n":8,"text":"ايها المتقون للرب امنوا به فلا يضيع اجركم"},{"n":9,"text":"ايها المتقون للرب املوا الخيرات والسرور الابدي والرحمة"},{"n":10,"text":"ايها المتقون للرب احبوه فتستنير قلوبكم"},{"n":11,"text":"انظروا الى الاجيال القديمة وتاملوا هل توكل احد على الرب فخزي"},{"n":12,"text":"او ثبت على مخافته فخذل او دعاه فاهمل"},{"n":13,"text":"فان الرب رؤوف رحيم يغفر الخطايا ويخلص في يوم الضيق"},{"n":14,"text":"ويل للقلوب الهيابة وللايدي المتراخية وللخاطئ الذي يمشي في طريقين"},{"n":15,"text":"ويل للقلب المتواني انه لا يؤمن ولذلك لا حماية له"},{"n":16,"text":"ويل لكم ايها الذين فقدوا الصبر وتركوا الطرق المستقيمة ومالوا الى طرق السوء"},{"n":17,"text":"فماذا تصنعون يوم افتقاد الرب"},{"n":18,"text":"ان المتقين للرب لا يعاصون اقواله والمحبين له يحفظون طرقه"},{"n":19,"text":"ان المتقين للرب يبتغون مرضاته والمحبين له يمتلئون من الشريعة"},{"n":20,"text":"ان المتقين للرب يهيئون قلوبهم ويخضعون امامه نفوسهم"},{"n":21,"text":"ان المتقين للرب يحفظون وصاياه ويصبرون الى يوم افتقاده"},{"n":22,"text":"قائلين ان لم نتب نقع في يدي الرب لا في ايدي الناس"},{"n":23,"text":"لان رحمته على قدر عظمته"}]},{"label":"سفر يشوع بن سيراخ 3","verses":[{"n":1,"text":"بنو الحكمة جماعة الصديقين وذريتهم اهل الطاعة والمحبة"},{"n":2,"text":"يا بني اسمعوا اقوال ابيكم واعملوا بها لكي تخلصوا"},{"n":3,"text":"فان الرب قد اكرم الاب في الاولاد واثبت حكم الام في البنين"},{"n":4,"text":"من اكرم اباه فانه يكفر خطاياه ويمتنع عنها ويستجاب له في صلاة كل يوم"},{"n":5,"text":"ومن احترم امه فهو كمدخر الكنوز"},{"n":6,"text":"من اكرم اباه سر باولاده وفي يوم صلاته يستجاب له"},{"n":7,"text":"من احترم اباه طالت ايامه ومن اطاع اباه اراح امه"},{"n":8,"text":"الذي يتقي الرب يكرم ابويه ويخدم والديه بمنزلة سيدين له"},{"n":9,"text":"اكرم اباك بفعالك ومقالك بكل اناة"},{"n":10,"text":"لكي تحل عليك البركة منه وتبقى بركته الى المنتهى"},{"n":11,"text":"فان بركة الاب توطد بيوت البنين ولعنة الام تقلع اسسها"},{"n":12,"text":"لا تفتخر بهوان ابيك فان هوان ابيك ليس فخرا لك"},{"n":13,"text":"بل فخر الانسان بكرامة ابيه ومذلة الام عار للبنين"},{"n":14,"text":"يا بني اعن اباك في شيخوخته ولا تحزنه في حياته"},{"n":15,"text":"وان ضعف عقله فاعذر ولا تهنه وانت في وفور قوتك فان الرحمة للوالد لا تنسى"},{"n":16,"text":"وباحتمالك هفوات امك تجزى خيرا"},{"n":17,"text":"وعلى برك يبنى لك بيت وتذكر يوم ضيقك وكالجليد في الصحو تحل خطاياك"},{"n":18,"text":"من خذل اباه فهو بمنزلة المجدف ومن غاظ امه فهو ملعون من الرب"},{"n":19,"text":"يا بني اقض اعمالك بالوداعة فيحبك الانسان الصالح"},{"n":20,"text":"ازدد تواضعا ما ازددت عظمة فتنال حظوة لدى الرب"},{"n":21,"text":"لان قدرة الرب عظيمة وبالمتواضعين يمجد"},{"n":22,"text":"لا تطلب ما يعييك نيله ولا تبحث عما يتجاوز قدرتك لكن ما امرك الله به فيه تامل ولا ترغب في استقصاء اعماله الكثيرة"},{"n":23,"text":"فانه لا حاجة لك ان ترى المغيبات بعينيك"},{"n":24,"text":"وما جاوز اعمالك فلا تكثر الاهتمام به"},{"n":25,"text":"فانك قد اطلعت على اشياء كثيرة تفوق ادراك الانسان"},{"n":26,"text":"وان كثيرين قد اضلهم زعمهم وازل عقولهم وهمهم الفاسد"},{"n":27,"text":"القلب القاسي عاقبته السوء والذي يحب الخطر يسقط فيه"},{"n":28,"text":"القلب الساعي في طريقين لا ينجح والفاسد القلب يعثر فيهما"},{"n":29,"text":"القلب القاسي يثقل بالمشقات والخاطئ يزيد خطيئة على خطيئة"},{"n":30,"text":"داء المتكبر لا دواء له لان جرثومة الشر قد تاصلت فيه"},{"n":31,"text":"قلب العاقل يتامل في المثل ومنية الحكيم اذن سامعة"},{"n":32,"text":"القلب الحكيم العاقل يمتنع من الخطايا وينجح في اعمال البر"},{"n":33,"text":"الماء يطفئ النار الملتهبة والصدقة تكفر الخطايا"},{"n":34,"text":"من صنع جميلا ذكر في اواخره وصادف سندا في يوم سقوطه"}]},{"label":"سفر يشوع بن سيراخ 4","verses":[{"n":1,"text":"يا بني لا تحرم المسكين ما يعيش به ولا تماطل عيني المعوز"},{"n":2,"text":"لا تحزن النفس الجائعة ولا تغظ الرجل في فاقته"},{"n":3,"text":"لا تزد القلب المغيظ قلقا ولا تماطل المعوز بعطيتك"},{"n":4,"text":"لا تاب اعطاء البائس سؤله ولا تحول وجهك عن المسكين"},{"n":5,"text":"لا تصرف طرفك عن المعوز ولا تصنع شيئا يجلب عليك لعنة الانسان"},{"n":6,"text":"فان من يلعنك بمرارة نفسه يستجيب صانعه دعاءه"},{"n":7,"text":"كن متوددا الى الجماعة واخفض راسك لذي الوجاهة"},{"n":8,"text":"امل اذنك الى المسكين واجبه برفق ووداعة"},{"n":9,"text":"انقذ المظلوم من يد الظالم ولا تكن صغير النفس في القضاء"},{"n":10,"text":"كن ابا لليتامى وبمنزلة رجل لامهم"},{"n":11,"text":"فتكون كابن العلي وهو يحبك اكثر من امك"},{"n":12,"text":"الحكمة تنشئ لها بنين والذين يلتمسونها تضمهم اليها"},{"n":13,"text":"من احبها احب الحياة والذين يبتكرون اليها يمتلئون سرورا"},{"n":14,"text":"من ملكها يرث مجدا وحيثما دخلت فهناك بركة الرب"},{"n":15,"text":"الذين يعبدونها يخدمون القدوس والذين يحبونها يحبهم الرب"},{"n":16,"text":"من سمع لها يحكم على الامم ومن اقبل اليها يسكن مطمئنا"},{"n":17,"text":"اذا استسلم لها يرثها واعقابه يبقون على امتلاكها"},{"n":18,"text":"فانها في اول الامر تسلك معه بعوج"},{"n":19,"text":"فتلقي عليه الخوف والرعب وتمتحنه بتاديبها الى ان تثق بنفسه وتختبره في احكامها"},{"n":20,"text":"ثم تعود فتعامله باستقامة وتسره"},{"n":21,"text":"وتكشف له اسرارها وتجمع فيه كنوزا من العلم وفهم البر"},{"n":22,"text":"واما اذا ذهب في الضلال فهي تخذله وتسلمه الى مصرعه"},{"n":23,"text":"يا بني احرص على الزمان واحتفظ من الشر"},{"n":24,"text":"ولا تستحي في امر نفسك"},{"n":25,"text":"فان من الحياء ما يجلب الخطيئة ومنه ما هو مجد ونعمة"},{"n":26,"text":"لا تحاب الوجوه فذلك ضرر لنفسك"},{"n":27,"text":"ولا تستحي حياء به هلاكك"},{"n":28,"text":"لا تمتنع من الكلام في وقت الخلاص ولا تكتم حكمتك اذا جمل ابداؤها"},{"n":29,"text":"فانما تعرف الحكمة بالكلام والتاديب بنطق اللسان"},{"n":30,"text":"لا تخالف الحق بل استحي من جهالتك"},{"n":31,"text":"لا تستحي ان تعترف بخطاياك ولا تغالب مجرى النهر"},{"n":32,"text":"ولا تتذلل للرجل الاحمق ولا تحاب وجه المقتدر"},{"n":33,"text":"جاهد عن الحق الى الموت والرب الاله يقاتل عنك"},{"n":34,"text":"لا تكن جافيا في لسانك ولا كسلا متوانيا في اعمالك"},{"n":35,"text":"لا تكن كاسد في بيتك وكمجنون بين اهلك"},{"n":36,"text":"لا تكن يدك مبسوطة للاخذ مقبوضة عن العطاء"}]},{"label":"سفر يشوع بن سيراخ 5","verses":[{"n":1,"text":"لا تعتد باموالك ولا تقل لي بها كفاية"},{"n":2,"text":"لا تتبع هواك ولا قوتك لتسير في شهوات قلبك"},{"n":3,"text":"ولا تقل من يتسلط على فان الرب ينتقم منك انتقاما"},{"n":4,"text":"لا تقل قد خطئت فاي سوء اصابني فان الرب طويل الاناة"},{"n":5,"text":"لا تكن بلا خوف من قبل الخطيئة المغفورة لتزيد خطيئة على خطيئة"},{"n":6,"text":"ولا تقل رحمته عظيمة فيغفر كثرة خطاياي"},{"n":7,"text":"فان عنده الرحمة والغضب وسخطه يحل على الخطاة"},{"n":8,"text":"لا تؤخر التوبة الى الرب ولا تتباطا من يوم الى يوم"},{"n":9,"text":"فان غضب الرب ينزل بغتة ويستاصل في يوم الانتقام"},{"n":10,"text":"لا تعتد باموال الظلم فانها لا تنفعك شيئا في يوم الانتقام"},{"n":11,"text":"لا تنقلب مع كل ريح ولا تسر في كل طريق فانه كذلك يفعل الخاطئ ذو اللسانين"},{"n":12,"text":"بل كن ثابتا في فهمك وليكن كلامك واحدا"},{"n":13,"text":"كن سريعا في الاستماع وكثير التاني في احارة الجواب"},{"n":14,"text":"ان كان لك فهم فجاوب قريبك والا فاجعل يدك على فمك"},{"n":15,"text":"في الكلام كرامة وهوان ولسان الانسان تهلكته"},{"n":16,"text":"لا تدع نماما ولا تختل بلسانك"},{"n":17,"text":"فان للسارق الخزي ولذي اللسانين المذمة الشديدة"},{"n":18,"text":"لا تكن جاهلا في كبيرة ولا في صغيرة"}]},{"label":"سفر يشوع بن سيراخ 6","verses":[{"n":1,"text":"ولا تصر عدوا بعد ان كنت صديقا فان القبيح السمعة يرث الخزي والعار وكذلك الخاطئ ذو اللسانين"},{"n":2,"text":"لا تكن كثور مستكبرا بافكار قلبك لئلا تسلب نفسك"},{"n":3,"text":"فتاكل اوراقك وتتلف اثمارك وتترك نفسك كالخشب اليابس"},{"n":4,"text":"النفس الشريرة تهلك صاحبها وتجعله شماتة لاعدائه"},{"n":5,"text":"الفم العذب يكثر الاصدقاء واللسان اللطيف يكثر المؤانسات"},{"n":6,"text":"ليكن المسالمون لك كثيرين واصحاب سرك من الالف واحدا"},{"n":7,"text":"اذا اتخذت صديقا فاتخذه عن خبرة ولا تثق به سريعا"},{"n":8,"text":"فان لك صديقا في يومه ولكنه لا يثبت في يوم ضيقك"},{"n":9,"text":"وصديقا يصير عدوا فيكشف عار مخاصمتك"},{"n":10,"text":"وصديقا يشترك في مائدتك ولكنه لا يثبت في يوم ضيقك"},{"n":11,"text":"يكون نظيرك في اموالك ويتخذ دالة بين اهل بيتك"},{"n":12,"text":"لكنه اذا انحططت يكون ضدك ويتوارى عن وجهك"},{"n":13,"text":"تباعد عن اعدائك واحذر من اصدقائك"},{"n":14,"text":"الصديق الامين معقل حصين ومن وجده فقد وجد كنزا"},{"n":15,"text":"الصديق الامين لا يعادله شيء وصلاحه لا موازن له"},{"n":16,"text":"الصديق الامين دواء الحياة والذين يتقون الرب يجدونه"},{"n":17,"text":"من يتقي الرب يحصل على صداقة صالحة لان صديقه يكون نظيره"},{"n":18,"text":"يا بني اتخذ التاديب منذ شبابك فتجد الحكمة الى مشيبك"},{"n":19,"text":"مثل الحارث والزارع اقبل اليها وانتظر ثمارها الصالحة"},{"n":20,"text":"فانك تتعب في حراثتها قليلا وتاكل من غلاتها سريعا"},{"n":21,"text":"ما اصعبها على الغير المتادبين ان فاقد اللب لا يستمر عليها"},{"n":22,"text":"فانها له كحجر الامتحان الثقيل فلا يلبث ان يتركها"},{"n":23,"text":"لان الحكمة هي كاسمها ولا تستبين لكثيرين والذين يعرفونها تثبت فيهم الى مشاهدة الله"},{"n":24,"text":"اسمع يا بني واقبل رايي ولا تنبذ مشورتي"},{"n":25,"text":"وادخل رجليك في قيودها وعنقك في غلها"},{"n":26,"text":"احن عاتقك واحملها ولا تغتظ من سلاسلها"},{"n":27,"text":"اقبل اليها بكل نفسك واحفظ طرقها بكل قوتك"},{"n":28,"text":"ابحث واطلب فتتعرف لك واذا فزت بها فلا تهملها"},{"n":29,"text":"فانك في اواخرك تجد راحتها وتتحول لك مسرة"},{"n":30,"text":"فتكون لك قيودها حماية قوة واغلالها حلة مجد"},{"n":31,"text":"لان عليها حليا من ذهب وسلاسلها سلك سمنجوني"},{"n":32,"text":"فتلبسها حلة مجد لك وتعقدها اكليل ابتهاج"},{"n":33,"text":"ان شئت يا بني فانك تتادب وان استسلمت تستفيد دهاء"},{"n":34,"text":"ان احببت ان تسمع فانك تعي وان املت اذنك تصير حكيما"},{"n":35,"text":"قف في جماعة الشيوخ ومن كان حكيما فلازمه ارغب ان تسمع كل حديث الهي ولا تهمل امثال التعقل"},{"n":36,"text":"وان رايت عاقلا فابتكر اليه ولتطا قدمك درج بابه"},{"n":37,"text":"تروا في اوامر الرب وفي وصاياه تامل كل حين فهو يثبت قلبك وينيلك ما تتمناه من الحكمة"}]},{"label":"سفر يشوع بن سيراخ 7","verses":[{"n":1,"text":"لا تعمل الشر فلا يلحقك الشر"},{"n":2,"text":"تباعد عن الاثيم فيميل الاثيم عنك"},{"n":3,"text":"يا بني لا تزرع في خطوط الاثم لئلا تحصد ما زرعت سبعة اضعاف"},{"n":4,"text":"لا تلتمس من الرب رئاسة ولا من الملك كرسي مجد"},{"n":5,"text":"لا تدع البر امام الرب ولا الحكمة لدى الملك"},{"n":6,"text":"لا تبتغ ان تصير قاضيا لعلك لا تستطيع ان تستاصل الظلم فربما هبت وجه المقتدر فتضع في طريق استقامتك حجر عثار"},{"n":7,"text":"لا تخطا الى جماعة المدينة ولا تطرح نفسك بين الجمهور"},{"n":8,"text":"لا تعد الى الخطيئة ثانية فانك لا تكون مزكى من الاولى"},{"n":9,"text":"لا تكن صغير النفس في صلاتك"},{"n":10,"text":"ولا تهمل الصدقة"},{"n":11,"text":"لا تقل ان الله ينظر الى كثرة تقادمي واذا قربتها للعلي فهو يقبلها"},{"n":12,"text":"لا تستهزئ باحد في مرارة نفسه فانه يوجد من يخفض ويرفع"},{"n":13,"text":"لا تفتر الكذب على اخيك ولا تختلقه على صديقك"},{"n":14,"text":"لا تبتغ ان تكذب بشيء فان تعود الكذب ليس للخير"},{"n":15,"text":"لا تكثر الكلام في جماعة الشيوخ ولا تكرر الالفاظ في صلاتك"},{"n":16,"text":"لا تكره الشغل المتعب ولا الحراثة التي سنها العلي"},{"n":17,"text":"لا تنظم نفسك في عداد الخاطئين"},{"n":18,"text":"اذكر ان الغضب لا يبطئ"},{"n":19,"text":"ضع نفسك جدا لان عقاب المنافق نار ودود"},{"n":20,"text":"لا تبدل صديقا بشيء زمني ولا اخا خالصا بذهب اوفير"},{"n":21,"text":"لا تفارق امراتك اذا كانت حكيمة صالحة فان نعمتها فوق الذهب"},{"n":22,"text":"لا تعنت عبدا يجد في عمله ولا اجيرا يبذل نفسه"},{"n":23,"text":"لتحبب نفسك العبد العاقل ولا تمنعه العتق"},{"n":24,"text":"ان كانت لك دواب فتعهدها وان كان لك منها نفع فابقها عندك"},{"n":25,"text":"ان كان لك بنون فادبهم واخضع رقابهم من صبائهم"},{"n":26,"text":"ان كانت لك بنات فصن اجسامهن ولا يكن وجهك اليهن كثير الطلاقة"},{"n":27,"text":"زوج بنتك تقض امرا عظيما وسلمها الى رجل عاقل"},{"n":28,"text":"ان كانت لك امراة على وفق قلبك فلا ترفضها اما المكروهة فلا تسلم اليها نفسك"},{"n":29,"text":"اكرم اباك بكل قلبك ولا تنس مخاض امك"},{"n":30,"text":"اذكر انك بهما كونت فماذا تجزيهما مكافاة عما جعلا لك"},{"n":31,"text":"اخش الرب بكل نفسك واحترم كهنته"},{"n":32,"text":"احبب صانعك بكل قوتك ولا تهمل خدامه"},{"n":33,"text":"اتق الرب واكرم الكاهن"},{"n":34,"text":"واعطه حصته بحسب ما امرت به والباكورة لاجل الخطاء"},{"n":35,"text":"وعطية الاكتاف وذبيحة التقديس وباكورة الاقداس"},{"n":36,"text":"وابسط يدك للفقير لكي تكمل بركتك"},{"n":37,"text":"كن عارفا للجميل من كل حي ولا تنكر على الميت جميله"},{"n":38,"text":"لا تتوار عن الباكين ونح مع النائحين"},{"n":39,"text":"لا تتقاعد عن عيادة المرضى فانك بمثل ذلك تكون محبوبا"},{"n":40,"text":"في جميع اعمالك اذكر اواخرك فلن تخطا الى الابد"}]},{"label":"سفر يشوع بن سيراخ 8","verses":[{"n":1,"text":"لا تخاصم المقتدر لئلا تقع في يديه"},{"n":2,"text":"لا تنازع الغني لئلا يجعل عليك ثقلا"},{"n":3,"text":"فان الذهب اهلك كثيرين وازاغ قلوب الملوك"},{"n":4,"text":"لا تخاصم الفتيق اللسان ولا تجمع على ناره حطبا"},{"n":5,"text":"لا تمازح الناقص الادب لئلا يهين اسلافك"},{"n":6,"text":"لا تعير المرتد عن الخطيئة اذكر انا باجمعنا نستوجب المؤاخذة"},{"n":7,"text":"لا تهن احدا في شيخوخته فان الذين يشيخون هم منا"},{"n":8,"text":"لا تشمت بموت احد اذكر انا باجمعنا نموت"},{"n":9,"text":"لا تستخف بكلام الحكماء بل كن لهجا بامثالهم"},{"n":10,"text":"فانك منهم تتعلم التاديب والخدمة للعظماء"},{"n":11,"text":"لا تهمل كلام الشيوخ فانهم تعلموا من ابائهم"},{"n":12,"text":"ومنهم تتعلم الحكمة وان ترد الجواب في وقت الحاجة"},{"n":13,"text":"لا توقد جمر الخاطئ لئلا تحترق بنار لهيبه"},{"n":14,"text":"لا تنتصب في وجه الشاتم لئلا يترصد لفمك في الكمين"},{"n":15,"text":"لا تقرض من هو اقوى منك فان اقرضته شيئا فاحسب انك قد اضعته"},{"n":16,"text":"لا تكفل ما هو فوق طاقتك فان كفلت فاهتم اهتمام من يفي"},{"n":17,"text":"لا تحاكم القاضي لانه يحكم له بحسب رايه"},{"n":18,"text":"لا تسر في الطريق مع المتقحم لئلا يجلب عليك وبالا فانه يسعى في هوى نفسه فتهلك انت بجهله"},{"n":19,"text":"لا تشاجر الغضوب ولا تسر معه في الخلاء فان الدم عنده كلا شيء فيصرعك حيث لا ناصر لك"},{"n":20,"text":"لا تشاور الاحمق فانه لا يستطيع كتمان الكلام"},{"n":21,"text":"لا تباشر امرا سريا امام الاجنبي فانك لا تعلم ما سيبدو منه"},{"n":22,"text":"لا تكشف ما في قلبك لكل انسان فعساه لا يجزيك شكرا"}]},{"label":"سفر يشوع بن سيراخ 9","verses":[{"n":1,"text":"لا تغر على المراة التي في حجرك ولا تعلم عليك تعليما سيئا"},{"n":2,"text":"لا تسلم نفسك الى المراة لئلا تتسلط على قدرتك"},{"n":3,"text":"لا تلق المراة البغي لئلا تقع في اشراكها"},{"n":4,"text":"لا تالف المغنية لئلا تصطاد بفنونها"},{"n":5,"text":"لا تتفرس في العذراء لئلا تعثرك محاسنها"},{"n":6,"text":"لا تسلم نفسك الى الزواني لئلا تتلف ميراثك"},{"n":7,"text":"لا تسرح بصرك في ازقة المدينة ولا تتجول في اخليتها"},{"n":8,"text":"اصرف طرفك عن المراة الجميلة ولا تتفرس في حسن الغريبة"},{"n":9,"text":"فان حسن المراة اغوى كثيرين وبه يتلهب العشق كالنار"},{"n":10,"text":"كل امراة زانية تداس كالزبل في الطريق"},{"n":11,"text":"كثيرون افتتنوا بجمال المراة الغريبة فكان حظهم الرذل لان محادثتها تتلهب كالنار"},{"n":12,"text":"لا تجالس ذات البعل البتة ولا تتكئ معها على المرفق"},{"n":13,"text":"ولا تكن لها منادما على الخمر لئلا تميل نفسك اليها وتزل بقلبك الى الهلاك"},{"n":14,"text":"لا تقاطع صديقك القديم فان الحديث لا يماثله"},{"n":15,"text":"الصديق الحديث خمر جديدة اذا عتقت لذ لك شربها"},{"n":16,"text":"لا تغر من مجد الخاطئ فانك لا تعلم كيف يكون انقلابه"},{"n":17,"text":"لا ترتض بمرضاة المنافقين اذكر انهم الى الجحيم لا يتزكون"},{"n":18,"text":"تباعد عمن له سلطان على القتل فلا تجري في خاطرك مخافة الموت"},{"n":19,"text":"وان دنوت منه فلا تجرم لئلا يذهب بحياتك"},{"n":20,"text":"اعلم انك تتخطى بين الفخاخ وتتمشى على متارس المدن"},{"n":21,"text":"اختبر الناس ما استطعت وشاور الحكماء منهم"},{"n":22,"text":"ليكن مؤاكلوك من الابرار وافتخارك بمخافة الرب"},{"n":23,"text":"اجعل عشرتك مع العقلاء وكل حديثك في شريعة العلي"},{"n":24,"text":"يثنى على عمل الصناع لاجل ايديهم اما رئيس الشعب فانه حكيم لاجل كلامه"},{"n":25,"text":"الفتيق اللسان يخاف منه في مدينته والهاذر في كلامه يمقت"}]},{"label":"سفر يشوع بن سيراخ 10","verses":[{"n":1,"text":"القاضي الحكيم يؤدب شعبه وتدبير العاقل يكون مرتبا"},{"n":2,"text":"كما يكون قاضي الشعب يكون الخادمون له وكما يكون رئيس المدينة يكون جميع سكانها"},{"n":3,"text":"الملك الفاقد التاديب يدمر شعبه والمدينة تعمر بعقل ولاتها"},{"n":4,"text":"ملك الارض في يد الرب فهو يقيم عليها في الاوان اللائق من به نفعها"},{"n":5,"text":"فوز الرجل في يد الرب وعلى وجه الكاتب يجعل مجده"},{"n":6,"text":"اذا ظلمك القريب في شيء فلا تحنق عليه ولا تات شيئا من امور الشتم"},{"n":7,"text":"الكبرياء ممقوتة عند الرب والناس وشانها ارتكاب الاثم امام الفريقين"},{"n":8,"text":"انما ينقل الملك من امة الى امة لاجل المظالم والشتائم والاموال"},{"n":9,"text":"لا احد اقبح جرما من البخيل لماذا يتكبر التراب والرماد"},{"n":10,"text":"لا احد اكبر اثما ممن يحب المال لان ذاك يجعل نفسه ايضا سلعة وقد اطرح احشاءه مدة حياته"},{"n":11,"text":"كل سلطان قصير البقاء ان المرض الطويل يثقل على الطبيب"},{"n":12,"text":"فيحسم الطبيب المرض قبل ان يطول هكذا الملك يتسلط اليوم وفي غد يموت"},{"n":13,"text":"والانسان عند مماته يرث الافاعي والوحوش والدود"},{"n":14,"text":"اول كبرياء الانسان ارتداده عن الرب"},{"n":15,"text":"اذ يرجع قلبه عن صانعه فالكبرياء اول الخطاء ومن رسخت فيه فاض ارجاسا"},{"n":16,"text":"ولذلك انزل الرب باصحابها نوازل غريبة ودمرهم عن اخرهم"},{"n":17,"text":"نقض الرب عروش السلاطين واجلس الودعاء مكانهم"},{"n":18,"text":"قلع الرب اصول الامم وغرس المتواضعين مكانهم"},{"n":19,"text":"قلب الرب بلدان الامم وابادها الى اسس الارض"},{"n":20,"text":"اقحل بعضها واباد سكانها وازال من الارض ذكرهم"},{"n":21,"text":"محا الرب ذكر المتكبرين وابقى ذكر المتواضعين بالروح"},{"n":22,"text":"لم تخلق الكبرياء مع الناس ولا الغضب مع مواليد النساء"},{"n":23,"text":"اي نسل هو الكريم نسل الانسان اي نسل هو الكريم المتقون للرب اي نسل هو اللئيم نسل الانسان اي نسل هو اللئيم \nالمتعدون الوصايا"},{"n":24,"text":"فيما بين الاخوة يكون رئيسهم مكرما هكذا في عيني الرب الذين يتقونه"},{"n":25,"text":"الغني والمجيد والفقير فخرهم مخافة الرب"},{"n":26,"text":"ليس من الحق ان يهان الفقير العاقل ولا من اللائق ان يكرم الرجل الخاطئ"},{"n":27,"text":"العظيم والقاضي والمقتدر يكرمون وليس احد منهم اعظم ممن يتقي الرب"},{"n":28,"text":"العبد الحكيم يخدمه الاحرار والرجل العاقل لا يتذمر"},{"n":29,"text":"لا تعتل عن الاشتغال بالاعمال ولا تنتفخ في وقت الاعسار"},{"n":30,"text":"فان الذي يشتغل بكل عمل خير ممن يتمشى او ينتفخ وهو في فاقة الى الخبز"},{"n":31,"text":"يا بني مجد نفسك بالوداعة واعط لها من الكرامة ما تستحق"},{"n":32,"text":"من خطئ الى نفسه فمن يزكيه ومن يكرم الذي يهين حياته"},{"n":33,"text":"الفقير يكرم من اجل عمله والغني يكرم لاجل غناه"},{"n":34,"text":"من اكرم مع الفقر فكيف مع الغنى ومن اهين مع الغنى فكيف مع الفقر"}]},{"label":"سفر يشوع بن سيراخ 11","verses":[{"n":1,"text":"حكمة الوضيع ترفع راسه وتجلسه في جماعة العظماء"},{"n":2,"text":"لا تمدح الرجل لجماله ولا تذم الانسان لمنظره"},{"n":3,"text":"النحل صغير في الطيور وجناه راس كل حلاوة"},{"n":4,"text":"لا تفتخر بتردي الثياب ولا تترفع في يوم الكرامة فان اعمال الرب عجيبة وافعاله خفية عن البشر"},{"n":5,"text":"كثيرون من المتسلطين جلسوا على التراب والخامل الذكر لبس التاج"},{"n":6,"text":"كثيرون من المقتدرين لحقهم اشد الهوان والمكرمون سلموا الى ايدي الاخرين"},{"n":7,"text":"لا تذم قبل ان تفحص تفهم اولا ثم وبخ"},{"n":8,"text":"لا تجاوب قبل ان تسمع ولا تعترض حديث احد قبل تمامه"},{"n":9,"text":"لا تجادل في امر لا يعنيك ولا تجلس للقضاء مع الخطاة"},{"n":10,"text":"يا بني لا تتشاغل باعمال كثيرة فانك ان اكثرت منها لم تخل من ملام ان تتبعتها لم تحشها وان سبقتها لم تنج"},{"n":11,"text":"رب انسان ينصب ويتعب ويجد ولا يزداد الا فاقة"},{"n":12,"text":"ورب انسان بليد فاقد المدد قليل القوة كثير الفقر"},{"n":13,"text":"نظرت اليه عينا الرب بالخير فنعشه من ضعته ورفع راسه فتعجب منه كثيرون"},{"n":14,"text":"الخير والشر الحياة والموت الفقر والغنى من عند الرب"},{"n":15,"text":"الحكمة والعلم ومعرفة الشريعة من عند الرب المحبة وطرق الاعمال الصالحة من عنده"},{"n":16,"text":"الضلال والظلمة خلقا مع الخطاة والذين يرتاحون الى الشر في الشر يشيخون"},{"n":17,"text":"عطية الرب تدوم للاتقياء ومرضاته تفوز الى الابد"},{"n":18,"text":"رب غني استغنى باهتمامه وامساكه وانما حظه من اجرته"},{"n":19,"text":"ان يقول قد بلغت الراحة وانا الان اكل من خيراتي"},{"n":20,"text":"وهو لا يعلم كم يمضي من الزمان حتى يترك ذلك لغيره ويموت"},{"n":21,"text":"اقم على عهدك وثابر عليه وشخ في عملك"},{"n":22,"text":"لا تعجب من اعمال الخطاة امن بالرب وابق على جهدك"},{"n":23,"text":"فانه هين في عيني الرب ان يغني المسكين في الحال بغتة"},{"n":24,"text":"بركة الرب في اجرة التقي وهو في لحظة يجعل بركته مزهرة"},{"n":25,"text":"لا تقل اي حاجة لي واي خير يحصل لي منذ الان"},{"n":26,"text":"لا تقل لي ما يكفيني فلم اتعنى منذ الان"},{"n":27,"text":"ان البؤوس تنسى في يوم النعم والنعم لا تذكر في يوم البؤوس"},{"n":28,"text":"فانه هين عند الرب ان يجازي الانسان بحسب طرقه يوم الموت"},{"n":29,"text":"شر ساعة ينسي اللذات وفي وفاة الانسان انكشاف اعماله"},{"n":30,"text":"لا تغبط احدا قبل موته ان الرجل يعرف ببنيه"},{"n":31,"text":"لا تدخل كل انسان الى بيتك فان مكايد الغشاش كثيرة"},{"n":32,"text":"كصفة الحجل الصياد في القفص صفة قلب المتكبر وهو كراصد يرقب السقوط"},{"n":33,"text":"فانه يكمن محولا الخير الى الشر ويصم المختارين بالنقائص"},{"n":34,"text":"من شرارة واحدة يكثر الحريق والرجل الخاطئ يكمن للدم"},{"n":35,"text":"احذر من الخبيث الذي يخترع المساوئ لئلا يجلب عليك عارا الى الابد"},{"n":36,"text":"ادخل الاجنبي الى بيتك فيقلب احوالك بالمشاغب ويطردك عن خاصتك"}]},{"label":"سفر يشوع بن سيراخ 12","verses":[{"n":1,"text":"اذا احسنت فاعلم الى من تحسن فيكون معروفك مرضيا"},{"n":2,"text":"احسن الى التقي فتنال جزاء ان لم يكن من عنده فمن عند العلي"},{"n":3,"text":"لا خير لمن يواظب على الشر ولا يتصدق لان العلي يمقت الخطاة ويرحم التائبين"},{"n":4,"text":"اعط التقي ولا تمد الخاطئ فانه سينتقم من المنافقين والخطاة لكنه يحفظهم ليوم الانتقام"},{"n":5,"text":"اعط الصالح ولا تؤاس الخاطئ"},{"n":6,"text":"احسن الى المتواضع ولا تعط المنافق امنع خبزك ولا تعطه له لئلا يتقوى به عليك"},{"n":7,"text":"فتصادف من الشر اضعاف كل ما كنت تصنع اليه من المعروف ان العلي يمقت الخطاة ويكافئ المنافقين بالانتقام"},{"n":8,"text":"لا يعرف الصديق في السراء ولا يخفى العدو في الضراء"},{"n":9,"text":"في سراء الرجل اعداؤه محزونون وفي ضرائه الصديق ايضا ينصرف"},{"n":10,"text":"لا تثق بعدوك ابدا فان خبثه كصدا النحاس"},{"n":11,"text":"وان كان متواضعا يمشي مطرقا فتنبه لنفسك وتحرز منه فانك تكون معه كمن جلا مراة وستعلم ان نقاءها من الصدا لا يدوم"},{"n":12,"text":"لا تجعله قريبا منك لئلا يقلبك ويقيم في مكانك لا تجلسه عن يمينك لئلا يطمع في كرسيك واخيرا تفهم كلامي وتنخس باقوالي"},{"n":13,"text":"من يرحم راقيا قد لدغته الحية او يشفق على الذين يدنون من الوحوش هكذا الذي يساير الرجل الخاطئ يمتزج بخطاياه"},{"n":14,"text":"انه يلبث معك ساعة وان ملت لا يثبت"},{"n":15,"text":"العدو يظهر حلاوة من شفتيه وفي قلبه ياتمر ان يسقطك في الحفرة"},{"n":16,"text":"العدو تدمع عيناه وان صادف فرصة يشبع من الدم"},{"n":17,"text":"ان صادفك شر وجدته هناك قد سبقك"},{"n":18,"text":"وفيما يوهمك انه معين لك يعقل رجلك"},{"n":19,"text":"يهز راسه ويصفق بيديه ويهمس باشياء كثيرة ويغير وجهه"}]},{"label":"سفر يشوع بن سيراخ 13","verses":[{"n":1,"text":"من لمس القير توسخ ومن قارن المتكبر اشبهه"},{"n":2,"text":"لا ترفع ثقلا يفوق طاقتك ولا تقارن من هو اقوى واغنى منك"},{"n":3,"text":"كيف يقرن بين قدر الخزف والمرجل انها اذا صدمت تنكسر"},{"n":4,"text":"الغني يظلم ويصخب والفقير يظلم ويتضرع"},{"n":5,"text":"ان كنت نافعا استغلك وان كنت عقيما خذلك"},{"n":6,"text":"ان كان لك مال عاشرك واستنفذ مالك وهو لا يتعب"},{"n":7,"text":"ان كان له بك حاجة غرك وتبسم اليك ووعدك وكلمك بالخير وقال ما حاجتك"},{"n":8,"text":"وقدم لك من الاطعمة ما يخجلك حتى يستنفذ ما لك في مرتين او ثلاث واخيرا يستهزئ بك ويراك بعد ذلك فيخذلك وينغض راسه \nعليك"},{"n":9,"text":"اخشع لله وانتظر يده"},{"n":10,"text":"احذر ان تغتر وتتذلل في جهالتك"},{"n":11,"text":"لا تكن ذليلا في حكمتك لئلا يستدرجك الذل الى الجهالة"},{"n":12,"text":"اذا دعاك مقتدر فتوار فبذلك يزيد في دعوته لك"},{"n":13,"text":"لا تقتحم لئلا تطرد ولا تقف بعيدا لئلا تنسى"},{"n":14,"text":"لا تقدم على محادثته ولا تثق بكلامه الكثير فانه بكثرة مخاطبته يختبرك وبتبسمه اليك يفحصك"},{"n":15,"text":"انه بلا رحمة لا ينجز ما وعد ولا يمسك عن الاساءة والقيود"},{"n":16,"text":"احترز وتنبه جدا فانك على شفا السقوط"},{"n":17,"text":"وان سمعت بهذه في منامك فتيقظ"},{"n":18,"text":"في حياتك كلها احبب الرب وادعه لخلاصك"},{"n":19,"text":"كل حيوان يحب نظيره وكل انسان يحب قريبه"},{"n":20,"text":"كل ذي جسد يصاحب نوعه والرجل يلازم نظيره"},{"n":21,"text":"ايقارن الذئب الحمل كذلك شان الخاطئ مع التقي"},{"n":22,"text":"اي سلام بين الضبع والكلب واي سلام بين الغني والفقير"},{"n":23,"text":"الفراء في البرية صيد الاسود وكذلك الفقراء هم مراعي الاغنياء"},{"n":24,"text":"التواضع رجس عند المتكبر وهكذا الفقير رجس عند الغني"},{"n":25,"text":"الغني اذا تزعزع يثبته اصدقاؤه والمتواضع اذا سقط فاصدقاؤه يطردونه"},{"n":26,"text":"يزل الغني فيعينه كثيرون يتكلم بالمنكرات فيبرئونه"},{"n":27,"text":"يزل المتواضع فيوبخونه ينطق بعقل فلا يجعلون لكلامه موضعا"},{"n":28,"text":"يتكلم الغني فينصت الجميع ويرفعون مقالته الى السحاب"},{"n":29,"text":"يتكلم الفقير فيقولون من هذا وان عثر يصرعونه"},{"n":30,"text":"الغنى يحسن بمن لا خطية له والفقر مستقبح في فم المنافق"},{"n":31,"text":"قلب الانسان يغير وجهه اما الى الخير واما الى الشر"},{"n":32,"text":"طلاقة الوجه من طيب القلب والبحث عن الامثال يجهد الافكار"}]},{"label":"سفر يشوع بن سيراخ 14","verses":[{"n":1,"text":"طوبى للرجل الذي لم يزل بفيه ولم ينخسه الندم على الخطيئة"},{"n":2,"text":"طوبى لمن لم يقض عليه ضميره ولم يسقط من رجائه"},{"n":3,"text":"الغنى لا يجمل بالرجل الشحيح وما منفعة الاموال مع الانسان الحسود"},{"n":4,"text":"من اختزن بخسران نفسه فانما يختزن للاخرين ويتنعم بخيراته غيره"},{"n":5,"text":"من اساء الى نفسه فالى من يحسن الم تره لا يتمتع من امواله"},{"n":6,"text":"لا اسوا ممن يحسد نفسه ان ذلك جزاء خبثه"},{"n":7,"text":"وان هو احسن فعن سهو وفي الاخر يبدي خبثه"},{"n":8,"text":"لا اخبث ممن يحسد بعينه ويحول وجهه ويحتقر النفوس"},{"n":9,"text":"عين البخيل لا تشبع من حظه وظلم الشرير يضني نفسه"},{"n":10,"text":"العين الشريرة تحسد على الخبز وعلى مائدتها تكون في عوز"},{"n":11,"text":"يا بني انفق على نفسك بحسب ما تملك وقرب للرب تقادم تليق به"},{"n":12,"text":"اذكر ان الموت لا يبطئ الم يبلغك عهد الجحيم"},{"n":13,"text":"قبل ان تموت احسن الى صديقك وعلى قدر طاقتك ابسط يدك واعطه"},{"n":14,"text":"لا تخسر يوما صالحا ولا يفتك حظ خير شهي"},{"n":15,"text":"الست مخلفا اتعابك لاخر وما جهدت فيه للاقتسام بالقرعة"},{"n":16,"text":"اعط وخذ وزك نفسك"},{"n":17,"text":"قبل وفاتك اصنع البر فانه لا سبيل الى التماس الطعام في الجحيم"},{"n":18,"text":"كل جسد يبلى مثل الثوب لان العهد من البدء انه يموت موتا فكما ان اوراق شجرة كثيفة"},{"n":19,"text":"بعضها يسقط وبعضها ينبت كذلك جيل اللحم والدم بعضهم يموت وبعضهم يولد"},{"n":20,"text":"كل عمل فاسد يزول وعامله يذهب معه"},{"n":21,"text":"وكل عمل منتقى يبرر وعامله يكرم لاجله"},{"n":22,"text":"طوبى للرجل الذي يتامل في الحكمة ويتحدث بها في عقله"},{"n":23,"text":"ويتفكر في طرقها بقلبه ويتبصر في اسرارها ينطلق في اثرها كالباحث ويترقب عند مداخلها"},{"n":24,"text":"ويتطلع من كواتها ويتسمع عند ابوابها"},{"n":25,"text":"ويحل بقرب بيتها ويضرب وتدا في حائطها وينصب خيمته بجانبها وينزل بمنزل الخيرات"},{"n":26,"text":"يجعل بنيه في كنفها ويسكن تحت اغصانها"},{"n":27,"text":"يستتر بظلها من الحر وفي مجدها يجد راحة"}]},{"label":"سفر يشوع بن سيراخ 15","verses":[{"n":1,"text":"الذي يتقي الرب يعمل ذلك والذي يتمسك بالشريعة ينال الحكمة"},{"n":2,"text":"تبادر اليه كام وتتخذه كامراة بكر"},{"n":3,"text":"تطعمه خبز العقل وتسقيه ماء الحكمة فيها يترسخ فلا يتزعزع"},{"n":4,"text":"وعليها يعتمد فلا يخزى فترفع مقامه عند اصحابه"},{"n":5,"text":"وتفتح فاه في الجماعة وتملاه من روح الحكمة والعقل وتلبسه حلة المجد"},{"n":6,"text":"فيرث السرور واكليل الابتهاج واسما ابديا"},{"n":7,"text":"الجهال من الناس لا يدركونها اما العقلاء فيبادرون اليها والخطاة لا يرونها لانها بعيدة عن الكبرياء والمكر"},{"n":8,"text":"الكذابون من الناس لا يذكرونها اما الصادقون فيوجدون فيها ويفلحون الى ان يشاهدوا الله"},{"n":9,"text":"لا يجمل الحمد في فم الخاطئ"},{"n":10,"text":"لان الخاطئ لم يرسله الرب انما ينطق بالحمد ذو الحكمة والرب ينجحه"},{"n":11,"text":"لا تقل انما ابتعادي عنها من الرب بل امتنع عن عمل ما يبغضه"},{"n":12,"text":"لا تقل هو اضلني فانه لا حاجة له في الرجل الخاطئ"},{"n":13,"text":"كل رجس مبغض عند الرب وليس بمحبوب عند الذين يتقونه"},{"n":14,"text":"هو صنع الانسان في البدء وتركه في يد اختياره"},{"n":15,"text":"واضاف الى ذلك وصاياه واوامره"},{"n":16,"text":"فان شئت حفظت الوصايا ووفيت مرضاته"},{"n":17,"text":"وعرض لك النار والماء فتمد يدك الى ما شئت"},{"n":18,"text":"الحياة والموت امام الانسان فما اعجبه يعطى له"},{"n":19,"text":"ان حكمة الرب عظيمة هو شديد القدرة ويرى كل شيء"},{"n":20,"text":"وعيناه الى الذين يتقونه ويعلم كل اعمال الانسان"},{"n":21,"text":"لم يوص احدا ان ينافق ولا اذن لاحد ان يخطئ"},{"n":22,"text":"لانه لا يحب كثرة البنين الكفرة الذين لا خير فيهم"}]},{"label":"سفر يشوع بن سيراخ 16","verses":[{"n":1,"text":"لا تشته كثرة اولاد لا خير فيهم ولا تفرح بالبنين المنافقين ولا تسر بكثرتهم اذا لم تكن فيهم مخافة الرب"},{"n":2,"text":"لا تثق بحياتهم وتلتفت الى مكانهم"},{"n":3,"text":"ولد واحد يتقي الرب خير من الف منافقين"},{"n":4,"text":"والموت بلا ولد خير من الاولاد المنافقين"},{"n":5,"text":"لانه بعاقل واحد تعمر المدينة وقبيلة من الاثماء تخرب"},{"n":6,"text":"كثير من امثال هذه رايته بعيني واعظم منها سمعت به اذني"},{"n":7,"text":"في مجمع الخطاة تتقد النار وفي الامة الكافرة يضطرم الغضب"},{"n":8,"text":"لم يعف عن الجبابرة الاولين الذين تمردوا بقوتهم"},{"n":9,"text":"ولم يشفق على جيل لوط الذين مقتهم لكبريائهم"},{"n":10,"text":"ولم يرحم امة الهلاك المتعظمين بخطاياهم"},{"n":11,"text":"وكذلك الست مئة الف من الرجالة الذين تعصبوا بقساوة قلوبهم بل لو وجد واحد قاسي الرقبة لكان من العجب ان يصفح عنه"},{"n":12,"text":"لان الرحمة والغضب من عنده هو رب العفو وساكب الغضب"},{"n":13,"text":"كما انه كثير الرحمة هكذا هو شديد العقاب فيقضي على الرجل بحسب اعماله"},{"n":14,"text":"لا يفلت الخاطئ بغنائمه ولا يضيع الرب صبر التقي"},{"n":15,"text":"لكل رحمة يجعل موضعا وكل واحد يلقى ما تستحق اعماله"},{"n":16,"text":"لا تقل ساتوارى عن الرب العل احدا من العلى يذكرني"},{"n":17,"text":"اني في شعب كثير لا اذكر فماذا تعتبر نفسي في خلق لا يقدر"},{"n":18,"text":"ها ان السماء وسماء سماء الله والغمر والارض تتزعزع عند افتقاده"},{"n":19,"text":"والجبال واسس الارض ترتعد رعبا عندما ينظر اليها"},{"n":20,"text":"وفي ذلك لا يتامل القلب"},{"n":21,"text":"وليس من يفهم طرقه رب زوبعة لا يبصرها الانسان"},{"n":22,"text":"فان اكثر اعمال الرب في الخفاء اعمال العدل من يخبر بها او من يحتملها ان العهد بعيد والفحص عن الجميع يكون عند \nالانقضاء"},{"n":23,"text":"المتواضع القلب يتامل في ذلك اما الرجل الجاهل الضال فيتامل في الحماقات"},{"n":24,"text":"اسمع لي يا بني وتعلم العلم ووجه قلبك الى كلامي"},{"n":25,"text":"اني اعبر عن التاديب بوزن وابدي العلم بتدقيق"},{"n":26,"text":"جميع اعمال الرب من البدء قدرها بحكمة ومنذ انشائها ميز اجزاءها"},{"n":27,"text":"زين اعماله الى الدهر ومبادئها الى احقابها فلم تجع ولم تتعب ولم تزل تعمل"},{"n":28,"text":"ولم يضايق بعضها بعضا"},{"n":29,"text":"وهي لا تعاصي كلمته مدى الدهر"},{"n":30,"text":"وبعد ذلك نظر الرب الى الارض وملاها من خيراته"},{"n":31,"text":"ونفوس ذوي الحياة تغطي وجهها واليها تعود"}]},{"label":"سفر يشوع بن سيراخ 17","verses":[{"n":1,"text":"خلق الرب الانسان من الارض"},{"n":2,"text":"واليها اعاده"},{"n":3,"text":"جعل لهم وقتا واياما معدودة واتاهم سلطانا على كل ما فيها والبسهم قوة بحسب طبيعتهم وصنعهم على صورته"},{"n":4,"text":"القى رعبه على كل ذي جسد وسلطه على الوحش والطير"},{"n":5,"text":"خلق منه عونا بازائه واعطاهم اختيارا ولسانا وعينين واذنين وقلبا يتفكر"},{"n":6,"text":"وملاهم من معرفة الحكمة واراهم الخير والشر"},{"n":7,"text":"وجعل عينه على قلوبهم ليظهر لهم عظائم اعماله"},{"n":8,"text":"ليحمدوا اسمه القدوس ويخبروا بعظائم اعماله"},{"n":9,"text":"وزادهم العلم واورثهم شريعة الحياة"},{"n":10,"text":"وعاهدهم عهد الدهر واراهم احكامه"},{"n":11,"text":"فرات عيونهم عظائم المجد وسمعت اذانهم مجد صوته وقال لهم احترزوا من كل ظلم"},{"n":12,"text":"واوصاهم كل واحد في حق القريب"},{"n":13,"text":"طرقهم امامه في كل حين فهي لا تخفى عن عينيه"},{"n":14,"text":"لكل امة اقام رئيسا"},{"n":15,"text":"اما اسرائيل فهو نصيب الرب"},{"n":16,"text":"جميع اعمالهم كالشمس امامه وعيناه على الدوام تنظران الى طرقهم"},{"n":17,"text":"لم تخف عنه اثامهم بل جميع خطاياهم امام الرب"},{"n":18,"text":"صدقة الرجل كخاتم عنده فيحفظ احسان الانسان كحدقة عينه"},{"n":19,"text":"وبعد ذلك يقوم ويجازيهم يجازيهم جزاءهم على رؤوسهم ويهبطهم الى بطون الارض"},{"n":20,"text":"لكنه جعل للتائبين مرجعا وعزى ضعفاء الصبر ورسم لهم نصيب الحق"},{"n":21,"text":"فتب الى الرب واقلع عن الخطايا"},{"n":22,"text":"تضرع امام وجهه واقلل من العثرات"},{"n":23,"text":"ارجع الى العلي واعرض عن الاثم وابغض الرجس اشد بغض فهل من حامد للعلي في الجحيم"},{"n":24,"text":"تعلم اوامر الله واحكامه وكن ثابتا على حظ التقدمة والصلاة للعلي"},{"n":25,"text":"ادخل في ميراث الدهر المقدس مع الاحياء المعترفين للرب"},{"n":26,"text":"لا تلبث في ضلال المنافقين اعترف قبل الموت فان الاعتراف يعدم من الميت اذ يعود كلا شيء"},{"n":27,"text":"انك ما دمت حيا معافى تحمد الرب وتفتخر بمراحمه"},{"n":28,"text":"ما اعظم رحمة الرب وعفوه للذين يتوبون اليه"},{"n":29,"text":"لا يستطيع الناس ان يحوزوا كل شيء لان ابن الانسان ليس بخالد"},{"n":30,"text":"اي شيء اضوا من الشمس وهذه ايضا تكسف والشرير يفكر في اللحم والدم"},{"n":31,"text":"الرب يستعرض جنود السماء العليا اما البشر فجميعهم تراب ورماد"}]},{"label":"سفر يشوع بن سيراخ 18","verses":[{"n":1,"text":"الحي الدائم خلق جميع الاشياء عامة الرب وحده يتزكى"},{"n":2,"text":"لم يسمح لاحد ان يخبر باعماله"},{"n":3,"text":"ومن استقصى عظائمه"},{"n":4,"text":"من يعدد قوة عظمته ومن يقدم على تبيان مراحمه"},{"n":5,"text":"ليس للانسان ان يسقط من عجائب الرب ولا ان يزيد عليها ولا ان يسبرها"},{"n":6,"text":"اذا اتم الانسان فحينئذ يبتدئ واذا استراح فحينئذ يتحير"},{"n":7,"text":"ما الانسان وما منفعته ما خيره وما شره"},{"n":8,"text":"عدة ايام الانسان على الاكثر مئة سنة كنقطة ماء من البحر وكذرة من الرمل هكذا سنون قليلة في يوم الابدية"},{"n":9,"text":"فلذلك طالت عليهم اناة الرب وافاض عليهم رحمته"},{"n":10,"text":"راى وعلم ان منقلبهم هائل"},{"n":11,"text":"فلذلك اكثر من العفو"},{"n":12,"text":"رحمة الانسان لقريبه اما رحمة الرب فلكل ذي جسد"},{"n":13,"text":"يوبخ ويؤدب ويعلم ويرد كالراعي رعيته"},{"n":14,"text":"يرحم الذين يقبلون تاديبه ويبادرون الى العمل باحكامه"},{"n":15,"text":"يا بني لا تقرن الصنيعة بالملام ولا العطية بكلام التنغيص"},{"n":16,"text":"اليس الندى يبرد الحر هكذا الكلام افضل من العطية"},{"n":17,"text":"اما ترى ان الكلام افضل من العطية وكلاهما عند الرجل المنعم عليه"},{"n":18,"text":"تعيير الاحمق مكروه وعطية الحاسد تكل العيون"},{"n":19,"text":"قبل القضاء كن على يقين من الحق وقبل الكلام تعلم"},{"n":20,"text":"قبل المرض استطب وقبل القضاء افحص نفسك فتنال العفو ساعة الافتقاد"},{"n":21,"text":"قبل المرض كن متواضعا وعند ارتكاب الخطايا ار توبتك"},{"n":22,"text":"لا يحبسك شيء عن قضاء نذرك في وقته ولا تحجم عن اعمال البر حتى الموت فان ثواب الرب يبقى الى الابد"},{"n":23,"text":"قبل الصلاة اهب نفسك ولا تكن كانسان يجرب الرب"},{"n":24,"text":"اذكر الغضب في ايام الانقضاء ووقت الانتقام عند تحول الوجه"},{"n":25,"text":"في وقت الشبع اذكر وقت الجوع وفي ايام الغنى اذكر الفقر والعوز"},{"n":26,"text":"بين الغداة الى العشي يتغير الزمان وكل شيء سريع التحول امام الرب"},{"n":27,"text":"الحكيم يتحذر في كل شيء وفي ايام الخطايا يحترز من الهفوات"},{"n":28,"text":"كل عاقل يعرف الحكمة ويعترف لمن يجدها"},{"n":29,"text":"العقلاء في الكلام يتممون اعمالهم بالحكمة ويفيضون الامثال السديدة"},{"n":30,"text":"لا تكن تابعا لشهواتك بل عاص اهواءك"},{"n":31,"text":"فانك ان ابحت لنفسك الرضى بالشهوة جعلتك شماتة لاعدائك"},{"n":32,"text":"لا تتلذذ بكثرة المادب ولا تلزم نفسك الانفاق عليها"},{"n":33,"text":"لا تفقر نفسك بالمادب تنفق عليها من الدين وليس في كيسك شيء فانك بذلك تكمن لحياتك"}]},{"label":"سفر يشوع بن سيراخ 19","verses":[{"n":1,"text":"العامل الشريب لا يستغني والذي يحتقر اليسير يسقط شيئا فشيئا"},{"n":2,"text":"الخمر والنساء تجعلان العقلاء اهل ردة"},{"n":3,"text":"والذي يخالط الزواني يزداد وقاحة السوس والدود يرثانه والنفس الوقحة تستاصل"},{"n":4,"text":"من اسرع الى التصديق فهو خفيف العقل ومن خطئ فهو مجرم على نفسه"},{"n":5,"text":"الذي يتلذذ بالاثم يلحقه الوصم والذي يكره التكلم يقلل الذنوب"},{"n":6,"text":"الذي يخطا الى نفسه يندم والذي يتلذذ بالشر يلحقه الوصم"},{"n":7,"text":"لا تنقل كلام السوء فلست بخاسر شيئا"},{"n":8,"text":"لا تطلع على سرك صديقك ولا عدوك ولا تكشف ما في نفسك لاحد وان لم تكن فيك خطيئة"},{"n":9,"text":"فانه يسمعك ثم يرصدك ويصير يوما عدوا لك"},{"n":10,"text":"ان سمعت كلاما فليمت عندك ثق فانه لا يشقك"},{"n":11,"text":"الاحمق يمخض بالكلمة مخاض الوالدة بالجنين"},{"n":12,"text":"الكلمة في جوف الاحمق كنبل مغروز في فخذ لحيمة"},{"n":13,"text":"عاتب صديقك فلعله لم يفعل وان كان قد فعل فلا يعود يفعل"},{"n":14,"text":"عاتب صديقك فلعله لم يقل وان كان قد قال فلا يكرر القول"},{"n":15,"text":"عاتب صديقك فان النميمة كثيرة"},{"n":16,"text":"ولا تصدق كل كلام فرب زال ليست زلته من قلبه"},{"n":17,"text":"ومن الذي لم يخطا بلسانه عاتب قريبك قبل ان تهدده"},{"n":18,"text":"وابق مكانا لشريعة العلي كل الحكمة مخافة الرب وفي كل حكمة العمل بالشريعة"},{"n":19,"text":"ليست الحكمة علم الشر وحيث تكون مشورة الخطاة فليست هناك الفطنة"},{"n":20,"text":"فان من الشر ما هو رجس ومن الجهال من نقص حظه من الحكمة"},{"n":21,"text":"ناقص العقل وهو تقي خير من وافر الفطنة وهو يتعدى الشريعة"},{"n":22,"text":"رب دهاء يكون محكما وهو جائر"},{"n":23,"text":"ورب رجل يهدم المحبة ليبدي العدل رب شرير يمشي مكبا في الحداد وبواطنه مملوءة مكرا"},{"n":24,"text":"يكب بوجهه ويصم احدى اذنيه وحين لا تشعر يفاجئك"},{"n":25,"text":"وان منعه العجز من الاساءة فاذا صادف فرصة فعل"},{"n":26,"text":"من منظره يعرف الرجل ومن استقبال الوجه يعرف العاقل"},{"n":27,"text":"لبسة الرجل وضحكة الاسنان ومشية الانسان تخبر بما هو عليه"},{"n":28,"text":"رب عتاب لا يجمل ورب صامت عن فطنة"}]},{"label":"سفر يشوع بن سيراخ 20","verses":[{"n":1,"text":"العتاب خير من الحقد والمقر يكفي الخسران"},{"n":2,"text":"الخصي المتشهي يفسد البكر"},{"n":3,"text":"وهكذا فعل من يقضي قضاء الجور"},{"n":4,"text":"ما احسن ابداءك الندامة اذا وبخت فانك بذلك تجتنب الخطيئة الاختيارية"},{"n":5,"text":"رب ساكت يعد حكيما ورب متكلم يكره لطول حديثه"},{"n":6,"text":"من الساكتين من يسكت لانه لا يجد جوابا ومن يسكت لانه يعرف الاوقات"},{"n":7,"text":"الانسان الحكيم يسكت الى حين اما العاتي والجاهل فلا يبالي بالاوقات"},{"n":8,"text":"الكثير الكلام يمقت والمتسلط جورا يبغض"},{"n":9,"text":"رب نجاح يكون لاذى صاحبه ورب وجدان يكون لخسرانه"},{"n":10,"text":"رب عطية لا تنفعك ورب عطية تكون مضاعفة الجزاء"},{"n":11,"text":"رب انحطاط سببه المجد ورب تواضع يرفع به الراس"},{"n":12,"text":"رب مشتر كثيرا بقليل يدفع ثمنه سبعة اضعاف"},{"n":13,"text":"الحكيم يحبب نفسه بالكلام ونعم الحمقى تفاض سدى"},{"n":14,"text":"عطية الجاهل لا تنفعك لان له عوض العينين عيونا"},{"n":15,"text":"يعطي يسيرا ويمتن كثيرا ويفتح فاه مثل المنادي"},{"n":16,"text":"يقرض اليوم ويطالب غدا ان انسان مثل هذا لبغيض"},{"n":17,"text":"يقول الاحمق لا صديق لي وصنائعي غير مشكورة"},{"n":18,"text":"ان الذين ياكلون خبزي خبثاء اللسان ما اكثر المستهزئين به واكثر استهزاءاتهم"},{"n":19,"text":"فانه لا يدركك حق الادراك ماذا يستبقي ولا يبالي بما لا يستبقي"},{"n":20,"text":"الزلة عن السطح ولا الزلة من اللسان فان سقوط الاشرار يفاجئ سريعا"},{"n":21,"text":"الانسان السمج كحديث في غير وقته لا يزال في افواه فاقدي الادب"},{"n":22,"text":"يرذل المثل من فم الاحمق لانه لا يقوله في وقته"},{"n":23,"text":"رب انسان يمنعه اقلاله عن الخطيئة وفي راحته لا ينخسه ضميره"},{"n":24,"text":"من الناس من يهلك نفسه من الحياء وانما يهلكها لاجل شخص الجاهل"},{"n":25,"text":"ومن يعد صديقه من الحياء فيصيره عدوا له بغير سبب"},{"n":26,"text":"الكذب عار قبيح في الانسان وهو لا يزال في افواه فاقدي الادب"},{"n":27,"text":"السارق خير ممن يالف الكذب لكن كليهما يرثان الهلاك"},{"n":28,"text":"شان الانسان الكذوب الهوان وخزيه معه على الدوام"},{"n":29,"text":"الحكيم في الكلام يشتهر والانسان الفطن يرضي العظماء"},{"n":30,"text":"الذي يفلح الارض يعلي كدسه والذي يرضي العظماء يكفر الذنب"},{"n":31,"text":"الهدايا والرشى تعمي اعين الحكماء وكلجام في الفم تحجز توبيخاتهم"},{"n":32,"text":"الحكمة المكتومة والكنز المدفون اي منفعة فيهما"},{"n":33,"text":"الانسان الذي يكتم حماقته خير من الانسان الذي يكتم حكمته"}]},{"label":"سفر يشوع بن سيراخ 21","verses":[{"n":1,"text":"يا بني ان خطئت فلا تزد بل استغفر عما سلف من الخطاء"},{"n":2,"text":"اهرب من الخطيئة هربك من الحية فانها ان دنوت منها لدغتك"},{"n":3,"text":"انيابها انياب اسد تقتل نفوس الناس"},{"n":4,"text":"كل اثم كسيف ذي حدين ليس من جرحه شفاء"},{"n":5,"text":"التقريع والشتم يسلبان الغنى وبمثل ذلك يسلب بيت المتكبر"},{"n":6,"text":"تضرع الفقير يبلغ الى اذني الرب فيجرى له القضاء سريعا"},{"n":7,"text":"من مقت التوبيخ فهو في اثر الخاطئ ومن اتقى الرب يتوب بقلبه"},{"n":8,"text":"السليط اللسان بعيد السمعة لكن العاقل يعلم متى يسقط"},{"n":9,"text":"من بنى بيتا باموال غيره فهو كمن يجمع حجارته في الشتاء"},{"n":10,"text":"جماعة الاثماء مشاقة مجموعة وغايتها لهيب نار"},{"n":11,"text":"طريق الخطاة مفروش بالبلاط وفي منتهاه حفرة الجحيم"},{"n":12,"text":"من حفظ الشريعة فطن لروحها"},{"n":13,"text":"وغاية مخافة الرب الحكمة"},{"n":14,"text":"من لم يكن ذا دهاء لم يؤدب"},{"n":15,"text":"ورب دهاء يكثر المرارة"},{"n":16,"text":"علم الحكيم يفيض كالعباب ومشورته كينبوع حياة"},{"n":17,"text":"باطن الاحمق كاناء مكسور لا يضبط شيئا من العلم"},{"n":18,"text":"العالم اذا سمع كلام حكمة مدحه وزاد عليه اما الخليع فاذا سمعه كرهه ونبذه وراء ظهره"},{"n":19,"text":"حديث الاحمق كحمل في الطريق وانما اللطف على شفتي العاقل"},{"n":20,"text":"فم الفطن يبتغى في الجماعة وكلامه يتامل به في القلب"},{"n":21,"text":"الحكمة للاحمق كبيت مخرب وعلم الجاهل كلام لا يفهم"},{"n":22,"text":"التاديب للجهال كالقيود في الرجلين وكالوثاق في اليد اليمنى"},{"n":23,"text":"الاحمق يرفع صوته عند الضحك اما ذو الدهاء فيبتسم قليلا بسكون"},{"n":24,"text":"التاديب للفطن كحلية من ذهب وكسوار في ذراعه اليمنى"},{"n":25,"text":"قدم الاحمق تسرع الى داخل البيت اما الانسان الواسع الخبرة فيستحيي"},{"n":26,"text":"الجاهل يتطلع من الباب الى داخل البيت اما الرجل المتادب فيقف خارجا"},{"n":27,"text":"من قلة الادب التسمع على الباب والفطن يستثقل ذلك الهوان"},{"n":28,"text":"شفاه الجهال تحدث بالخزعبلات وكلام الفطنين يوزن بالميزان"},{"n":29,"text":"قلوب الحمقى في افواههم وافواه الحكماء في قلوبهم"},{"n":30,"text":"اذا لعن المنافق الشيطان فقد لعن نفسه"},{"n":31,"text":"النمام ينجس نفسه ومعاشرته مكروهة"}]},{"label":"سفر يشوع بن سيراخ 22","verses":[{"n":1,"text":"الكسلان اشبه بحجر قذر كل احد يصفر لهوانه"},{"n":2,"text":"الكسلان اشبه بزبل الدمن كل من قبضه ينفض يده"},{"n":3,"text":"الابن الفاقد الادب عار لابيه والبنت انما تعقب الخسران"},{"n":4,"text":"البنت الفطينة ميراث لرجلها والبنت المخزية غم لوالدها"},{"n":5,"text":"الوقحة تخزي اباها ورجلها وكلاهما يهينانها"},{"n":6,"text":"الكلام في غير وقته كالغناء في النوح اما السياط والتاديب فهما في كل وقت حكمة"},{"n":7,"text":"الذي يعلم الاحمق يجبر اناء من خزف"},{"n":8,"text":"وينبه مستغرقا في نومه"},{"n":9,"text":"من كلم الاحمق فانما يكلم متناعسا فاذا انتهى قال ماذا"},{"n":10,"text":"ابك على الميت لانه فقد النور وابك على الاحمق لانه فقد العقل"},{"n":11,"text":"اقلل من البكاء على الميت فانه في راحة"},{"n":12,"text":"اما الاحمق فحياته اشقى من موته"},{"n":13,"text":"النوح على الميت سبعة ايام والنوح على الاحمق والمنافق جميع ايام حياته"},{"n":14,"text":"لا تكثر الكلام مع الجاهل ولا تخالط الغبي"},{"n":15,"text":"تحفظ منه لئلا يعنتك وينجسك برجسه"},{"n":16,"text":"اعرض عنه فتجد راحة ولا يغمك سفهه"},{"n":17,"text":"اي شيء اثقل من الرصاص وماذا يسمى الا احمق"},{"n":18,"text":"الرمل والملح والحديد اخف حملا من الانسان الجاهل"},{"n":19,"text":"عرق الخشب المربوطة في البناء لا تتفكك في الزلزلة كذلك القلب المعتمد على مشورة سديدة لا يخاف اصلا"},{"n":20,"text":"القلب المستند على راي عاقل كزينة من رمل على حائط مصقول"},{"n":21,"text":"كما ان الاوتاد الموضوعة في مكان عال لا تثبت امام الريح"},{"n":22,"text":"كذلك قلب الاحمق الخائف الافكار لا يثبت امام هول من الاهوال"},{"n":23,"text":"قلب الاحمق يخاف في افكاره اما الذي يستمر على وصايا الله في كل حين فلا يخاف ابدا"},{"n":24,"text":"من نخس العين اسال الدموع ومن نخس القلب ابرز الحس"},{"n":25,"text":"من رمى الطيور بالحجر نفرها ومن عير صديقه قطع الصداقة"},{"n":26,"text":"ان جردت السيف على صديقك فلا تياس فانه يرجع"},{"n":27,"text":"ان فتحت فمك على صديقك فلا تخف فانه يصالح الا في التعيير والتكبر وافشاء السر والجرح بالمكر فانه في هذه يفر كل \nصديق"},{"n":28,"text":"ابق امينا للقريب في فقره لكي تشبع معه من خيراته"},{"n":29,"text":"اثبت معه في وقت ضيقه لكي تشترك في ميراثه"},{"n":30,"text":"قبل النار بخار الاتون والدخان وكذلك قبل الدماء التقريعات"},{"n":31,"text":"لا استحيي ان ادفع عن صديقي ولا اتوارى عن وجهه ثم ان اصابني منه شر"},{"n":32,"text":"فكل من يسمع بذلك يتحفظ منه"},{"n":33,"text":"من يجعل حارسا لفمي وخاتما وثيقا على شفتي لئلا اسقط بسببهما ويهلكني لساني"}]},{"label":"سفر يشوع بن سيراخ 23","verses":[{"n":1,"text":"ايها الرب الاب يا سيد حياتي لا تتركني ومشورة شفتي ولا تدعني اسقط بهما"},{"n":2,"text":"من ياخذ افكاري بالسياط وقلبي بتاديب الحكمة بحيث لا يشفق على جهالاتي ولا تهمل خطاياي"},{"n":3,"text":"لكي لا تتكاثر جهالاتي وتتوافر خطاياي فاسقط تجاه اضدادي ويشمت عدوي بي"},{"n":4,"text":"ايها الرب الاب يا اله حياتي لا تتركني ومشورة شفتاي"},{"n":5,"text":"لا تدعني اطمح بعيني والهوى اصرفه عني"},{"n":6,"text":"لا تملكني شهوة البطن ولا الزنى ولا تسلمني الى نفس وقحة"},{"n":7,"text":"ايها البنون دونكم ادب الفم فان من يحفظه لا يؤخذ بشفتيه"},{"n":8,"text":"انه بهما يصطاد الخاطئ وبهما يعثر القاذف والمتكبر"},{"n":9,"text":"لا تعود فاك الحلف"},{"n":10,"text":"ولا تالف تسمية القدوس"},{"n":11,"text":"فانه كما ان العبد الذي لا يزال يفحص لا يخلو من الحبط كذلك من لم يبرح يحلف ويسمي لا يتزكى"},{"n":12,"text":"الرجل الحلاف يمتلئ اثما ولا يبرح السوط من بيته"},{"n":13,"text":"وهو ان لم يف فعليه خطيئة وان استخف فخطيئته مضاعفة"},{"n":14,"text":"وان حلف باطلا لا يبرر وبيته يملا نوائب"},{"n":15,"text":"ومن الكلام كلام اخر يلابسه الموت لا كان في ميراث يعقوب"},{"n":16,"text":"ان هذه كلها تبعد عن الاتقياء فلا يتمرغون في الخطايا"},{"n":17,"text":"لا تعود فاك فحش الكلام فان ذلك لا يخلو من خطيئة"},{"n":18,"text":"تذكر اباك وامك اذا جلست بين العظماء"},{"n":19,"text":"لئلا تنساهما امامهم ويسفهك تعود معاشرتهم فتود لو لم تولد منهما وتلعن يوم ولادتك"},{"n":20,"text":"من تعود كلام الشتيمة لا يتادب طول ايامه"},{"n":21,"text":"من الناس صنفان يكثران من الخطايا وصنف ثالث يجلب الغضب"},{"n":22,"text":"النفس المتوهجة كنار ملتهبة فلا تنطفئ الى ان تفنى"},{"n":23,"text":"والانسان الزاني بنجاسة لحمه فلا يكف الى ان يوقد النار"},{"n":24,"text":"لان الانسان الزاني كل خبز يحلو له فلا يكل الى ان يفرغ"},{"n":25,"text":"والانسان الذي يتعدى على فراشه قائلا في نفسه من يراني"},{"n":26,"text":"حولي الظلمة والحيطان تسترني ولا احد يراني فماذا اخشى ان العلي لا يذكر خطاياي"},{"n":27,"text":"وهو انما يخاف من عيون البشر"},{"n":28,"text":"ولا يعلم ان عيني الرب اضوا من الشمس عشرة الاف ضعف فتبصران جميع طرق البشر وتطلعان على الخفايا"},{"n":29,"text":"هو عالم بكل شيء قبل ان يخلق فكذلك بعد ان انقضى"},{"n":30,"text":"فهذا يعاقب في شوارع المدينة وحيث لا يظن يقبض عليه"},{"n":31,"text":"ويهان من الجميع لانه لم يفهم مخافة الرب"},{"n":32,"text":"هكذا ايضا المراة التي تترك بعلها وتجعل له وارثا من الغريب"},{"n":33,"text":"لانها اولا عصت شريعة العلي وثانيا خانت رجلها وثالثا تنجست بالزنى واقامت نسلا من رجل غريب"},{"n":34,"text":"فهذه يؤتى بها الى الجماعة وتبحث احوال اولادها"},{"n":35,"text":"ان اولادها لا يتاصلون واغصانها لا تثمر"},{"n":36,"text":"وهى تخلف ذكرا ملعونا وفضيحتها لا تمحى"},{"n":37,"text":"فيعرف المتخلفون ان لا شيء افضل من مخافة الرب ولا شيء اعذب من رعاية وصايا الرب"},{"n":38,"text":"ان اتباع الله مجد عظيم وفي قبوله لك طول ايام"}]},{"label":"سفر يشوع بن سيراخ 24","verses":[{"n":1,"text":"الحكمة تمدح نفسها وتفتخر بين شعبها"},{"n":2,"text":"تفتح فاها في جماعة العلي وتفتخر امام جنوده"},{"n":3,"text":"وتعظم في شعبها وتمجد في ملا القديسين"},{"n":4,"text":"وتحمد في جميع المختارين وتبارك بين المباركين وتقول"},{"n":5,"text":"اني خرجت من فم العلي بكرا قبل كل خليقة"},{"n":6,"text":"وجعلت النور يشرق في السماوات على الدوام وغشيت الارض كلها بمثل الضباب"},{"n":7,"text":"وسكنت في الاعالي وجعلت عرشي في عمود الغمام"},{"n":8,"text":"انا وحدي جلت في دائرة السماء وسلكت في عمق الغمار ومشيت على امواج البحر"},{"n":9,"text":"وداست قدمي كل الارض وعلى كل شعب"},{"n":10,"text":"وكل امة تسلطت"},{"n":11,"text":"ووطئت بقدرتي قلوب الكبار والصغار في هذه كلها التمست الراحة وباي ميراث احل"},{"n":12,"text":"حينئذ اوصاني خالق الجميع والذي حازني عين مقر مسكني"},{"n":13,"text":"وقال اسكني في يعقوب ورثي في اسرائيل"},{"n":14,"text":"قبل الدهر من الاول حازني والى الدهر لا ازول وقد خدمت امامه في المسكن المقدس"},{"n":15,"text":"وهكذا في صهيون ترسخت وجعل لي مقرا في المدينة المحبوبة وسلطنتي هي في اورشليم"},{"n":16,"text":"فتاصلت في شعب مجيد وفي نصيب الرب نصيب ميراثه وفي ملا القديسين مقامي"},{"n":17,"text":"ارتفعت كالارز في لبنان وكالسرو في جبال حرمون"},{"n":18,"text":"كالنخل في السواحل وكغراس الورد في اريحا"},{"n":19,"text":"كالزيتون النضير في السهل وكالدلب على مجارى المياه في الشوارع"},{"n":20,"text":"فاح عرفي كالدارصيني والقندول العطر وانتشرت رائحتي كالمر المنتقى"},{"n":21,"text":"كالقنة والجزع والميعة ومثل بخور اللبان في المسكن"},{"n":22,"text":"اني مددت اغصاني كالبطمة واغصاني اغصان مجد ونعمة"},{"n":23,"text":"انا كالكرمة المنبتة النعمة وازهاري ثمار مجد وغنى"},{"n":24,"text":"انا ام المحبة البهية والمخافة والعلم والرجاء الطاهر"},{"n":25,"text":"في كل نعمة الطريق والحق وكل رجاء الحياة والفضيلة"},{"n":26,"text":"تعالوا الي ايها الراغبون في واشبعوا من ثماري"},{"n":27,"text":"فان روحي احلى من العسل وميراثي الذ من شهد العسل"},{"n":28,"text":"وذكري يبقى في اجيال الدهور"},{"n":29,"text":"من اكلني عاد الي جائعا ومن شربني عاد ظامئا"},{"n":30,"text":"من سمع لي فلا يخزى ومن عمل بارشادي فلا يخطا"},{"n":31,"text":"من شرحني فله الحياة الابدية"},{"n":32,"text":"هذه كلها هي سفر الحياة وعهد العلي وعلم الحق"},{"n":33,"text":"ان موسى امر بالشريعة واحكام العدل ميراث ال يعقوب ومواعيد اسرائيل"},{"n":34,"text":"ان الرب وعد داود عبده ان يقيم منه الملك القدير الجالس على عرش المجد الى الابد"},{"n":35,"text":"هو يفيض الحكمة كفيشون ومثل دجلة في ايام الغلال"},{"n":36,"text":"ويملا فهما كالفرات ومثل الاردن في ايام الحصاد"},{"n":37,"text":"ويبدي التاديب كالنور ومثل جيحون في ايام القطاف"},{"n":38,"text":"الحكمة لا يستوفي معرفتها الاول ولا يستقصيها الاخر"},{"n":39,"text":"لان فكرها اوسع من البحر ومشورتها اعمق من الغمر العظيم"},{"n":40,"text":"انا الحكمة مفيضة الانهار"},{"n":41,"text":"انا كساقية من النهر وكقناة خرجت الى الفردوس"},{"n":42,"text":"قلت اسقي جنتي واروي روضتي"},{"n":43,"text":"فاذا بساقيتي قد صارت نهرا وبنهري قد صار بحرا"},{"n":44,"text":"فاني اضيء بالتاديب مثل الفجر واذيع الى الاقاصي"},{"n":45,"text":"انفذ الى جميع اعماق الارض وانظر الى جميع الراقدين وانير لجميع الذين يرجون الرب"},{"n":46,"text":"اني افيض التعليم مثل نبوة واخلفه لاجيال الدهور"},{"n":47,"text":"فانظروا كيف لم يكن عنائي لي وحدي بل ايضا لجميع الذين يلتمسون الحكمة"}]},{"label":"سفر يشوع بن سيراخ 25","verses":[{"n":1,"text":"ثلاث هن زينة لي وبهن قمت جميلة امام الرب والناس"},{"n":2,"text":"اتفاق الاخوة وحب القريب والمصافاة بين المراة ورجلها"},{"n":3,"text":"ثلاثة تبغضهم نفسي وتمقت حياتهم"},{"n":4,"text":"الفقير المتكبر والغني الكذاب والشيخ الزاني الفاقد الفهم"},{"n":5,"text":"ان لم تدخر في شبابك فكيف تجد في شيخوختك"},{"n":6,"text":"ما اجمل القضاء للشيب وحسن المشورة للشيوخ"},{"n":7,"text":"ما اجمل الحكمة للشيوخ والراي والمشورة لارباب المجد"},{"n":8,"text":"كثرة الخبرة اكليل الشيوخ ومخافة الرب فخرهم"},{"n":9,"text":"تسع خصال غبطتها في قلبي والعاشرة ينطق بها لساني"},{"n":10,"text":"مغبوط الانسان الذي يفرح بالاولاد والذي يرى في حياته سقوط اعدائه"},{"n":11,"text":"مغبوط من يساكن امراة عاقلة ومن لم يزلل بلسانه ومن لم يخدم من لا يستاهله"},{"n":12,"text":"مغبوط من وجد الفطنة ومن يجعل حديثه في اذن واعية"},{"n":13,"text":"ما اعظم من وجد الحكمة لكنه ليس افضل ممن يتقي الرب"},{"n":14,"text":"مخافة الرب اعلى من كل شيء"},{"n":15,"text":"الذي يحوزها بمن يشبه"},{"n":16,"text":"مخافة الرب اول محبته والايمان اول الاتصال به"},{"n":17,"text":"غاية الالم الم القلب وغاية الخبث خبث المراة"},{"n":18,"text":"كل الم ولا الم القلب"},{"n":19,"text":"وكل خبث ولا خبث المراة"},{"n":20,"text":"وكل نائبة ولا النائبة من المبغضين"},{"n":21,"text":"وكل انتقام ولا انتقام الاعداء"},{"n":22,"text":"لا راس شر من راس الحية"},{"n":23,"text":"ولا غضب شر من غضب المراة مساكنة الاسد والتنين خير عندي من مساكنة المراة الخبيثة"},{"n":24,"text":"خبث المراة يغير منظرها ويرد وجهها اسود كالمسح"},{"n":25,"text":"رجلها يكمد بين اصحابه واذا سمع تاوه بمرارة"},{"n":26,"text":"كل سوء بازاء سوء المراة خفيف لتقع قرعة الخاطئ عليها"},{"n":27,"text":"مثل العقبة الكثيرة الرمل لقدمي الشيخ مثل المراة الخبيثة اللسان للرجل الهادئ"},{"n":28,"text":"لا يعثرك جمال امراة ولا تشته امراة لحسنها"},{"n":29,"text":"غضب ووقاحة وفضيحة عظيمة"},{"n":30,"text":"المراة التي تتسلط على رجلها"},{"n":31,"text":"المراة الشريرة ذلة للقلب وتقطيب للوجه والم للفؤاد"},{"n":32,"text":"التي لا تنشئ سعادة رجلها انما هي تراخ لليدين وتخلع للركبتين"},{"n":33,"text":"من المراة ابتدات الخطيئة وبسببها نموت نحن اجمعون"},{"n":34,"text":"لا تجعل للماء مخرجا ولا للمراة الشريرة سلطانا"},{"n":35,"text":"ان لم تسلك طوع يدك تخزيك امام اعدائك"},{"n":36,"text":"فاقطعها عن جسدك لئلا تؤذيك على الدوام"}]},{"label":"سفر يشوع بن سيراخ 26","verses":[{"n":1,"text":"رجل المراة الصالحة مغبوط وعدد ايامه مضاعف"},{"n":2,"text":"المراة الفاضلة تسر رجلها وتجعله يقضي سنيه بالسلام"},{"n":3,"text":"المراة الصالحة نصيب صالح تمنح حظا لمن يتقي الرب"},{"n":4,"text":"فيكون قلبه جذلا ووجهه بهجا كل حين غنيا كان ام فقيرا"},{"n":5,"text":"ثلاث خاف منهن قلبي وعلى الرابعة ابتهلت بوجهي"},{"n":6,"text":"شكاية المدينة وتالب الجمع"},{"n":7,"text":"والبهتان كل ذلك اثقل من الموت"},{"n":8,"text":"لكن المراة الغائرة من المراة وجع قلب ونوح"},{"n":9,"text":"ولسانها سوط يصيب الجميع"},{"n":10,"text":"المراة الشريرة نير قلق ومثل متخذها مثل من يمسك عقربا"},{"n":11,"text":"المراة السكيرة سخط عظيم وفضيحتها لا تستر"},{"n":12,"text":"زنى المراة في طموح البصر ويعرف من جفنيها"},{"n":13,"text":"واظب على مراقبة البنت القليلة الحياء لئلا تجد فرصة فتبذل نفسها"},{"n":14,"text":"تنبه لطرفها الوقح ولا تعجب اذا عقتك"},{"n":15,"text":"تفتح فمها كالمسافر العطشان وتشرب من كل ماء صادفته وتجلس عند كل جذع وتفتح الكنانة تجاه كل سهم"},{"n":16,"text":"لطف المراة ينعم رجلها"},{"n":17,"text":"وادبها يسمن عظامه"},{"n":18,"text":"المراة المحبة للصمت عطية من الرب والنفس المتادبة لا يستبدل بها"},{"n":19,"text":"المراة الحيية نعمة على نعمة"},{"n":20,"text":"والنفس العفيفة لا قيمة توازنها"},{"n":21,"text":"الشمس تشرق في على الرب وجمال المراة الصالحة في عالم بيتها"},{"n":22,"text":"السراج يضيء على المنارة المقدسة وحسن الوجه على القامة الرزينة"},{"n":23,"text":"العمد من الذهب تقوم على قواعد من الفضة والساقان الجميلتان على اخمصي ذات الوقار"},{"n":24,"text":"الاسس على الصخر تثبت الى الابد ووصايا الرب في قلب المراة الطاهرة"},{"n":25,"text":"اثنان يحزن لهما قلبي والثالث ياخذني عليه الغضب"},{"n":26,"text":"رجل الحرب اذا اعجزته الفاقة والرجال العقلاء اذا اهينوا"},{"n":27,"text":"اما من ارتد عن البر الى الخطيئة فالرب يستبقيه للسيف"},{"n":28,"text":"قلما يتخلص التاجر من الاثم والخمار لا يتزكى من الخطيئة"}]},{"label":"سفر يشوع بن سيراخ 27","verses":[{"n":1,"text":"كثيرون خطئوا لاجل عرض الدنيا والذي يطلب الغنى يغضي طرفه"},{"n":2,"text":"بين الحجارة المتضامة يغرز الوتد وبين البيع والشراء تنشب الخطيئة"},{"n":3,"text":"وسيسحق الاثم مع الاثيم"},{"n":4,"text":"من لم يحرص على الثبات في مخافة الرب يهدم بيته سريعا"},{"n":5,"text":"عند هز الغربال يبقى الزبل كذلك كساحة الانسان عند تفكره"},{"n":6,"text":"انية الخزاف تختبر بالاتون والانسان يمتحن بحديثه"},{"n":7,"text":"حراثة الشجر تظهر من ثمرها كذلك تفكر قلب الانسان يظهر من كلامه"},{"n":8,"text":"لا تمدح رجلا قبل ان يتكلم فانه بهذا يمتحن الناس"},{"n":9,"text":"اذا تعقبت العدل فانك تدركه وتلبسه حلة مجد وتسكن معه فيصونك الى الابد وفي يوم الافتقاد تجد سندا"},{"n":10,"text":"الطيور تاوى الى اشكالها والحق يعود الى العاملين به"},{"n":11,"text":"الاسد يكمن للفريسة كذلك الخطايا تكمن لفاعلي الاثم"},{"n":12,"text":"حديث التقي في كل حين حكمة اما الجاهل فيتغير كالقمر"},{"n":13,"text":"بين السفهاء ترقب الفرصة وبين العقلاء كن مواظبا"},{"n":14,"text":"حديث الحمقى مكروه وضحكهم في ملذات الخطيئة"},{"n":15,"text":"محادثة الحلاف تقف الشعر ومخاصمته سد الاذان"},{"n":16,"text":"مخاصمة المتكبرين سفك الدماء ومشاتمتهم سماع ثقيل"},{"n":17,"text":"الذي يفشي الاسرار يهدم الثقة ولا يجد صديقا لنفسه"},{"n":18,"text":"احبب الصديق وكن معه امينا"},{"n":19,"text":"لكن ان افشيت اسراره فلا تطلبه من بعد"},{"n":20,"text":"فان من اتلف صداقة القريب كان بمنزلة من اتلف عدوه"},{"n":21,"text":"ومثل تسريحك للقريب مثل اطلاقك طائرا من يدك فلا تعود تصطاده"},{"n":22,"text":"لا تطلبه فانه قد ابتعد وفر كالظبي من الفخ"},{"n":23,"text":"ان الجرح له ضماد والمشاتمة بعدها صلح"},{"n":24,"text":"اما الذي يفشي الاسرار فشانه الياس"},{"n":25,"text":"الغامز بالعين يختلق الشرور وليس من يتجنبه"},{"n":26,"text":"امام عينيك يحلو بفمه ويستحسن كلامك ثم يقلب منطقه ومن كلامك يلقي امامك معثرة"},{"n":27,"text":"قد ابغضت امورا كثيرة ولكن لا كبغضي له والرب سيبغضه"},{"n":28,"text":"من رمى حجرا الى فوق فقد رماه على راسه والضربة بالمكر تجرح الماكر"},{"n":29,"text":"من حفر حفرة سقط فيها ومن نصب شركا اصطيد به"},{"n":30,"text":"من صنع المساوئ فعليه تنقلب ولا يشعر من اين تقع عليه"},{"n":31,"text":"الاستهزاء والتعيير شان المتكبرين والانتقام يكمن لهم مثل الاسد"},{"n":32,"text":"الشامتون بسقوط الاتقياء يصطادون بالشرك والوجع يفنيهم قبل موتهم"},{"n":33,"text":"الحقد والغضب كلاهما رجس والرجل الخاطئ متمسك بهما"}]},{"label":"سفر يشوع بن سيراخ 28","verses":[{"n":1,"text":"من انتقم يدركه الانتقام من لدن الرب ويترقب الرب خطاياه"},{"n":2,"text":"اغفر لقريبك ظلمه لك فاذا تضرعت تمحى خطاياك"},{"n":3,"text":"ايحقد انسان على انسان ثم يلتمس من الرب الشفاء"},{"n":4,"text":"ام لا يرحم انسانا مثله ثم يستغفر عن خطاياه"},{"n":5,"text":"ان امسك الحقد وهو بشر فمن يكفر خطاياه"},{"n":6,"text":"اذكر اواخرك واكفف عن العدواة"},{"n":7,"text":"اذكر الفساد والموت واثبت على الوصايا"},{"n":8,"text":"اذكر الوصايا ولا تحقد على القريب"},{"n":9,"text":"اذكر ميثاق العلي واغض عن الجهالة"},{"n":10,"text":"امسك عن النزاع فتقلل الخطايا"},{"n":11,"text":"فان الانسان الغضوب يضرم النزاع والرجل الخاطئ يبلبل الاصدقاء ويلقي الشقاق بين المسالمين"},{"n":12,"text":"بحسب الحطب تضطرم النار وبحسب قوة الانسان يكون غيظه وبحسب غناه يثير غضبه وبحسب شدة النزاع يستشيط"},{"n":13,"text":"الخصومة عن عجلة تضرم النار والنزاع عن عجلة يسفك الدم"},{"n":14,"text":"اذا نفخت في شرارة اضطرمت واذا تفلت عليها انطفات وكلاهما من فمك"},{"n":15,"text":"النمام وذو اللسانين اهل للعنة لاهلاكهما كثيرين من اهل المسالمة"},{"n":16,"text":"اللسان الثالث اقلق كثيرين وبددهم من امة الى امة"},{"n":17,"text":"وهدم مدنا محصنة وخرب بيوت العظماء"},{"n":18,"text":"وكسر جيوش الشعوب وافنى امما ذات اقتدار"},{"n":19,"text":"اللسان الثالث طرد نساء فاضلات وسلبهن اتعابهن"},{"n":20,"text":"من اصغى اليه لا يجد راحة ولا يسكن مطمئنا"},{"n":21,"text":"ضربة السوط تبقي حبطا وضربة اللسان تحطم العظام"},{"n":22,"text":"كثيرون سقطوا بحد السيف لكنهم ليسوا كالساقطين بحد اللسان"},{"n":23,"text":"طوبى لمن وقي شره ولم يعرض على غضبه ولم يحمل نيره ولم يوثق بقيوده"},{"n":24,"text":"فان نيره نير من حديد وقيوده قيود من نحاس"},{"n":25,"text":"الموت به موت قاس والجحيم انفع منه"},{"n":26,"text":"لكنه لا يتسلط على الاتقياء ولا هم يحترقون بلهيبه"},{"n":27,"text":"بل الذين يتركون الرب يقعون تحت سلطانه فيشتعل فيهم ولا ينطفئ يطلق عليهم كالاسد ويفترسهم كالنمر"},{"n":28,"text":"سيج ملكك بالشوك"},{"n":29,"text":"احبس فضتك وذهبك واجعل لكلامك ميزانا ومعيارا ولفمك بابا ومزلاجا"},{"n":30,"text":"واحذر ان تزل به فتسقط امام الكامن لك"}]},{"label":"سفر يشوع بن سيراخ 29","verses":[{"n":1,"text":"الذي يصنع رحمة يقرض القريب والسخي اليد يحفظ الوصايا"},{"n":2,"text":"اقرض القريب في وقت حاجته واقضه ما له عليك في اجله"},{"n":3,"text":"حقق ما نطقت به وكن امينا معه فتنال في كل حين بغيتك"},{"n":4,"text":"كثيرون حسبوا القرض لقطة فعنوا الذين امدوهم"},{"n":5,"text":"قبل ان يقبض يقبل اليد ويخشع بصوته حتى ينال مال القريب"},{"n":6,"text":"فاذا ان الرد ماطل ونطق بكلام مضجر وشكا صرف الدهر"},{"n":7,"text":"ان كان الرد في طاقته لم يكد يرد النصف ويحسب ما رده لقطة"},{"n":8,"text":"والا فيسلبه امواله ويتخذه عدوا بلا سبب"},{"n":9,"text":"يجزيه اللعنة والشتيمة وبدل الاكرام يكافئه الاهانة"},{"n":10,"text":"كثيرون امسكوا لاجل خبث الناس مخافة ان يسلبوا بغير سبب"},{"n":11,"text":"مع ذلك كن طويل الاناة على البائس ولا تماطله في الصدقة"},{"n":12,"text":"لاجل الوصية اعن المسكين وفي عوزه لا تردده فارغا"},{"n":13,"text":"اتلف فضتك على اخيك وصديقك ولا تدعها تصدا تحت الحجر وتتلف"},{"n":14,"text":"انفق ذخيرتك بحسب وصايا العلي فتنفعك اكثر من الذهب"},{"n":15,"text":"اغلق على الصدقة في اخاديرك فهي تنقذك من كل شر"},{"n":16,"text":"17 18 تقاتل عنك عدوك اكثر من ترس الباس ورمح الحماسة 19 الرجل الصالح يكفل القريب والذي فقد كل حياء يخذله 20 لا تنس نعم الكافل فانه بذل نفسه لاجلك 21 الخاطئ يهرب من كافله واللئيم الروح يخذله 22 الخاطئ يدمر خيرات الكافل وجاحد الجميل يخذل مخلصه 23 من الناس من يكفل قريبه لكنه يفقد كل حياء فيخذله 24 كثيرون كانوا في نجح فاهلكتهم الكفالة واقلقتهم كامواج البحر 25 الجات رجالا مقتدرين الى المهاجرة فتاهوا بين امم غريبة 26 الخاطئ الذي يتهافت على الكفالة ويصبوا الى المعاملات يقع تحت الاقضية 27 امدد قريبك بقدر طاقتك واحذر على نفسك ان تسقط 28 راس المعيشة الماء والخبز واللباس والبيت الساتر للسوءة 29 عيش الفقير تحت سقف من الواح خير من الاطعمة الفاخرة في دار الغربة 30 ارض بالقليل والكثير فلا تسمع تعييرا في امر البيت 31 بئس حياة الانسان من بيت الى بيت وحيثما ضاف لم يفتح فاه 32 تطعم وتسقي جاحدين لجميلك وانت ضيفهم ووراء ذلك تسمع اقوالا مرة 33 ان قم يا ضيف جهز المائدة وان كان بيدك شيء فاطعمني 34 انصرف يا ضيف من امام شخص كريم ان اخا لي يتضيفني فانا محتاج الى البيت 35 امران يستثقلهما الانسان الفطن الانتهار في امر البيت وتعيير المقرض"}]},{"label":"سفر يشوع بن سيراخ 30","verses":[{"n":1,"text":"من احب ابنه اكثر من ضربه لكي يسر في اخرته"},{"n":2,"text":"من ادب ابنه يجتني ثمر تاديبه ويفتخر به بين الوجهاء"},{"n":3,"text":"من علم ابنه يغير عدوه ويبتهج به امام اصدقائه"},{"n":4,"text":"اذا توفى ابوه فكانه لم يمت لانه خلف من هو نظيره"},{"n":5,"text":"في حياته راى وفرح وعند وفاته لم يحزن"},{"n":6,"text":"خلف منتقما من الاعداء ومكافئا للاصدقاء بالجميل"},{"n":7,"text":"من دلل ابنه فسيضمد جراحه وعند كل صراخ تضطرب احشاءه"},{"n":8,"text":"الفرس الذي لم يرض يصير جموحا والابن الذي لم يضبط يصير سفيها"},{"n":9,"text":"ان دللت ابنك روعك وان لاعبته حزنك"},{"n":10,"text":"لا تضاحكه لئلا يغمك وفي اواخرك ياخذك صريف الاسنان"},{"n":11,"text":"لا تجعل له سلطانا في صبائه ولا تهمل جهالاته"},{"n":12,"text":"احن رقبته في صبائه وارضض اضلاعه ما دام صغيرا لئلا يتصلب فيعصيك فياخذك وجع القلب"},{"n":13,"text":"ادب ابنك واجتهد في تهذيبه لئلا يسقط فيما يخجلك"},{"n":14,"text":"فقير ذو عافية وصحيح البنية خير من غني منهوك بالاسقام"},{"n":15,"text":"العافية وصحة البنية خير من كل الذهب وقوة الجسم افضل من نشب لا يحصى"},{"n":16,"text":"لا غنى خير من عافية الجسم ولا سرور يفوق فرح القلب"},{"n":17,"text":"الموت افضل من الحياة المرة او السقم الملازم"},{"n":18,"text":"الخيرات المسكوبة على فم مغلق كالاطعمة الموضوعة على قبر"},{"n":19,"text":"اي منفعة للصنم بالقربان فانه لا ياكل ولا يشم"},{"n":20,"text":"هكذا من يرهقه الرب ويجازيه على اثامه"},{"n":21,"text":"يرى بعينيه ويتنهد كالخصي الذي يعانق عذراء ثم يتنهد"},{"n":22,"text":"لا تغم نفسك ولا تضيق صدرك بافكارك"},{"n":23,"text":"سرور القلب حياة الانسان وابتهاج الرجل طول الايام"},{"n":24,"text":"احبب نفسك وفرج عن قلبك وانف الحزن عنك بعيدا"},{"n":25,"text":"فان الحزن قتل كثيرين وليس فيه ثمرة"},{"n":26,"text":"الغيرة والغضب يقللان الايام والغمة تاتي بالشيخوخة قبل الاوان"},{"n":27,"text":"القلب البهج الصالح لا يزال في الولائم ومادبة معدة باهتمام"}]},{"label":"سفر يشوع بن سيراخ 31","verses":[{"n":1,"text":"السهر لاجل الغنى يذيب الجسم والاهتمام به ينفي النوم"},{"n":2,"text":"سهر الاهتمام يحرم الوسن والمرض الشديد يذهبه النوم"},{"n":3,"text":"يجد الغني في جمع الاموال وفي راحته يشبع من اللذات"},{"n":4,"text":"يجد الفقير في حاجة العيش وفي راحته يمسي معوزا"},{"n":5,"text":"من احب الذهب لا يزكى ومن اتبع الفساد يشبع منه"},{"n":6,"text":"كثيرون سقطوا لاجل الذهب فاضحى هلاكهم امام وجوههم"},{"n":7,"text":"الذهب عود عثار للذين يذبحون له وكل جاهل يصطاد به"},{"n":8,"text":"طوبى للغني الذي وجد بغير عيب ولم يسع وراء الذهب"},{"n":9,"text":"من هو فنغبطه لانه صنع عجائب في شعبه"},{"n":10,"text":"من الذي امتحن به فوجد كاملا به فليفتخر من الذي قدر ان يتعدى فلم يتعد وان يصنع الشر ولم يصنع"},{"n":11,"text":"ستكون خيراته ثابتة وتخبر الجماعة بصدقاته"},{"n":12,"text":"اذا جلست على مائدة حافلة فلا تفتح لها حنجرتك"},{"n":13,"text":"ولا تقل ما اكثر ما عليها"},{"n":14,"text":"اذكر ان العين الشريرة سوء عظيم"},{"n":15,"text":"اي شيء خلق اسوا من العين فلذلك هي تدمع من كل شخص"},{"n":16,"text":"حيثما لحظت فلا تمدد اليه يدك"},{"n":17,"text":"ولا تزاحمها في الصحفة"},{"n":18,"text":"افهم ما عند القريب مما عندك وتامل في كل امر"},{"n":19,"text":"كل مما وضع امامك كما ياكل الانسان ولا تكن لهما لئلا تكره"},{"n":20,"text":"وكن اول من امسك مراعاة للادب ولا تتضلع لئلا ينكر عليك"},{"n":21,"text":"واذا اتكات بين كثيرين فلا تمدد يدك قبلهم"},{"n":22,"text":"ما اقل ما يكتفي به الانسان المتادب ومثل هذا لا تاخذه الكظة على فراشه"},{"n":23,"text":"السهاد والهيضة والمغص للرجل الشره"},{"n":24,"text":"رقاد الصحة لقنوع الجوف يقوم باكرا وهو مالك نفسه"},{"n":25,"text":"واذا اكرهت على الاكل فاعتزل من بين الجماعة فتستريح"},{"n":26,"text":"اسمع لي يا بني ولا تستخف بي واخيرا تختبر اقوالي"},{"n":27,"text":"في جميع اعمالك كن نشيطا فلا يلحق بك سقم"},{"n":28,"text":"من سخا بالطعام تباركه الشفاه ويشهد بكرمه شهادة صدق"},{"n":29,"text":"من شح بالطعام تتذمر عليه المدينة ويشهد بلؤمه شهادة يقين"},{"n":30,"text":"لا تكن ذا باس تجاه الخمر فان الخمر اهلكت كثيرين"},{"n":31,"text":"الاتون يمتحن الحديد الممهى والخمر تمتحن قلوب المتجبرين في القتال"},{"n":32,"text":"الخمر حياة للانسان اذا اقتصدت في شربها"},{"n":33,"text":"اي عيش لمن ليس له خمر"},{"n":34,"text":"اي شيء يعدم الحياة الموت"},{"n":35,"text":"الخمر من البدء خلقت للانبساط لا للسكر"},{"n":36,"text":"الخمر ابتهاج القلب وسرور النفس لمن شرب منها في وقتها ما كفى"},{"n":37,"text":"الشرب بالرفق صحة للنفس والجسد"},{"n":38,"text":"الافراط من شرب الخمر خصومة ونزاع"},{"n":39,"text":"الافراط من شرب الخمر مرارة للنفس"},{"n":40,"text":"السكر يهيج غضب الجاهل لمصرعه ويقلل القوة ويكثر الجراح"},{"n":41,"text":"في مجلس الخمر لا توبخ القريب ولا تحتقره في سروره"},{"n":42,"text":"لا تخاطبه بكلام تعيير ولا تضايقه في المطالبة"}]},{"label":"سفر يشوع بن سيراخ 32","verses":[{"n":1,"text":"اذا جعلوك رئيسا فلا تتكبر بل كن بينهم كواحد منهم"},{"n":2,"text":"اهتم بهم ثم اجلس وبعد قضائك ما عليك اتكئ"},{"n":3,"text":"لكي تفرح بهم وتاخذ الاكليل زينة وتكرم بهداياهم"},{"n":4,"text":"تكلم يا شيخ فانك اهل ذلك"},{"n":5,"text":"لكن عن دقة علم ولا تمنع الغناء"},{"n":6,"text":"لا تطلق كلامك عند السماع ولا تات بالحكمة في غير وقتها"},{"n":7,"text":"الحان المغنين في مجلس الخمر كفص من ياقوت في حلي من ذهب"},{"n":8,"text":"انغام المغنين على خمر لذيذة كفص من زمرد في مصوغ من ذهب"},{"n":9,"text":"اسمع وانت ساكت فباحتشامك تنال الحظوة"},{"n":10,"text":"تكلم يا شاب لكن نادرا متى دعتك الحاجة"},{"n":11,"text":"ان سئلت مرتين فجاوب بالايجاز"},{"n":12,"text":"معبرا عن الكثير بالقليل وكن كمن يعلم ويصمت"},{"n":13,"text":"في جماعة العظماء لا تساو نفسك بهم وبين الشيوخ لا تكن كثير الهذر"},{"n":14,"text":"قدام الرعد ينطلق البرق وقدام المحتشم تسبق الحظوة"},{"n":15,"text":"اذا ان الوقت فقم لا تتاخر اسرع الى بيتك لا تتهاون هناك تنزه"},{"n":16,"text":"واصنع ما بدا لك ولا تخطا بكلام الكبرياء"},{"n":17,"text":"وعلى هذه كلها بارك صانعك الذي يسكرك من طيباته"},{"n":18,"text":"من اتقى الرب يقبل تاديبه والمبتكرون اليه يجدون مرضاته"},{"n":19,"text":"من ابتغى الشريعة يمتلئ منها والمراءي يعثر فيها"},{"n":20,"text":"الذين يتقون الرب يجدون العدل ويوقدون من الاحكام مصباحا لهم"},{"n":21,"text":"الانسان الخاطئ يجانب التوبيخ ويجد حججا توافق مبتغاه"},{"n":22,"text":"صاحب المشورة لا يهمل التامل اما المتكبر ممن ليس كذلك فلا ياخذه الخوف"},{"n":23,"text":"ولا بعدما عمل بهواه عن غير مشورة"},{"n":24,"text":"لا تعمل شيئا عن غير مشورة فلا تندم على عملك"},{"n":25,"text":"لا تسر في طريق الهلكة فلا تعثر بالحجارة لا ترم نفسك في طريق لم تختبره فلا تجعل لنفسك معثرة"},{"n":26,"text":"احترز حتى من بنيك وتحفظ من اهل بيتك"},{"n":27,"text":"في جميع اعمالك اقتد بضميرك فان ذلك هو حفظ الوصايا"},{"n":28,"text":"الذي يقتدي بالشريعة يرعى الوصايا والذي يتكل على الرب لا يخسر"}]},{"label":"سفر يشوع بن سيراخ 33","verses":[{"n":1,"text":"من اتقى الرب لا يلقى ضرا بل عند التجربة يحفظه الرب وينجيه من الشرور"},{"n":2,"text":"الرجل الحكيم لا يبغض الشريعة اما الذي يراءي فيها فهو كسفينة في الزوبعة"},{"n":3,"text":"الانسان العاقل يؤمن بالشريعة والشريعة امينة له"},{"n":4,"text":"هيئ كلامك كما يفعل الصديقون في مسائلهم فتسمع انظم معاني علمك وجاوب"},{"n":5,"text":"احشاء الاحمق كمحالة العجلة وفكره مثل المحور الخفيف الدوران"},{"n":6,"text":"الصديق المتهزئ كفحل الخيل الذي يصهل تحت كل راكب"},{"n":7,"text":"لماذا يفضل يوم على يوم ونور كل يوم في السنة من الشمس"},{"n":8,"text":"علم الرب ميز بينها اذ صنعت الشمس التي تحفظ الرسم"},{"n":9,"text":"وخالف بين الازمنة فعيدت الاعياد في الساعة المعينة"},{"n":10,"text":"فمنها ما اعلاه وقدسه ومنها ما جعله في عداد الايام وكذا البشر كلهم من التراب وادم صنع من الارض"},{"n":11,"text":"لكن الرب ميز بينهم بسعة علمه وخالف بين طرقهم"},{"n":12,"text":"فمنهم من باركه واعلاه ومنهم من قدسه وقربه اليه ومنهم من لعنه وخفضه ونكسه من مقامه"},{"n":13,"text":"كما يكون الطين في يد الخزاف وتجري جميع احواله بحسب مرضاته"},{"n":14,"text":"كذلك الناس في يد صانعهم وهو يجازيهم بحسب قضائه"},{"n":15,"text":"بازاء الشر الخير وبازاء الموت الحياة كذلك بازاء التقي الخاطئ وهكذا تامل في جميع اعمال العلي تجدها اثنين اثنين \nالواحد بازاء الاخر"},{"n":16,"text":"اني انا الاخير قد استيقظت وورثت هذه كما كانت منذ البدء"},{"n":17,"text":"كمن يلتقط وراء القطافين اقبلت ببركة الرب فملات المعصرة كالذي قطف"},{"n":18,"text":"فانظروا كيف لم يكن اجتهادي لي وحدي بل ايضا لجميع الذين يلتمسون التاديب"},{"n":19,"text":"اسمعوني يا عظماء الشعب واصغوا الي يا رؤساء الجماعة"},{"n":20,"text":"لا تول على نفسك في حياتك ابنك او امراتك او اخاك او صديقك ولا تعط لاخر اموالك لئلا تندم فتتضرع اليه بها"},{"n":21,"text":"ما حييت وما دام فيك نفس لا تسلم نفسك الى احد من البشر"},{"n":22,"text":"لانه خير ان يطلب بنوك منك من ان تنظر انت الى ايدي بنيك"},{"n":23,"text":"في جميع امورك احفظ لنفسك مزيتها"},{"n":24,"text":"ولا تجعل عيبا في كرامتك قسم ميراثك عند انقضاء ايام حياتك حين يحضر الموت"},{"n":25,"text":"العلف والعصا والحمل للحمار والخبز والتاديب والعمل للعبد"},{"n":26,"text":"اشغل الغلام بالعمل فتستريح ارخ يديك عنه فيلتمس العتق"},{"n":27,"text":"النير والسيور تحني الرقاب ومواظبة العمل تخضع العبد"},{"n":28,"text":"للعبد الشرير التنكيل والعذاب اقسره على العمل لئلا يتفرغ"},{"n":29,"text":"فان الفراغ يعلم ضروب الخبث"},{"n":30,"text":"الزمه الاعمال كما يليق به فان لم يطع فثقل عليه القيود لكن لا تفرط في عقاب ذي جسد ولا تصنع شيئا بغير تمييز"},{"n":31,"text":"ان كان لك عبد فليكن عندك كنفسك فانك اكتسبته بالدم ان كان لك عبد فعامله كنفسك فانك تحتاج اليه احتياجك الى نفسك"},{"n":32,"text":"ان اذيته ابق"},{"n":33,"text":"واذا فر ذاهبا ففي اي طريق تطلبه"}]},{"label":"سفر يشوع بن سيراخ 34","verses":[{"n":1,"text":"الامال الفارغة الكاذبة لذي السفه والاحلام يطير بها الجهال"},{"n":2,"text":"مثل الملتفت الى الاحلام مثل القابض على الظل والمتطلب للريح"},{"n":3,"text":"رؤيا الاحلام هي هذا بازاء هذا شبه الشخص امام الشخص"},{"n":4,"text":"بالنجس ماذا يطهر وبالكذب ماذا يصدق"},{"n":5,"text":"العرافة والتطير والاحلام باطلة"},{"n":6,"text":"كخيالات قلب الماخض ان لم ترسل هذه من عند العلي في افتقاد منه فلا توجه اليها قلبك"},{"n":7,"text":"فان كثيرين اضلتهم الاحلام فسقطوا لاعتمادهم عليها"},{"n":8,"text":"الشريعة تتمم بغير تلك الاكاذيب والحكمة في الفم الصادق كمال"},{"n":9,"text":"الرجل المتادب يعلم كثيرا والكثير الخبرة يحدث بعقل"},{"n":10,"text":"الذي لم يختبر يعلم قليلا اما الذي جال فهو كثير الحيلة"},{"n":11,"text":"الذي لم يمتحن ماذا يعلم اما الذي ضل فهو كثير الدهاء"},{"n":12,"text":"اني رايت في مطافي امورا كثيرة واكثر اقوالي مما اختبرت"},{"n":13,"text":"وقد طالما خاطرت بنفسي في هذا الطلب حتى الى الموت ثم نجوت"},{"n":14,"text":"روح المتقين للرب يحيا"},{"n":15,"text":"لان رجاءهم في مخلصهم"},{"n":16,"text":"من اتقى الرب فلا يخاف ولا يفزع لانه هو رجاؤه"},{"n":17,"text":"من اتقى الرب فطوبى لنفسه"},{"n":18,"text":"الى من يتوجه ومن عمدته"},{"n":19,"text":"ان عيني الرب الى محبيه هو مجير قدير وعمدة قوية ستر من الحر وظل من الهجير"},{"n":20,"text":"صيانة من العثار ومعونة عند السقوط هو يعلي النفس وينير العينين يمنح الشفاء والحياة والبركة"},{"n":21,"text":"الذابح من كسب الظلم يستهزا بتقدمته واستهزاءات الاثماء ليست بمرضية"},{"n":22,"text":"الرب وحده للذين ينتظرونه في طريق الحق والعدل"},{"n":23,"text":"ليست مرضاة العلي بتقادم المنافقين ولا بكثرة ذبائحهم يغفر خطاياهم"},{"n":24,"text":"من قدم ذبيحة من مال المساكين فهو كمن يذبح الابن امام ابيه"},{"n":25,"text":"خبز المعوزين حياتهم فمن امسكه عليهم فانما هو سافك دماء"},{"n":26,"text":"من يخطف معاش القريب يقتله"},{"n":27,"text":"من يمسك اجرة الاجير يسفك دمه"},{"n":28,"text":"واحد بنى واخر هدم فماذا انتفعا سوى التعب"},{"n":29,"text":"واحد صلى واخر لعن فايهما يستجيب الرب لدعائه"},{"n":30,"text":"من اغتسل من لمس الميت ثم لمسه فماذا نفعه غسله"},{"n":31,"text":"كذلك الانسان الذي يصوم عن خطاياه ثم يعود يفعلها من يستجيب لصلاته وماذا نفعه اتضاعه"}]},{"label":"سفر يشوع بن سيراخ 35","verses":[{"n":1,"text":"من حفظ الشريعة فقد قدم ذبائح كثيرة"},{"n":2,"text":"من رعى الوصايا فقد ذبح ذبيحة الخلاص"},{"n":3,"text":"ومن اقلع عن الاثم فقد ذبح ذبيحة الخطيئة وكفر ذنوبه"},{"n":4,"text":"من قدم السميذ فقد وفى بالشكر ومن تصدق فقد ذبح ذبيحة الحمد"},{"n":5,"text":"مرضاة الرب الاقلاع عن الشر وتكفير الذنوب الرجوع عن الاثم"},{"n":6,"text":"لا تحضر امام الرب فارغا"},{"n":7,"text":"فان هذه كلها تجرى طاعة للوصية"},{"n":8,"text":"تقدمة الصديق تدسم المذبح ورائحتها طيبة امام العلي"},{"n":9,"text":"ذبيحة الرجل الصديق مرضية وذكرها لا ينسى"},{"n":10,"text":"مجد الرب عن قرة عين ولا تنقص من بواكير يديك"},{"n":11,"text":"كن متهلل الوجه في كل عطية وقدس العشور بفرح"},{"n":12,"text":"اعط العلي على حسب عطيته وقدم كسب يدك عن قرة عين"},{"n":13,"text":"فان الرب مكافئ فيكافئك سبعة اضعاف"},{"n":14,"text":"لا تقدم هدايا بها عيب فان الرب لا يقبلها"},{"n":15,"text":"ولا تعتمد على ذبيحة اثيمة فان الرب ديان ولا يلتفت الى كرامة الوجوه"},{"n":16,"text":"لا يحابي الوجوه في حكم الفقير بل يستجيب صلاة المظلوم"},{"n":17,"text":"لا يهمل اليتيم المتضرع اليه ولا الارملة اذا سكبت شكواها"},{"n":18,"text":"اليست دموع الارملة تسيل على خديها اما هي صراخ على الذي اسالها"},{"n":19,"text":"انها من خديها تصعد الى السماء والرب المستجيب لا يتلذذ بها"},{"n":20,"text":"ان المتعبد يقبل بمرضاة وصلاته تبلغ الى الغيوم"},{"n":21,"text":"صلاة المتواضع تنفذ الغيوم ولا تستقر حتى تصل ولا تنصرف حتى يفتقد العلي ويحكم بعدل ويجري القضاء"},{"n":22,"text":"فالرب لا يبطئ ولا يطيل اناته عليهم حتى يحطم صلب الذين لا رحمة فيهم"},{"n":23,"text":"وينتقم من الامم حتى يمحو قوم المتجبرين ويحطم صوالجة الظالمين"},{"n":24,"text":"حتى يكافئ الانسان على حسب افعاله ويجزي البشر باعمالهم على حسب نياتهم"},{"n":25,"text":"حتى يجري الحكم لشعبه ويفرج عنهم برحمته"},{"n":26,"text":"الرحمة تجمل في اوان الضيق كسحاب المطر في اوان القحط"}]},{"label":"سفر يشوع بن سيراخ 36","verses":[{"n":1,"text":"ايها الرب اله الجميع ارحمنا وانظر الينا وارنا نور مراحمك"},{"n":2,"text":"والق رعبك على جميع الامم الذين لم يلتمسوك ليعلموا انه لا اله الا انت ويخبروا بعظائمك"},{"n":3,"text":"ارفع يدك على الامم الغريبة وليعرفوا عزتك"},{"n":4,"text":"كما قد ظهرت فينا قداستك امامهم هكذا فلتظهر عظمتك فيهم امامنا"},{"n":5,"text":"وليعرفوك كما عرفنا نحن ان لا اله الا انت يا رب"},{"n":6,"text":"استانف الايات واحدث العجائب"},{"n":7,"text":"مجد يدك وذراعك اليمنى"},{"n":8,"text":"اثر غضبك وصب سخطك"},{"n":9,"text":"دمر المقاوم واحطم العدو"},{"n":10,"text":"عجل الزمان واذكر الميثاق وليخبر بعظائمك"},{"n":11,"text":"لتاكل نار الغضب الناجي وليلق مضايقو شعبك الهلاك"},{"n":12,"text":"اهشم رؤوس قادة الاعداء القائلين ليس غيرنا"},{"n":13,"text":"اجمع كل اسباط يعقوب واتخذها ميراثا لك كما كانت في البدء"},{"n":14,"text":"ايها الرب ارحم الشعب الذي دعي باسمك واسرائيل الذي انزلته منزلة بكرك"},{"n":15,"text":"اشفق على مدينة قدسك اورشليم مدينة راحتك"},{"n":16,"text":"املا صهيون لكي تنادي باقوالك املا شعبك من مجدك"},{"n":17,"text":"اشهد للذين هم خلقك منذ البدء وايقظ النبوءات التي باسمك"},{"n":18,"text":"اعط الذين ينتظرونك الثواب وليتبين صدق انبيائك استجب ايها الرب لصلاة المتضرعين اليك"},{"n":19,"text":"على حسب بركة هرون على شعبك فيعلم جميع سكان الارض انك انت الرب اله الدهور"},{"n":20,"text":"الجوف يتناول كل طعام لكن من الطعام ما هو اطيب من غيره"},{"n":21,"text":"الحلق يميز اطعمة الصيد والقلب الفهم يميز الاقوال الكاذبة"},{"n":22,"text":"القلب الخبيث يورث الغم والرجل الكثير الخبرة يكافئه"},{"n":23,"text":"المراة تتزوج اي رجل كان لكن في البنات من تفضل على غيرها"},{"n":24,"text":"جمال المراة يبهج الوجه ويفوق جميع منى الانسان"},{"n":25,"text":"وان كان في لسانها رحمة ووداعة فليس رجلها كسائر بني البشر"},{"n":26,"text":"من حاز امراة فهي له راس الغنى وعون بازائه وعمود يستريح اليه"},{"n":27,"text":"حيث لا سياج ينتهب الملك وحيث لا امراة ينوح التائه"},{"n":28,"text":"من ذا يامن اللص المشدود الازر الهائم من مدينة الى مدينة هكذا حال الرجل الذي لا وكر له فياوي حيثما امسى"}]},{"label":"سفر يشوع بن سيراخ 37","verses":[{"n":1,"text":"كل صديق يقول لي مع فلان صداقة لكن رب صديق انما هو صديق بالاسم الا يورث الغم حتى الموت"},{"n":2,"text":"كل صاحب وصديق يتحول الى العداوة"},{"n":3,"text":"ايها الاختراع الموبق من اين هبطت فغطيت اليبس خيانة"},{"n":4,"text":"رب صاحب يتنعم مع صديقه في السراء وعند الضراء يضحي له عدوا"},{"n":5,"text":"رب صاحب لاجل بطنه يجد مع صديقه ويحمل الترس في الحرب"},{"n":6,"text":"لا تنس صديقك في قلبك ولا تتغاض عنه وانت موسر"},{"n":7,"text":"لا تستشر من يرصدك واكتم مشورتك عمن يحسدك"},{"n":8,"text":"كل مشير يبدي مشورة لكن رب مشير انما يشير لنفسه"},{"n":9,"text":"الحذر لنفسك من المشير واستخبر اولا عن حاجته فانه يشير بما ينفعه"},{"n":10,"text":"لئلا يلقي القرعة عليك ويقول لك"},{"n":11,"text":"سبيلك حسن ثم يقف تجاهك ينظر ماذا يحل بك"},{"n":12,"text":"لا تستشر المنافق في التقوى ولا الظالم في العدل ولا المراة في ضرتها ولا الجبان في الحرب ولا التاجر في التجارة ولا \nالمبتاع في البيع ولا الحاسد في شكر المعروف"},{"n":13,"text":"ولا الجافي في الرقة ولا الكسلان في شيء من الشغل"},{"n":14,"text":"ولا الاجير المساكن في انجاز الشغل ولا البطال في كثرة العمل لا تلتفت الى هؤلاء لشيء من المشورة"},{"n":15,"text":"لكن ائلف الرجل التقي ممن علمته يحفظ الوصايا"},{"n":16,"text":"ونفسه كنفسك واذا سقطت يتوجع لك"},{"n":17,"text":"واعقد المشورة مع القلب فانه ليس لك مشير انصح منه"},{"n":18,"text":"لان نفس الرجل قد تخبر بالحق اكثر من سبعة رقباء يرقبون من موضع عال"},{"n":19,"text":"وفي كل هذه تضرع الى العلي ليهديك بالحق في الطريق المستقيم"},{"n":20,"text":"الكلام مبدا كل عمل والمشورة قبل الفعل"},{"n":21,"text":"الوجه يدل على تغير القلب اربعة تصدر من القلب الخير والشر والحياة والموت والمتسلط على هذه في كل حين هو اللسان"},{"n":22,"text":"من الناس من هو ذو دهاء مؤدب لكثيرين لكنه لا ينفع نفسه شيئا"},{"n":23,"text":"ومنهم من يدعي الحكمة وكلامه مكروه فمثل هذا يحرم كل قوت"},{"n":24,"text":"لانه لم يؤت الحظوة من عند الرب اذ ليس من الحكمة على شيء"},{"n":25,"text":"ومنهم من حكمته لنفسه وثمار عقله صالحة في الفم"},{"n":26,"text":"الرجل الحكيم يعلم شعبه وثمار عقله صالحة"},{"n":27,"text":"الرجل الحكيم يمتلئ بركة ويغبطه كل من يراه"},{"n":28,"text":"حياة الرجل ايام معدودة اما ايام اسرائيل فلا عدد لها"},{"n":29,"text":"الحكيم يرث ثقة شعبه واسمه يحيا الى الابد"},{"n":30,"text":"يا بني جرب نفسك في حياتك وانظر ماذا يضرها وامنعها عنه"},{"n":31,"text":"فانه ليس كل شيء ينفع كل احد ولا كل نفس ترضى بكل امر"},{"n":32,"text":"لا تشره الى كل لذة ولا تنصب على الاطعمة"},{"n":33,"text":"فان كثرة الاكل تهيض الاكل والشره يبلغ الى المغص"},{"n":34,"text":"كثيرون هلكوا من الشره اما القنوع فيزداد حياة"}]},{"label":"سفر يشوع بن سيراخ 38","verses":[{"n":1,"text":"اعط الطبيب كرامته لاجل فوائده فان الرب خلقه"},{"n":2,"text":"لان الطب ات من عند العلي وقد افرغت عليه جوائز الملوك"},{"n":3,"text":"علم الطبيب يعلي راسه فيعجب به عند العظماء"},{"n":4,"text":"الرب خلق الادوية من الارض والرجل الفطن لا يكرهها"},{"n":5,"text":"اليس بعود تحول الماء عذبا حتى تعرف قوته"},{"n":6,"text":"ان العلي الهم الناس العلم لكي يمجد في عجائبه"},{"n":7,"text":"بتلك يشفي ويزيل الاوجاع ومنها يصنع العطار امزجة وصنعته لا نهاية لها"},{"n":8,"text":"فيحل السلام من الرب على وجه الارض"},{"n":9,"text":"يا بني اذا مرضت فلا تتهاون بل صل الى الرب فهو يشفيك"},{"n":10,"text":"اقلع عن ذنوبك وقوم اعمالك ونق قلبك من كل خطيئة"},{"n":11,"text":"قرب رائحة مرضية وتذكار السميذ واستسمن التقدمة كانك لست بكائن"},{"n":12,"text":"ثم اجعل موضعا للطبيب فان الرب خلقه ولا يفارقك فانك تحتاج اليه"},{"n":13,"text":"ان للاطباء وقتا فيه النجح على ايديهم"},{"n":14,"text":"لانهم يتضرعون الى الرب ان ينجح عنايتهم بالراحة والشفاء لاسترجاع العافية"},{"n":15,"text":"من خطئ امام صانعه فليقع في يدي الطبيب"},{"n":16,"text":"يا بني اذرف الدموع على الميت واشرع في النياحة على ما يليق بذي مصيبة شديدة وكفن جسده كما يحق ولا تتهاون بدفنه"},{"n":17,"text":"ليكن بكاؤك مرا وتوهج في النحيب"},{"n":18,"text":"اقم المناحة بحسب منزلته يوما او يومين دفعا للغيبة ثم تعز عن الحزن"},{"n":19,"text":"فان الحزن يجلب الموت وغمة القلب تحني القوة"},{"n":20,"text":"في الانفراد الحزن يتشدد وحياة البائس هي على حسب قلبه"},{"n":21,"text":"لا تسلم قلبك الى الحزن بل اصرفه ذاكرا الاواخر"},{"n":22,"text":"لا تنس فانه لا رجوع من هناك ولست تنفعه ولكنك تضر نفسك"},{"n":23,"text":"اذكر ان ما قضي عليه يقضى عليك لي امس ولك اليوم"},{"n":24,"text":"اذا استراح الميت فاسترح من تذكره وتعز عنه عند خروج روحه"},{"n":25,"text":"الكاتب يكتسب الحكمة في اوان الفراغ والقليل الاشتغال يحصل عليها"},{"n":26,"text":"كيف يحصل على الحكمة الذي يمسك المحراث ويفتخر بالمنخس ويسوق البقر ويتردد في اعمالها وحديثه في اولاد الثيران"},{"n":27,"text":"قلبه في خطوط المحراث وسهره في تسمين العجال"},{"n":28,"text":"كذلك كل صانع ومهندس ممن يقضي الليل كانهار والحافرون نقوش الخواتم الجاهدون في تنويع الاشكال الذين قلوبهم في \nتمثيل الصورة باصلها وسهرهم في استكمال صنعتهم"},{"n":29,"text":"وكذلك الحداد الجالس عند السندان المكب على صوغ حديدة ضخمة يصلب وهج النار لحمه وهو يكافح حر الكير"},{"n":30,"text":"صوت المطرقة يتتابع على اذنيه وعيناه الى مثال المصنوع"},{"n":31,"text":"قلبه في اتمام المصنوعات وسهره في تزيينها الى التمام"},{"n":32,"text":"وهكذا الخزاف الجالس على عمله المدير دولابه برجليه فانه لا يزال مهتما بعمله ويحصي جميع مصنوعاته"},{"n":33,"text":"بذراعه يعرك الطين وامام قدميه يحني قوته"},{"n":34,"text":"قلبه في اتقان الدهان وسهره في تنظيف الاتون"},{"n":35,"text":"هؤلاء كلهم يتوكلون على ايديهم وكل منهم حكيم في صناعته"},{"n":36,"text":"بدونهم لا تعمر مدينة"},{"n":37,"text":"لا ياوون المدن ولا يتمشون ولا يدخلون الجماعة"},{"n":38,"text":"ولا يجلسون على منبر القاضي ولا يفقهون فنون الدعاوي ولا يشرحون الحكم والقضاء ولا يضربون الامثال"},{"n":39,"text":"لكنهم يصلحون الاشياء الدهرية ودعاؤهم لاجل عمل صناعتهم خلافا لمن يسلم نفسه الى التامل في شريعة العلي"}]},{"label":"سفر يشوع بن سيراخ 39","verses":[{"n":1,"text":"فانه يبحث عن حكمة جميع المتقدمين ويتفرغ للنبوءات"},{"n":2,"text":"يحفظ احاديث الرجال المشهورين ويدخل في افانين الامثال"},{"n":3,"text":"يبحث عن خفايا الاقوال السائرة ويتبحر في الغاز الاحاجي"},{"n":4,"text":"يخدم بين ايدي العظماء ويقف امام الرئيس"},{"n":5,"text":"يجول في ارض الامم الغريبة فيختبر في الناس الخير والشر"},{"n":6,"text":"يوجه قلبه الى الابتكار امام الرب صانعه ويتضرع الى العلي"},{"n":7,"text":"ويفتح فاه بالصلاة ويستغفر لخطاياه"},{"n":8,"text":"فان شاء الرب العظيم يملاه من روح الفهم"},{"n":9,"text":"فيمطر باقوال حكمته وفي الصلاة يعترف للرب"},{"n":10,"text":"يستهدي بمشورته وعلمه ويتامل في خفاياه"},{"n":11,"text":"يبين تاديب ارشاده ويفتخر بشريعة عهد الرب"},{"n":12,"text":"كثيرون يمدحون حكمته وهي لا تمحى الى الابد"},{"n":13,"text":"ذكره لا يزول واسمه يحيا الى جيل الاجيال"},{"n":14,"text":"تحدث الامم بحكمته وتشيد الجماعة بحمده"},{"n":15,"text":"ان بقي خلف اسما اكثر من الف وان دخل الى الراحة افاد نفسه"},{"n":16,"text":"اني استمر على بيان افكاري لاني امتلات كبدر تم"},{"n":17,"text":"اسمعوني ايها البنون الاصفياء انبتوا كورد مغروس على نهر الصحراء"},{"n":18,"text":"وافيحوا عرفكم كاللبان"},{"n":19,"text":"وازهروا كالزنبق انشروا عرفكم وسبحوا بترنيمكم باركوا الرب على جميع اعماله"},{"n":20,"text":"وعظموا اسمه اعترفوا له بالتسبيح بترانيم الشفاه وبالكنارة وقولوا هكذا بالاعتراف"},{"n":21,"text":"اعمال الرب كلها حسنة جدا وجميع اوامره تجرى في اوقاتها وكلها تطلب في اونتها"},{"n":22,"text":"بكلمته وقف الماء كربوة وقفت حياض المياه بقول فمه"},{"n":23,"text":"في امره كل مرضاة وليس احد يمنع تمام خلاصه"},{"n":24,"text":"اعمال كل ذي جسد امامه ولا شيء يخفى عن عينيه"},{"n":25,"text":"ينظر من دهر الى دهر وليس شيء عجيبا امامه"},{"n":26,"text":"ليس لقائل ان يقول ما هذا او لم هذا لان كل شيء خلق لفوائد تختص به"},{"n":27,"text":"فاضت بركته كنهر"},{"n":28,"text":"وروت اليبس كطوفان كذلك يورث الامم غضبه"},{"n":29,"text":"كما حول المياه الى يبس طرقه مستقيمة للقديسين كذلك هي معاثر للاثماء"},{"n":30,"text":"الصالحات خلقت للصالحين منذ البدء كذلك الشرور للاشرار"},{"n":31,"text":"راس ما تحتاج اليه حياة الانسان الماء والنار والحديد والملح وسميذ الحنطة والعسل واللبن ودم العنب والزيت واللباس"},{"n":32,"text":"كل هذه خيرات للاتقياء وكذلك هي تتحول للخطاة شرورا"},{"n":33,"text":"من الارواح ارواح خلقت للانتقام وهذه في غضبها تشدد سياطها"},{"n":34,"text":"وفي وقت الانقضاء تصب قوتها وتسكن غضب صانعها"},{"n":35,"text":"النار والبرد والجوع والموت كل هذه خلقت للانتقام"},{"n":36,"text":"انياب السباع والعقارب والافاعي والسيف تنتقم من المنافقين باهلاكهم"},{"n":37,"text":"هذه تفرح بوصيته وعلى الارض تستعد لوقت الحاجة وفي ازمنتها لا تتعدى كلمته"},{"n":38,"text":"فلذلك ترسخت منذ البدء وتاملت ورسمت في كتابي"},{"n":39,"text":"ان جميع اعمال الرب صالحة فتؤتي كل فائدة في ساعتها"},{"n":40,"text":"وليس لقائل ان يقول ان هذا شر من هذا فان كل امر يستحسن في وقته"},{"n":41,"text":"فالان سبحوا بكل قلوبكم وافواهكم وباركوا اسم الرب"}]},{"label":"سفر يشوع بن سيراخ 40","verses":[{"n":1,"text":"جهد عظيم خلق لكل انسان ونير ثقيل وضع على بني ادم من يوم خروجهم من اجواف امهاتهم الى يوم دفنهم في الارض ام الجميع"},{"n":2,"text":"فان عندهم انزعاج الافكار وروع القلب وقلق الانتظار ويوم الانقضاء"},{"n":3,"text":"من الجالس على العرش في المجد الى المتضع على التراب والرماد"},{"n":4,"text":"من اللابس السمنجوني والتاج الى الملتف بالكتان الخشن وزد على ذلك الغضب والغيرة والاضطراب والجزع وخوف الموت والحقد \nوالخصومة"},{"n":5,"text":"وفي وقت الراحة على الفراش نوم الليل الذي يكدر خاطر الانسان"},{"n":6,"text":"فهو في راحة قليلة كلا شيء وبعد ذلك في الاحلام كما في يوم المراقبة"},{"n":7,"text":"يرتعد من رؤيا قلبه كالمنهزم من وجه الحرب وعند نجاته يهب ويتعجب من زوال خوفه"},{"n":8,"text":"هذا حال كل ذي جسد من الانسان الى البهيمة وللخطاة من ذلك سبعة اضعاف"},{"n":9,"text":"الموت والدم والخصومة والسيف والنوائب والجوع والسحق والسوط"},{"n":10,"text":"كل ذلك خلق للاثماء ولاجلهم اتى الطوفان"},{"n":11,"text":"كل ما هو من الارض فالى الارض يعود وكل ما هو من المياه فالى البحر ينثني"},{"n":12,"text":"كل رشوة ومظلمة تمحى والامانة تبقى الى الابد"},{"n":13,"text":"اموال الظالمين تجف كالسيل وتدوي كالرعد الشديد عند المطر"},{"n":14,"text":"يفرح الظالم عند بسط يديه لكن المعتدين يضمحلون في الانقضاء"},{"n":15,"text":"اعقاب المنافقين لا ياتون بفروع كثيرة ولا الاصول النجسة التي على الصخر الصلب"},{"n":16,"text":"الخضر الذي على كل ماء وشط نهر يقلع قبل كل عشب"},{"n":17,"text":"النعمة كجنة بركات والرحمة تستمر الى الابد"},{"n":18,"text":"حياة العامل القنوع تحلو لكن الذي يجد كنزا هو فوق كليهما"},{"n":19,"text":"النسل وابتناء مدينة يخلدان الاسم لكن المراة التي لا عيب فيها تحسب فوق كليهما"},{"n":20,"text":"الخمر والغناء يسران القلب لكن حب الحكمة فوق كليهما"},{"n":21,"text":"المزمار والعود يطيبان اللحن لكن اللسان العذب فوق كليهما"},{"n":22,"text":"البهاء والجمال تشتهيهما عينك لكن خضر المزرعة فوق كليهما"},{"n":23,"text":"الصديق والصاحب لهما لقاء وفاق لكن المراة مع رجلها فوق كليهما"},{"n":24,"text":"الاخوة والعون لساعة الضيق لكن نصرة الرحمة فوق كليهما"},{"n":25,"text":"الذهب والفضة يثبتان القدم لكن المشورة تفضل على كليهما"},{"n":26,"text":"الغنى والقوة يعزان القلب لكن مخافة الرب فوق كليهما"},{"n":27,"text":"ليس في مخافة الرب افتقار ولا يحتاج صاحبها الى نصرة"},{"n":28,"text":"مخافة الرب كجنة بركة وقد البست مجدا يفوق كل مجد"},{"n":29,"text":"يا بني لا تعش عيش الاستعطاء فان الموت خير من التكفف"},{"n":30,"text":"الرجل الذي يترصد مائدة الغريب عيشه لا يعد عيشا ونفسه تتنجس باطعمة غريبة"},{"n":31,"text":"الرجل الاريب المتادب يتحفظ من ذلك"},{"n":32,"text":"يحلو الاستعطاء في فم الوقح وفي جوفه تتقد النار"}]},{"label":"سفر يشوع بن سيراخ 41","verses":[{"n":1,"text":"ايها الموت ما اشد مرارة ذكرك على الانسان المتقلب في السلام فيما بين امواله"},{"n":2,"text":"على الرجل الذي لا تتجاذبه الهموم الموفق في كل امر القادر على التلذذ بالطعام"},{"n":3,"text":"ايها الموت حسن قضاؤك للانسان المعوز الضعيف القوة"},{"n":4,"text":"الهرم الذي يتجاذبه كل هم القنط الفاقد الصبر"},{"n":5,"text":"لا تخش قضاء الموت اذكر اوائلك واواخرك هذا هو قضاء الرب على كل ذي جسد"},{"n":6,"text":"وماذا ترفض مما هو مرضاة العلي عشر سنين كانت مرضاته ام مئة ام الفا"},{"n":7,"text":"انه ليس في الجحيم حساب على العمر"},{"n":8,"text":"بنو الخطاة بنو رجس وكذلك الذين يترددون الى بيوت المنافقين"},{"n":9,"text":"بنو الخطاة يهلك ميراثهم ويلازم ذريتهم العار"},{"n":10,"text":"الاب المنافق يتشكى منه بنوه لانهم بسببه يلحقهم العار"},{"n":11,"text":"ويل لكم ايها الرجال المنافقون النابذون لشريعة الاله العلي"},{"n":12,"text":"فانكم اذ ولدتم انما ولدتم للعنة ومتى متم فاللعنة هي نصيبكم"},{"n":13,"text":"كل ما هو من الارض يذهب الى الارض كذلك المنافقون يذهبون من اللعنة الى الهلاك"},{"n":14,"text":"الناس ينوحون على اجسادهم لكن اسم الخطاة يمحى"},{"n":15,"text":"ليكن اهتمامك بالاسم فانه ادوم لك من الف كنز عظيم من الذهب"},{"n":16,"text":"الحياة الصالحة ايام معدودات اما الاسم الصالح فيدوم الى الابد"},{"n":17,"text":"احفظوا التاديب في السلام ايها البنون اما الحكمة المكتومة والكنز المدفون فاية منفعة فيهما"},{"n":18,"text":"الانسان الذي يكتم حماقته خير من الانسان الذي يكتم حكمته"},{"n":19,"text":"استحيوا مما اقول لكم"},{"n":20,"text":"فانه ليس بحسن الخجل من كل شيء ولا امر مما يصنع برشد يعجب كل انسان"},{"n":21,"text":"اخجلوا امام الاب والام من الزنى وامام الرئيس والمقتدر من الكذب"},{"n":22,"text":"وامام القاضي والامير من الزلة وامام المجمع والشعب من الاثم"},{"n":23,"text":"وامام الشريك والصديق من الظلم وامام بلد سكناك من السرقة"},{"n":24,"text":"ومن مخالفة حق الله وعهده ومن اتكاء المرفق على الخبز ومن الخيانة في الاخذ والعطاء"},{"n":25,"text":"ومن السكوت امام الذين يسلمون عليك ومن النظر الى المراة البغي"},{"n":26,"text":"ومن اعراض وجهك عن نسيبك ومن سلب النصيب والعطاء"},{"n":27,"text":"ومن التفرس في امراة ذات بعل ومن مراودة جاريتها وعلى سريرها لا تقف"},{"n":28,"text":"ومن كلام التعيير امام الاصدقاء ومن الامتنان بعد العطاء ومن نقل الكلام المسموع وافشاء ما قيل في السر"}]},{"label":"سفر يشوع بن سيراخ 42","verses":[{"n":1,"text":"حينئذ يكون خجلك في محله وتنال حظوة امام كل انسان اما هذه فلا تخجل فيها ولا تحاب الوجوه لتخطا فيها"},{"n":2,"text":"شريعة العلي والميثاق والقضاء بحيث لا يبرا المنافق"},{"n":3,"text":"ودعوى صاحبك مع المتغربين واقتسام الميراث بين الاصدقاء"},{"n":4,"text":"وعدل الميزان والمعيار والمكسب كثر ام قل"},{"n":5,"text":"والاعتدال في البيع بين المشترين والمبالغة في تاديب البنين وضرب العبد الشرير حتى تدمي جنبه"},{"n":6,"text":"والختم على المراة الشريرة اليق بها"},{"n":7,"text":"وحيث تكون الايدي الكثيرة اقفل ومتى قسمت فبالعدد والوزن والعطاء والاخذ كل شيء ليكن في دفتر"},{"n":8,"text":"ولا تخجل في تاديب الجاهل والاحمق والهرم المتحاكم الى الشبان حينئذ تكون متادبا في الحقيقة وممدوحا امام كل حي"},{"n":9,"text":"البنت سهاد خفي لابيها وهم يسلبه النوم مخافة من العنوس اذا شبت والصلف اذا تزوجت"},{"n":10,"text":"وفي عذرتها من التدنس والعلوق في بيت ابيها وفي الزواج من التعدي على رجلها او العقم"},{"n":11,"text":"واظب على مراقبة البنت القليلة الحياء لئلا تجعلك شماتة لاعدائك وحديثا في المدينة ومذمة لدى الشعب فتخزيك في الملا \nالكثير"},{"n":12,"text":"لا تتفرس في جمال احد ولا تجلس بين النساء"},{"n":13,"text":"فانه من الثياب يتولد السوس ومن المراة الخبث"},{"n":14,"text":"رجل يسيء خير من امراة تحسن ثم تجلب الخزي والفضيحة"},{"n":15,"text":"اني اذكر اعمال الرب واخبر بما رايت ان في اقوال الرب اعماله"},{"n":16,"text":"عين الشمس المنيرة تبصر كل شيء وعمل الرب مملوء من مجده"},{"n":17,"text":"الم ينطق الرب القديسين بجميع عجائبه التي اثبتها الرب القدير لكي يثبت كل الخلق في مجده"},{"n":18,"text":"انه بحث الغمر والقلب وفطن لكل دهاء"},{"n":19,"text":"علم الرب كل علم واطلع على علامة الدهر مخبرا بالماضي والمستقبل وكاشفا عن اثار الخفايا"},{"n":20,"text":"لا يفوته فكر ولا يخفى عليه كلام"},{"n":21,"text":"وقد زين عظائم حكمته وهو الدائم منذ الدهر والى الدهر ولم يزد شيئا"},{"n":22,"text":"ولم ينقص ولا يحتاج الى مشورة"},{"n":23,"text":"ما اشهى جميع اعماله والذي يرى منها مثل شرارة"},{"n":24,"text":"كل هذه تحيا وتبقى الى الابد لكل فائدة وجميعها تطيعه"},{"n":25,"text":"كل شيء اثنان واحد بازاء الاخر ولم يصنع شيئا ناقصا"},{"n":26,"text":"بل الواحد يؤيد مزايا الاخر فمن الذي يشبع من النظر الى مجده"}]},{"label":"سفر يشوع بن سيراخ 43","verses":[{"n":1,"text":"الجلد الطاهر فخر العلاء ومنظر السماء مراى مجده"},{"n":2,"text":"الشمس عند خروجها تبشر بمراها هي الة عجيبة صنع العلي"},{"n":3,"text":"عند هاجرتها تيبس البقعة فمن يقوم امام حرها الشمس كنافخ في الاتون لما يصنع في النار"},{"n":4,"text":"تحرق الجبال ثلاثة اضعاف وتبعث ابخرة نارية وتلمع باشعة تجهر العيون"},{"n":5,"text":"عظيم الرب صانعها الذي بامره تسرع في سيرها"},{"n":6,"text":"والقمر بجميع احواله الموقتة هو نبا الازمنة وعلامة الدهر"},{"n":7,"text":"من القمر علامة العيد هو نير ينقص عند التمام"},{"n":8,"text":"باسمه سمي الشهر وفي تغيره يزداد زيادة عجيبة"},{"n":9,"text":"ان في العلاء محلة عسكر تتلالا في جلد السماء"},{"n":10,"text":"هناك بهاء السماء ومجد النجوم وعالم متالق والرب في الاعالي"},{"n":11,"text":"عند كلام القدوس تقوم لاجراء احكامه ولا ياخذها في محارسها فتور"},{"n":12,"text":"انظر الى قوس الغمام وبارك صانعها ان رونقها في غاية الجمال"},{"n":13,"text":"تنطق السماء منطقة مجد ويد العلي تمدانها"},{"n":14,"text":"بامره عجل الثلج ورشق بروق قضائه"},{"n":15,"text":"وبه انفتحت الكنوز وطارت الغيوم كذوات الاجنحة"},{"n":16,"text":"بعظمته شدد الغيوم فانقضت حجارة البرد"},{"n":17,"text":"بلحظاته تتزلزل الجبال وبارادته تهب الجنوب"},{"n":18,"text":"عند صوت رعده تتمخض الارض عند عاصفة الشمال وزوبعة الريح"},{"n":19,"text":"يذري الثلج كما يتطاير ذوات الاجنحة وانحداره كنزول الجراد"},{"n":20,"text":"تعجب العين من حسن بياضه وينذهل القلب من مطره"},{"n":21,"text":"ويسكب الصقيع كالملح على الارض واذا جمد صار كاطراف الاوتاد"},{"n":22,"text":"تهب ريح الشمال الباردة فيجمد الماء يستقر الجليد على كل مجتمع المياه ويلبس المياه درعا"},{"n":23,"text":"تاكل الجبال وتحرق الصحراء وتتلف الخضر كالنار"},{"n":24,"text":"يسرع الغمام فيشفي كل شيء والندى الناشئ من الحر يعيد البهجة"},{"n":25,"text":"بكلامه طامن الغمر وانبت فيه الجزائر"},{"n":26,"text":"الذين يركبون البحر يحدثون بهوله نسمع باذاننا فنتعجب"},{"n":27,"text":"هناك المصنوعات العجيبة الغريبة انواع الحيوانات خلائق الحيتان"},{"n":28,"text":"به ينتهي الى النجاح وبكلمته يقوم الجميع"},{"n":29,"text":"انا نكثر الكلام ولا نستقصي وغاية ما يقال انه هو الكل"},{"n":30,"text":"ماذا نستطيع من تمجيده وهو العظيم فوق جميع مصنوعاته"},{"n":31,"text":"مرهوب الرب وعظيم جدا وقدرته عجيبة"},{"n":32,"text":"ارفعوا الرب في تمجيده ما استطعتم فلا يزال ارفع"},{"n":33,"text":"باركوا الرب وارفعوه ما قدرتم فانه اعظم من كل مدح"},{"n":34,"text":"بالغوا في رفعه قدر طاقتكم لا تكلوا فانكم لن تدركوه"},{"n":35,"text":"من راه فيخبر ومن يكبره كما هو"},{"n":36,"text":"وهناك خفايا كثيرة اعظم من هذه فان الذي رايناه من اعماله هو القليل"},{"n":37,"text":"ان الرب صنع كل شيء واتى الاتقياء الحكمة"}]},{"label":"سفر يشوع بن سيراخ 44","verses":[{"n":1,"text":"لنمدح الرجال النجباء اباءنا الذين ولدنا منهم"},{"n":2,"text":"فيهم انشا الرب مجدا كثيرا وابدى عظمته منذ الدهر"},{"n":3,"text":"وقد كانوا ذوي سلطان في ممالكهم رجال اسم وباس مؤتمرين بفطنتهم ناطقين بالنبوءات"},{"n":4,"text":"ائمة الشعب بمشوراتهم وبفهم كتب امتهم"},{"n":5,"text":"قد ضمنوا تاديبهم اقوال الحكمة وبحثوا في الحان الغناء وانشدوا قصائد الكتاب"},{"n":6,"text":"رجال غنى واقتدار فاعلي سلامة في بيوتهم"},{"n":7,"text":"اولئك كلهم نالوا مجدا في اجيالهم وكانت ايامهم ايام فخر"},{"n":8,"text":"فمنهم من خلفوا اسما يخبر بمدائحهم"},{"n":9,"text":"ومنهم من لا ذكر لهم وقد هلكوا كانهم لم يكونوا قط وولدوا كانهم لم يولدوا هم وبنوهم بعدهم"},{"n":10,"text":"اما اولئك فهم رجال رحمة وبرهم لا ينسى"},{"n":11,"text":"الميراث الصالح يدوم مع ذريتهم واعقابهم يبقون على المواعيد"},{"n":12,"text":"تثبت ذريتهم وبنوهم لاجلهم"},{"n":13,"text":"الى الابد تدوم ذريتهم ولا يمحى مجدهم"},{"n":14,"text":"اجسامهم دفنت بالسلام واسماؤهم تحيا مدى الاجيال"},{"n":15,"text":"الشعوب يحدثون بحكمتهم والجماعة تخبر بمدحتهم"},{"n":16,"text":"اخنوخ ارضى الرب فنقل وسينادي الاجيال الى التوبة"},{"n":17,"text":"نوح وجد برا كاملا وبه كانت المصالحة في زمان الغضب"},{"n":18,"text":"فلذلك ابقيت بقية على الارض حين كان الطوفان"},{"n":19,"text":"واقيمت معه عهود لكي لا يهلك بالطوفان كل ذي جسد"},{"n":20,"text":"ابراهيم كان ابا عظيما لامم كثيرة ولم يوجد نظيره في المجد وقد حفظ شريعة العلي فعاهده عهدا"},{"n":21,"text":"وجعل العهد في جسده وعند الامتحان وجد امينا"},{"n":22,"text":"فلذلك حلف له ان الامم سيباركون في نسله وانه يكثر نسله كتراب الارض"},{"n":23,"text":"ويعلي ذريته كنجوم ويورثهم من البحر الى البحر ومن النهر الى اقصى الارض"},{"n":24,"text":"وكذلك جعل في اسحق لاجل ابراهيم ابيه"},{"n":25,"text":"بركة جميع الناس والعهد ثم اقرهما على راس يعقوب"},{"n":26,"text":"اثره ببركاته وورثه الميراث ميز حظوظه وقسمها على الاسباط الاثني عشر"},{"n":27,"text":"واقام منه رجل رحمة قد نال حظوة امام كل بشر"}]},{"label":"سفر يشوع بن سيراخ 45","verses":[{"n":1,"text":"موسى كان محبوبا عند الله والناس مبارك الذكر"},{"n":2,"text":"فاتاه مجدا كمجد القديسين وجعله عظيما مرهوبا عند الاعداء بكلامه ازال الايات"},{"n":3,"text":"ومجده امام الملوك اوصاه بشعبه واراه مجده"},{"n":4,"text":"قدسه بايمانه ووداعته واصطفاه من بين جميع البشر"},{"n":5,"text":"اسمعه صوته وادخله في الغمام"},{"n":6,"text":"اعطاه الوصايا مواجهة شريعة الحياة والعلم ليعلم يعقوب العهد واسرائيل احكامه"},{"n":7,"text":"اعلى هرون القديس نظيره اخاه من سبط لاوي"},{"n":8,"text":"جعل له عهد الدهر واعطاه كهنوت الشعب اسعده في البهاء"},{"n":9,"text":"ونطقه حلة مجد البسه كمال الفخر وايده بادوات العزة"},{"n":10,"text":"السراويل والثوب السابغ والافود وجعل حوله الرمانات من ذهب مع جلاجل كثيرة من حوله"},{"n":11,"text":"ليرن صوتها عند خطوه ليسمع الصليل في الهيكل ذكرا لبني شعبه"},{"n":12,"text":"واعطاه الحلة المقدسة من ذهب وسمنجوني وارجوان صنعة نساج حاذق صدرة القضاء التي فيها النور والحق"},{"n":13,"text":"نسيجها من قرمز مشزور صنعة عامل حاذق وعليها حجارة كريمة كنقش الخاتم مرصعة في الذهب صنعة نقاش الجوهر منقوش عليها \nاسماء اسباط اسرائيل ذكرا"},{"n":14,"text":"وكان على العمامة اكليل من ذهب منقوش عليه عنوان القداسة وكان زينة كرامة صنعة براعة تعشقها العيون لحسنها"},{"n":15,"text":"كل هذه كانت في غاية الجمال ولم يكن لها مثيل في الدهر"},{"n":16,"text":"لم يلبسها الا من هو من عشيرته بنوه واعقابه في كل عهد"},{"n":17,"text":"ذبائحه تحرق بالنار كل يوم مرتين بلا انقطاع"},{"n":18,"text":"كرس موسى يديه ومسحه بالدهن المقدس"},{"n":19,"text":"فصار ذلك عهدا ابديا له ولذريته ما دامت السماء ليخدم للرب ويمارس الكهنوت ويبارك شعبه باسمه"},{"n":20,"text":"اصطفاه من بين جميع الاحياء ليقرب التقدمة للرب البخور والرائحة الطيبة ذكرا وتكفيرا عن شعبه"},{"n":21,"text":"اقامه على وصاياه واعطاه سلطانا على عهود الاحكام ليعلم يعقوب الشهادات وينير اسرائيل بشريعته"},{"n":22,"text":"اجتمع عليه الغرباء وحسدوه في البرية رجال داتان وابيرام وجماعة قورح بالحدة والغضب"},{"n":23,"text":"نظر الرب فلم يرض فابادهم بحدة غضبه"},{"n":24,"text":"اجرى بهم عجائب وافناهم بنار لهيبه"},{"n":25,"text":"وزاد هرون مجدا واعطاه ميراثا جعل لهم بواكير ثمار الارض"},{"n":26,"text":"وهيا لهم قبل غيرهم شبعهم من الخبز فهم ياكلون من ذبائح الرب التي اعطاها له ولذريته"},{"n":27,"text":"الا انه لم يرث في ارض الشعب ولم يكن له نصيب فيما بينهم لانه هو نصيبه وميراثه"},{"n":28,"text":"وفنحاس ابن العازار هو الثالث في المجد لاجل غيرته في مخافة الرب"},{"n":29,"text":"ولانه قام عند ارتداد الشعب بصلاح نشاط نفسه وكفر عن اسرائيل"},{"n":30,"text":"لذلك اعطاه الرب عهد سلامه لكي يكون امام شعبه في الاقداس وتبقى له ولنسله عظمة الكهنوت مدى الدهور"},{"n":31,"text":"وعاهد داود بن يسى من سبط يهوذا على ميراث الملك من ابن الى ابن في ذريته كالميراث لهرون ونسله ليعطكم الحكمة \nفيقلوبكم لكي تحكموا بالعدل في شعبه فلا تزول خيراتهم ومجدهم مدى اجيالهم"}]},{"label":"سفر يشوع بن سيراخ 46","verses":[{"n":1,"text":"كان يشوع بن نون رجل باس في الحروب خليفة موسى في النبوءات"},{"n":2,"text":"وكان كاسمه عظيما في خلاص مختاريه شديد الانتقام على الاعداء المقاومين لكي يورث اسرائيل"},{"n":3,"text":"ما اعظم مجده عند رفع يديه وتسديد حربته على المدن"},{"n":4,"text":"من قام نظيره من قبله ان الرب نفسه دفع اليه الاعداء"},{"n":5,"text":"الم ترجع الشمس الى الوراء على يده وصار اليوم نحوا من يومين"},{"n":6,"text":"دعا العلي القدير اذ كان يهزم الاعداء من كل جهة فاستجاب له الرب العظيم بحجارة برد عظيمة الثقل"},{"n":7,"text":"اغار على الامة بالقتال وفي المنهبط اهلك المقاومين"},{"n":8,"text":"لكي تعرف الامم كمال عدتهم وان حربه امام الرب لانه منقاد للقدير"},{"n":9,"text":"وفي ايام موسى صنع رحمة هو وكالب بن يفنا اذ قاما على العدو وردا الشعب عن الخطيئة وسكنا تذمر السوء"},{"n":10,"text":"وهما وحدهما ابقيا من الست مئة الف راجل ليدخلاهم الى الميراث الى ارض تدر لبنا وعسلا"},{"n":11,"text":"واتى الرب كالب قوة وبقيت معه الى شيخوخته فصعد الى ذلك الموضع المرتفع من الارض الذي نالته ذريته ميراثا"},{"n":12,"text":"لكي يعلم جميع بني اسرائيل ان الانقياد للرب حسن"},{"n":13,"text":"والقضاة كل منهم باسمه الذين لم تزن قلوبهم على الرب ولم يرتدوا عنه"},{"n":14,"text":"ليكن ذكرهم مباركا ولتزهر عظامهم من مواضعها"},{"n":15,"text":"وليتجدد اسمهم وليمجدهم بنوهم"},{"n":16,"text":"صموئيل المحبوب عند الرب نبي الرب سن الملك ومسح رؤساء شعبه"},{"n":17,"text":"قضى للجماعة بحسب شريعة الرب وافتقد الرب يعقوب"},{"n":18,"text":"بايمانه اختبر انه نبي وبايمانه علم انه صادق الرؤيا"},{"n":19,"text":"دعا الرب القدير عندما كان اعداؤه يضيقون من كل جهة واصعد حملا رضيعا"},{"n":20,"text":"فارعد الرب من السماء وبقصيف عظيم اسمع صوته"},{"n":21,"text":"وحطم رؤساء الصوريين وجميع اقطاب فلسطين"},{"n":22,"text":"وقبل رقاده عن الدهر شهد امام الرب ومسيحه اني لم اخذ من احد من البشر مالا بل ولا حذاء ولم يشكه انسان"},{"n":23,"text":"ومن بعد رقاده تنبا واخبر الملك بوفاته ورفع من الارض صوته بالنبوءة لمحو اثم الشعب"}]},{"label":"سفر يشوع بن سيراخ 47","verses":[{"n":1,"text":"وبعد ذلك قام ناتان وتنبا في ايام داود"},{"n":2,"text":"كما يفصل الشحم من ذبيحة الخلاص هكذا فصل داود من بين بني اسرائيل"},{"n":3,"text":"لاعب الاسود ملاعبته الجداء والادباب كانها حملان الضان"},{"n":4,"text":"الم يقتل الجبار وهو شاب الم يرفع العار عن شعبه"},{"n":5,"text":"اذ رفع يده بحجر المقلاع وحط صلف جليات"},{"n":6,"text":"لانه دعا الرب العلي فاعطى يمينه قوة ليقتل رجلا شديد القتال ويعلي قرن شعبه"},{"n":7,"text":"فاعطاه الرب مجد قاتل ربوات ومدحه ببركاته اذ نقل اليه تاج المجد"},{"n":8,"text":"فانه حطم الاعداء من كل جهة وافنى الفلسطينيين المناصبين وحطم قرنهم الى يومنا هذا"},{"n":9,"text":"في جميع اعماله اعترف للقدوس العلي بكلام مجد"},{"n":10,"text":"بكل قلبه سبح واحب صانعه"},{"n":11,"text":"اقام المغنين امام المذبح ولقنهم الحانا لذيذة السماع"},{"n":12,"text":"جعل للاعياد رونقا وللمواسم زينة الى الانقضاء لكي يسبح اسمه القدوس ويرنم في قدسه منذ الصباح"},{"n":13,"text":"الرب غفر خطاياه واعلى قرنه الى الابد عاهده على الملك وعرش المجد في اسرائيل"},{"n":14,"text":"بعده قام ابن حكيم وعلى يده استراح في الرحب"},{"n":15,"text":"ملك سليمان ايام سلام واراحه الله من كل جهة لكي يشيد بيتا لاسمه ويهيئ قدسا الى الابد"},{"n":16,"text":"ما اعظم حكمتك في صبائك وفطنتك التي طفحت بها مثل النهر فان قريحتك عمت الارض"},{"n":17,"text":"فملاتها من امثال الاحاجي بلغ اسمك الى الجزائر البعيدة واحببت لاجل سلامك"},{"n":18,"text":"اعجبت الافاق بما لك من الاغاني والامثال والالغاز والتفاسير"},{"n":19,"text":"باسم الرب الاله الموصوف باله اسرائيل"},{"n":20,"text":"جمعت الذهب كالقصدير والفضة كالرصاص"},{"n":21,"text":"املت فخذيك الى النساء فاستولين على جسدك"},{"n":22,"text":"جعلت عيبا في مجدك ونجست نسلك فجلبت الغضب على بنيك لقد صدعت قلبي جهالتك"},{"n":23,"text":"حتى قسم السلطان الى قسمين ونشا من افرائيم ملك متمرد"},{"n":24,"text":"لكن الرب لا يترك رحمته ولا يفسد من اعماله شيئا لا يدمر اعقاب مصطفاه ولا يهلك ذرية محبه"},{"n":25,"text":"فابقى ليعقوب بقية ولداود جرثومة منه"},{"n":26,"text":"واستراح سليمان مع ابائه"},{"n":27,"text":"وخلف بعده ذا سفه عند الشعب من نسله"},{"n":28,"text":"رحبعام السخيف الراي الذي بعث بمشورته الشعب على التمرد"},{"n":29,"text":"وياربعام بن ناباط الذي اثم اسرائيل وسن لافرائيم طريق الخطيئة فكثرت خطاياهم"},{"n":30,"text":"جدا حتى اجلتهم عن ارضهم"},{"n":31,"text":"والتمسوا كل شر حتى حل بهم الانتقام"}]},{"label":"سفر يشوع بن سيراخ 48","verses":[{"n":1,"text":"وقام ايليا النبي كالنار وتوقد كلامه كالمشعل"},{"n":2,"text":"بعث عليهم الجوع وبغيرته ردهم نفرا قليلا"},{"n":3,"text":"اغلق السماء بكلام الرب وانزل منها نارا ثلاث مرات"},{"n":4,"text":"ما اعظم مجدك يا ايليا بعجائبك ومن له فخر كفخرك"},{"n":5,"text":"انت الذي اقمت ميتا من الموت ومن الجحيم بكلام العلي"},{"n":6,"text":"واهبطت الملوك الى الهلاك والمفتخرين من اسرتهم"},{"n":7,"text":"وسمعت في سيناء القضاء وفي حوريب احكام الانتقام"},{"n":8,"text":"ومسحت ملوكا للنقمة وانبياء خلائف لك"},{"n":9,"text":"وخطفت في عاصفة من النار في مركبة خيل نارية"},{"n":10,"text":"وقد اكتتبك الرب لاقضية تجرى في اوقاتها ولتسكين الغضب قبل حدته ورد قلب الاب الى الابن واصلاح اسباط يعقوب"},{"n":11,"text":"طوبى لمن عاينك ولمن حاز فخر مصافاتك"},{"n":12,"text":"انا نحيا هذه الحياة وبعد الموت لا يكون لنا مثل هذا الاسم"},{"n":13,"text":"وتوارى ايليا في العاصفة فامتلا اليشاع من روحه وفي ايامه لم يتزعزع مخافة من ذي سلطان ولم يستول عليه احد"},{"n":14,"text":"لم يغلبه كلام وفي رقاد الموت جسده تنبا"},{"n":15,"text":"صنع في حياته الايات وبعد موته الاعمال العجيبة"},{"n":16,"text":"ومع هذه كلها لم يتب الشعب ولم يقلعوا عن الخطايا الى ان طردوا من ارضهم وتبددوا في كل الارض"},{"n":17,"text":"وابقى شعب قليل ورؤساء لبيت داود"},{"n":18,"text":"بعضهم صنعوا المرضي وبعضهم اكثروا من الخطايا"},{"n":19,"text":"حزقيا حصن مدينته وادخل اليها ماء جيحون حفر الصخر بالحديد وبنى ابارا للماء"},{"n":20,"text":"في ايامه صعد سنحاريب وبعث ربشاقا فاقبل ورفع يده على صهيون وتنفخ بكبريائه"},{"n":21,"text":"حينئذ ارتجفت قلوبهم وايديهم وتمخضوا كالوالدات"},{"n":22,"text":"فدعوا الرب الرحيم باسطين اليه ايديهم فالقدوس من السماء استجاب لهم سريعا"},{"n":23,"text":"وافتداهم على يد اشعيا"},{"n":24,"text":"ضرب محلة اشور وملاكه حطمهم"},{"n":25,"text":"لان حزقيا صنع المرضي امام الرب وجد في السلوك في طرق داود ابيه التي اوصاه بها اشعيا النبي العظيم الصادق في رؤياه"},{"n":26,"text":"في ايامه رجعت الشمس الى الوراء وهو زاد على عمر الملك"},{"n":27,"text":"بروح عظيم راى العواقب وعزى النائحين في صهيون"},{"n":28,"text":"كشف عما سيكون على مدى الدهور وعن الخفايا قبل حدوثها"}]},{"label":"سفر يشوع بن سيراخ 49","verses":[{"n":1,"text":"ذكر يوشيا مزاج طيب قد عبئ بصناعة العطار"},{"n":2,"text":"في كل فم يحلو كالعسل وهو كالغناء في مجلس الخمر"},{"n":3,"text":"اقيم ليتوب الشعب على يده فرفع ارجاس الاثم"},{"n":4,"text":"وجه قلبه الى الرب وفي ايام الاثماء وطد التقوى"},{"n":5,"text":"كلهم اجرموا ما خلا داود وحزقيا ويوشيا"},{"n":6,"text":"تركوا شريعة العلي ارتد ملوك يهوذا"},{"n":7,"text":"دفعوا قرنهم الى غيرهم ومجدهم الى امة غريبة"},{"n":8,"text":"احرقوا بالنار مدينة القدس المختارة وخربوا طرقها على يد ارميا"},{"n":9,"text":"فانهم اساءوا اليه وهو قد قدس في جوف امه نبيا ليستاصل ويسيء ويهلك وايضا ليبني ويغرس"},{"n":10,"text":"وراى حزقيال رؤيا المجد التي اراه اياها بمركبة الكروبين"},{"n":11,"text":"انذر الاعداء بالمطر ووعد المستقيمين في طرقهم بالاحسان"},{"n":12,"text":"لتزهر عظام الانبياء الاثني عشر من مكانها فانهم عزوا يعقوب وافتدوهم بايمان الرجاء"},{"n":13,"text":"كيف نعظم زربابل انه كخاتم في اليد اليمنى"},{"n":14,"text":"كذلك يشوع بن يوصاداق فانهما في ايامهما بنيا البيت ورفعا شان الشعب المقدس للرب المهيا لمجد ابدي"},{"n":15,"text":"ونحميا يكون ذكره طول الايام فانه اقام لنا السور المنهدم ونصب الابواب والمزاليج ورم منازلنا"},{"n":16,"text":"لم يخلق على الارض احد مثل اخنوخ الذي نقل عن الارض"},{"n":17,"text":"ولم يولد رجل مثل يوسف رئيس اخوته وعمدة الشعب"},{"n":18,"text":"عظامه افتقدت وبعد موته تنبات"},{"n":19,"text":"سام وشيث ممجدان بين الناس وفوق كل نفس في الخلق ادم"}]},{"label":"سفر يشوع بن سيراخ 50","verses":[{"n":1,"text":"سمعان بن اونيا الكاهن العظيم رم البيت في حياته ووثق الهيكل في ايامه"},{"n":2,"text":"واسس سمكا مضاعفا تحصينا شامخا حول الهيكل"},{"n":3,"text":"في ايامه استنبطت ابار المياه وكالبحر تناهت في الفيضان"},{"n":4,"text":"هو الذي اهتم بشعبه لئلا يهلك وحصن المدينة لئلا تفتح"},{"n":5,"text":"ما امجده في تصرفه بين الشعب وفي خروجه من وراء حجاب البيت"},{"n":6,"text":"مثله مثل كوكب الصبح بين الغمام او البدر ايام تمامه"},{"n":7,"text":"او الشمس المشرقة على هيكل العلي"},{"n":8,"text":"او القوس المتلالئة بين سحب البهاء او زهر الورد في ايام الربيع او الزنبق على مجاري المياه او نبات لبنان في ايام \nالصيف"},{"n":9,"text":"او النار او اللبان على المجمرة"},{"n":10,"text":"او اناء الذهب المصمت المزين بكل حجر كريم"},{"n":11,"text":"او الزيتون المثمر او السرو المرتفع الى السحب اذ كان ياخذ حلة مجده ويلبس كمال زينته"},{"n":12,"text":"ويصعد الى المذبح المقدس كان يزيد لباس القدس بهاء"},{"n":13,"text":"واذ كان يتناول اعضاء الذبيحة من ايدي الكهنة وهو واقف على موقد المذبح كان يحيط به اكليل من الاخوة احاطة الفروع \nبارزلبنان"},{"n":14,"text":"والشطب بالنخل وكان جميع بني هرون في مجدهم"},{"n":15,"text":"وتقدمة الرب في ايديهم امام كل جماعة اسرائيل وكان هو عند اتمام خدمته على المذبح لتزيين تقدمة العلي القدير"},{"n":16,"text":"يمد يده على المسكب ويسكب من دم العنب"},{"n":17,"text":"يصبه على اسس المذبح رائحة مرضية امام العلي ملك الجميع"},{"n":18,"text":"حينئذ كان بنو هرون يهتفون بالابواق المطروقة ويسمعون صوتا عظيما ذكرا امام العلي"},{"n":19,"text":"وكان عند ذلك كل الشعب يبادرون معا ويخرون على وجوههم الى الارض ساجدين لربهم القدير لله العلي"},{"n":20,"text":"وكان المغنون يسبحون باصواتهم ويسمعون في البيت المعظم الحانهم اللذيذة"},{"n":21,"text":"وكان الشعب يتضرعون الى الرب العلي بصلاتهم امام الرحيم الى ان يفرغ من اكرام الرب وتتم خدمته"},{"n":22,"text":"ثم كان ينزل ويرفع يديه على كل جماعة بني اسرائيل مباركا الرب بشفتيه ومفتخرا باسمه"},{"n":23,"text":"ويكرر سجوده ليظهر ان البركة من لدن العلي"},{"n":24,"text":"فالان يا جميع الناس باركوا الله الذي يصنع العظائم في كل مكان ويزيد ايامنا منذ الرحم ويعاملنا على حسب رحمته"},{"n":25,"text":"ليمنحنا سرور القلب والسلام في اسرائيل في ايامنا وعلى مدى الدهور"},{"n":26,"text":"مقرا علينا رحمته ومفتديا لنا في ايامه"},{"n":27,"text":"امتان مقتتهما نفسي والثالثة ليست بامة"},{"n":28,"text":"الساكنون في جبل السامرة والفلسطينيون والشعب الاحمق الساكن في شكيم"},{"n":29,"text":"قد رسم تاديب العقل والعلم في هذا الكتاب يشوع بن سيراخ الاورشليمي الذي افاض الحكمة من قلبه"},{"n":30,"text":"طوبى لمن يواظب على هذه فان الذي يجعلها في قلبه يكون حكيما"},{"n":31,"text":"واذا عمل بها يقدر على كل شيء لان نور الرب دليله"}]},{"label":"سفر يشوع بن سيراخ 51","verses":[{"n":1,"text":"صلاة يشوع بن سيراخ اعترف لك ايها الرب الملك واسبح الله مخلصي"},{"n":2,"text":"اعترف لاسمك لانك كنت لي مجيرا ونصيرا"},{"n":3,"text":"وافتديت جسدي من الهلاك ومن شرك سعاية اللسان ومن شفاه مختلقي الزور وكنت لي ناصرا تجاه المقاومين"},{"n":4,"text":"وافتديتني برحمتك الغزيرة واسمك من زئير المستعدين للافتراس"},{"n":5,"text":"من ايدي طالبي نفسي ومن مضايقي الكثيرة"},{"n":6,"text":"من الاختناق باللهيب المحيط بي ومن وسط النار حتى لا اصلى"},{"n":7,"text":"من عمق جوف الجحيم ومن اللسان الدنس وكلام الزور وسعاية اللسان الجائر عند الملك"},{"n":8,"text":"دنت نفسي من الموت"},{"n":9,"text":"واقتربت حياتي من عمق الجحيم"},{"n":10,"text":"احيط بي من كل جهة ولا نصير التفت لاغاثة الناس فلم تكن"},{"n":11,"text":"فتذكرت رحمتك ايها الرب وصنيعك الذي منذ الدهر"},{"n":12,"text":"كيف تنقذ الذين ينتظرونك وتخلصهم من ايدي الامم"},{"n":13,"text":"فرفعت من الارض صلاتي وتضرعت لانقذ من الموت"},{"n":14,"text":"دعوت الرب ابا ربي لئلا يخذلني في ايام الضيق في عهد المتكبرين الخاذلين لي"},{"n":15,"text":"اني اسبح اسمك في كل حين وارنم له بالاعتراف لان صلاتي قد استجيبت"},{"n":16,"text":"فانك قد خلصتني من الهلكة وانقذتني من زمان السوء"},{"n":17,"text":"فلذلك اعترف لك واسبحك وابارك اسم الرب"},{"n":18,"text":"في صبائي قبل ان اتيه التمست الحكمة علانية في صلاتي"},{"n":19,"text":"امام الهيكل ابتهلت لاجلها والى اواخري التمسها فازهرت كباكورة العنب"},{"n":20,"text":"ابتهج بها قلبي ودرجت قدمي في الاستقامة ومنذ صبائي جددت في اثرها"},{"n":21,"text":"املت اذني قليلا ووعيت"},{"n":22,"text":"فوجدت لنفسي تاديبا كثيرا وكان لي فيها نجح عظيم"},{"n":23,"text":"ان الذي اتاني حكمة اوتيه تمجيدا"},{"n":24,"text":"فاني عزمت ان اعمل بها وقد حرصت على الخير ولست اخزى"},{"n":25,"text":"جاهدت نفسي لاجلها وفي اعمالي لم ابرح متنطسا"},{"n":26,"text":"مددت يدي الى العلاء وبكيت على جهالاتي"},{"n":27,"text":"وجهت نفسي اليها وبالطهارة وجدتها"},{"n":28,"text":"بها ملكت قلبي من البدء فلذلك لا اخذل"},{"n":29,"text":"وجوفي اضطرب في طلبها فلذلك اقتنيت قنية صالحة"},{"n":30,"text":"اعطاني الرب اللسان جزاء فبه اسبحه"},{"n":31,"text":"ادنوا مني ايها الغير المتادبين وامكثوا في منزل التاديب"},{"n":32,"text":"لماذا تتقاعدون عن هذه ونفوسكم ظامئة جدا"},{"n":33,"text":"اني فتحت فمي وتكلمت دونكم كسبا بلا فضة"},{"n":34,"text":"اخضعوا رقابكم تحت النير ولتتخذ نفوسكم التاديب فان وجدانه قريب"},{"n":35,"text":"انظروا باعينكم كيف تعبت قليلا فوجدت لنفسي راحة كثيرة"},{"n":36,"text":"نالوا التاديب كمقدار كثير من الفضة واكتسبوا به ذهبا كثيرا"},{"n":37,"text":"تبتهج نفوسكم برحمته ولا تخزوا بمدحته"},{"n":38,"text":"اعملوا عملكم قبل الاوان فيؤتيكم ثوابكم في اوانه"}]}],"sources":["https://ar.wikisource.org/wiki/سفر_يشوع_بن_سيراخ"]},{"name":"باروخ","chapters":[{"label":"سفر باروخ 1","verses":[{"n":1,"text":"هذا كلام الكتاب الذي كتبه باروك بن نيريا بن معسيا بن صدقيا بن حسديا ابن حلقيا في بابل"},{"n":2,"text":"في السنة الخامسة في السابع من الشهر حين اخذ الكلدانيون اورشليم واحرقوها بالنار"},{"n":3,"text":"وتلا باروك كلام هذا الكتاب على مسمعي يكنيا بن يوياقيم ملك يهوذا وعلى مسامع جميع الشعب الذين جاءوا لاستماع الكتاب"},{"n":4,"text":"وعلى مسامع المقتدرين وبني الملوك ومسامع الشيوخ ومسامع جميع الشعب من الصغار الى الكبار جميع الساكنين في بابل على \nنهر سود"},{"n":5,"text":"فبكوا وصاموا وصلوا امام الرب"},{"n":6,"text":"وجمعوا من الفضة قدر ما استطاعت يد كل واحد"},{"n":7,"text":"وبعثوا الى اورشليم الى يوياقيم بن حلقيا بن شلوم الكاهن والى الكهنة والى جميع الشعب الذين معه في اورشليم"},{"n":8,"text":"عندما اخذ انية بيت الرب المسلوبة من الهيكل ليردها الى ارض يهوذا في العاشر من سيوان وهي انية الفضة التي صنعها \nصدقيا ابن يوشيا ملك يهوذا"},{"n":9,"text":"بعدما اجلى نبوكد نصر ملك بابل يكنيا والرؤساء والمحصنين والمقتدرين وشعب الارض من اورشليم وذهب بهم الى بابل"},{"n":10,"text":"وقالوا انا قد ارسلنا اليكم فضة فابتاعوا بالفضة محرقات وذبائح للخطية ولبانا واصنعوا تقادم وقدموها علىمذبح الرب \nالهنا"},{"n":11,"text":"وصلوا من اجل حياة نبوكد نصر ملك بابل وحياة بلشصر ابنه لكي تكون ايامهما كايام السماء على الارض"},{"n":12,"text":"فيؤتينا الرب قوة وينير عيوننا ونحيا تحت ظل نبوكد نصر ملك بابل وظل بلشصر ابنه ونتعبد لهما اياما كثيرة \nونحننائلون لديهما حظوة"},{"n":13,"text":"وصلوا من اجلنا الى الرب الهنا فانا قد خطئنا الى الرب الهنا ولم يرتد سخط الرب وغضبه عنا الى هذا اليوم"},{"n":14,"text":"واتلوا هذا الكتاب الذي ارسلناه اليكم لينادى به في بيت الرب في يوم العيد وفي ايام المحفل"},{"n":15,"text":"وقولوا للرب الهنا العدل ولنا خزي الوجوه كما في هذا اليوم لرجال يهوذا وسكان اورشليم"},{"n":16,"text":"ولملوكنا ورؤسائنا وكهنتنا وانبيائنا وابائنا"},{"n":17,"text":"لانا خطئنا امام الرب وعصيناه"},{"n":18,"text":"ولم نسمع لصوت الرب الهنا لنسلك في اوامر الرب التي جعلها امام وجوهنا"},{"n":19,"text":"من يوم اخرج الرب اباءنا من ارض مصر الى هذا اليوم ما زلنا نعاصي الرب الهنا ونعرض عن استماع صوته"},{"n":20,"text":"فلحق بنا الشر واللعنة اللذان امر الرب موسى عبده ان يوعد بهما يوم اخرج اباءنا من ارض مصر ليعطينا ارضا تدر لبنا \nوعسلا كما في هذا اليوم"},{"n":21,"text":"فلم نسمع لصوت الرب الهنا ولا لجميع كلام الانبياء الذين ارسلهم الينا"},{"n":22,"text":"ومضينا كل واحد على اصرار قلبه الشرير عابدين الهة اخر صانعين الشر امام عيني الرب الهنا"}]},{"label":"سفر باروخ 2","verses":[{"n":1,"text":"فاقام الرب كلامه الذي تكلم به علينا وعلى قضاتنا الذين يقضون في اسرائيل وعلى ملوكنا ورؤسائنا وعلى رجال اسرائيل ويهوذا"},{"n":2,"text":"جالبا علينا شرا عظيما بحيث لم يحدث تحت السماء باسرها مثل ما احدثه في اورشليم على حسب ما كتب في شريعة موسى"},{"n":3,"text":"حتى اكل بعضنا لحم ابنه والاخر لحم بنته"},{"n":4,"text":"واخضعهم تحت ايدي جميع الممالك التي حولنا وجعلهم عارا ودهشا في جميع الشعوب الذين شتتهم الرب بينهم"},{"n":5,"text":"فاذا هم في الانحطاط بدل الرفعة لانا خطئنا الى الرب الهنا غير سامعين لصوته"},{"n":6,"text":"للرب الهنا العدل ولنا ولابائنا خزي الوجوه كما في هذا اليوم"},{"n":7,"text":"لان الرب تكلم علينا بجميع هذا الشر الذي حل بنا"},{"n":8,"text":"ونحن لم نستعطف وجه الرب تائبين كل واحد عن افكار قلبه الشرير"},{"n":9,"text":"فسهر الرب على الشر وجلبه الرب علينا لان الرب عادل في جميع اعماله التي اوصانا بها"},{"n":10,"text":"فلم نسمع لصوته لنسلك في اوامر الرب التي جعلها امام وجوهنا"},{"n":11,"text":"فالان ايها الرب اله اسرائيل الذي اخرج شعبه من ارض مصر بيد قديرة وبايات ومعجزات وقوة عظيمة وذراع مبسوطة واقام له \nاسما كما في هذا اليوم"},{"n":12,"text":"انا خطئنا ونافقنا واثمنا ايها الرب الهنا في جميع رسومك"},{"n":13,"text":"لينصرف غضبك عنا فقد بقينا نفرا قليلا في الامم الذين شتتنا بينهم"},{"n":14,"text":"اسمع يا رب صلاتنا وتضرعنا وانقذنا لاجلك وانلنا حظوة امام وجوه الذين اجلونا"},{"n":15,"text":"لكي تعرف الارض باسرها انك انت الرب الهنا وانه باسمك دعي اسرائيل وعشائره"},{"n":16,"text":"ايها الرب التفت من بيت قدسك وانظر الينا وامل ايها الرب اذنك واستجب"},{"n":17,"text":"افتح عينيك وانظر فانه ليس الاموات في الجحيم الذين اخذت ارواحهم عن احشائهم يعترفون للرب بالمجد والعدل"},{"n":18,"text":"لكن الروح الكئيب من الشدة والذي يمشي منحنيا ضعيفا والعيون الكليلة والنفس الجائعة هم يعترفون لك بالمجد والعدل \nيا رب"},{"n":19,"text":"فانا لا لاجل بر ابائنا وملوكنا نلقي تضرعنا امامك ايها الرب الهنا"},{"n":20,"text":"بل لانك ارسلت سخطك وغضبك علينا كما تكلمت على السنة عبيدك الانبياء"},{"n":21,"text":"هكذا قال الرب احنوا مناكبكم وتعبدوا لملك بابل فتسكنوا في الارض التي اعطيتها لابائكم"},{"n":22,"text":"وان لم تسمعوا لصوت الرب بان تتعبدوا لملك بابل"},{"n":23,"text":"فاني ابطل من مدن يهوذا ومن شوارع اورشليم صوت الطرب وصوت الفرح صوت العروس وصوت العروسة وتكون كل الارض مستوحشة لا \nساكن فيها"},{"n":24,"text":"فلم نسمع لصوتك بان نتعبد لملك بابل فاقمت كلامك الذي تكلمت به على السنة عبيدك الانبياء ان تخرج عظام ملوكنا وعظام \nابائنا من مواضعها"},{"n":25,"text":"وها انها مطروحة لحر النهار وقرس الليل وقد ماتوا في اوجاع اليمة بالجوع والسيف والطرد"},{"n":26,"text":"وجعلت البيت الذي دعي باسمك كما في هذا اليوم لاجل شر ال اسرائيل وال يهوذا"},{"n":27,"text":"وقد عاملتنا ايها الرب الهنا بكل رافتك وكل رحمتك العظيمة"},{"n":28,"text":"كما تكلمت على لسان عبدك موسى يوم امرته ان يكتب شريعتك امام بني اسرائيل قائلا"},{"n":29,"text":"ان لم تسمعوا لصوتي فان هذا الجمع العظيم الكثير ليصيرن نفرا قليلا في الامم الذين اشتتهم بينهم"},{"n":30,"text":"فاني عالم بانهم لا يسمعون لي لانهم شعب قساة الرقاب لكنهم سيرجعون الى قلوبهم في ارض جلائهم"},{"n":31,"text":"ويعلمون اني انا الرب الههم واعطيهم قلوبا واذانا سامعة"},{"n":32,"text":"فيسبحونني في ارض جلائهم ويذكرون اسمي"},{"n":33,"text":"ويتوبون عن صلابة رقابهم وعن شر اعمالهم لانهم يتذكرون طريق ابائهم الذين خطئوا امام الرب"},{"n":34,"text":"واعيدهم الى الارض التي حلفت عليها لابائهم ابراهيم واسحق ويعقوب فيتسلطون عليها واكثرهم فلا يقلون"},{"n":35,"text":"واقيم لهم عهدا ابديا فاكون لهم الها ويكونون لي شعبا ولا اعود ازعزع شعبي اسرائيل من الارض التي اعطيتها لهم"}]},{"label":"سفر باروخ 3","verses":[{"n":1,"text":"ايها الرب القدير اله اسرائيل قد صرخت اليك النفس في المضايق والروح في الكروب"},{"n":2,"text":"فاسمع يا رب وارحم فانك اله رحيم ارحم فانا قد خطئنا اليك"},{"n":3,"text":"فانك انت تدوم الى الابد اما نحن فنهلك الى الابد"},{"n":4,"text":"ايها الرب القدير اله اسرائيل اسمع صلاة قوم اسرائيل وبني الذين خطئوا اليك الذين لم يسمعوا لصوت الههم وقد لحق الشر \nبنا"},{"n":5,"text":"لا تذكر اثام ابائنا بل اذكر يدك واسمك في هذا الزمان"},{"n":6,"text":"فانك انت الرب الهنا واياك نسبح يا رب"},{"n":7,"text":"لانك لذلك جعلت مخافتك في قلوبنا ولندعو باسمك انا نسبحك في جلائنا لانا قد نبذنا عن قلوبنا كل اثم ابائنا الذين خطئوا \nامامك"},{"n":8,"text":"وها انا اليوم في الجلاء حيث شتتنا للتعيير واللعنة والعقاب لاجل جميع اثام ابائنا الذين ارتدوا عن الرب الهنا"},{"n":9,"text":"اسمع يا اسرائيل وصايا الحياة اصغوا وتعلموا الفطنة"},{"n":10,"text":"لماذا يا اسرائيل لماذا انت في ارض الاعداء"},{"n":11,"text":"قد ذبلت في ارض الغربة وتنجست بالاموات وحسبت مع الذين هم في الجحيم"},{"n":12,"text":"انك قد تركت ينبوع الحكمة"},{"n":13,"text":"ولو انك سلكت في طريق الله لسكنت في السلام مدى الدهر"},{"n":14,"text":"تعلم اين الفطنة واين القوة واين التعقل لكي تعلم ايضا اين طول الايام والحياة واين نور العيون والسلام"},{"n":15,"text":"من وجد موضعها ومن بلغ الى كنوزها"},{"n":16,"text":"اين رؤساء الامم والذين يتسلطون على وحوش الارض"},{"n":17,"text":"والذين يلاعبون طيور السماء"},{"n":18,"text":"ويكنزون الفضة والذهب مما يتوكل عليه البشر ولا حد لكسبهم ويصوغون الفضة ويهتمون ولا استقصاء لمساعيهم"},{"n":19,"text":"انهم قد اضمحلوا والى الجحيم هبطوا واخرون قاموا من مكانهم"},{"n":20,"text":"احداث راوا النور وسكنوا الارض لكنهم لم يعرفوا طريق التادب"},{"n":21,"text":"ولم يفهموا سبله وبنوهم لم يدركوه وابتعدوا عن طريقه"},{"n":22,"text":"لم يسمع به في كنعان ولا تراءى في تيمان"},{"n":23,"text":"وبنو هاجر ايضا المبتغون للتعقل على الارض وتجار مران وتيمان وقائلو الامثال ومبتغو التعقل لم يعرفوا طريق الحكمة ولم يتذكروا سبلها"},{"n":24,"text":"يا اسرائيل ما اعظم بيت الله وما اوسع موضع ملكه"},{"n":25,"text":"عظيم هو بغير حد وعال بغير قياس"},{"n":26,"text":"هناك ولد الجبابرة المذكورون الذين كانوا في البدء الطوال القامات الحاذقون بالقتال"},{"n":27,"text":"اولئك لم يخترهم الرب ولم يجعل لهم طريق التادب"},{"n":28,"text":"فهلكوا لعدم الفطنة هلكوا لغباوتهم"},{"n":29,"text":"من صعد الى السماء فتناولها ونزل بها من الغيوم"},{"n":30,"text":"من اجتاز الى عبر البحر ووجدها واثرها على الذهب الابريز"},{"n":31,"text":"ليس احد يعرف طريقها ويطلع على سبيلها"},{"n":32,"text":"لكن العالم بكل شيء هو يعلمها وبعقله وجدها الذي ثبت الارض الى الابد وملاها حيوانا ذا اربع"},{"n":33,"text":"الذي يرسل النور فينطلق يدعوه فيطيعه برعدة"},{"n":34,"text":"ان النجوم اشرقت في محارسها وتهللت"},{"n":35,"text":"دعاها فقالت نحن لديك واشرقت متهللة للذي صنعها"},{"n":36,"text":"هذا هو الهنا ولا يعتبر حذاءه اخر"},{"n":37,"text":"هو وجد طريق التادب بكماله وجعله ليعقوب عبده ولاسرائيل حبيبه"},{"n":38,"text":"وبعد ذلك تراءى على الارض وتردد بين البشر"}]},{"label":"سفر باروخ 4","verses":[{"n":1,"text":"هذا كتاب اوامر الله والشريعة التي الى الابد كل من تمسك بها فله الحياة والذين يهملونها يموتون"},{"n":2,"text":"تب يا يعقوب واتخذها وسر في الضياء تجاه نورها"},{"n":3,"text":"لا تعط مجدك لاخر ومزيتك لامة غريبة"},{"n":4,"text":"طوبى لنا يا اسرائيل لان ما يرضي عند الله معروف لدينا"},{"n":5,"text":"ثقوا يا شعبي يا تذكار اسرائيل"},{"n":6,"text":"فانكم لم تباعوا للامم لهلاككم ولكن بما انكم اسخطتم الله قد اسلمتم الى اعدائكم"},{"n":7,"text":"لانكم اغضبتم صانعكم اذ ذبحتم للشياطين لا لله"},{"n":8,"text":"ونسيتم رازقكم الاله الازلي وحزنتم مربيتكم اورشليم"},{"n":9,"text":"انها رات الغضب الذي حل بكم من قبل الله فقالت اسمعن يا جارات صهيون ان الله قد جلب علي نوحا عظيما"},{"n":10,"text":"فاني رايت سبي بني وبناتي الذي جلبه عليهم الازلي"},{"n":11,"text":"اني ربيتهم بفرح ثم ودعتهم ببكاء ونوح"},{"n":12,"text":"لا يشمتن احد بي انا الارملة التي ثكلت كثيرين فاني قد اوحشت لاجل خطايا بني لانهم زاغوا عن شريعة الله"},{"n":13,"text":"ولم يعرفوا رسومه ولم يسلكوا في طرق وصايا الله ولم يسيروا في سبل التادب ببره"},{"n":14,"text":"هلم يا جارات صهيون فاذكرن سبي بني وبناتي الذي جلبه عليهم الازلي"},{"n":15,"text":"فانه جلب عليهم امة من بعيد امة وقحة اعجمية اللسان"},{"n":16,"text":"لم تهب شيخا ولم تشفق على طفل فذهبوا باحباء الارملة واثكلوا المتوحدة بناتها"},{"n":17,"text":"باي شيء استطيع ان اغيثكم"},{"n":18,"text":"الذي جلب عليكم الشر هو ينقذكم من ايدي اعدائكم"},{"n":19,"text":"سيروا يا بني سيروا اني بقيت مستوحشة"},{"n":20,"text":"قد خلعت حلة السلام ولبست مسح التضرع اصرخ الى الازلي مدى ايامي"},{"n":21,"text":"ثقوا يا بني واستغيثوا بالله فينقذكم من ايدي الاعداء المتسلطين عليكم"},{"n":22,"text":"فاني قد رجوت بالازلي خلاصكم وحلت بي مسرة من لدن القدوس بالرحمة التي تؤتونها عما قليل من عند الازلي مخلصكم"},{"n":23,"text":"قد ودعتكم ببكاء ونوح ولكن الله سيردكم لي بفرح ومسرة الى الابد"},{"n":24,"text":"فكما ترى الان جارات صهيون سبيكم هكذا عما قليل سيرين خلاصكم من عند الله تؤتونه بمجد عظيم وببهاء الازلي"},{"n":25,"text":"يا بني احتملوا بالصبر الغضب الذي حل بكم من الله قد اضطهدك العدو لكنك سترى هلاكه عن قليل وتطا رقابهم"},{"n":26,"text":"ان مترفي سلكوا طرقا وعرة وسيقوا كغنم نهبتها الاعداء"},{"n":27,"text":"ثقوا يا بني واستغيثوا بالله فان الذي جلب عليكم هذه سيتذكركم"},{"n":28,"text":"وكما كنتم تهوون ان تشردوا عن الله فبقدر ذلك عشر مرات تلتمسونه تائبين"},{"n":29,"text":"والذي جلب عليكم الشر يجلب لكم المسرة الابدية مع خلاصكم"},{"n":30,"text":"ثقي يا اورشليم فان الذي سماك باسمه يعزيك"},{"n":31,"text":"ويل للذين جاروا عليك وشمتوا بسقوطك"},{"n":32,"text":"ويل للمدن التي استعبدت بنيك ويل للتي اخذت اولادك"},{"n":33,"text":"فانها كما شمتت بسقوطك وفرحت بخرابك كذلك ستكتئب عند دمارها"},{"n":34,"text":"وابطل مفاخرتها بكثرة سكانها واحول مرحها الى نوح"},{"n":35,"text":"لان نار تنزل عليها من عند الازلي الى ايام كثيرة وتسكنها الشياطين طول الزمان"},{"n":36,"text":"تطلعي يا اورشليم من حولك نحو المشرق وانظري المسرة الوافدة عليك من عند الله"},{"n":37,"text":"ها ان بنيك الذين ودعتهم قادمون يقدمون مجتمعين من المشرق الى المغرب بكلمة القدوس مبتهجين بمجد الله"}]},{"label":"سفر باروخ 5","verses":[{"n":1,"text":"اخلعي يا اورشليم حلة النوح والمذلة والبسي بهاء المجد من عند الله الى الابد"},{"n":2,"text":"تسربلي ثوب البر الذي من الله واجعلي على راسك تاج مجد الازلي"},{"n":3,"text":"فان الله يظهر سناك لكل ما تحت السماء"},{"n":4,"text":"ويكون اسمك من قبل الله الى الابد سلام البر ومجد عبادة الله"},{"n":5,"text":"انهضي يا اورشليم وقفي في الاعالي وتطلعي من حولك نحو المشرق وانظري بنيك مجتمعين من مغرب الشمس الى مشرقها بكلمة \nالقدوس مبتهجين بذكر الله"}]},{"label":"سفر باروخ 6","verses":[{"n":0,"text":"نسخة الرسالة التي ارسل بها ارميا الى الذين كان ملك بابل مزمعا ان يسوقهم في الجلاء الى بابل يخبرهم بما امره الله به"},{"n":1,"text":"انه لاجل الخطايا التي خطئتم امام الله يسوقكم نبوكد نصر ملك بابل في الجلاء الى بابل"},{"n":2,"text":"فاذا دخلتم بابل فستكونون هناك سنين كثيرة وزمانا طويلا الى سبعة اجيال وبعد ذلك اخرجكم من هناك بسلام"},{"n":3,"text":"والان فانكم سترون في بابل الهة من الفضة والذهب والخشب تحمل على المناكب وتلقي الرهبة على الامم"},{"n":4,"text":"فاحترزوا ان تتشبهوا بالغرباء وتاخذكم منها رهبة"},{"n":5,"text":"واذا رايتم الجموع امامها ووراءها يسجدون لها فقولوا في قلوبكم لك يا رب ينبغي السجود"},{"n":6,"text":"فان ملاكي معكم وهو يطالب بانفسكم"},{"n":7,"text":"اما تلك فان لها السنة قد نحتها النجار وهي مغشاة بالذهب والفضة لكنها الهة زور لا تستطيع نطقا"},{"n":8,"text":"ياخذ الناس لها ذهبا كما يؤخذ لعذراء تحب الزينة"},{"n":9,"text":"فيصوغون اكاليل يجعلونها على رؤوس الهتهم وربما سرق الكهنة من الهتهم الذهب والفضة لمنفعة انفسهم"},{"n":10,"text":"وقد يبذلون منهما بالزواني اللاتي في البيت يزينون الالهة بالملابس كالبشر وهي من الفضة والذهب والخشب"},{"n":11,"text":"فهي لا تسلم من الصدا والسوس وان كانت تلبس الارجوان"},{"n":12,"text":"ويمسحون وجوهها من غبار البيت المتراكم عليها"},{"n":13,"text":"وفي يد كل منها صولجان كالحاكم على بلد لكنه لا يقتل من يجرم اليه"},{"n":14,"text":"وفي يمينه سيف وفاس لكنه لا ينجي نفسه من الحرب واللصوص فحق بذلك انها ليست الهة"},{"n":15,"text":"فلا تخافوها فانه كما ان الاناء المكسور لا ينفع صاحبه كذلك الهتهم"},{"n":16,"text":"اذا نصبت في البيوت فعيونها تمتلئ غبارا من اقدام الداخلين"},{"n":17,"text":"يحظر عليها في الديار كما يحظر على من اجرم الى الملك وكهنتها يحصنون بيوتها بابواب واقفال ومزاليج كما يفعل بمن \nحكم عليه بالموت لئلا تسلبها اللصوص"},{"n":18,"text":"يوقدون لها من السرج اكثر مما يوقدون لانفسهم وهي لا تستطيع ان ترى منها شيئا"},{"n":19,"text":"انما هي كجوائز البيت وقد ذكر ان حشرات الارض تنهش قلوبها فتؤكل هي وثيابها ولا تشعر"},{"n":20,"text":"تسود وجوهها من الدخان الذي في البيت"},{"n":21,"text":"على ابدانها ورؤوسها تثب البوم والخطاف وسائر الطيور والسنانير"},{"n":22,"text":"فاعلموا من ذلك انها ليست الهة فلا تخافوها"},{"n":23,"text":"والذهب الذي يغشيها للزينة ان لم يمسح صداه لم يكن لها رونق كما انها اذ صيغ عليها لم تشعر"},{"n":24,"text":"تبتاع بكل ثمن وان لم يكن فيها روح"},{"n":25,"text":"ليس لها ارجل فتحمل على المناكب وبذلك تبدي للناس هوانها والذين يعبدونها هم ايضا يخزون"},{"n":26,"text":"لانها اذا سقطت على الارض لا تقوم من نفسها ولا اذا نصبها احد تتحرك من نفسها ولا اذا اميلت تستقيم بل تقدم اليها \nالهدايا كما تقدم الى اموات"},{"n":27,"text":"وكهنتها يبيعون ذبائحها لمنفعة انفسهم وكذلك نساؤهم يملحن ما بقي منها ولا يجعلن فيها حظا لمسكين ولا سقيم"},{"n":28,"text":"الطامث والنفساء تلمسان ذبائحها فاذ قد علمتم من ذلك انها ليست الهة فلا تخافوها"},{"n":29,"text":"لماذا تسمى الهة لان النساء يقدمن الهدايا لهذه الالهة التي هي من الفضة والذهب والخشب"},{"n":30,"text":"ولان الكهنة يجلسون في بيوتها باقمصة ممزقة وهم محلوقو الرؤوس واللحى ورؤوسهم مكشوفة"},{"n":31,"text":"ويعجون صائحين امام الهتهم كالجالسين على مادبة الميت"},{"n":32,"text":"الكهنة ينزعون من ثيابها ما يكسون نساؤهم واولادهم"},{"n":33,"text":"واذا اساء اليها احد او احسن فلا تستطيع المكافاة ولا في وسعها ان تقيم ملكا او تخلعه"},{"n":34,"text":"ولا تقدر ان تهب عرضا ولا نقدا واذا نذر احد نذرا ولم يقضه فلا تطالب"},{"n":35,"text":"لا تنحي احدا من الموت ولا تنقذ الضعيف من يد القوي"},{"n":36,"text":"لا ترد البصر لاعمى ولا تفرج عن ذي شدة"},{"n":37,"text":"لا ترحم ارملة ولا تحسن الى يتيم"},{"n":38,"text":"فهذه الالهة التي هي من الخشب مغشاة بالذهب والفضة تماثل حجارة من الجبل والذين يعبدونها يخزون"},{"n":39,"text":"فكيف يسوغ ان تحسب او تسمى الهة"},{"n":40,"text":"بل الكلدانيون انفسهم يزدرونها فانهم اذا راوا ابكم لا ينطق يقدمونه الى بال ويطلبون منه النطق كانه يشعر"},{"n":41,"text":"ومع اختبارهم لها لا يتركون عبادتها لانهم لا يشعرون"},{"n":42,"text":"والنساء يقعدن على الطرق متحزمات بالحبال يبخرن بالنخالة"},{"n":43,"text":"فاذا اجتذب مجتاز واحدة منهن وضاجعها عيرت صاحبتها بانها لم تحظ مثلها ولم يقطع حبلها"},{"n":44,"text":"وكل ما يصنع لهذه الالهة انما هو زور فكيف يسوغ ان تحسب او تسمى الهة"},{"n":45,"text":"هي صنعة النجار والصايغ فلا تكون الا ما يريد صانعها"},{"n":46,"text":"والذين صنعوها قصيرو بقاء فكيف يكون ما صنعوه"},{"n":47,"text":"انهم تركوا لمن يليهم زورا وعارا"},{"n":48,"text":"واذا اتى عليها حرب وشر ياتمر الكهنة فيما بينهم اين يختبئون بها"},{"n":49,"text":"فكيف لا يشعر انها ليست بالهة وهي لا تخلص انفسها من الحرب والشر"},{"n":50,"text":"وبما انها من الخشب مغشاة بالذهب والفضة فسيعلم فيما بعد انها زور ويتبين لجميع الامم والملوك انها ليست الهة بل \nصنعة ايدي الناس ولا شيء فيها من صنعة الله"},{"n":51,"text":"فهل من حاجة الى التنبيه على انها ليست الهة"},{"n":52,"text":"فانها لا تقيم ملكا على بلد ولا تعطي الناس مطرا"},{"n":53,"text":"ولا تخاصم حتى لخصومة انفسها ولا تنقذ احدا من مظلمة اذ لا تستطيع شيئا وانما هي كالغربان التي بين السماء والارض"},{"n":54,"text":"واذا وقعت نار في بيت هذه الالهة المصنوعة من الخشب المغشاة بالذهب او الفضة فكهنتها يفرون وينجون اما هي فتحترق \nكجوائز البيت"},{"n":55,"text":"انها لا تقاوم ملكا ولا عدوا فكيف يسوغ ان تحسب او تعد الهة"},{"n":56,"text":"وهذه الالهة المصنوعة من الخشب المغشاة بالفضة والذهب لا تنجي انفسها من السراق او اللصوص"},{"n":57,"text":"والذين يستولون عليها ينزعون عنها الذهب والفضة والثياب التي عليها ويذهبون بها وهي لا تدافع عن انفسها"},{"n":58,"text":"لا جرم ان ملكا من ذوي الباس او اناء نافعا في البيت يستخدمه مالكه خير من الهة الزور وبابا في البيت يحفظ ما فيه \nخير من الهة الزور وعمود من الخشب في قصر خير من الهة الزور"},{"n":59,"text":"ان الشمس والقمر والنجوم تضيء وترسل لمنفعة الخلق وتطيع مرسلها"},{"n":60,"text":"وكذلك البرق اذا لمع يروق العين والريح تهب في كل ناحية"},{"n":61,"text":"والسحب يامرها الله ان تمر على كل المسكونة فتقضي ما امرت به"},{"n":62,"text":"والنار المرسلة من فوق لتفني الجبال والغاب تفعل ما اوصيت به اما تلك فلا تعدل بهذه منظرا ولا قوة"},{"n":63,"text":"فلا يسوغ ان تحسب او تسمى الهة اذ لا تستطيع ان تجري حكما او تصنع احسانا"},{"n":64,"text":"فاذ قد علمتم انها ليست بالهة فلا تخافوها"},{"n":65,"text":"فانها لا تلعن الملوك ولا تباركهم"},{"n":66,"text":"ولا تبدي ايات في الامم ولا في السماء ولا تنير كالشمس ولا تضيء كالقمر"},{"n":67,"text":"الوحوش خير منها لان في طاقتها ان تهرب الى ملجا وتنفع انفسها"},{"n":68,"text":"وبالجملة فلا يتبين لنا بوجه من الوجوه انها الهة فلا تخافوها"},{"n":69,"text":"مثل الهتهم المصنوعة من الخشب المغشاة بالذهب والفضة مثل شخص منصوب في مقثاة لا يحرس شيئا"},{"n":70,"text":"وايضا مثل الهتهم المصنوعة من الخشب المغشاة بالذهب والفضة مثل عوسج في بستان يقع عليه كل طير او مثل ميت مطروح في \nالظلمة"},{"n":71,"text":"ومن الارجوان والقرمز اللذين ياكلهما العث عليها يعلم انها ليست الهة وفي اخر الامر هي ايضا تؤكل وتصير عارا في \nالافاق"},{"n":72,"text":"ان الرجل الصديق الذي لا صنم له افضل لانه بمعزل عن العار"}]}],"sources":["https://ar.wikisource.org/wiki/سفر_باروخ","https://ar.wikisource.org/wiki/رسالة_ارميا"]},{"name":"تتمة دانيال","chapters":[{"label":"تتمة سفر دانيال 3","verses":[{"n":1,"text":"وان نبوخذنصر الملك صنع تمثالا من ذهب طوله ستون ذراعا وعرضه ست اذرع ونصبه في بقعة دورا في ولاية بابل"},{"n":2,"text":"ثم ارسل نبوخذنصر الملك ليجمع المرازبة والشحن والولاة والقضاة والخزنة والفقهاء والمفتين وكل حكام الولايات لياتوا \nلتدشين التمثال الذي نصبه نبوخذنصر الملك"},{"n":3,"text":"حينئذ اجتمع المرازبة والشحن والولاة والقضاة والخزنة والفقهاء والمفتون وكل حكام الولايات لتدشين التمثال الذي نصبه \nنبوخذنصر الملك ووقفوا امام التمثال الذي نصبه نبوخذنصر"},{"n":4,"text":"ونادى مناد بشدة قد امرتم ايها الشعوب والامم والالسنة"},{"n":5,"text":"عندما تسمعون صوت القرن والناي والعود والرباب والسنطير والمزمار وكل انواع العزف ان تخروا وتسجدوا لتمثال الذهب \nالذي نصبه نبوخذنصر الملك"},{"n":6,"text":"ومن لا يخر ويسجد ففي تلك الساعة يلقى في وسط اتون نار متقدة"},{"n":7,"text":"لاجل ذلك وقتما سمع كل الشعوب صوت القرن والناي والعود والرباب والسنطير وكل انواع العزف خر كل الشعوب والامم والالسنة \nوسجدوا لتمثال الذهب الذي نصبه نبوخذنصر الملك"},{"n":8,"text":"لاجل ذلك تقدم حينئذ رجال كلدانيون واشتكوا على اليهود"},{"n":9,"text":"اجابوا وقالوا للملك نبوخذنصر ايها الملك عش الى الابد"},{"n":10,"text":"انت ايها الملك قد اصدرت امرا بان كل انسان يسمع صوت القرن والناي والعود والرباب والسنطير والمزمار وكل انواع \nالعزف يخر ويسجد لتمثال الذهب"},{"n":11,"text":"ومن لا يخر ويسجد فانه يلقى في وسط اتون نار متقدة"},{"n":12,"text":"يوجد رجال يهود الذين وكلتهم على اعمال ولاية بابل شدرخ ومشيخ وعبد نغو هؤلاء الرجال لم يجعلوا لك ايها الملك \nاعتبارا الهتك لا يعبدون ولتمثال الذهب الذي نصبت لا يسجدون"},{"n":13,"text":"حينئذ امر نبوخذنصر بغضب وغيظ باحضار شدرخ وميشخ وعبد نغو فاتوا بهؤلاء الرجال قدام الملك"},{"n":14,"text":"فاجاب نبوخذنصر وقال لهم تعمدا يا شدرخ وميشخ وعبد نغو لا تعبدون الهتي ولا تسجدون لتمثال الذهب الذي نصبت"},{"n":15,"text":"فان كنتم الان مستعدين عندما تسمعون صوت القرن والناي والعود والرباب والسنطير والمزمار وكل انواع العزف الى ان \nتخروا وتسجدوا للتمثال الذي عملته وان لم تسجدوا ففي تلك الساعة تلقون في وسط اتون النار المتقدة ومن هو الاله الذي \nينقذكم من يدي"},{"n":16,"text":"فاجاب شدرخ وميشخ وعبد نغو وقالوا للملك يا نبوخذنصر لا يلزمنا ان نجيبك عن هذا الامر"},{"n":17,"text":"هوذا يوجد الهنا الذي نعبده يستطيع ان ينجينا من اتون النار المتقدة وان ينقذنا من يدك ايها الملك"},{"n":18,"text":"والا فليكن معلوما لك ايها الملك اننا لا نعبد الهتك ولا نسجد لتمثال الذهب الذي نصبته"},{"n":19,"text":"حينئذ امتلا نبوخذنصر غيظا وتغير منظر وجهه على شدرخ وميشخ وعبد نغو فاجاب وامر بان يحموا الاتون سبعة اضعاف اكثر \nمما كان معتادا ان يحمى"},{"n":20,"text":"وامر جبابرة القوة في جيشه بان يوثقوا شدرخ وميشخ وعبد نغو ويلقوهم في اتون النار المتقدة"},{"n":21,"text":"ثم اوثق هؤلاء الرجال في سراويلهم واقمصتهم وارديتهم ولباسهم والقوا في وسط اتون النار المتقدة"},{"n":22,"text":"ومن حيث ان كلمة الملك شديدة والاتون قد حمي جدا قتل لهيب النار الرجال الذين رفعوا شدرخ وميشخ وعبد نغو"},{"n":23,"text":"وهؤلاء الثلاثة الرجال شدرخ وميشخ وعبد نغو سقطوا موثقين في وسط اتون النار المتقدة"},{"n":24,"text":"فكانوا يتمشون في وسط اللهيب مسبحين الله ومباركين الرب"},{"n":25,"text":"ووقف عزريا وصلى هكذا وفتح فاه في وسط النار وقال"},{"n":26,"text":"مبارك انت ايها الرب اله ابائنا وحميد واسمك ممجد الى الدهور"},{"n":27,"text":"لانك عادل في جميع ما صنعت واعمالك كلها صدق وطرقك استقامة وجميع احكامك حق"},{"n":28,"text":"وقد اجريت احكام حق في جميع ما جلبت علينا وعلى مدينة ابائنا المقدسة اورشليم لانك بالحق والحكم جلبت جميع ذلك لاجل \nخطايانا"},{"n":29,"text":"اذ قد خطئنا واثمنا مرتدين عنك واجرمنا في كل شيء"},{"n":30,"text":"ولم نسمع لوصاياك ولم نحفظها ولم نعمل بما اوصيتنا لكي يكون لنا خير"},{"n":31,"text":"فجميع ما جلبت علينا وجميع ما صنعت بنا انما صنعته بحكم حق"},{"n":32,"text":"فاسلمتنا الى ايدي اعداء اثمة وكفرة ذوي بغضاء وملك ظالم شر من كل من على الارض"},{"n":33,"text":"والان ليس لنا ان نفتح افواهنا فقد صرنا خزيا وعارا لعبيدك والقانتين لك"},{"n":34,"text":"فلا تخذلنا الى الانقضاء لاجل اسمك ولا تنقض عهدك"},{"n":35,"text":"ولا تصرف رحمتك عنا لاجل ابراهيم خليلك واسحق عبدك واسرائيل قديسك"},{"n":36,"text":"الذين قلت لهم انك تكثر نسلهم كنجوم السماء وكالرمل الذي على شاطئ البحر"},{"n":37,"text":"لقد جعلنا ايها الرب اقل عددا من كل امة ونحن اليوم اذلاء في كل الارض لاجل خطايانا"},{"n":38,"text":"وليس لنا في هذا الزمان رئيس ولا نبي ولا قائد ولا محرقة ولا ذبيحة ولا تقدمة ولا بخور ولا موضع لتقريب البواكير امامك"},{"n":39,"text":"ولنيل رحمتك ولكن لانسحاق نفوسنا وتواضع ارواحنا اقبلنا"},{"n":40,"text":"وكمحرقات الكباش والثيران وربوات الحملان السمان هكذا فلتكن ذبيحتنا امامك اليوم حتى ترضيك فانه لا خزي للمتوكلين \nعليك"},{"n":41,"text":"انا نتبعك الان بكل قلوبنا ونتقيك ونبتغي وجهك"},{"n":42,"text":"فلا تخزنا بل عاملنا بحسب رافتك وكثرة رحمتك"},{"n":43,"text":"وانقذنا على حسب عجائبك واعط المجد لاسمك ايها الرب"},{"n":44,"text":"وليخجل جميع الذين اروا عبيدك المساوئ وليخزوا ساقطين عن كل اقتدارهم ولتحطم قوتهم"},{"n":45,"text":"وليعلموا انك انت الرب الاله وحدك المجيد في كل المسكونة"},{"n":46,"text":"ولم يزل خدام الملك الذين القوهم يوقدون الاتون بالنفط والزفت والمشاقة والزرجون"},{"n":47,"text":"فارتفع اللهيب فوق الاتون تسعا واربعين ذراعا"},{"n":48,"text":"وانتشر واحرق الذين صادفهم حول الاتون من الكلدانيين"},{"n":49,"text":"اما اصحاب عزريا فنزل ملاك الرب الى داخل الاتون وطرد لهيب النار عن الاتون"},{"n":50,"text":"وجعل وسط الاتون ريحا ذات ندى تهب فلم تمسهم النار البتة ولم تسؤهم ولم تزعجهم"},{"n":51,"text":"حينئذ سبح الثلاثة بفم واحد ومجدوا وباركوا الله في الاتون قائلين"},{"n":52,"text":"مبارك انت ايها الرب اله ابائنا وحميد ورفيع الى الدهور ومبارك اسم مجدك القدوس ورفيع الى الدهور"},{"n":53,"text":"مبارك انت في هيكل مجدك القدوس ومسبح وممجد الى الدهور"},{"n":54,"text":"مبارك انت في عرش ملكك ومسبح ورفيع الى الدهور"},{"n":55,"text":"مبارك انت ايها الناظر الاعماق الجالس على الكروبين ومسبح ورفيع الى الدهور"},{"n":56,"text":"مبارك انت في جلد السماء ومسبح وممجد الى الدهور"},{"n":57,"text":"باركي الرب يا جميع اعمال الرب سبحي وارفعيه الى الدهور"},{"n":58,"text":"باركوا الرب يا ملائكة الرب سبحوا وارفعوه الى الدهور"},{"n":59,"text":"باركي الرب ايتها السماوات سبحي وارفعيه الى الدهور"},{"n":60,"text":"باركي الرب يا جميع المياه التي فوق السماء سبحي وارفعيه الى الدهور"},{"n":61,"text":"باركي الرب يا جميع جنود الرب سبحي وارفعيه الى الدهور"},{"n":62,"text":"باركا الرب ايها الشمس والقمر سبحا وارفعاه الى الدهور"},{"n":63,"text":"باركي الرب يا نجوم السماء سبحي وارفعيه الى الدهور"},{"n":64,"text":"باركي الرب يا جميع الامطار والانداء سبحي وارفعيه الى الدهور"},{"n":65,"text":"باركي الرب يا جميع الرياح سبحي وارفعيه الى الدهور"},{"n":66,"text":"باركا الرب ايها النار والحر سبحا وارفعاه الى الدهور"},{"n":67,"text":"باركا الرب ايها البرد والحر سبحا وارفعاه الى الدهور"},{"n":68,"text":"باركا الرب ايها الندى والجليد سبحا وارفعاه الى الدهور"},{"n":69,"text":"باركا الرب ايها الجمد والبرد سبحا وارفعاه الى الدهور"},{"n":70,"text":"باركا الرب ايها الصقيع والثلج سبحا وارفعاه الى الدهور"},{"n":71,"text":"باركا الرب ايها الليل والنهار سبحا وارفعاه الى الدهور"},{"n":72,"text":"باركا الرب ايها النور والظلمة سبحا وارفعاه الى الدهور"},{"n":73,"text":"باركي الرب ايتها البروق والسحب سبحي وارفعيه الى الدهور"},{"n":74,"text":"لتبارك الارض الرب لتسبح وترفعه الى الدهور"},{"n":75,"text":"باركي الرب ايتها الجبال والتلال سبحي وارفعيه الى الدهور"},{"n":76,"text":"باركي الرب يا جميع انبتة الارض سبحي وارفعيه الى الدهور"},{"n":77,"text":"باركي الرب ايتها الينابيع سبحي وارفعيه الى الدهور"},{"n":78,"text":"باركي الرب ايتها البحار والانهار سبحي وارفعيه الى الدهور"},{"n":79,"text":"باركي الرب ايتها الحيتان وجميع ما يتحرك في المياه سبحي وارفعيه الى الدهور"},{"n":80,"text":"باركي الرب يا جميع طيور السماء سبحي وارفعيه الى الدهور"},{"n":81,"text":"باركي الرب يا جميع الوحوش والبهائم سبحي وارفعيه الى الدهور"},{"n":82,"text":"باركوا الرب يا بني البشر سبحوا وارفعوه الى الدهور"},{"n":83,"text":"باركوا الرب يا اسرائيل سبحوا وارفعوه الى الدهور"},{"n":84,"text":"باركوا الرب يا كهنة الرب سبحوا وارفعوه الى الدهور"},{"n":85,"text":"باركوا الرب يا عبيد الرب سبحوا وارفعوه الى الدهور"},{"n":86,"text":"باركوا الرب يا ارواح ونفوس الصديقين سبحوا وارفعوه الى الدهور"},{"n":87,"text":"باركوا الرب ايها القديسون والمتواضعو القلوب سبحوا وارفعوه الى الدهور"},{"n":88,"text":"باركوا الرب يا حننيا وعزريا وميشائيل سبحوا وارفعوه الى الدهور لانه انقذنا من الجحيم وخلصنا من يد الموت ونجانا من وسط اتون اللهيب المضطرم ومن وسط النار"},{"n":89,"text":"اعترفوا للرب لانه صالح لان الى الابد رحمته"},{"n":90,"text":"باركوا يا جميع القانتين الرب اله الالهة سبحوا واعترفوا لان الى الابد رحمته"},{"n":91,"text":"حينئذ تحير نبوخذنصر الملك وقام مسرعا فاجاب وقال لمشيريه الم نلقي ثلاثة رجال موثقين في وسط النار فاجابوا وقالوا \nللملك صحيح ايها الملك"},{"n":92,"text":"اجاب وقال ها انا ناظر اربعة رجال محلولين يتمشون في وسط النار وما بهم ضرر ومنظر الرابع شبيه بابن الالهة"},{"n":93,"text":"ثم اقترب نبوخذنصر الى باب اتون النار المتقدة واجاب فقال يا شدرخ وميشخ وعبد نغو يا عبيد الله العلي اخرجوا وتعالوا \nفخرج شدرخ وميشخ وعبد نغو من وسط النار"},{"n":94,"text":"فاجتمعت المرازبة والشحن والولاة ومشيرو الملك وراوا هؤلاء الرجال الذين لم تكن للنار قوة على اجسامهم وشعرة من \nرؤوسهم لم تحترق وسراويلهم لم تتغير ورائحة النار لم تات عليهم"},{"n":95,"text":"فاجاب نبوخذنصر وقال تبارك اله شدرخ وميشخ وعبد نغو الذي ارسل ملاكه وانقذ عبيده الذين اتكلوا عليه وغيروا كلمة \nالملك واسلموا اجسادهم لكيلا يعبدوا او يسجدوا لاله غير الههم"},{"n":96,"text":"فمني قد صدر امر بان كل شعب وامة ولسان يتكلمون بالسوء على اله شدرخ وميشخ وعبد نغو فانهم يصيرون اربا اربا وتجعل بيوتهم مزبلة اذ ليس اله اخر يستطيع ان ينجي هكذا"},{"n":97,"text":"حينئذ قدم الملك شدرخ وميشخ وعبد نغو في ولاية بابل"},{"n":98,"text":"من نبوخذنصر الملك الى كل الشعوب والامم والالسنة الساكنين في الارض كلها ليكثر سلامكم"},{"n":99,"text":"الايات والعجائب التي صنعها معي الله العلي حسن عندي ان اخبر بها"},{"n":100,"text":"اياته ما اعظمها وعجائبه ما اقواها ملكوته ملكوت ابدي وسلطانه الى دور فدور"}]},{"label":"سفر دانيال 13","verses":[{"n":1,"text":"وكان في بابل رجل اسمه يوياقيم"},{"n":2,"text":"وكان متزوجا امراة اسمها سوسنة ابنة حلقيا جميلة جدا ومتقية للرب"},{"n":3,"text":"وكان ابواها صديقين فادبا ابنتهما على حسب شريعة موسى"},{"n":4,"text":"وكان يواقيم غنيا جدا وكانت له حديقة تلي داره وكان اليهود يجتمعون اليه لانه كان اوجههم جميعا"},{"n":5,"text":"وكان قد اقيم شيخان من الشعب للقضاء في تلك السنة وهما من الذين قال الرب فيهم ان الاثم قد صدر من بابل من شيوخ قضاة \nيحسبون مدبري الشعب"},{"n":6,"text":"وكانا يترددان الى دار يوياقيم فياتيهما كل ذي دعوى"},{"n":7,"text":"وكانت سوسنة متى انصرف الشعب عند الظهر تدخل وتتمشى في حديقة رجلها"},{"n":8,"text":"فكان الشيخان يريانها كل يوم تدخل وتتمشى فكلفا بهواها"},{"n":9,"text":"واسلما عقولهما الى الفساد وصرفا اعينهما لئلا ينظرا الى السماء فيذكرا الاحكام العادلة"},{"n":10,"text":"وكانا كلاهما مشغوفين بها ولم يكاشف احدهما الاخر بوجده"},{"n":11,"text":"حياء من كشف هواهما ورغبة في مضاجعتها"},{"n":12,"text":"وكانا كل يوم يجدان في الترقب لكي ينظراها"},{"n":13,"text":"وان احدهما قال للاخر لنتصرف الى بيوتنا فانها ساعة الغذاء فخرجا وتفارقا"},{"n":14,"text":"ثم انقلبا ورجعا الى الموضع فسال بعضهما بعضا عن سبب رجوعه فاعترفا بهواهما وحينئذ اتفقا معا على وقت يمكنهما \nفيهان يخلوا بها"},{"n":15,"text":"وكان في بعض الايام بينما هما مترقبان اليوم الموافق انها دخلت مثل امس فما قبل ومعها جاريتان فقط وارادت ان تغتسل \nفي الحديقة لانه كان حر"},{"n":16,"text":"ولم يكن هناك احد الا الشيخان وهما مختبئان يترقبانها"},{"n":17,"text":"فقالت للجاريتين ائتياني بدهن وغسول واغلقا ابواب الحديقة لاغتسل"},{"n":18,"text":"ففعلتا كما امرتهما اغلقتا ابواب الحديقة وخرجتا من ابواب السر لتاتيا بما امرتا به ولم تعلما ان الشيخين مختبئان \nهناك"},{"n":19,"text":"فلما خرجت الجاريتان قام الشيخان وهجما عليها وقالا"},{"n":20,"text":"ها ان ابواب الحديقة مغلقة ولا يرانا احد ونحن كلفان بهواك فوافقينا وكوني معنا"},{"n":21,"text":"والا فنشهد عليك انه كان معك شاب ولذلك صرفت الجاريتين عنك"},{"n":22,"text":"فتنهدت سوسنة وقالت لقد ضاق بي الامر من كل جهة فاني ان فعلت هذا فهو لي موت وان لم افعل فلا انجو من ايديكما"},{"n":23,"text":"ولكن خير لي ان لا افعل ثم اقع في ايديكما من ان اخطا امام الرب"},{"n":24,"text":"وصرخت سوسنة بصوت عظيم فصرخ الشيخان عليها"},{"n":25,"text":"واسرع احدهما وفتح ابواب الحديقة"},{"n":26,"text":"فلما سمع اهل البيت الصراخ في الحديقة وثبوا اليها من باب السر ليروا ما وقع لها"},{"n":27,"text":"ولما تكلم الشيخان بكلامهما خجل العبيد جدا لانه لم يقل قط هذا القول على سوسنة"},{"n":28,"text":"وفي الغد لما اجتمع الشعب الى رجلها يوياقيم اتى الشيخان مضمرين نية اثيمة على سوسنة ليهلكاها"},{"n":29,"text":"وقالا امام الشعب ارسلوا الى سوسنة بنة حلقيا التي هي امراة يوياقيم فارسلوا"},{"n":30,"text":"فاتت هي ووالداها وبنوها وجميع ذوي قرابتها"},{"n":31,"text":"وكانت سوسنة ترفة جدا وجميلة المنظر"},{"n":32,"text":"فامر هذان الفاجران ان يكشف وجهها وكانت مبرقعة ليشبعا من جمالها"},{"n":33,"text":"وكان اهلها وجميع الذين يعرفونها يبكون"},{"n":34,"text":"فقام الشيخان في وسط الشعب ووضعا ايديهما على راسها"},{"n":35,"text":"فرفعت طرفها الى السماء وهي باكية لان قلبها كان متوكلا على الرب"},{"n":36,"text":"فقال الشيخان اننا كنا نتمشى في الحديقة وحدنا فاذا بهذه قد دخلت ومعها جاريتان واغلقت ابواب الحديقة ثم صرفت \nالجاريتين"},{"n":37,"text":"فاتاها شاب كان مختبئا ووقع عليها"},{"n":38,"text":"وكنا نحن في زاوية من الحديقة فلما راينا الاثم اسرعنا اليهما ورايناهما متعانقين"},{"n":39,"text":"اما ذاك فلم نستطيع ان نمسكه لانه كان اقوى منا ففتح الابواب وفر"},{"n":40,"text":"واما هذه فقبضنا عليها وسالناها من الشاب فابت ان تخبرنا هذا ما نشهد به"},{"n":41,"text":"فصدقهما المجمع لانهما شيخان وقاضيان في الشعب وحكموا عليها بالموت"},{"n":42,"text":"فصرخت سوسنة بصوت عظيم وقالت ايها الاله الازلي البصير بالخفايا العالم بكل شيء قبل ان يكون"},{"n":43,"text":"انك تعلم انهما شهدا علي بالزور وها انا اموت ولم اصنع شيئا مما افترى علي هذان"},{"n":44,"text":"فاستجاب الرب لصوتها"},{"n":45,"text":"واذ كانت تساق الى الموت نبه الله روحا مقدسا لشاب حدث اسمه دانيال"},{"n":46,"text":"فصرخ بصوت عظيم انا بريء من دم هذه"},{"n":47,"text":"فالتفت اليه الشعب كله وقالوا ما هذا الكلام الذي قلته"},{"n":48,"text":"فوقف في وسطهم وقال اهكذا انتم اغبياء يا بني اسرائيل حتى تقضوا على بنت اسرائيل بغير ان تفحصوا وتتحققوا الامر"},{"n":49,"text":"ارجعوا الى القضاء فان هذين انما شهدا عليها بالزور"},{"n":50,"text":"فاسرع الشعب كله ورجع فقال له الشيخان هلم اجلس بيننا وافدنا فقد اتاك الله مزية الشيوخ"},{"n":51,"text":"فقال لهم دانيال فرقوهما بعضهما عن بعض فاحكم فيهما"},{"n":52,"text":"فلما فرقا الواحد عن الاخر دعا احدهما وقال له يا ايها المتعتق الايام الشريرة لقد اتت عليك خطاياك التي ارتكبت من \nقبل"},{"n":53,"text":"بقضائك اقضية ظلم وحكمك على الابرياء واطلاقكك للمجرمين وقد قال الله البريء والزكي لا تقتلهما"},{"n":54,"text":"فالان ان كنت قد رايتها فقل تحت اي شجرة رايتهما يتحدثان فقال تحت الضروة"},{"n":55,"text":"فقال دانيال لقد صوبت كذبك على راسك فملاك الله قد امر من لدن الله بان يشقك شطرين"},{"n":56,"text":"ثم نحاه وامر باقبال الاخر فقال له يا نسل كنعان لا يهوذا قد فتنك الجمال واسلم الهوى قلبك الى الفساد"},{"n":57,"text":"هكذا كنتما تصنعان مع بنات اسرائيل وكن يحدثنكما مخافة منكما اما بنت يهوذا فلم تحتمل فجوركما"},{"n":58,"text":"فالان قل لي تحت اية شجرة صادفتهما يتحدثان فقال تحت السنديانة"},{"n":59,"text":"فقال له دانيال وانت ايضا قد صوبت كذبك على راسك فملاك الله واقف وبيده سيف ليقطعك شطرين حتى يهلككما"},{"n":60,"text":"فصرخ المجمع كله بصوت عظيم وباركوا الله مخلص الذين يرجونه"},{"n":61,"text":"وقاموا على الشيخين وقد اثبت دانيال من نطقهما انهما شهدا بالزور وصنعوا بهما كما نويا ان يصنعا بالقريب"},{"n":62,"text":"عملا بما في شريعة موسى فقتلوهما وخلص الدم الزكي في ذلك اليوم"},{"n":63,"text":"فسبح حلقيا وامراته لاجل ابنتهما مع يوياقيم رجلها وذوي قرابتهم لانه لم يوجد فيها شيء قبيح"},{"n":64,"text":"وعظم دانيال عند الشعب من ذلك اليوم فما بعد"},{"n":65,"text":"وانضم الملك اسطواج الى ابائه واخذ كورش الفارسي ملكه"}]},{"label":"سفر دانيال 14","verses":[{"n":1,"text":"وكان دانيال نديما للملك ومكرما فوق جميع اصدقائه"},{"n":2,"text":"وكان لاهل بابل صنم اسمه بال وكانوا ينفقون له كل يوم اثني عشر اردبا من السميذ واربعين شاة وستة امتار من الخمر"},{"n":3,"text":"وكان الملك يعبده وينطلق كل يوم فيسجد له اما دانيال فكان يسجد لالهه فقال الملك لماذا لا تسجد لبال"},{"n":4,"text":"فقال لاني لا اعبد اصناما صنعة الايدي بل الاله الحي خالق السماوات والارض الذي له السلطان على كل ذي جسد"},{"n":5,"text":"فقال له الملك اتحسب ان بالا ليس باله حي او لا ترى كم ياكل ويشرب كل يوم"},{"n":6,"text":"فضحك دانيال وقال لا تضل ايها الملك فان هذا باطنه طين وظاهره نحاس فلم ياكل قط"},{"n":7,"text":"فغضب الملك ودعا كهنته وقال لهم ان لم تقولوا لي من الذي ياكل هذه النفقة تموتون"},{"n":8,"text":"وان بينتم ان بالا ياكل هذه يموت دانيال لانه جدف على بال فقال دانيال للملك ليفعل كما تقول"},{"n":9,"text":"وكان كهنة بال سبعين كاهنا ما خلا النساء والاولاد فاتى الملك ودانيال الى بيت بال"},{"n":10,"text":"فقال كهنة بال ها انا ننصرف الى الخارج وانت ايها الملك ضع الاطعمة وامزج الخمر وضعها ثم اغلق الباب واختم عليه \nبخاتمك"},{"n":11,"text":"وفي غد ارجع فان لم تجد بالا قد اكل الجميع فانا نموت والا فيموت دانيال الذي افترى علينا"},{"n":12,"text":"وكانوا يستخفون بالامر لانهم كانوا قد صنعوا تحت المائدة مدخلا خفيا يدخلون منه كل يوم ويلتهمون الجميع"},{"n":13,"text":"فلما خرجوا وضع الملك الاطعمة لبال فامر دانيال غلمانه فاتوا برماد وذروه في الهيكل كله بحضرة الملك وحده ثم خرجوا \nواغلقوا الباب وختموا عليه بخاتم الملك وانصرفوا"},{"n":14,"text":"فلما كان الليل دخل الكهنة كعادتهم هم ونساؤهم واولادهم واكلوا الجميع وشربوا"},{"n":15,"text":"وبكر الملك في الغد ودانيال معه"},{"n":16,"text":"فقال اسالمة الخواتيم يا دانيال قال سالمة ايها الملك"},{"n":17,"text":"ولما فتحت الابواب نظر الملك الى المائدة فهتف بصوت عال عظيم انت يا بال ولا مكر عندك"},{"n":18,"text":"فضحك دانيال وامسك الملك لئلا يدخل الى داخل وقال انظر البلاط واعرف ما هذه الاثار"},{"n":19,"text":"فقال الملك اني ارى اثار رجال ونساء واولاد وغضب الملك"},{"n":20,"text":"حينئذ قبض على الكهنة ونسائهم واولادهم فاروه الابواب الخفية التي يدخلون منها وياكلون ما على المائدة"},{"n":21,"text":"فقتلهم الملك واسلم بالا الى يد دانيال فحطمه هو وهيكله"},{"n":22,"text":"وكان في بابل تنين عظيم وكان اهلها يعبدونه"},{"n":23,"text":"فقال الملك لدانيال اتقول عن هذا ايضا انه نحاس ها انه حي ياكل ويشرب ولا تستطيع ان تقول انه ليس الها حيا فاسجد له"},{"n":24,"text":"فقال دانيال اني انما اسجد للرب الهي لانه هو الاله الحي"},{"n":25,"text":"وانت ايها الملك اجعل لي سلطانا فاقتل التنين بلا سيف ولا عصا فقال الملك قد جعلت لك"},{"n":26,"text":"فاخذ دانيال زفتا وشحما وشعرا وطبخها معا وصنع اقراصا وجعلها في فم التنين فاكلها التنين فانشق فقال انظروا \nمعبوداتكم"},{"n":27,"text":"فلما سمع بذلك اهل بابل غضبوا جدا واجتمعوا على الملك وقالوا ان الملك قد صار يهوديا فحطم بالا وقتل التنين وذبح \nالكهنة"},{"n":28,"text":"واتوا الى الملك وقالوا له اسلم الينا دانيال والا قتلناك انت والك"},{"n":29,"text":"فلما راهم الملك ثائرين به اضطر فاسلم دانيال اليهم"},{"n":30,"text":"فالقوه في جب الاسود فكان هناك ستة ايام"},{"n":31,"text":"وكان في الجب سبعة اسود يلقى لها كل يوم جثتان ونعجتان فلم يلق لها حينئذ شيء لكي تفترس دانيال"},{"n":32,"text":"وكان حبقوق النبي في ارض يهوذا وكان قد طبخ طبيخا وثرد خبزا في جفنة وانطلق الى الصحراء ليحمله للحصادين"},{"n":33,"text":"فقال ملاك الرب لحبقوق احمل الغداء الذي معك الى بابل الى دانيال في جب الاسود"},{"n":34,"text":"فقال حبقوق ايها السيد اني لم ار بابل قط ولا اعرف الجب"},{"n":35,"text":"فاخذ ملاك الرب بجمته وحمله بشعر راسه ووضعه في بابل عند الجب باندفاع روحه"},{"n":36,"text":"فنادى حبقوق قائلا يا دانيال يا دانيال خذ الغداء الذي ارسله لك الله"},{"n":37,"text":"فقال دانيال اللهم لقد ذكرتني ولم تخذل الذين يحبونك"},{"n":38,"text":"وقام دانيال واكل ورد ملاك الرب حبقوق من ساعته الى موضعه"},{"n":39,"text":"وفي اليوم السابع اتى الملك ليبكي على دانيال فدنى من الجب ونظر فاذا بدانيال جالس"},{"n":40,"text":"فهتف بصوت عال وقال عظيم انت ايها الرب اله دانيال ولا اله غيرك ثم اخرجه من جب الاسود"},{"n":41,"text":"اما الذين سعوا به للهلاك فالقاهم في الجب فافترسوا من ساعتهم امامه"},{"n":42,"text":"فقال الملك ليتق جميع سكان الارض اله دانيال فانه المخلص الصانع الايات والعجائب في الارض وهو الذي انقذ دانيال من جب \nالاسود"}]}],"sources":["https://ar.wikisource.org/wiki/تتمة_سفر_دانيال"]},{"name":"المكابيين الأول","chapters":[{"label":"سفر المكابيين الأول 1","verses":[{"n":1,"text":"ان الاسكندر بن فيلبس المكدوني بعد خروجه من ارض كتيم وايقاعه بداريوس ملك فارس وماداي ملك مكانه وهو اول من ملك على اليونان"},{"n":2,"text":"ثم اثار حروبا كثيرة وفتح حصونا متعددة وقتل ملوك الارض"},{"n":3,"text":"واجتاز الى اقاصي الارض وسلب غنائم جمهور من الامم فسكتت الارض بين يديه فترفع في قلبه وتشامخ"},{"n":4,"text":"وحشد جيشا قويا جدا"},{"n":5,"text":"واستولى على البلاد والامم والسلاطين فكانوا يحملون اليه الجزية"},{"n":6,"text":"وبعد ذلك انطرح على فراشه واحس من نفسه بالموت"},{"n":7,"text":"فدعا عبيده الكبراء الذين نشاوا معه منذ الصباء فقسم مملكته بينهم في حياته"},{"n":8,"text":"وكان ملك الاسكندر اثنتي عشرة سنة ومات"},{"n":9,"text":"فتملك عبيده كل واحد في مكانه"},{"n":10,"text":"ولبس كل منهم التاج بعد وفاته وكذلك بنوهم من بعدهم سنين كثيرة فكثرت الشرور في الارض"},{"n":11,"text":"وخرجت منهم جرثومة اثيمة هي انطيوكس الشهير ابن انطيوكس الملك وكان رهينة في رومية وملك في السنة المئة والسابعة \nوالثلاثين من دولة اليونان"},{"n":12,"text":"وفي تلك الايام خرج من اسرائيل ابناء منافقون فاغروا كثيرين قائلين هلم نعقد عهدا مع الامم حولنا فانا منذ انفصلنا عنهم \nلحقتنا شرور كثيرة"},{"n":13,"text":"فحسن الكلام في عيونهم"},{"n":14,"text":"وبادر نفر من الشعب وذهبوا الى الملك فاطلق لهم ان يصنعوا بحسب احكام الامم"},{"n":15,"text":"فابتنوا مدرسة في اورشليم على حسب سنن الامم"},{"n":16,"text":"وعملوا لهم غلفا وارتدوا عن العهد المقدس ومازجوا الامم وباعوا انفسهم لصنيع الشر"},{"n":17,"text":"ولما استتب الملك لانطيوكس ازمع على امتلاك مصر ليكون مالكا على كلتا المملكتين"},{"n":18,"text":"فدخل مصر بجيش كثيف وعجلات وفيلة وفرسان واسطول عظيم"},{"n":19,"text":"واثار الحرب على بطلماوس ملك مصر فارتاع بطلماوس من وجهه وهرب وسقط قتلى كثيرون"},{"n":20,"text":"فاستحوذوا على المدن الحصينة بارض مصر وسلبوا غنائم ارض مصر"},{"n":21,"text":"ورجع انطيوكس بعدما اوقع بمصر وذلك في السنة المئة والثالثة والاربعين ونهض نحو اسرائيل"},{"n":22,"text":"فصعد الى اورشليم بجيش كثيف"},{"n":23,"text":"ودخل المقدس بتجبر واخذ مذبح الذهب ومنارة النور مع جميع ادواتها ومائدة التنضيد والمساكب والجامات ومجامر الذهبو \nالحجاب والاكاليل والحلية الذهبية التي كانت على وجه الهيكل وحطمها جميعا"},{"n":24,"text":"واخذ الفضة والذهب والانية النفيسة واخذ ما وجد من الكنوز المكنونة اخذ الجميع وانصرف الى ارضه"},{"n":25,"text":"واكثر من القتل وتكلم بتجبر عظيم"},{"n":26,"text":"فكانت مناحة عظيمة في اسرائيل في كل ارضهم"},{"n":27,"text":"وانتحب الرؤساء والشيوخ وخارت العذارى والفتيان وتغير جمال النساء"},{"n":28,"text":"وكل عروس اتخذ مرثاة والجالسة في الحجلة عقدت مناحة"},{"n":29,"text":"فارتجت الارض على سكانها وجميع ال يعقوب لبسوا الخزي"},{"n":30,"text":"وبعد سنتين من الايام ارسل الملك رئيس الجزية الى مدن يهوذا فوفد على اورشليم في جيش كثيف"},{"n":31,"text":"وخاطبهم خطاب سلام مكرا فوثقوا به"},{"n":32,"text":"ثم هجم على المدينة فجاة وضربها ضربة عظيمة واهلك شعبا كثيرا من اسرائيل"},{"n":33,"text":"وسلب غنائم المدينة واحرقها بالنار وهدم بيوتها واسوارها من حولها"},{"n":34,"text":"وسبوا النساء والاولاد واستولوا على المواشي"},{"n":35,"text":"وبنوا على مدينة داود سورا عظيما متينا وبروجا حصينة فصارت قلعة لهم"},{"n":36,"text":"وجعلوا هناك امة اثيمة رجالا منافقين فتحصنوا فيها ووضعوا فيها السلاح والطعام وجمعوا غنائم اورشليم"},{"n":37,"text":"ووضعوها هناك فصاروا لهم شركا مهلكا"},{"n":38,"text":"وكان ذلك مكمنا للمقدس وشيطانا خبيثا لاسرائيل على الدوام"},{"n":39,"text":"فسفكوا الدم الزكي حول المقدس ونجسوا المقدس"},{"n":40,"text":"فهرب اهل اورشليم بسببهم فامست مسكن غرباء وصارت غريبة للمولودين فيها وابناؤها هجروها"},{"n":41,"text":"ورد مقدسها خرابا كالقفر وحولت اعيادها مناحة وسبوتها عارا وعزها اضمحلالا"},{"n":42,"text":"وعلى قدر مجدها اكثر هوانها ورفعتها الت الى مناحة"},{"n":43,"text":"وكتب الملك انطيوكس الى مملكته كلها بان يكونوا جميعهم شعبا واحدا ويتركوا كل واحد سننه"},{"n":44,"text":"فاذعنت الامم باسرها لكلام الملك"},{"n":45,"text":"وكثيرون من اسرائيل ارتضوا دينه وذبحوا للاصنام ودنسوا السبت"},{"n":46,"text":"وانفذ الملك كتبا على ايدي رسل الى اورشليم ومدن يهوذا ان يتبعوا سنن الاجانب في الارض"},{"n":47,"text":"ويمتنعوا عن المحرقات والذبيحة والسكيب في المقدس"},{"n":48,"text":"ويدنسوا السبوت والاعياد"},{"n":49,"text":"وينجسوا المقادس والقديسين"},{"n":50,"text":"ويبتنوا مذابح وهياكل ومعابد للاصنام ويذبحوا الخنازير والحيوانات النجسة"},{"n":51,"text":"ويتركوا بنيهم قلفا ويقذروا نفوسهم بكل نجاسة ورجس حتى ينسوا الشريعة ويغيروا جميع الاحكام"},{"n":52,"text":"ومن لا يعمل بمقتضى كلام الملك يقتل"},{"n":53,"text":"وكتب بمثل هذا الكلام كله الى مملكته باسرها واقام رقباء على جميع الشعب"},{"n":54,"text":"وامر مدائن يهوذا بان يذبحوا في كل مدينة"},{"n":55,"text":"فانضم اليهم كثيرون من الشعب كل من نبذ الشريعة فصنعوا الشر في الارض"},{"n":56,"text":"والجاوا اسرائيل الى المختبات في كل موضع فروا اليه"},{"n":57,"text":"وفي اليوم الخامس عشر من كسلو في السنة المئة والخامسة والاربعين بنوا رجاسة الخراب على المذبح وبنوا مذابح في مدن \nيهوذا من كل ناحية"},{"n":58,"text":"وكانوا يقترون على ابواب البيوت وفي الساحات"},{"n":59,"text":"وما وجدوه من اسفار الشريعة مزقوه واحرقوه بالنار"},{"n":60,"text":"وكل من وجد عنده سفر من العهد او اتبع الشريعة فانه مقتول بامر الملك"},{"n":61,"text":"هكذا كانوا يفعلون بسطوتهم في اسرائيل بالذين يصادفونهم في المدن شهرا فشهرا"},{"n":62,"text":"وفي اليوم الخامس والعشرين من الشهر ذبحوا على مذبح الاصنام الذي فوق المذبح"},{"n":63,"text":"والنساء اللواتي ختن اولادهن قتلوهن بمقتضى الامر"},{"n":64,"text":"وعلقوا الاطفال في اعناقهن ونهبوا بيوتهن وقتلوا الذين ختنوهم"},{"n":65,"text":"وان كثيرين في اسرائيل عزموا وصمموا في انفسهم على ان لا ياكلوا نجسا واختاروا الموت لئلا يتنجسوا بالاطعمة"},{"n":66,"text":"ولا يدنسوا العهد المقدس فماتوا"},{"n":67,"text":"وكان على اسرائيل غضب شديد جدا"}]},{"label":"سفر المكابيين الأول 2","verses":[{"n":1,"text":"في تلك الايام خرج من اورشليم متتيا بن يوحنا بن سمعان كاهن من بني يوياريب وسكن في مودين"},{"n":2,"text":"وكان له خمسة بنين يوحنا الملقب بكديس"},{"n":3,"text":"وسمعان المسمى بطسي"},{"n":4,"text":"ويهوذا الملقب بالمكابي"},{"n":5,"text":"والعازار الملقب باواران ويوناتان الملقب بافوس"},{"n":6,"text":"ولما راى ما يصنع من المنكرات في يهوذا واورشليم"},{"n":7,"text":"قال ويل لي لم ولدت فانظر حطم شعبي وحطم المدينة المقدسة وامكث ههنا اراها مسلمة الى ايدي الاعداء"},{"n":8,"text":"وارى المقدس في ايدي الاجانب وهيكلها كرجل ذليل"},{"n":9,"text":"وقد اخذت انية مجدها في السبي وقتل اطفالها في الساحات وفتيانها بسيف العدو"},{"n":10,"text":"اية امة لم ترث ملكها ولم تسلب غنائمها"},{"n":11,"text":"جميع حلاها قد نزعت والتي كانت حرة صارت امة"},{"n":12,"text":"ها ان اقداسنا وبهاءنا ومجدنا قد دمرت ودنستها الامم"},{"n":13,"text":"فلم حياتنا بعد"},{"n":14,"text":"ومزق متتيا وبنوه ثيابهم وتحزموا بالمسوح وناحوا مناحة شديدة"},{"n":15,"text":"وان الذين ارسلهم الملك ليجبروا الناس على الارتداد قدموا الى مدينة مودين ليذبحوا"},{"n":16,"text":"فاقبل عليهم كثيرين من اسرائيل واجتمع متتيا وبنوه"},{"n":17,"text":"فاجاب رسل الملك وكلموا متتيا قائلين انت رئيس في هذه المدينة شريف عظيم معزز بالبنين والاخوة"},{"n":18,"text":"فالان ابدا انت وتقدم لامضاء امر الملك كما فعلت الامم كلها ورجال يهوذا ومن بقي في اورشليم فتكون انت واهل بيتك من \nاصدقاء الملك وتكرم انت وبنوك بالذهب والفضة والهدايا الكثيرة"},{"n":19,"text":"فاجاب متتيا بصوت عظيم وقال انه وان طاعت للملك كل الامم التي في دار ملكه وارتد كل احد عن دين ابائه ورضي باوامره"},{"n":20,"text":"فانا وبني واخوتي نسلك في عهد ابائنا"},{"n":21,"text":"فحاشا لنا ان نترك الشريعة والاحكام"},{"n":22,"text":"انا لن نسمع لكلام الملك فنحيد عن ديننا يمنة او يسرة"},{"n":23,"text":"ولما فرغ من هذا الكلام اقبل رجل يهودي على عيون الجميع ليذبح على المذبح الذي في مودين على مقتضى امر الملك"},{"n":24,"text":"فلما راى متتيا ذلك غار وارتعش حقواه واستشاط غضبا وفاقا للشريعة فوثب عليه وقتله على المذبح"},{"n":25,"text":"وفي ذلك الوقت قتل ايضا رجل الملك الذي كان يجبر على الذبح وهدم المذبح"},{"n":26,"text":"وغار للشريعة كما فعل فنحاس بزمري بن سالو"},{"n":27,"text":"وصاح متتيا في المدينة بصوت عظيم قائلا كل من غار للشريعة وحافظ على العهد فليخرج ورائي"},{"n":28,"text":"وهرب هو وبنوه الى الجبال وتركوا كل ما لهم في المدينة"},{"n":29,"text":"حينئذ نزل كثيرون الى البرية ممن يبتغون العدل والحكم"},{"n":30,"text":"ليسكنوا هناك هم وبنوهم ونساؤهم ومواشيهم لان الشرور كثرت عليهم"},{"n":31,"text":"فاخبر رجال الملك والجند الذين كانوا في اورشليم في مدينة داود بان رجالا من الناقضين لامر الملك قد نزلوا واختباوا في \nالبرية فجرى كثيرون في اعقابهم"},{"n":32,"text":"فادركوهم وجيشوا حولهم وناصبوهم القتال في يوم السبت"},{"n":33,"text":"وقالوا لهم حسبكم ما فعلتم فاخرجوا وافعلوا كما امر الملك فتحيوا"},{"n":34,"text":"فقالوا لا نخرج ولا نفعل كما امر الملك لئلا ندنس يوم السبت"},{"n":35,"text":"فاثاروا عليهم القتال"},{"n":36,"text":"فلم يردوا عليهم ولا رموهم بحجر ولا سدوا مختباتهم"},{"n":37,"text":"قائلين لنمت جميعا في استقامتنا والسماء والارض شاهدتان لنا بانكم تهلكوننا ظلما"},{"n":38,"text":"فهجموا عليهم وقاتلوهم في السبت فهلكوا هم ونساؤهم وبنوهم ومواشيهم وكانوا الف نفس من الناس"},{"n":39,"text":"واخبر متتيا واصحابه فناحوا عليهم نوحا شديدا"},{"n":40,"text":"وقال بعضهم لبعض ان فعلنا كلنا كما فعل اخوتنا ولم نقاتل الامم عن نفوسنا واحكامنا لم يلبثوا ان يبيدونا عن الارض"},{"n":41,"text":"واتمروا في ذلك اليوم قائلين كل رجل اتانا مقاتلا يوم السبت نقاتله ولا نموت جميعا كما مات اخوتنا في المختبات"},{"n":42,"text":"حينئذ اجتمعت اليهم جماعة الحسيديين ذوي الباس في اسرائيل وكل من انتدب للشريعة"},{"n":43,"text":"وانضم اليهم جميع الذين فروا من الشر فازدادوا بهم تعزيزا"},{"n":44,"text":"والفوا جيشا واوقعوا بالخطاة في غضبهم وبرجال النفاق في حنقهم وفر الباقون الى الامم طالبين النجاة"},{"n":45,"text":"ثم جال متتيا واصحابه وهدموا المذابح"},{"n":46,"text":"وختنوا كل من وجدوه في تخوم اسرائيل من الاولاد الغلف وتشددوا"},{"n":47,"text":"وتتبعوا ذوي التجبر ونجحوا في عمل ايديهم"},{"n":48,"text":"وانقذوا الشريعة من ايدي الامم وايدي الملوك ولم يجعلوا للخاطئ قرنا"},{"n":49,"text":"وقاربت ايام متتيا ان يموت فقال لبنيه لقد اشتد التجبر والعقاب وزمان الانقلاب ووغر الحنق"},{"n":50,"text":"فالان ايها البنون غاروا للشريعة وابذلوا نفوسكم دون عهد ابائنا"},{"n":51,"text":"اذكروا اعمال ابائنا التي صنعوها في اجيالهم فتنالوا مجدا عظيما واسما مخلدا"},{"n":52,"text":"الم يكن ابرهيم في التجربة وجد مؤمنا فحسب له ذلك برا"},{"n":53,"text":"ويوسف في اوان ضيقه حفظ الوصية فصار سيدا على مصر"},{"n":54,"text":"وفنحاس ابونا غار غيرة فاخذ عهد كهنوت ابدي"},{"n":55,"text":"ويشوع اذ اتم ما امر به صار قاضيا في اسرائيل"},{"n":56,"text":"وكالب بشهادته في الجماعة نال ميراثا في الارض"},{"n":57,"text":"وداود برحمته ورث عرش الملك الى ابد الاباد"},{"n":58,"text":"وايليا بغيرته للشريعة رفع الى السماء"},{"n":59,"text":"وحننيا وعزريا وميشائيل بايمانهم خلصوا من اللهيب"},{"n":60,"text":"ودانيال باستقامته انقذ من افواه الاسود"},{"n":61,"text":"وهكذا اعتبروا في جيل فجيل ان جميع المتوكلين عليه لا يزلون"},{"n":62,"text":"ولا تخشوا من كلام الرجل الخاطئ لان مجده ياول الى قذر ودود"},{"n":63,"text":"اليوم يرتفع وغدا لا وجود له لانه يعود الى ترابه وتضمحل افكاره"},{"n":64,"text":"فانتم ايها البنون تشددوا وكونوا رجالا في الشريعة فانكم بها ستمجدون"},{"n":65,"text":"وهوذا سمعان اخوكم اني اعلم انه رجل مشورة فاسمعوا منه كل الايام وليكن لكم ابا"},{"n":66,"text":"ويهوذا المكابي الشديد الباس منذ صباه هو يكون لكم رئيس الجيش ويتولى قتال الشعوب"},{"n":67,"text":"واجمعوا اليكم جميع العاملين بالشريعة وانتقموا لشعبكم انتقاما"},{"n":68,"text":"كافئوا الامم مكافاة وواظبوا على وصايا الشريعة"},{"n":69,"text":"ثم باركهم وانضم الى ابائه"},{"n":70,"text":"وكانت وفاته في السنة المئة والسادسة والاربعين فدفنه بنوه في قبور ابائهم بمودين وبكى عليه جميع اسرائيل بكاء شديدا"}]},{"label":"سفر المكابيين الأول 3","verses":[{"n":1,"text":"فقام مكانه يهوذا ابنه المسمى بالمكابي"},{"n":2,"text":"وكان كل اخوته وجميع الذين انضموا الى ابيه انصارا له يحاربون حرب اسرائيل بفرح"},{"n":3,"text":"فزاد شعبه بسطة في العز ولبس لامته كجبار وتقلد سلاحه للقتال وباشر الحروب وبسيفه حمى الجيش"},{"n":4,"text":"وكان كالاسد في حركاته وكالشبل الزائر على الفريسة"},{"n":5,"text":"فتعقب اهل النفاق مستقصيا اثارهم واحرق الذين يفتنون شعبه بالنار"},{"n":6,"text":"فنكص المنافقون خوفا منه واضطرب جميع فاعلي الاثم ونجح الخلاص على يده"},{"n":7,"text":"واحنق ملوكا كثيرين وفرح يعقوب باعماله فصار ذكره مباركا مدى الدهر"},{"n":8,"text":"وجال في مدن يهوذا واهلك الكفرة منها وصرف الغضب عن اسرائيل"},{"n":9,"text":"فاشتهر الى اقاصي الارض وجمع المشرفين على الهلاك"},{"n":10,"text":"وحشد ابلونيوس الامم وجاء بجيش عظيم من السامرة ليحارب اسرائيل"},{"n":11,"text":"فلما علم يهوذا خرج للقائه فاوقع به وقتله وسقط قتلى كثيرون وانهزم الباقون"},{"n":12,"text":"فسلب غنائمهم واخذ يهوذا سيف ابلونيوس فكان يقاتل به كل الايام"},{"n":13,"text":"وسمع سارون قائد جيش سورية ان يهوذا قد عصب عصابة وجماعة من المؤمنين يسيرون معه الى القتال"},{"n":14,"text":"فقال اقيم لنفسي اسما واتمجد في المملكة واقاتل يهوذا والذين معه من المستهينين بامر الملك"},{"n":15,"text":"ثم تجهز للخروج وخرج معه جيش قوي من الكفرة يظاهرونه وينتقمون من بني اسرائيل"},{"n":16,"text":"فدنوا الى عقبة بيت حورون فخرج يهوذا للقائهم في نفر يسير"},{"n":17,"text":"فلما راوا الجيش مقبلا الى لقائهم قالوا ليهوذا كيف نطيق قتال مثل هذا الجمع القوي ونحن نفر يسير وقد استرخينا اليوم من \nالصوم"},{"n":18,"text":"فقال يهوذا ما اسهل ان يدفع الكثيرون الى ايدي القليلين وسواء عند اله السماء ان يخلص بالكثيرين وبالقليلين"},{"n":19,"text":"فانه ليس الظفر في الحرب بكثرة الجنود وانما القوة من السماء"},{"n":20,"text":"اولئك ياتوننا بجمع من ذوي الشتائم والنفاق ليبيدونا نحن ونساءنا واولادنا ويسلبونا"},{"n":21,"text":"واما نحن فنحارب عن نفوسنا وسنننا"},{"n":22,"text":"وهو يكسرهم امام وجوهنا فلا تخافوهم"},{"n":23,"text":"ولما فرغ من كلامه هجم عليهم بغتة فانكسر سارون وجيشه امامه"},{"n":24,"text":"فتتبعه في عقبة بيت حورون الى السهل فسقط منهم ثماني مئة رجل وانهزم الباقون الى ارض فلسطين"},{"n":25,"text":"فوقع خوف يهوذا واخوته ورعبهم على الامم الذين حولهم"},{"n":26,"text":"وبلغ ذكره الى الملك وتحدثت الامم كلها بوقائع يهوذا"},{"n":27,"text":"فلما سمع انطيوكس الملك بهذا الكلام استشاط غضبا وارسل وجمع كل جيوش مملكته عسكرا شديدا جدا"},{"n":28,"text":"وفتح خزانته ودفع الى جيوشه وظائف سنة وامرهم بان يكونوا متاهبين لكل شيء"},{"n":29,"text":"ثم راى ان الفضة قد نفدت من الخزائن وقد قل جباة ضرائب البلاد لسبب الفتنة والضربة التي احدثها في الارض لينسخ السنن \nالتي كانت لها منذ ايام القدم"},{"n":30,"text":"وخشي انه لا يملك ما يقوم بنفقاته وعطاياه التي طال ما كان يجود بها جودا واسعا فاق به الملوك الذين كانوا من قبله"},{"n":31,"text":"فتحير في نفسه حيرة شديدة وازمع ان يذهب الى بلاد فارس وياخذ جزية البلاد ويجبي مالا جزيلا"},{"n":32,"text":"فاستخلف ليسياس على امور الملك من نهر الفرات الى حدود مصر وهو رجل شريف من النسل الملكي"},{"n":33,"text":"وان يتولى تربية انطيوكوس ابنه الى ان يعود"},{"n":34,"text":"وفوض اليه شطر الجيش والفيلة وامره بكل ما كان في نفسه وبامر سكان اليهودية واورشليم"},{"n":35,"text":"ان يوجه اليهم جيشا يكسر ويستاصل شوكة اسرائيل وبقية اورشليم ويمحو ذكرهم من المكان"},{"n":36,"text":"وينزل في جميع تخومهم ابناء الاجانب ويقسم الارض بينهم"},{"n":37,"text":"واخذ الملك الشطر الباقي من الجيش وسار من انطاكية عاصمة ملكه في السنة المئة والسابعة والاربعين وعبر نهر الفرات وجال \nفي الاقاليم العليا"},{"n":38,"text":"فاختار ليسياس بطلماوس بن دوريمانس ونكانور وجرجياس رجالا ذوي باس من اصحاب الملك"},{"n":39,"text":"ووجه منهم اربعين الف راجل وسبعة الاف فارس لياتوا ارض يهوذا ويدمروها على حسب امر الملك"},{"n":40,"text":"فساروا بالجيش كله حتى بلغوا الى قرب عماوس ونزلوا هناك في ارض السهل"},{"n":41,"text":"وسمع بخبرهم تجار البلاد فاخذوا من الفضة والذهب شيئا كثيرا وعبيدهم وجاءوا المحلة حتى يشتروا بني اسرائيل عبيدا لهمو انضمت اليهم جيوش سورية وارض الغرباء"},{"n":42,"text":"وراى يهوذا واخوته تفاقم الشر وان الجيوش حالة في تخومهم وبلغهم كلام الملك انه امر باهلاك الشعب واستئصاله"},{"n":43,"text":"فقال كل واحد لصاحبه هلم ننهض شعبنا من مذلته ونقاتل عن شعبنا واقداسنا"},{"n":44,"text":"فاحتشدت الجماعة لتتاهب للقتال وتصلي وتسال الرافة والمراحم"},{"n":45,"text":"وكانت اورشليم مهجورة كالقفر لا يدخلها ولا يخرج منها احد من بنيها وكان المقدس مدوسا وابناء الاجانب في القلعة التيكانت \nمسكنا للامم وقد زال الطرب عن يعقوب وبطل المزمار والكنارة"},{"n":46,"text":"فاجتمعوا وساروا الى المصفاة قبالة اورشليم لان المصفاة كانت من قبل هي موضع الصلاة لاسرائيل"},{"n":47,"text":"وصاموا في ذلك اليوم وتحزموا بالمسوح وحثوا الرماد على رؤوسهم ومزقوا ثيابهم"},{"n":48,"text":"ونشروا كتاب الشريعة الذي كانت الامم تبحث فيه عن مثال لاصنامها"},{"n":49,"text":"واتوا بثياب الكهنوت وبالبواكير والعشور ثم دعوا النذراء الذين قد استوفوا ايامهم"},{"n":50,"text":"ورفعوا اصواتهم الى السماء قائلين ما نصنع بهؤلاء والى اين ننطلق بهم"},{"n":51,"text":"فان اقداسك قد ديست ودنست وكهنتك في النحيب والمذلة"},{"n":52,"text":"وها ان الامم قد اجتمعوا علينا ليبيدونا وانت عليم بما ياتمرون علينا"},{"n":53,"text":"فكيف نستطيع الثبات امامهم ان لم تكن انت في نصرتنا"},{"n":54,"text":"ثم نفخوا في الابواق وصرخوا بصوت عظيم"},{"n":55,"text":"وبعد ذلك رتب يهوذا قواد الشعب رؤساء الالف والمئة والخمسين والعشرة"},{"n":56,"text":"وامر من اخذ في بناء بيت او خطب امراة او غرس كرما او كان خائفا بان يرجع الى بيته بحسب الشريعة"},{"n":57,"text":"ثم سار الجيش ونزلوا بجنوب عماوس"},{"n":58,"text":"فقال يهوذا تنطقوا وكونوا ذوي باس وتاهبوا للغد لمقاتلة هذه الامم المجتمعة علينا لتبيدنا نحن واقداسنا"},{"n":59,"text":"فانه خير لنا ان نموت في القتال ولا نعاين الشر في قومنا واقداسنا"},{"n":60,"text":"وكما تكون مشيئته في السماء فليصنع بنا"}]},{"label":"سفر المكابيين الأول 4","verses":[{"n":1,"text":"واخذ جرجياس خمسة الاف راجل والف فارس منتخبين وسار الجيش ليلا"},{"n":2,"text":"ليهجموا على محلة اليهود ويوقعوا بهم بغتة وكان اهل القلعة ادلاء لهم"},{"n":3,"text":"فسمع يهوذا فسار هو ورجال الباس ليضرب جيش الملك الذي في عماوس"},{"n":4,"text":"وكان لا يزال متفرقا في خارج المحلة"},{"n":5,"text":"فلما انتهى جرجياس الى محلة يهوذا ليلا لم يجد احدا فطلبهم في الجبال لانه قال انهم هربوا منا"},{"n":6,"text":"فلما كان النهار ظهر يهوذا في السهل ومعه ثلاثة الاف رجل الا انهم لم يكن معهم من الجنن والسيوف ما يوافق مرادهم"},{"n":7,"text":"وراوا ان جيش الامم قوي وعليه الدروع والخيل من حوله وهم مدربون على الحرب"},{"n":8,"text":"فقال يهوذا لمن معه من الرجال لا تخافوا كثرتهم ولا تخشوا بطشهم"},{"n":9,"text":"اذكروا كيف نجا اباؤنا في بحر القلزم حين تتبعهم فرعون بجيشه"},{"n":10,"text":"فالان لنصرخن الى السماء لعله يرحمنا ويتذكر عهد ابائنا ويكسر هذا الجيش امامنا اليوم"},{"n":11,"text":"فتعلم كل الامم ان لاسرائيل فاديا ومخلصا"},{"n":12,"text":"ورفع الاجانب ابصارهم فراوهم مقبلين عليهم"},{"n":13,"text":"فخرجوا من المحلة للقتال ونفخ اصحاب يهوذا في البوق"},{"n":14,"text":"واقتتلوا فانكسرت الامم وانهزمت الى السهل"},{"n":15,"text":"وسقط جميع ساقتهم بالسيف فتعقبوهم الى جازر وسهول ادوم واشدود ويمنيا وكان الساقطون منهم ثلاثة الاف رجل"},{"n":16,"text":"ثم رجع يهوذا وجيشه عن تعقبهم"},{"n":17,"text":"وقال للشعب لا تطمعوا في الغنائم لان الحرب لا تزال قائمة علينا"},{"n":18,"text":"فان جرجياس وجيشه بالقرب منا في الجبل فاثبتوا الان امام اعدائنا وقاتلوهم وبعد ذلك تاخذون الغنائم بامان"},{"n":19,"text":"ولم يفرغ يهوذا من هذا الكلام حتى ظهرت فرقة تتشوف من الجبل"},{"n":20,"text":"فرات انهم قد انكسروا وان المحلة قد احرقت كما دلهم على ذلك الدخان المتصاعد"},{"n":21,"text":"فلما عاينوا ذلك خافوا جدا واذ راوا جيش يهوذا في السهل مستعدا للقتال"},{"n":22,"text":"فروا جميعا الى ارض الاجانب"},{"n":23,"text":"فرجع يهوذا الى غنائم المحلة فاخذوا ذهبا كثيرا وفضة وسمنجونيا وارجوانا بحريا واموالا جزيلة"},{"n":24,"text":"وعادوا وهم يسبحون الرب ويباركونه الى السماء لانه صالح لان الى الابد رحمته"},{"n":25,"text":"وكان في ذلك اليوم خلاص عظيم في اسرائيل"},{"n":26,"text":"ووفد كل من نجا من الاجانب على ليسياس واخبروه بجميع ما وقع"},{"n":27,"text":"فلما سمع ذلك بهت وانكسر عزمه اذ لم ينفذ في اسرائيل ما كان يريده ولم يتم ما امر به الملك"},{"n":28,"text":"فلما كانت السنة القابلة جمع ليسياس ستة الاف راجل منتخبين وخمسة الاف فارس لمحاربتهم"},{"n":29,"text":"فاتوا الى ادوم ثم نزلوا ببيت صور فلاقاهم يهوذا في عشرة الاف رجل"},{"n":30,"text":"فراى جيشا قويا فصلى وقال مبارك انت يا مخلص اسرائيل الذي حطم بطش الجبار على يد عبده داود واسلم محلة الاجانب الى يد \nيوناتان بن شاول وحامل سلاحه"},{"n":31,"text":"فالق هذا الجيش في ايدي شعبك اسرائيل وليخزوا مع جنودهم وفرسانهم"},{"n":32,"text":"احلل عليهم الرعدة واذب تجبر قوتهم وليضطربوا وينسحقوا"},{"n":33,"text":"اسقطهم بسيف محبيك وليسبحك بالاناشيد جميع الذين يعرفون اسمك"},{"n":34,"text":"ثم التحم القتال فسقط من جيش ليسياس خمسة الاف رجل وصرعوا امامهم"},{"n":35,"text":"فلما راى ليسياس انكسار جيشه وبسالة جيش يهوذا وانهم مستعدون بشجاعتهم اما للحياة واما للموت ذهب الى انطاكية وجمع \nجيشا من الغرباء ولما كثر جيشه الاول هم بالرجوع الى اليهودية"},{"n":36,"text":"وان يهوذا واخوته قالوا ها ان اعداءنا قد انسحقوا فلنصعد الان لتطهير المقادس وتدشينها"},{"n":37,"text":"فاجتمع كل الجيش وصعدوا الى جبل صهيون"},{"n":38,"text":"فراوا المقدس خاليا والمذبح منجسا والابواب محرقة وقد طلع النبات في الديار كما يطلع في غابة او جبل من الجبال والغرفات \nمهدومة"},{"n":39,"text":"فمزقوا ثيابهم وناحوا نوحا عظيما وحثوا على رؤوسهم رمادا"},{"n":40,"text":"وسقطوا بوجوههم على الارض ونفخوا في ابواق الاشارة وصرخوا الى السماء"},{"n":41,"text":"حينئذ رتب يهوذا رجالا يصادمون اهل القلعة ريثما يطهر المقادس"},{"n":42,"text":"واختار كهنة لا عيب فيهم من ذوي الحرص على الشريعة"},{"n":43,"text":"فطهروا المقادس ورفعوا الحجارة المدنسة الى موضع نجس"},{"n":44,"text":"ثم ائتمروا في مذبح المحرقة المدنس ماذا يصنعون به"},{"n":45,"text":"فخطرت لهم مشورة صالحة ان يهدموه لئلا يكون لهم عارا لتدنيس الامم اياه فهدموا المذبح"},{"n":46,"text":"ووضعوا الحجارة في جبل البيت في موضع لائق الى ان ياتي نبي ويجيب عنها"},{"n":47,"text":"ثم اخذوا حجارة غير منحوتة وفاقا للشريعة وبنوا المذبح الجديد على رسم الاول"},{"n":48,"text":"وبنوا المقادس وداخل البيت وقدسوا الديار"},{"n":49,"text":"وصنعوا انية مقدسة جديدة وحملوا المنارة ومذبح البخور والمائدة الى الهيكل"},{"n":50,"text":"وبخروا على المذبح واوقدوا السرج التي على المنارة فكانت تضيء في الهيكل"},{"n":51,"text":"وجعلوا الخبز على المائدة ونشروا السجوف واتموا جميع الاعمال التي عملوها"},{"n":52,"text":"وبكروا في اليوم الخامس عشر من الشهر التاسع وهو كسلو في السنة المئة والثامنة والاربعين"},{"n":53,"text":"وقدموا ذبيحة بحسب الشريعة على مذبح المحرقة الجديد الذي صنعوه"},{"n":54,"text":"وفي مثل الوقت واليوم الذي فيه دنسته الامم في ذلك اليوم دشن بالاناشيد والعيدان والكنارات والصنوج"},{"n":55,"text":"فخر جميع الشعب على وجوههم وسجدوا للذي انجحهم وباركوه الى السماء"},{"n":56,"text":"واتموا تدشين المذبح في ثمانية ايام وقدموا المحرقات بفرح وذبحوا ذبيحة السلامة والحمد"},{"n":57,"text":"وزينوا وجه الهيكل باكاليل من الذهب وتروس ودشنوا الابواب والغرفات وجعلوا لها مصاريع"},{"n":58,"text":"فكان عند الشعب سرور عظيم جدا وازيل تعيير الامم"},{"n":59,"text":"ورسم يهوذا واخوته وجماعة اسرائيل كلها ان يعيد لتدشين المذبح في وقته سنة فسنة مدة ثمانية ايام من اليوم الخامس \nوالعشرين من شهر كسلو بسرور وابتهاج"},{"n":60,"text":"وفي ذلك الزمان بنوا على جبل صهيون من حوله اسوارا عالية وبروجا حصينة لئلا تجيء الامم وتطاه كما فعلت من قبل"},{"n":61,"text":"واقام ثم جيشا يحرسونه وحصنوا بيت صور صيانة له حتى يكون للشعب معقلا تلقاء ادوم"}]},{"label":"سفر المكابيين الأول 5","verses":[{"n":1,"text":"ولما سمعت الامم التي من حولهم ان قد بني المذبح ودشن المقدس كما كانا من قبل استشاطوا غضبا"},{"n":2,"text":"واتمروا ان يبيدوا من بينهم من نسل يعقوب وطفقوا يقتلون ويهلكون من الشعب"},{"n":3,"text":"وكان يهوذا يحارب بني عيسو في ادوم عند اقربتين لانهم كانوا يضيقون على اسرائيل فضربهم ضربة عظيمة ودفعهم وسلب غنائمهم"},{"n":4,"text":"وتذكر شر بني بيان الذين كانوا شركا ومعثرة للشعب يكمنون لهم على الطرق"},{"n":5,"text":"فالجاهم الى البروج وحاصرهم وابسلهم واحرق بروجهم وكل من كان فيها بالنار"},{"n":6,"text":"ثم عبر الى بني عمون فصادف عسكرا قويا وشعبا كثيرا تحت قيادة تيموتاوس"},{"n":7,"text":"فواقعهم في حروب كثيرة فانكسروا امامه فاوقع بهم"},{"n":8,"text":"وفتح يعزير وتوابعها ثم عاد الى اليهودية"},{"n":9,"text":"وان الامم الذين في جلعاد اجتمعوا على من كان من اسرائيل في تخومهم ليبيدوهم ففروا الى حصن دياتما"},{"n":10,"text":"وارسلوا كتابا الى يهوذا واخوته قائلين ان الامم الذين حولنا قد اجتمعوا علينا يريدون ابادتنا"},{"n":11,"text":"وفي عزمهم ان ياتوا ويستفتحوا الحصن الذي التجانا اليه وجيشهم تحت قيادة تيموتاوس"},{"n":12,"text":"فالان هلم واستنقذنا من ايديهم فقد سقط منا عدد كثير"},{"n":13,"text":"وجميع اخوتنا الذين في ارض طوب قد قتلوا وسبيت نساؤهم واولادهم وسلبت امتعتهم وهلك هناك نحو الف رجل"},{"n":14,"text":"فبينما هم يقراون الكتاب اذا برسل اخرين قد وفدوا من الجليل وثيابهم ممزقة واخبروا بمثل ذلك"},{"n":15,"text":"قائلين قد اجتمعوا علينا من بطلمايس وصور وصيدا وكل جليل الامم ليبيدونا"},{"n":16,"text":"فلما سمع يهوذا والشعب هذا الكلام عقدوا مجمعا عظيما وتشاوروا فيما يصنعون باخوتهم الذين في الضيق تحت الحصار"},{"n":17,"text":"فقال يهوذا لسمعان اخيه اختر لك رجالا وانطلق واستنقذ اخوتك الذين في الجليل وانا ويوناتان اخي ننطلق الى ارض جلعاد"},{"n":18,"text":"واستخلف يوسف بن زكريا وعزريا قائدي الشعب مع بقية الجيش في اليهودية للمحافظة"},{"n":19,"text":"واوصاهما قائلا توليا امر هذا الشعب ولا تقيما على الامم حربا حتى نعود"},{"n":20,"text":"فانقسمت الرجال ثلاثة الاف مع سمعان ينطلقون الى الجليل وثمانية الاف مع يهوذا الى ارض جلعاد"},{"n":21,"text":"وانطلق سمعان الى الجليل وناصب الامم حروبا كثيرة فانكسرت الامم من وجهه فتتبعهم الى باب بطلمايس"},{"n":22,"text":"فسقط من الامم ثلاثة الاف رجل وسلب غنائمهم"},{"n":23,"text":"واخذ الذين في الجليل وعربات مع النساء والاولاد وكل ما كان لهم وجاء بهم الى اليهودية بسرور عظيم"},{"n":24,"text":"واما يهوذا المكابي ويوناتان اخوه فعبرا الاردن وسارا مسيرة ثلاثة ايام في البرية"},{"n":25,"text":"فصادفا النباطيين فتلقوهما بسلام وقصوا عليهما كل ما اصاب اخوتهما في ارض جلعاد"},{"n":26,"text":"وان كثيرين منهم قد حصروا في بصرة وباصر وعليم وكسفور ومكيد وقرنائيم وكلها مدن حصينة عظيمة"},{"n":27,"text":"وانهم ايضا محصورون في سائر مدن ارض جلعاد والقوم مستعدون لمحاصرتهم غدا في الحصون والقبض عليهم وابادتهم جميعا في يوم \nواحد"},{"n":28,"text":"فعدل يهوذا جيشه بغتة وتوجه جهة البرية الى باصر فاستحوذ على المدينة وقتل كل ذكر بحد السيف وسلب جميع غنائمهم واحرق \nالمدينة بالنار"},{"n":29,"text":"ثم قام من هناك ليلا وسار الى الحصن"},{"n":30,"text":"ولما كان الصبح رفعوا ابصارهم فاذا بقوم كثيرين لا عدد لهم حاملين سلالم ومجانيق لفتح الحصن وهم محاصرون لهم"},{"n":31,"text":"وراى يهوذا ان الحرب قد التحمت وقد علت جلبة المدينة الى السماء بالابواق والصراخ العظيم"},{"n":32,"text":"فقال لرجال الجيش قاتلوا اليوم عن اخوتكم"},{"n":33,"text":"وخرج في ثلاث فرق من ورائهم ونفخوا في الابواق وصرخوا في الصلاة"},{"n":34,"text":"وعلم جيش تيموتاوس انه المكابي فهربوا من وجهه فضربهم ضربة عظيمة فسقط منهم في ذلك اليوم ثمانية الاف رجل"},{"n":35,"text":"ثم انصرف الى المصفاة وحاربها فافتتحها وقتل كل ذكر بها وسلب غنائمها واحرقها بالنار"},{"n":36,"text":"ومضى من هناك فافتتح كسفور ومكيد وباصر وسائر مدن ارض جلعاد"},{"n":37,"text":"وبعد هذه الامور جمع تيموتاوس جيشا اخر ونزل قبالة رافون في عبر الوادي"},{"n":38,"text":"فارسل يهوذا رجالا يكشفون امر الجيش فاخبروه قائلين ان جميع الامم التي حولنا قد انضمت اليهم وهم جيش عظيم جدا"},{"n":39,"text":"وقد استاجروا العرب يظاهرونهم ونزلوا في عبر الوادي وفي عزمهم ان ياتوك للقتال فخرج يهوذا لملاقاتهم"},{"n":40,"text":"وقال تيموتاوس لرؤساء جيشه اذا بلغ يهوذا وجيشه الى وادي الماء فان عبر الينا اولا فلا نطيق الثبات امامه بل يتغلب علينا \nتغلبا"},{"n":41,"text":"وان تخوف وحل في عبر النهر جزنا اليه وتغلبنا عليه"},{"n":42,"text":"فلما بلغ يهوذا الى وادي الماء اقام كتبة الشعب على الوادي وامرهم قائلا لا تدعوا احدا يحل ههنا بل لينطلقوا بجملتهم الى \nالحرب"},{"n":43,"text":"وعبر اليهم وهو في المقدمة وكل الشعب وراءه فانكسرت امامه جميع الامم والقوا سلاحهم وفروا الى المعبد الذي في قرنائيم"},{"n":44,"text":"فاستولى اليهود على المدينة واحرقوا المعبد مع كل من كان فيه بالنار وانكسر اهل قرنائيم ولم يطيقوا الثبات امام يهوذا"},{"n":45,"text":"وجمع يهوذا كل من كان من اسرائيل في ارض جلعاد صغيرهم وكبيرهم ونساءهم واولادهم مع امتعتهم جيشا عظيما جدا لينصرف بهم \nالى ارض يهوذا"},{"n":46,"text":"فبلغوا الى عفرون وهي مدينة عظيمة على المدخل حصينة جدا فلم يكن لهم ان يحيدوا عنها يمنة ولا يسرة الا ان يجوزوا فيوسطها"},{"n":47,"text":"فاغلق اهل المدينة على انفسهم وردموا الابواب بالحجارة فارسا اليهم يهوذا بكلام السلم"},{"n":48,"text":"قائلا انا نجوز في ارضك لنذهب الى ارضنا ولا يضركم احد انما نمر باقدامنا فابوا ان يفتحوا له"},{"n":49,"text":"فامر يهوذا ان ينادى في المحلة بان يهجم كل واحد من المكان الذي هو فيه"},{"n":50,"text":"فهجم رجال الباس وحاربوا المدينة كل ذلك اليوم وليلته كلها فاسلمت المدينة الى يديه"},{"n":51,"text":"فاهلك كل ذكر بحد السيف ودمرها وسلب غنائمها واجتاز في المدينة من فوق القتلى"},{"n":52,"text":"ثم عبروا الاردن الى السهل العظيم قبالة بيت شان"},{"n":53,"text":"وكان يهوذا يجمع المتخلفين ويشجع الشعب طول الطريق حتى وصلوا الى ارض يهوذا"},{"n":54,"text":"فصعدوا جبل صهيون بسرور وابتهاج وقدموا المحرقات لاجل انه لم يسقط احد منهم حتى رجعوا بسلام"},{"n":55,"text":"وفي الايام التي كان فيها يهوذا ويوناتان في جلعاد وسمعان اخوه في الجليل قبالة بطلمايس"},{"n":56,"text":"سمع يوسف بن زكريا وعزريا رئيسا الجيش بما ابدوا من الحماسة والقتال"},{"n":57,"text":"فقالا لنقم لنا نحن ايضا اسما ولننطلق لمحاربة الامم التي حولنا"},{"n":58,"text":"ثم امرا الجيش الذي معهما فزحفوا على يمنيا"},{"n":59,"text":"فخرج جرجياس ورجاله من المدينة الى ملاقاتهم للقتال"},{"n":60,"text":"فانكسر يوسف وعزريا فتتبعوهما الى حدود اليهودية وسقط في ذلك اليوم من شعب اسرائيل الفا رجل وكانت في شعب اسرائيل حطمة \nعظيمة"},{"n":61,"text":"ذلك لانهما لم يسمعا ليهوذا واخوته ظنا منهما بانهما يبديان حماسة"},{"n":62,"text":"الا انهما لم يكونا من نسب اولئك الرجال الذين اوتوا خلاص اسرائيل على ايديهم"},{"n":63,"text":"وعظم الرجل يهوذا واخوته جدا في عيون كل اسرائيل وجميع الامم التي سار اليها ذكرهم"},{"n":64,"text":"وكانوا يجتمعون اليهم باصوات التهنئة"},{"n":65,"text":"وخرج يهوذا واخوته وحاربوا بني عيسو في ارض الجنوب وضرب حبرون وتوابعها وهدم سورها واحرق البروج التيحولها"},{"n":66,"text":"وسار قاصدا ارض الاجانب وجال في ارض السامرة"},{"n":67,"text":"وفي ذلك الحين سقط كهنة في الحرب وكانوا يريدون ان يبدوا حماسة فخرجوا الى الحرب عن غير تدبر"},{"n":68,"text":"ثم توجه يهوذا الى اشدود في ارض الاجانب فهدم مذابحهم واحرق منحوتات الهتهم بالنار وسلب غنائم المدن وعاد الى ارض يهوذا"}]},{"label":"سفر المكابيين الأول 6","verses":[{"n":1,"text":"وفيما كان انطيوكس الملك يجول في الاقاليم العليا سمع بذكر المايس وهي مدينة بفارس مشهورة باموالها من الفضة والذهب"},{"n":2,"text":"وان بها هيكلا فيه كثير من الاموال وفيه سجوف الذهب والدروع والاسلحة التي تركها ثم الاسكندر بن فيلبس الملك المكدوني الذي \nكان اول ملك في اليونان"},{"n":3,"text":"فاتى وحاول ان ياخذ المدينة وينهبها فلم يستطع لان الامر كان قد عرف عند اهل المدينة"},{"n":4,"text":"فثاروا اليه وقاتلوه فهرب ومضى من هناك بغم شديد راجعا الى بابل"},{"n":5,"text":"وجاءه في فارس مخبر بان الجيوش التي وجهت الى ارض يهوذا قد انكسرت"},{"n":6,"text":"وان ليسياس قد انهزم من وجههم وكان قد خرج عليهم في جيش في غاية القوة فتعززوا بالسلاح والذخائر والغنائم الكثيرة التي \nاخذوها ممن دمروهم من الجيوش"},{"n":7,"text":"وهدموا الرجاسة التي كان قد بناها على المذبح في اورشليم وحوطوا المقدس بالاسوار الرفيعة كما كان من قبل وحصنوا بيت صور \nمدينتهم"},{"n":8,"text":"فلما سمع الملك هذا الكلام بهت واضطرب جدا وانطرح على الفراش وقد اوقعه الغم في السقم لان الامر وقع على خلاف مشتهاه"},{"n":9,"text":"فلبث هناك اياما كثيرة لانه تجدد فيه غم شديد وايقن بالموت"},{"n":10,"text":"فدعا جميع اصحابه وقال لهم لقد شرد النوم عن عيني وسقط قلبي من الكرب"},{"n":11,"text":"فقلت في نفسي الى اي بلاء صرت وما اعظم اللجة التي انا فيها بعد ان كنت مسرورا ومحبوبا في سلطاني"},{"n":12,"text":"اني لاتذكر المساوئ التي صنعتها في اورشليم وكيف اخذت كل انية الذهب والفضة التي كانت فيها وارسلت لابادة سكان يهوذا \nبغير سبب"},{"n":13,"text":"فانا اعلم باني لاجل ذلك اصابتني هذه البلايا وها انا اهلك بكمد شديد في ارض غريبة"},{"n":14,"text":"ثم دعا فيلبس احد اصحابه واقامه على جميع مملكته"},{"n":15,"text":"ودفع اليه تاجه وحلته وخاتمه واوصاه بتدبير انطيوكس ابنه وترشيحه للملك"},{"n":16,"text":"ومات هناك انطيوكس الملك في السنة المئة والتاسعة والاربعين"},{"n":17,"text":"وعلم ليسياس ان الملك قد توفي وملك موضعه انطيوكس ابنه الذي رباه هو في حداثته وسماه باسم اوباطور"},{"n":18,"text":"وكان اهل القلعة يصدون اسرائيل عن دخول المقادس ويحاولون الاضرار بهم من كل جانب وتوطيد الامم بينهم"},{"n":19,"text":"فعزم يهوذا على الايقاع بهم وحشد جميع الشعب لمحاصرتهم"},{"n":20,"text":"فاجتمعوا معا وحاصروهم سنة مئة وخمسين ونصب عليهم القذافات والمجانيق"},{"n":21,"text":"فخرج بعض منهم من الحصار فانضم اليهم نفر منافقون من اسرائيل"},{"n":22,"text":"وانطلقوا الى الملك وقالوا الى متى لا تجري القضاء ولا تنتقم لاخوتنا"},{"n":23,"text":"انا ارتضينا بخدمة ابيك والعمل باوامره واتباع رسومه"},{"n":24,"text":"ولذلك ابناء شعبنا يحاصرون القلعة بغضا لنا وكل من صادفوه منا قتلوه ونهبوا املاكنا"},{"n":25,"text":"ولم يكتفوا بمد ايديهم علينا ولكنهم تجاوزا الى جميع تخومنا"},{"n":26,"text":"وها انهم قد زحفوا الى قلعة اورشليم ليستحوذوا عليها وعلى المقدس وحصنوا بيت صور"},{"n":27,"text":"فالان ان لم تسرع وتبادرهم فسيصنعون شرا من ذلك فلا تقدر ان تكفهم"},{"n":28,"text":"فلما سمع الملك غضب وجمع جميع اصحابه وقواد جيشه ورؤساء الفرسان"},{"n":29,"text":"وجاءته من ممالك اخرى ومن جزائر البحار جنود مستاجرة"},{"n":30,"text":"وكان عدد جيوشه مئة الف راجل وعشرين الف فارس واثنين وثلاثين فيلا مضراة على الحرب"},{"n":31,"text":"فزحفوا مجتازين في ادوم ونزلوا عند بيت صور وحاربوا اياما كثيرة وصنعوا المجانيق فخرجوا واحرقوها بالنار وقاتلوا بباس"},{"n":32,"text":"فسار يهوذا عن القلعة ونزل ببيت زكريا تجاه محلة الملك"},{"n":33,"text":"فبكر الملك ووجه بباس جيشه الى طريق بيت زكريا فتاهبت الجيوش للقتال ونفخوا في الابواق"},{"n":34,"text":"واروا الفيلة عصير العنب والتوت حتى يهيجوها للقتال"},{"n":35,"text":"ثم وزعوها على الفرق فجعلوا عند كل فيل الف رجل لابسين الدروع المسرودة وعلى رؤوسهم خوذ النحاس واقاموا لكل فيل خمسمئة \nفارس منتخبين"},{"n":36,"text":"فكان اولئك حيثما وجد الفيل سبقوا اليه وحيثما ذهب ذهبوا معه لا يفارقونه"},{"n":37,"text":"وكان على كل فيل برج حصين من الخشب يحميه مطوق بالمجانيق وعلى البرج اثنان وثلاثون رجلا من ذوي الباس يقاتلون منه \nوالهندي يدير الفيل"},{"n":38,"text":"وجعلوا سائر الفرسان من هنا وهناك على جانبي الجيش يحثونه ويكتنفونه في الشعاب"},{"n":39,"text":"فلما لمعت الشمس على تروس الذهب والنحاس لمعت بها الجبال وتاججت كسرج من نار"},{"n":40,"text":"وانتشر جيش الملك قسم على الجبال العالية وقسم في البطاح ومشوا بتحفظ وانتظام"},{"n":41,"text":"فارتعد كل من سمع جلبتهم ودرجان جمهورهم وقعقعة سلاحهم فان الجيش كان عظيما وقويا جدا"},{"n":42,"text":"فتقدم يهوذا وجيشه للمبارزة فسقط من جيش الملك ست مئة رجل"},{"n":43,"text":"وراى العازار بن سواران واحدا من الفيلة عليه الدرع الملكية يفوق جميع الفيلة فظن ان عليه الملك"},{"n":44,"text":"فبذل نفسه ليخلص شعبه ويقيم لنفسه اسما مخلدا"},{"n":45,"text":"وعدا اليه مقتحما في وسط الفرقة يقتل يمنة ويسرة فتفرقوا عنه من هنا ومن هناك"},{"n":46,"text":"ودخل بين قوائم الفيل حتى صار تحته وقتله فسقط عليه الى الارض فمات مكانه"},{"n":47,"text":"وان اليهود لما راوا سطوة الملك وبطش الجيوش ارتدوا عنهم"},{"n":48,"text":"فصعد الملك بجيشه نحو اورشليم لملاقاتهم وزحف الى اليهودية وجبل صهيون"},{"n":49,"text":"وعقد صلحا مع اهل بيت صور فخرجوا من المدينة لنفاد الطعام من عندهم مدة حصرهم فيها اذ كان سبت للارض"},{"n":50,"text":"فاستولى الملك على بيت صور واقام هناك حرسا يحافظون عليها"},{"n":51,"text":"ونزل عند المقدس اياما كثيرة ونصب هناك القذافات والمجانيق والات لرشق النار والحجارة وادوات لرمي السهام ومقاليع"},{"n":52,"text":"وصنع اليهود مجانيق قبالة مجانيقهم وحاربوا اياما كثيرة"},{"n":53,"text":"ولم يكن في اوعيتهم طعام لانها كانت السنة السابعة وكان الذين لجاوا الى اليهودية من الامم قد اكلوا ما فضل من الذخيرة"},{"n":54,"text":"فلم يبق في المقادس الا نفر يسير لان الجوع غلب عليهم فتفرقوا كل واحد الى موضعه"},{"n":55,"text":"وبلغ ليسياس ان فيلبس الذي اقامه انطيوكس في حياته ليرشح انطيوكس ابنه للملك"},{"n":56,"text":"قد رجع من فارس وماداي ومعه جيوش الملك التي سارت في صحبته وانه يحاول ان يتولى الامور"},{"n":57,"text":"فبادر وسعى الى الملك والقواد والجيش وقال لهم انا لنضعف يوما بعد يوم وقد قل طعامنا والمكان الذي نحاصره حصين وامور \nالمملكة تستحثنا"},{"n":58,"text":"والان فلنعاقد هؤلاء الناس ولنبرم صلحا معهم ومع جميع امتهم"},{"n":59,"text":"ولنقرر لهم ان يسلكوا في سننهم كما كانوا من قبل فانهم لاجل سننهم التي نقضناها غضبوا وفعلوا كل ذلك"},{"n":60,"text":"فحسن الكلام في عيون الملك والرؤساء فارسل اليهم في المصالحة فاجابوا"},{"n":61,"text":"فحلف لهم الملك والرؤساء وعلى ذلك خرجوا من الحصن"},{"n":62,"text":"فدخل الملك الى جبل صهيون وراى الموضع حصينا فنقض الحلف الذي حلفه وامر بهدم السور الذي حوله"},{"n":63,"text":"ثم انصرف مسرعا ورجع الى انطاكية فوجد فيلبس قد استولى على المدينة فقاتله واخذ المدينة عنوة"}]},{"label":"سفر المكابيين الأول 7","verses":[{"n":1,"text":"وفي السنة المئة والحادية والخمسين خرج ديمتريوس بن سلوقس من رومية وصعد في نفر يسير الى مدينة بالساحل وملك هناك"},{"n":2,"text":"ولما دخل دار ملك ابائه قبضت الجيوش على انطيوكس وليسياس لتاتيه بهما"},{"n":3,"text":"فلما علم بذلك قال لا تروني اوجههما"},{"n":4,"text":"فقتلتهما الجيوش وجلس ديمتريوس على عرش ملكه"},{"n":5,"text":"فاتاه جميع رجال النفاق والكفر من اسرائيل وفي مقدمتهم الكيمس وهو يطمع ان يصير كاهنا اعظم"},{"n":6,"text":"ووشوا على الشعب عند الملك قائلين ان يهوذا واخوته قد اهلكوا اصحابك وطردونا عن ارضنا"},{"n":7,"text":"فالان ارسل رجلا تثق به يذهب ويفحص عن جميع ما انزله بنا وببلاد الملك من الدمار ويعاقبهم مع جميع اعوانهم"},{"n":8,"text":"فاختار الملك بكيديس احد اصحاب الملك امير عبر النهر وكان عظيما في المملكة وامينا للملك وارسله"},{"n":9,"text":"هو والكيمس الكافر وقد قلده الكهنوت وامره ان ينتقم من بني اسرائيل"},{"n":10,"text":"فسارا وقدما ارض يهوذا في جيش كثيف وانفذا رسلا الى يهوذا واخوته يخاطبونهم بالسلام مكرا"},{"n":11,"text":"فلم يلتفتوا الى كلامهما لانهم راوهما قادمين في جيش كثيف"},{"n":12,"text":"واجتمعت الى الكيمس وبكيديس جماعة الكتبة يسالون حقوقا"},{"n":13,"text":"ووافى الحسيديون وهم المقدمون في بني اسرائيل يسالونهما السلم"},{"n":14,"text":"لانهم قالوا ان مع جيوشه كاهنا من نسل هرون فلا يظلمنا"},{"n":15,"text":"فخاطبهم خطاب سلام وحلف لهم قائلا انا لا نريد بكم ولا باصحابكم سوءا"},{"n":16,"text":"فصدقوه فقبض على ستين رجلا منهم وقتلهم في يوم واحد كما هو مكتوب"},{"n":17,"text":"جعلوا لحوم اصفيائك وسفكوا دماءهم حول اورشليم ولم يكن لهم من دافن"},{"n":18,"text":"فوقع خوفهم ورعبهم على جميع الشعب لانهم قالوا ليس فيهم شيء من الحق والعدل اذ نكثوا العهد والحلف الذي حلفوه"},{"n":19,"text":"وارتحل بكيديس عن اورشليم ونزل ببيت زيت وارسل وقبض على كثيرين من الذين كانوا قد خذلوه وعلى بعض من الشعب وذبحهم \nعلىالجب العظيم"},{"n":20,"text":"ثم سلم البلاد الى الكيمس وابقى معه جيشا يؤازره وانصرف بكيديس الى الملك"},{"n":21,"text":"وكان الكيمس يجهد في تولى الكهنوت الاعظم"},{"n":22,"text":"واجتمع اليه جميع المفسدين في الشعب واستولوا على ارض يهوذا وضربوا اسرائيل ضربة عظيمة"},{"n":23,"text":"وراى يهوذا جميع الشر الذي صنعه الكيمس ومن معه في بني اسرائيل وكان فوق ما صنعت الامم"},{"n":24,"text":"فخرج الى جميع حدود اليهودية مما حولها وانزل نقمته بالقوم الذين خذلوه فكفوا عن مهاجمة البلاد"},{"n":25,"text":"فلما راى الكيمس ان قد تقوى يهوذا ومن معه وعلم انه لا يستطيع الثبات امامهم رجع الى الملك ووشى عليهم بجرائم"},{"n":26,"text":"فارسل الملك نكانور احد رؤسائه المشهورين وكان عدوا مبغضا لاسرائيل وامره بابادة الشعب"},{"n":27,"text":"فوفد نكانور على اورشليم في جيش كثير وارسل الى يهوذا واخوته يخاطبهم بالسلام مكرا"},{"n":28,"text":"قائلا لا يكن قتال بيني وبينكم فانني قادم في نفر قليل لاواجهكم بسلام"},{"n":29,"text":"وجاء الى يهوذا وحيا بعضهما بعضا تحية السلم وكان الاعداء مستعدين لاختطاف يهوذا"},{"n":30,"text":"وعلم يهوذا ان مواجهته كانت مكرا فاجفل منه وابي ان يعود الى مواجهته"},{"n":31,"text":"فلما راى نكانور ان مشورته قد كشفت خرج لملاقاة يهوذا بالقتال عند كفر سلامة"},{"n":32,"text":"فسقط من جيش نكانور نحو خمسة الاف رجل وفر الباقون الى مدينة داود"},{"n":33,"text":"وبعد هذه الامور صعد نكانور الى جبل صهيون فخرج بعض الكهنة من المقادس وبعض شيوخ الشعب يحيونه تحية السلم ويرونه \nالمحرقات المقربة عن الملك"},{"n":34,"text":"فاستهزا بهم وسخر منهم وتقذرهم وكلمهم بتجبر"},{"n":35,"text":"واقسم بغضب قائلا ان لم يسلم يهوذا وجيشه الى يدي اليوم فسيكون متى عدت بسلام اني احرق هذا البيت وخرج بحنق شديد"},{"n":36,"text":"فدخل الكهنة ووقفوا امام المذبح والهيكل وبكوا وقالوا"},{"n":37,"text":"انك يا رب قد اخترت هذا البيت ليدعى فيه باسمك ويكون بيت صلاة وتضرع لشعبك"},{"n":38,"text":"فانزل النقمة بهذا الرجل وجيشه وليسقطوا بالسيف واذكر تجاديفهم ولا تبق عليهم"},{"n":39,"text":"ثم خرج نكانور من اورشليم ونزل ببيت حورون فانحاز اليه جيش سورية"},{"n":40,"text":"ونزل يهوذا باداسة في ثلاثة الاف رجل وصلى يهوذا وقال"},{"n":41,"text":"انه لما جدف الذين كانوا مع ملك اشور خرج ملاكك يا رب وضرب مئة الف وخمسة وثمانين الفا منهم"},{"n":42,"text":"هكذا فاحطم هذا الجيش امامنا اليوم فيعلم الباقون انهم تكلموا على اقداسك سوءا واقض عليه بحسب خبثه"},{"n":43,"text":"ثم الحم الجيشان القتال في اليوم الثالث عشر من شهر اذار فانكسر جيش نكانور وكان هو اول من سقط في القتال"},{"n":44,"text":"فلما راى جيش نكانور انه قد سقط القوا اسلحتهم وهربوا"},{"n":45,"text":"فتعقبوهم مسيرة يوم من اداسة الى مدخل جازر ونفخوا وراءهم في ابواق الاشارة"},{"n":46,"text":"فخرج الناس من جميع قرى اليهودية من كل جانب وصدموهم فارتدوا الى جهة الذين يتعقبونهم فسقطوا جميعهم بالسيف ولم يبق \nمنهم احد"},{"n":47,"text":"فاخذوا الغنائم والاسلاب وقطعوا راس نكانور ويمينه التي مدها بتجبر واتوا بهما وعلقوهما قبالة اورشليم"},{"n":48,"text":"ففرح الشعب جدا وقضوا ذلك النهار بمسرة عظيمة"},{"n":49,"text":"ورسموا ان يعيد ذلك اليوم الثالث عشر من اذار كل سنة"},{"n":50,"text":"وهدات ارض يهوذا اياما يسيرة"}]},{"label":"سفر المكابيين الأول 8","verses":[{"n":1,"text":"وسمع يهوذا باسم الرومانيين انهم ذوو اقتدار عظيم ويعزون كل من ضوى اليهم وكل من جاءهم اثروه بمودتهم ولهم شوكة شديدة"},{"n":2,"text":"وقصت عليه وقائعهم وما ابدوا من الحماسة في قتال الغاليين وانهم اخضعوهم وضربوا عليهم الجزية"},{"n":3,"text":"وما فعلوا في بلاد اسبانية واستيلاؤهم على معادن الفضة والذهب التي هناك وانهم اخضعوا كل مكان بمشورتهم وطول اناتهم"},{"n":4,"text":"وان كان ذلك المكان عنهم بمسافة بعيدة وكسروا الذين اغاروا عليهم من الملوك من اقاصي الارض وضربوهم ضربة عظيمة وانسائر الملوك يحملون اليهم الجزية كل سنة"},{"n":5,"text":"وقد قهروا فيلبس وفرساوس ملك كتيم في الحرب وكل من قاتلهم واخضعوهم"},{"n":6,"text":"وكسروا انطيوكس الكبير ملك اسية الذي زحف لقتالهم ومعه مئة وعشرون فيلا وفرسان وعجلات وجيش كثير جدا"},{"n":7,"text":"وقبضوا عليه حيا وضربوا عليه وعلى الذين يملكون بعده جزية عظيمة ورهائن ووضائع معلومة"},{"n":8,"text":"وان يتركوا بلاد الهند وماداي ولود وخيار بلادهم واخذوها منه واعطوها لاومينيس الملك"},{"n":9,"text":"ولما هم اليونان ان يسيروا لمقاتلتهم بلغهم ذلك"},{"n":10,"text":"فارسلوا اليهم قائدا واحدا وحاربوهم فسقط منهم قتلى كثيرون وسبوا نساءهم واولادهم ونهبوهم واستولوا على ارضهم وهدموا \nحصونهم واستعبدوهم الى هذا اليوم"},{"n":11,"text":"ودمروا سائر الممالك والجزائر التي قاومتهم واستعبدوا سكانها"},{"n":12,"text":"وانهم حفظوا المودة لاوليائهم والذين اعتمدوا عليهم وتسلطوا على الممالك قريبها وبعيدها وكل من سمع باسمهم خافهم"},{"n":13,"text":"ومن ارادوا مؤازرته وتمليكه ملكوه ومن ارادوا خلعه خلعوه فعلا شانهم جدا"},{"n":14,"text":"ومع ذلك كله لم يلبس احد منهم التاج ولا تردى الارجوان مباهاة به"},{"n":15,"text":"وانما وضعوا لهم شورى ياتمر فيها كل يوم ثلاث مئة وعشرون رجلا لاصلاح شؤونهم"},{"n":16,"text":"وهم يفوضون سلطانهم وسياسة ارضهم بجملتها كل سنة الى رجل واحد وجميعهم يطيعون هذا الواحد وليس فيهم حسد ولا منافسة"},{"n":17,"text":"فاختار يهوذا اوبولمس بن يوحنا بن اكوس وياسون بن العازار وارسلهما الى رومية ليعقدا معهم عهد الموالاة والمناصرة"},{"n":18,"text":"ويرفعا عنهم النير لانهم راوا ان دولة اليونان قد استعبدت اسرائيل استعبادا"},{"n":19,"text":"فانطلقا الى رومية في سفر بعيد جدا ودخلا الشورى وتكلما وقالا"},{"n":20,"text":"انا مرسلان اليكم من قبل يهوذا المكابي واخوته وجمهور اليهود لنعقد معكم عهد المناصرة والمسالمة وان تثبتونا في جملة \nمناصريكم واوليائكم"},{"n":21,"text":"فحسن الكلام لديهم"},{"n":22,"text":"وهذه نسخة الكتاب الذي دونوه على الواح من نحاس وارسلوه الى اورشليم حتى يكون عندهم تذكار للمسالمة والمناصرة"},{"n":23,"text":"الفلاح للرومانيين ولامة اليهود في البحر والبر الى الابد وليبعد عنهم السيف والعدو"},{"n":24,"text":"اذا قامت حرب في رومية اولا او عند اي كان من مناصريهم في جميع سلطانهم"},{"n":25,"text":"فامة اليهود تناصر بكل عزمها كما تقتضيه الحال"},{"n":26,"text":"وليس على الرومانيين ان يؤدوا الى المحاربين معهم او يجهروا لهم طعاما ولا اسلحة ولا فضة ولا سفنا كذلك حسن عند الرومانيين لكن يحافظون على اوامر الرومانيين بغير ان ياخذوا شيئا"},{"n":27,"text":"وكذلك امة اليهود اذا حدثت لها حرب اولا فالرومانيون ينتدبون للمناصرة كما تقتضيه الحال"},{"n":28,"text":"وليس على اليهود ان يؤدوا الى المناصرين طعاما ولا اسلحة ولا فضة ولاسفنا كذلك حسن عند الرومانيين لكن يحافظون على اوامر \nاليهود دون غش"},{"n":29,"text":"على هذا الكلام عاهد الرومانيون شعب اليهود"},{"n":30,"text":"واذا شاء هؤلاء او اولئك ان يزيدوا على هذا الكلام او يسقطوا منه فيفعلون برضى الفريقين وكل ما زادوا او اسقطوا يكون \nمقررا"},{"n":31,"text":"اما الشرور التي انزلها بهم الملك ديمتريوس فقد كتبنا اليه قائلين لم ثقلت النير على اوليائنا ومناصرينا اليهود"},{"n":32,"text":"فان عادوا يتظلمون منك فسنجري لهم الحكم ونقاتلك بحرا وبرا"}]},{"label":"سفر المكابيين الأول 9","verses":[{"n":1,"text":"ولما سمع ديمتريوس بان نكانور وجيوشه قد سقطوا في الحرب عاد ثانية فارسل الى ارض يهوذا بكيديس والكيمس ومعهما الجناح الايمن"},{"n":2,"text":"فانطلقا في طريق الجلجال ونزلا عند مشالوت باربيل فاستولى عليها واهلكا نفوسا كثيرة"},{"n":3,"text":"وفي الشهر الاول من السنة المئة والثانية والخمسين نزلا على اورشليم"},{"n":4,"text":"ثم زحفا وانطلقا الى بئروت في عشرين الف راجل والفي فارس"},{"n":5,"text":"وكان يهوذا قد نزل بلاشع ومعه ثلاثة الاف رجل منتخبين"},{"n":6,"text":"فلما راوا كثرة عدد الجيوش خافوا خوفا شديدا فجعل كثيرون ينسابون من المحلة ولم يبق منهم الا ثماني مئة رجل"},{"n":7,"text":"فلما راى يهوذا ان جيشه قد انساب والحرب تضايقه انكسر قلبه لانه لم يبق له وقت لردهم واسترخت عزائمه"},{"n":8,"text":"فقال لمن بقي معه لنقم ونهجم على مناصبينا عسى ان نقدر على مدافعتهم"},{"n":9,"text":"فصرفوه عن عزمه قائلين انه ليس في طاقاتنا اليوم الا ان ننجو بنفوسنا ثم نرجع مع اخواتنا ونقاتلهم فانا عدد قليل"},{"n":10,"text":"فقال يهوذا حاش لي ان افعل مثل ذلك واهرب منهم وان كان قد دنا اجلنا فلنموتن بشجاعة عن اخواتنا ولا نبقين على مجدنا \nوصمة"},{"n":11,"text":"وبرز جيش العدو من المحلة ووقفوا بازائهم وانقسمت الفرسان قسمين وكان الرماة بالمقاليع والقسي يتقدمون الجيش كلها من \nذوي الباس"},{"n":12,"text":"وكان بكيديس في الجناح الايمن فازدلفت الفرقة من الجانبين وهتفوا بالابواق"},{"n":13,"text":"ونفخ رجال يهوذا ايضا في الابواق فارتجت الارض من جلبة العسكرين والتحم القتال من الصبح الى المساء"},{"n":14,"text":"وراى يهوذا ان بكيديس وقوة الجيش في الجناح الايمن فقصدهم ومعه كل ذي قلب ثابت"},{"n":15,"text":"فكسروا الجناح الايمن وتعقبوا اثرهم الى جبل اشدود"},{"n":16,"text":"فلما راى رجال الجناح الايسر انكسار الجناح الايمن انقلبوا على اثار يهوذا ومن معه"},{"n":17,"text":"فاشتد القتال وسقط قتلى كثيرون من الفريقين"},{"n":18,"text":"وسقط يهوذا وهرب الباقون"},{"n":19,"text":"فحمل يوناتان وسمعان يهوذا اخاهما ودفناه في قبر ابائه في مودين"},{"n":20,"text":"فبكاه شعب اسرائيل بكاء عظيما ولطموا عليه وناحوا اياما وقالوا"},{"n":21,"text":"كيف سقط البطل مخلص اسرائيل"},{"n":22,"text":"وبقية اخبار يهوذا وحروبه وما ابداه من الحماسة وجبروته لم تكتب في هذا الموضع لانها كثيرة جدا"},{"n":23,"text":"وكان بعد وفاة يهوذا ان المنافقين برزوا في جميع تخوم اسرائيل وظهر كل فاعلي الاثم"},{"n":24,"text":"وفي تلك الايام حدثت مجاعة عظيمة جدا فتخاذلت البلاد اليهم"},{"n":25,"text":"فاختار بكيديس الكفرة منهم واقامهم رؤساء على البلاد"},{"n":26,"text":"فكانوا يتطلبون اصحاب يهوذا ويتفقدونهم وياتون بهم الى بكيديس فينتقم منهم ويستهزئ بهم"},{"n":27,"text":"فحل باسرائيل ضيق عظيم لم يحدث مثله منذ لم يظهر فيهم نبي"},{"n":28,"text":"فاجتمع جميع اصحاب يهوذا وقالوا ليوناتان"},{"n":29,"text":"انه منذ وفاة يهوذا اخيك لم يقم له كفؤ يخرج على العدو وعلى بكيديس والمبغضين لامتنا"},{"n":30,"text":"فنحن نختارك اليوم رئيسا لنا وقائدا مكانه تحارب حربنا"},{"n":31,"text":"فقبل يوناتان القيادة في ذلك الوقت وقام في موضع يهوذا اخيه"},{"n":32,"text":"فلما علم بكيديس طلب قتله"},{"n":33,"text":"وبلغ ذلك يوناتان وسمعان اخاه وجميع من معه فهربوا الى برية تقوع ونزلوا على ماء جب اسفار"},{"n":34,"text":"فعلم بكيديس فزحف بجميع جيشه الى عبر الاردن يوم سبت"},{"n":35,"text":"وارسل يوناتان يوحنا اخاه بجماعة تحت قيادته يسال النباطيين اولياءه ان يعيروهم عدتهم الوافرة"},{"n":36,"text":"فخرج بنو يمري من ميدابا وقبضوا على يوحنا وكل ما معه وذهبوا بالجميع"},{"n":37,"text":"وبعد هذه الامور اخبر يوناتان وسمعان اخوه ان بني يمري يقيمون عرسا عظيما ويزفون العروس من ميدابا باحتفال عظيم وهيابنة \nبعض عظماء كنعان"},{"n":38,"text":"فذكروا يوحنا اخاهم وصعدوا واختباوا وراء الجبل"},{"n":39,"text":"ثم رفعوا ابصارهم ونظروا فاذا بجلبة وجهاز كثير والعروس واصحابه واخوته خارجون للقائهم بالدفوف والات الطرب واسلحة \nكثيرة"},{"n":40,"text":"فثار عليهم رجال يوناتان من المكمن وضربوهم فسقط قتلى كثيرون وهرب الباقون الى الجبل فاخذوا كل اسلابهم"},{"n":41,"text":"وتحول العرس الى مناحة وصوت الات طربهم الى نحيب"},{"n":42,"text":"ولما انتقموا لدم اخيهم رجعوا الى غيضة الاردن"},{"n":43,"text":"فسمع بكيديس فوفد الى شطوط الاردن يوم سبت في جيش عظيم"},{"n":44,"text":"فقال يوناتان لمن معه لننهض الان ونقاتل عن نفوسنا فليس الامر اليوم كما كان امس فما قبل"},{"n":45,"text":"ها ان الحرب امامنا وخلفنا وماء الاردن والغياض والغاب من هنا ومن هناك فليس لنا مناص"},{"n":46,"text":"والان فاصرخوا الى السماء فتنقذوا من ايدي اعدائكم ثم التحم القتال"},{"n":47,"text":"ومد يوناتان يده ليضرب بكيديس فانصاع عنه الى الوراء"},{"n":48,"text":"فرمى يوناتان ومن معه بانفسهم في الاردن وعاموا الى العبر فلم يعبروا الاردن اليهم"},{"n":49,"text":"وسقط من رجال بكيديس في ذلك اليوم الف رجل فعاد الى اورشليم"},{"n":50,"text":"ثم بنى مدائن حصينة في اليهودية وحصن اريحا وعماوس وبيت حورون وبيت ايل وتمنة وفرعتون وتفون باسوار عالية وابواب \nومزاليج"},{"n":51,"text":"وجعل فيها حرسا يراغمون اسرائيل"},{"n":52,"text":"وحصن مدينة صور وجازر والقلعة وجعل فيها جيوشا وميرة"},{"n":53,"text":"واخذ ابناء قواد البلاد رهائن وجعلهم في القلعة باورشليم في الحبس"},{"n":54,"text":"وفي السنة الثالثة والخمسين في الشهر الثاني امر الكيمس ان يهدم حائط دار المقدس الداخلية فهدم اعمال الانبياء وشرع في التدمير"},{"n":55,"text":"في ذلك الزمان ضرب الكيمس فكف عن صنيعه واعتقل لسانه وفلج ولم يعد يستطيع ان ينطق بكلمة ولا ان يوصي لبنيه"},{"n":56,"text":"ومات الكيمس في ذلك الزمان في عذاب شديد"},{"n":57,"text":"فلما راى بكيديس ان الكيمس قد مات رجع الى الملك وهدات ارض يهوذا سنتين"},{"n":58,"text":"وبعد ائتمر المنافقون كلهم وقالوا ها ان يوناتان والذين معه في منازلهم هادئون مطمئنون فهلموا الان نحمل عليهم بكيديس \nفيقبض عليهم اجمعين في ليلة واحدة"},{"n":59,"text":"وانطلقوا واشاروا عليه بذلك"},{"n":60,"text":"فقام وسار في جيش عظيم وبعث سرا يكتب الى جميع نصرائه في اليهودية ان يقبضوا على يوناتان والذين معه فلم يجدوا الى ذلك سبيلا لان مشورتهم انكشفت لهم"},{"n":61,"text":"ثم قبضوا على خمسين رجلا من البلاد وهم ارباب الفتنة وقتلوهم"},{"n":62,"text":"وانصرف يوناتان وسمعان ومن معهما الى بيت حجلة في البرية وبنى مهدومها وحصنها"},{"n":63,"text":"ولما علم بكيديس حشد جميع جمهوره وراسل حلفاءه في اليهودية"},{"n":64,"text":"وزحف ونزل على بيت حجلة وحاربها اياما كثيرة ونصب المجانيق"},{"n":65,"text":"وان يوناتان ترك سمعان اخاه في المدينة وخرج في عدد من الجند وانتشر في البلاد"},{"n":66,"text":"وضرب ادورين واخوته وبني فاسرون في خيامهم وطفق يوقع بالعدو ويزداد قوة"},{"n":67,"text":"وخرج سمعان ومن معه من المدينة واحرقوا المجانيق"},{"n":68,"text":"وقاتلوا بكيديس فانكسر وضايقوه جدا واذ ذهبت مشورته وخروجه في الباطل"},{"n":69,"text":"استشاط غضبا على الرجال المنافقين الذين اشاروا عليه بالخروج من البلاد وقتل كثيرين منهم وازمع الانصراف الى ارضه"},{"n":70,"text":"وعلم يوناتان فانفذ اليه رسلا في عقد المصالحة ورد الاسرى"},{"n":71,"text":"فاجاب وفعل بحسب كلامه وحلف له انه لن يطلبه بسوء كل ايام حياته"},{"n":72,"text":"ورد اليه الاسرى الذين اسرهم من قبل في ارض يهوذا ثم عاد الى ارضه ولم يعد يسير الى تخومهم"},{"n":73,"text":"فزال السيف من اسرائيل وسكن يوناتان في مكماش واخذ يوناتان يحاكم الشعب واستاصل المنافقين من اسرائيل"}]},{"label":"سفر المكابيين الأول 10","verses":[{"n":1,"text":"وفي السنة المئة والستين صعد الاسكندر الشهير ابن انطيوكس وفتح بطلمايس فقبلوه فملك هناك"},{"n":2,"text":"فسمع ديمتريوس الملك فجمع جيوشا كثيرة جدا وخرج لملاقاته في الحرب"},{"n":3,"text":"وانفذ ديمتريوس الى يوناتان كتبا في معنى السلم متقربا اليه بالاطراء"},{"n":4,"text":"لانه قال لنسبق الى مسالمته قبل ان يسالم الاسكندر علينا"},{"n":5,"text":"فانه سيذكر كل ما انزلنا به وباخوته وامته من المساوئ"},{"n":6,"text":"واذن له ان يجمع جيوشا ويتجهز بالاسلحة ويكون مناصرا له وامر له برد الرهائن الذين في القلعة"},{"n":7,"text":"فجاء يوناتان الى اورشليم وتلا الكتب على مسامع الشعب كله واهل القلعة"},{"n":8,"text":"فلما سمع ان الملك اذن له في جمع الجيوش جزعوا جزعا شديدا"},{"n":9,"text":"ورد اهل القلعة الرهائن الى يوناتان فردهم الى ذوي قرابتهم"},{"n":10,"text":"واقام يوناتان باورشليم وطفق يبني ويجدد المدينة"},{"n":11,"text":"وامر صناع العمل ان يبنوا الاسوار حول جبل صهيون بحجارة منحوتة للتحصين ففعلوا"},{"n":12,"text":"فهرب الغرباء الذين في الحصون التي بناها بكيديس"},{"n":13,"text":"وترك كل واحد مكانه وذهب الى ارضه"},{"n":14,"text":"غير انه بقي في بيت صور قوم من المرتدين عن الشريعة والرسوم فانها كانت ملجا لهم"},{"n":15,"text":"وسمع الاسكندر الملك بالمواعيد التي عرضها ديمتريوس على يوناتان وحدث بما صنع هو واخوته من الحروب واعمال الباس وما \nكابدوه من النصب"},{"n":16,"text":"فقال انا لا نجد من رجل يماثله فلنتخذه لنا وليا ومناصرا"},{"n":17,"text":"وكتب كتبا وبعث اليه بها في هذا المعنى قائلا"},{"n":18,"text":"من الملك الاسكندر الى اخيه يوناتان سلام"},{"n":19,"text":"لقد بلغنا عنك انك رجل شديد الجبروت وخليق بان تكون لنا وليا"},{"n":20,"text":"فنحن نقيمك اليوم كاهنا اعظم في امتك وتسمى ولي الملك وتهتم بما لنا وتبقى في مودتنا وارسل اليه ارجوانا وتاجا من ذهب"},{"n":21,"text":"فلبس يوناتان الحلة المقدسة في الشهر السابع من السنة المئة والستين في عيد المظال وجمع الجيوش وتجهز باسلحة كثيرة"},{"n":22,"text":"وذكر ذلك لديمتريوس فشق عليه وقال"},{"n":23,"text":"كيف تركنا الاسكندر يسبقنا الى مصافاة اليهود والتعزز بهم"},{"n":24,"text":"فاكتب انا ايضا اليهم بكلام ملاطفة وتعظيم واعدهم بعطايا ليكونوا من مناصري"},{"n":25,"text":"وكاتبهم بقوله من الملك ديمتريوس الى امة اليهود سلام"},{"n":26,"text":"لقد بلغنا انكم محافظون على عهودكم لنا ثابتون في مودتنا ولم تتقربوا الى اعدائنا فسرنا ذلك"},{"n":27,"text":"فاثبتوا في المحافظة على وفائكم لنا فنحسن ثوابكم على ما تفعلون في حقنا"},{"n":28,"text":"ونحط عنكم كثيرا مما لنا عليكم ونصلكم بالعطايا"},{"n":29,"text":"والان فاني اعفيكم واحط عن جميع اليهود كل جزية ومكس الملح والاكاليل وثلث الزرع"},{"n":30,"text":"ونصف اتاء الشجر الذي يحق لي اخذه اعفيكم من هذه الاشياء من اليوم فصاعد في ارض يهوذا وفي المدن الثلاث الملحقة بها من \nارض السامرة والجليل من هذا اليوم على طول الزمان"},{"n":31,"text":"ولتكن اورشليم مقدسة وحرة هي وتخومها واحط عنها العشور والضرائب"},{"n":32,"text":"واتخلى عن القلعة التي باورشليم واعطيها للكاهن الاعظم يقيم فيها من يختاره من الرجال لحراستها"},{"n":33,"text":"وجميع النفوس التي سبيت من اليهود من ارض يهوذا في مملكتي باسرها اطلقها حرة بلا ثمن وليكن الجميع معفين من اتاوة \nالمواشي"},{"n":34,"text":"ولتكن الاعياد كلها والسبوت ورؤوس الشهور والايام المخصصة والايام الثلاثة التي قبل العيد والايام الثلاثة التي بعد العيد \nايام ابراء وعفو لجميع اليهود الذين في مملكتي"},{"n":35,"text":"فلا يكون لاحد ان يرافع احدا منهم او يثقل عليه في اي امر كان"},{"n":36,"text":"وليكتتب من اليهود في جيوش الملك الى ثلاثين الف رجل تعطى لهم وظائف كما يحق لسائر جنود الملك"},{"n":37,"text":"فيجعل منهم في حصون الملك العظيمة ويفوض الى البعض منهم النظر في مهام المملكة التي تقتضي الامانة ورؤساؤهم ومدبروهم \nيكونون من جملتهم ويسلكون بحسب سننهم كما امر الملك لارض يهوذا"},{"n":38,"text":"واما المدن الثلاث الملحقة باليهودية من بلاد السامرة فلتبق ملحقة باليهودية فتكون معها خاضعة لواحد ولا تطيع سلطانا اخر \nالا سلطان الكاهن الاعظم"},{"n":39,"text":"وقد وهبت بطلمايس وما يتبعها للمقدس الذي باورشليم لاجل نفقة الاقداس"},{"n":40,"text":"وزدت عليها خمسة عشر الف مثقال فضة كل سنة من دخل الملك من الاماكن التي تختص به"},{"n":41,"text":"وكل ما بقي مما لم يدفعه وكلاء المال عن السنين السالفة يؤدونه من الان لاعمال البيت"},{"n":42,"text":"وما عدا ذلك فخمسة الاف مثقال الفضة التي كانت تؤخذ من دخل المقدس في كل سنة تترك رزقا للكهنة القائمين بالخدمة"},{"n":43,"text":"واي من لاذ بالمقدس في اورشليم في جميع حدوده وللملك عليه مال او اي حق كان فليعف وليبق له كل ما ملك في مملكتي"},{"n":44,"text":"ونفقة البناء واعمال الترميم في المقادس تعطى من حساب الملك"},{"n":45,"text":"وبناء اسوار اورشليم وتحصينها على محيطها وبناء الاسوار في سائر اليهودية تعطى نفقته من حساب الملك"},{"n":46,"text":"فلما سمع يوناتان والشعب هذا الكلام لم يثقوا به ولا قبلوه لانهم تذكروا ما انزله ديمتريوس باسرائيل من الشر العظيم \nوالضغط الشديد"},{"n":47,"text":"فاثروا الاسكندر لانه بداهم بكلام السلام وبقوا على مناصرته كل الايام"},{"n":48,"text":"وجمع الاسكندر الملك جيوشا عظيمة نزل تجاه ديمتريوس"},{"n":49,"text":"فانتشب القتال بين الملكين فانهزم جيش ديمتريوس فتعقبه الاسكندر وهجم عليهم"},{"n":50,"text":"واشتد القتال جدا الى ان غابت الشمس وسقط ديمتريوس في ذلك اليوم"},{"n":51,"text":"ثم بعث الاسكندر رسلا الى بطلماوس ملك مصر بهذا الكلام قائلا"},{"n":52,"text":"اذ قد رجعت الى ارض مملكتي وجلست على عرش ابائي واستتب لي السلطان وكسرت ديمتريوس واستوليت على بلادنا"},{"n":53,"text":"اذ الحمت عليه القتال فانكسر امامنا هو وجيشه وجلست على عرش ملكه"},{"n":54,"text":"فهلم الان نوال بعضنا بعضا وهب لي ابنتك زوجة فاصاهرك واهدي اليك هدايا تليق بك"},{"n":55,"text":"فاجاب بطلماوس الملك قائلا ما اسعد اليوم الذي رجعت فيه الى ارض ابائك وجلست على عرش ملكهم"},{"n":56,"text":"واني صانع ما كتبت الى به فهلم الى بطلمايس فنتواجه واصاهرك كما قلت"},{"n":57,"text":"وخرج بطلماوس من مصر هو وكلوبطرة ابنته ودخلا بطلمايس في السنة المئة والثانية والستين"},{"n":58,"text":"فلاقاه الاسكندر الملك فاعطاه كلوبطرة ابنته واقام عرسها في بطلمايس على عادة الملوك باحتفال عظيم"},{"n":59,"text":"وكتب الاسكندر الملك الى يوناتان ان يقدم لملاقاته"},{"n":60,"text":"فانطلق الى بطلمايس في موكب مجيد ولقى الملكين واهدى لهما ولاصحابهما فضة وذهبا وهدايا كثيرة فنال حظوة لديهما"},{"n":61,"text":"واجتمع عليه رجال مفسدون من اسرائيل رجال منافقون ووشوا به فلم يصغ الملك اليهم"},{"n":62,"text":"وامر الملك ان ينزعوا ثياب يوناتان ويلبسوه ارجوانا ففعلوا واجلسه الملك بجانبه"},{"n":63,"text":"وقال لعظمائه اخرجوا معه الى وسط المدينة ونادوا ان لا يتعرض له احد في امر من الامور ولا يسوءه بشيء من المكروه"},{"n":64,"text":"فلما راى الذين وشوا به ما هو فيه من المجد وكيف نودي له والبس الارجون هربوا جميعهم"},{"n":65,"text":"واعزه الملك وجعله من اصدقائه الخواص واقامه قائدا وشريكا في الملك"},{"n":66,"text":"فعاد يوناتان الى اورشليم سالما مسرورا"},{"n":67,"text":"وفي السنة المئة والخامسة والستين جاء ديمتريوس بن ديمتريوس الى ارض ابائه"},{"n":68,"text":"فسمع بذلك الاسكندر الملك فاغتم جدا ورجع الى انطاكية"},{"n":69,"text":"وفوض ديمتريوس قيادة الجيش الى ابلونيوس والى بقاع سورية فحشد جيشا عظيما ونزل بيمنيا وراسل يوناتان الكاهن الاعظم قائلا"},{"n":70,"text":"انه ليس لنا من مقاوم الا انت وبسببك قد اصبحت عرضة للسخرية والتعيير فعلام انت تناهضنا في الجبال"},{"n":71,"text":"فالان ان كنت واثقا بجيوشك فانزل الينا في السهل فنتبارز هناك فان معي قوة الامصار"},{"n":72,"text":"سل واعلم من انا ومن الذين يؤازرونني فانه يقال انكم لا تستطيعون الثبات امامنا لان ابائك قد انكسروا في ارضهم مرتين"},{"n":73,"text":"فلست تطيق الثبات امام الفرسان وجيش في كثرة جيشي في سهل لا حجر فيه ولا حصاة ولا ملجا تهربون اليه"},{"n":74,"text":"فلما سمع يوناتان كلام ابلونيوس اضطرب غيظا واختار عشرة الاف رجل وخرج من اورشليم ولحق به سمعان اخوه لمظاهرته"},{"n":75,"text":"ونزل تجاه يافا فاغلقوا في وجهه ابواب المدينة لان حرس ابلونيوس كان فيها فحاصرها"},{"n":76,"text":"فخاف الذين في المدينة وفتحوا له فاستولى يوناتان على يافا"},{"n":77,"text":"وسمع ابلونيوس فتقدم في ثلاثة الاف فارس وجيش كثير"},{"n":78,"text":"وسار نحو اشدود كانه عابر سبيل ثم عطف بغتة الى السهل اذ كان معه كثيرون من الفرسان الذين يعتمد عليهم فتعقبه يوناتان \nالى اشدود والتحم القتال بين الفريقين"},{"n":79,"text":"وكان ابلونيوس قد خلف الف فارس وراءهم في خفية"},{"n":80,"text":"الا ان يوناتان كان عالما ان وراءه كمينا ولم يلبثوا ان احدقوا بجيشه يرمون الشعب بالسهام من الصبح الى المساء"},{"n":81,"text":"اما الشعب فبقي في مواقفه كما امر يوناتان حتى اعيت خيل اولئك"},{"n":82,"text":"حينئذ برز سمعان بجيشه والحم القتال على الفرقة لان الخيل كانت قد وهنت فكسرهم فهربوا"},{"n":83,"text":"وتبددت الخيل في السهل وفروا الى اشدود ودخلوا بيت داجون معبد صنمهم لينجوا بنفوسهم"},{"n":84,"text":"فاحرق يوناتان اشدود والمدن التي حولها وسلب غنائمهم واحرق هيكل داجون والذين انهزموا اليه بالنار"},{"n":85,"text":"وكان الذين قتلوا بالسيف مع الذين احرقوا ثمانية الاف رجل"},{"n":86,"text":"ثم سار يوناتان من هناك ونزل تجاه اشقلون فخرج اهل المدينة للقائه باجلال عظيم"},{"n":87,"text":"ورجع يوناتان بمن معه الى اورشليم ومعهم غنائم كثيرة"},{"n":88,"text":"ولمل سمع الاسكندر الملك بهذه الحوادث زاد يوناتان مجدا"},{"n":89,"text":"وبعث اليه بعروة من ذهب كما كان يعطى لانسباء الملوك ووهب له عقرون وتخومها ملكا"}]},{"label":"سفر المكابيين الأول 11","verses":[{"n":1,"text":"وجمع ملك مصر جيوشا كثيرة كالرمل الذي على ساحل البحر وسفنا عديدة وحاول الاستيلاء على مملكة الاسكندر بالمكر والحاقها بمملكته"},{"n":2,"text":"فقدم سورية متظاهرا بالسلم ففتح له اهل المدن ولاقوه اذ كان الاسكندر الملك قد امر بلقائه لانه صهره"},{"n":3,"text":"وكان بطلماوس عند دخوله المدن يبقي في كل مدينة حرسا من الجند"},{"n":4,"text":"ولما وصل الى اشدود اروه هيكل داجون المحرق واشدود وضواحيها المهدومة والجثث المطروحة والذين كان يوناتان قد احرقهم في \nالحرب وكانوا قد جعلوا رجامهم على طريقه"},{"n":5,"text":"وحدثوا الملك بما فعل يوناتان يريدون تجرمه فسكت الملك"},{"n":6,"text":"ولاقى يوناتان الملك في يافا باجلال وسلم بعضهما على بعض وناما هناك"},{"n":7,"text":"ثم شيع يوناتان الملك الى النهر الذي يقال له الوتارس ورجع الى اورشليم"},{"n":8,"text":"فاستحوذ الملك بطلماوس على مدن الساحل الى سلوكية الساحلية وكان مضمرا للاسكندر السوء"},{"n":9,"text":"ثم انفذ رسلا الى ديمتريوس الملك قائلا هلم فنعقد عقدا بيني وبينك واهب لك بنتي التي عند الاسكندر وتملك ملك ابيك"},{"n":10,"text":"فاني قد ندمت على عطائي ابنتي له لانه رام قتلي"},{"n":11,"text":"وتجنى عليه طمعا في ملكه"},{"n":12,"text":"ثم استرد ابنته واعطاها لديمتريوس وتغير على الاسكندر وظهرت عداوتهما"},{"n":13,"text":"ثم ان بطلماوس دخل انطاكية ووضع على راسه تاجين تاج اسية وتاج مصر"},{"n":14,"text":"وكان الاسكندر الملك اذ ذاك في كيليكية لان اهل تلك البلاد كانوا قد تمردوا"},{"n":15,"text":"فلما سمع الاسكندر قدم لمقاتلته فاخرج بطلماوس جيشه ولاقاه بعسكر شديد فكسره"},{"n":16,"text":"فهرب الاسكندر الى ديار العرب مستجيرا بهم وعظم امر بطلماوس الملك"},{"n":17,"text":"فقطع زبديئيل العربي راس الاسكندر وبعث به الى بطلماوس"},{"n":18,"text":"وفي اليوم الثالث مات بطلماوس الملك فاهلك رجال الجند الحراس الذين في الحصون"},{"n":19,"text":"وملك ديمتريوس في السنة المئة والسابعة والستين"},{"n":20,"text":"في تلك الايام جمع يوناتان رجال اليهودية لفتح القلعة التي باورشليم ونصب عليها مجانيق كثيرة"},{"n":21,"text":"فانطلق قوم من مبغضي امتهم من الرجال المنافقين الى الملك واخبروه بان يوناتان يحاصر القلعة"},{"n":22,"text":"فلما سمع استشاط غضبا وسار من ساعته قاصدا بطلمايس وكتب الى يوناتان ان يكف عن محاصرة القلعة وان يبادر الى ملاقاته في \nبطلمايس للمواجهة"},{"n":23,"text":"فلما بلغ ذلك يوناتان امر بان يستمروا على الحصار واختار بعضا من شيوخ اسرائيل والكهنة وخاطر بنفسه"},{"n":24,"text":"واخذ من الفضة والذهب والحلل وسائر الهدايا شيئا كثيرا وانطلق الى الملك في بطلمايس فنال حظوة لديه"},{"n":25,"text":"ووشى به قوم من الامة من اهل النفاق"},{"n":26,"text":"الا ان الملك عامله كما كان اسلافه يعاملونه وعظمه لدى اصحابه جميعا"},{"n":27,"text":"واقره في الكهنوت الاعظم وفي كل ما كان له من الاختصاصات وجعله من اول اصدقائه"},{"n":28,"text":"وسال يوناتان الملك ان يعفي اليهودية والمدن الثلاث وارض السامرة من كل جزية ووعده بثلاث مئة قنطار"},{"n":29,"text":"فارتضى الملك وكتب ليوناتان كتبا في ذلك كله وهذه صورتها"},{"n":30,"text":"من ديمتريوس الملك الى يوناتان اخيه وامة اليهود سلام"},{"n":31,"text":"نسخة الكتاب الذي كتبناه في حقكم الى لسطانيس قريبنا كتبنا بها اليكم لتقفوا على مضمونها"},{"n":32,"text":"من ديمتريوس الملك الى لسطانيس ابيه سلام"},{"n":33,"text":"لقد راينا ان نحسن الى امة اليهود اوليائنا المحافظين على ما يحق لنا وفاء بما سبق من برهم لنا"},{"n":34,"text":"فجعلنا لهم تخوم اليهودية والمدن الثلاث وهي افيرمة ولدة والرامتائيم التي الحقت باليهودية من ارض السامرة وجميع \nتوابعها فتكون لجميع الذين يذبحون في اورشليم بدل الضرائب الملكية التي كان الملك يستخرجها منهم قبلا في كل سنة من اتاء \nالارض وثمر الاشجار"},{"n":35,"text":"وسائر ما يحق لنا من العشور والوضائع ووهاد الملح والاكاليل"},{"n":36,"text":"هذا كله قد انعمنا عليهم به تبرعا ومن الان لا يلغى شيء من هذا الانعام ما طال الزمان"},{"n":37,"text":"فالان اكتبوا نسخة من هذا الرسم ولتسلم الى يوناتان ولتوضع في الجبل المقدس في موضع مشهود"},{"n":38,"text":"وراى ديمتريوس الملك ان الارض قد اطمانت لديه لا ينازعه منازع فسرح جميع جيوشه كل واحد الى موضعه ما خلا الجنود الغرباء \nالذين جاء بهم من جزائر الامم فمقته جيوش ابائه كلهم"},{"n":39,"text":"وكان تريفون من احزاب الاسكندر قبلا فلما راى ان الجيوش جميعها تتذمر على ديمتريوس انطلق الى ايملكوئيل العربي وكان يربي \nانطيوكس بن الاسكندر"},{"n":40,"text":"فالح عليه ان يسلمه اليه لكي يملك مكان ابيه واخبره بما فعل ديمتريوس وبما له في الجيوش من العداوة ومكث هناك اياما \nكثيرة"},{"n":41,"text":"وارسل يوناتان الى ديمتريوس الملك ان يخرج الجنود الذين في القلعة من اورشليم والذين في الحصون لانهم كانوا يحاربون \nاسرائيل"},{"n":42,"text":"فارسل ديمتريوس الى يوناتان قائلا سافعل ذلك لك ولامتك بل ساعظمك انت وامتك تعظيما متى وافقتني فرصة"},{"n":43,"text":"والان فانك تحسن الصنيع اذا ارسلت الى رجالا يكونون في نجدتي فاني قد خذلتني جيوشي كلها"},{"n":44,"text":"فوجه يوناتان ثلاث الاف رجل اشداء الباس الى انطاكية فوافوا الملك ففرح الملك بقدومهم"},{"n":45,"text":"واجتمع اهل المدينة في وسط المدينة وكانوا مئة وعشرين الف رجل يحاولون قتل الملك"},{"n":46,"text":"فهرب الملك الى داره فاستولى اهل المدينة على طرق المدينة وشرعوا في القتال"},{"n":47,"text":"فدعا الملك اليهود لنجدته فاجتمعوا اليه كلهم ثم تفرقوا بجملتهم في المدينة فقتلوا فى المدينة في ذلك اليوم مئة الف \nرجل"},{"n":48,"text":"واحرقوا المدينة واخذوا غنائم كثيرة في ذلك اليوم وخلصوا الملك"},{"n":49,"text":"فلما راى اهل المدينة ان اليهود قد استولوا على المدينة يفعلون ما شاءوا انخلعت قلوبهم وصرخوا الى الملك متضرعين \nوقالوا"},{"n":50,"text":"عاقدنا وليكف اليهود عن الايقاع بنا وبالمدينة"},{"n":51,"text":"فالقوا السلاح وعقدوا المصالحة فعظم امر اليهود عند الملك وعند جميع اهل مملكته ثم رجعوا الى اورشليم بغنائم كثيرة"},{"n":52,"text":"وجلس ديمتريوس الملك على عرش ملكه وهدات الارض امامه"},{"n":53,"text":"فاخلف في جميع ما وعد وتغير على يوناتان وكافاه بخلاف ما صنع اليه من المعروف وضيق عليه جدا"},{"n":54,"text":"وبعد ذلك رجع تريفون ومعه انطيوكس وهو غلام صغير فملك انطيوكس ولبس التاج"},{"n":55,"text":"فاجتمع اليه جميع الجيوش التي سرحها ديمتريوس وقاتلوا ديمتريوس ففر منهم منهزما"},{"n":56,"text":"فاستولى تريفون على الفيلة ثم فتح انطاكية"},{"n":57,"text":"وكتب انطيوكس الصغير الى يوناتان قائلا اني اقرك في الكهنوت الاعظم واقيمك على المدن الاربع واتخذك من اصدقاءالملك"},{"n":58,"text":"وارسل اليه انية من الذهب لخدمته واباح له ان يشرب في الذهب ويلبس الارجوان بعروة الذهب"},{"n":59,"text":"واقام سمعان اخاه قائدا من عقبة صور الى حدود مصر"},{"n":60,"text":"وخرج يوناتان وطاف في عبر النهر وفي المدن فاجتمعت لمظاهرته جميع جيوش سورية وقدم اشقلون فلاقاه اهل المدينة باحتفال"},{"n":61,"text":"وانصرف من هناك الى غزة فاغلق اهل غزة الابواب في وجهه فحاصرها واحرق ضواحيها بالنار ونهبها"},{"n":62,"text":"فسال اهل غزة يوناتان الامان فعاقدهم واخذ ابناء رؤسائهم رهائن وارسلهم الى اورشليم ثم جال في البلاد الى دمشق"},{"n":63,"text":"وسمع يوناتان ان قواد ديمتريوس قد بلغوا الى قادش الجليل في جيش كثيف يريدون ان يعزلوه عن الولاية"},{"n":64,"text":"فزحف لملاقاتهم وخلف سمعان اخاه في البلاد"},{"n":65,"text":"فحاصر سمعان بيت صور وحاربها اياما كثيرة واحاط بها"},{"n":66,"text":"فسالوه المعاقدة فعاقدهم واخرجهم من هناك وفتح المدينة واقام فيها حرسا"},{"n":67,"text":"واما يوناتان وجيشه فنزلوا على ماء جناسر وقبل الفجر زحفوا الى سهل حاصور"},{"n":68,"text":"فاذا بجيش الاجانب يلاقيهم في السهل وقد اقاموا عليهم كمينا في الجبال فبينما هم يتقدمون تجاههم"},{"n":69,"text":"ثار الكمين من مواضعهم والحموا القتال"},{"n":70,"text":"ففر رجال يوناتان جميعا ولم يبق منهم احد الا متتيا ابن ابشالوم ويهوذا بن حلفي قائدا الجيوش"},{"n":71,"text":"فمزق يوناتان ثيابه وحثا التراب على راسه وصلى"},{"n":72,"text":"ثم عاد اليهم يقاتلهم فانهزموا وهربوا"},{"n":73,"text":"ولما راى ذلك الذين هربوا من رجاله رجعوا وتعقبوا العدو معه الى قادش الى معسكرهم ونزلوا هناك"},{"n":74,"text":"فسقط من الاجانب في ذلك اليوم ثلاثة الف رجل ورجع يوناتان الى اورشليم"}]},{"label":"سفر المكابيين الأول 12","verses":[{"n":1,"text":"وراى يوناتان ان له فرصة ملائمة فاختار رجالا وسيرهم الى رومية ليقروا الموالاة بينهم ويجددوها"},{"n":2,"text":"وارسل معهم الى اسبرطة واماكن اخرى كتبا في هذا المعنى"},{"n":3,"text":"فانطلقوا الى رومية ودخلوا الشورى وقالوا انا مرسلون من قبل يوناتان الكاهن الاعظم وامة اليهود لنجدد ما بينكم وبينهم من \nالموالاة والمناصرة كما كان من قبل"},{"n":4,"text":"فاعطوهم كتبا للعمال في الاقاليم حتى يبلغوهم ارض يهوذا بسلام"},{"n":5,"text":"وهذه نسخة الكتب التي كتبها يوناتان الى اهل اسبرطة"},{"n":6,"text":"من يوناتان الكاهن الاعظم وشيوخ الامة ومن الكهنة وسائر شعب اليهود الى اهل اسبرطة اخوتهم سلام"},{"n":7,"text":"ان اريوس المالك فيكم كان قديما قد انفذ كتبا الى اونيا الكاهن الاعظم يشهد انكم اخوتنا على ما هو في نسختها"},{"n":8,"text":"فتلقى اونيا الرسول باكرام واخذ الكتب المصرح فيها بالمناصرة والموالاة"},{"n":9,"text":"فنحن وان لم تكن بنا حاجة الى ذلك بما لنا من التعزية في الاسفار المقدسة التي في ايدينا"},{"n":10,"text":"قد اثرنا مراسلتكم لنجدد الاخاء والموالاة لئلا نعد من الاجانب عندكم اذ قد مضى على مكاتبتكم لنا زمان مديد"},{"n":11,"text":"وانا في كل حين في الاعياد وسائر الايام المفروضة لا نزال نذكركم في الذبائح التي نقدمها وفي الصلوات كما ينبغي ويليقان \nيذكر الاخوة"},{"n":12,"text":"ويسرنا ما انتم عليه من الاعتزاز"},{"n":13,"text":"اما نحن فقد احاطت بنا مضايق كثيرة وحروب عديدة وقاتلنا الملوك الذين من حولنا"},{"n":14,"text":"لكنا كرهنا ان نثقل عليكم وعلى سائر مناصرينا واوليائنا في تلك الحروب"},{"n":15,"text":"فان لنا من السماء مددا يمدنا وقد تخلصنا من اعدائنا واذللناهم"},{"n":16,"text":"والان فقد اخترنا نومانيوس بن انطيوكس وانتيباتير بن ياسون وارسلناهما الى الرومانيين لنجدد ما كان بيننا قبلا من الموالاة والمناصرة"},{"n":17,"text":"وامرناهما بان يقدما اليكم ويقرئاكم السلام ويسلما اليكم الكتب من قبلنا في تجديد اخائنا"},{"n":18,"text":"ولكم جميل الصنع ان اجبتمونا الى ذلك"},{"n":19,"text":"وهذه نسخة الكتب التي ارسلها الى اونيا"},{"n":20,"text":"من اريوس ملك الاسبرطيين الى اونيا الكاهن الاعظم سلام"},{"n":21,"text":"وبعد فقد وجد في بعض الكتب ان الاسبرطيين واليهود اخوة من نسل ابراهيم"},{"n":22,"text":"واذ قد علمنا ذلك فلكم جميل الصنع ان راسلتمونا فيما انتم عليه من السلام"},{"n":23,"text":"والان فان جوابنا اليكم ان مواشيكم واملاككم هي لنا وان ما لنا هو لكم هذا ما اوصينا بان تبلغوه"},{"n":24,"text":"وبلغ يوناتان ان قواد ديمتريوس قد عادوا لمحاربته بجيش يزيد على جيشه الاول"},{"n":25,"text":"فخرج من اورشليم ووافاهم في ارض حماة ولم يمهلهم ان يطاوا ارضه"},{"n":26,"text":"ثم ارسل جواسيس الى محلتهم فرجعوا واخبروه انهم مزمعون ان يهجموا عليهم في الليل"},{"n":27,"text":"فلما غربت الشمس امر يوناتان الذين معه بان يسهروا تحت السلاح الليل كله استعدادا للقتال وفرق الحرس حول المحلة"},{"n":28,"text":"وسمع العدو بان يوناتان والذين معه متاهبون للقتال فداخل قلوبهم الرعب والرعدة فاضرموا النيران في محلتهم وهربوا"},{"n":29,"text":"الا ان يوناتان والذين معه لم يعلموا بما كان الا عند الصبح لانهم كانوا يرون ضوء النيران"},{"n":30,"text":"فتعقبهم يوناتان فلم يدركهم لانهم كانوا قد قطعوا نهر الوطارس"},{"n":31,"text":"فارتد يوناتان الى العرب المسمين بالزبديين وضربهم وسلب غنائمهم"},{"n":32,"text":"ثم ارتحل واتى دمشق وجال في البلاد كلها"},{"n":33,"text":"واما سمعان فخرج وبلغ الى اشقلون والحصون التي بالقرب منها ثم ارتد الى يافا واستحوذ عليها"},{"n":34,"text":"لانه سمع انهم يريدون ان يسلموا الحصن الى احزاب ديمتريوس واقام هناك حرسا يحافظون على المدينة"},{"n":35,"text":"ثم رجع يوناتان وجمع شيوخ الشعب واتمر معهم ان يبني حصونا في اليهودية"},{"n":36,"text":"ويرفع اسوار اورشليم ويشيد حائطا عاليا بين القلعة والمدينة ليفصلها عن المدينة وتبقى على حدتها حتى لا يشتروا ويبيعوا"},{"n":37,"text":"فاتفقوا على ان يبنوا المدينة وتقدم اليهم ان يبنوا سور الوادي شرقا ورمموا السور المسمى كافيناطا"},{"n":38,"text":"وابتنى سمعان حاديد في السهل وحصنها بالابواب والمزاليج"},{"n":39,"text":"وحاول تريفون ان يملك على اسية ويلبس التاج ويلقي يده على انطيوكس الملك"},{"n":40,"text":"لكنه خشي من يوناتان ان يمنعه ويحاربه فطلب سبيلا لان يقبض على يوناتان ويهلكه فسار واتى الى بيت شان"},{"n":41,"text":"فخرج يوناتان لملتقاه في اربعين الف رجل منتخبين للقتال واتى الى بيت شان"},{"n":42,"text":"فلما راى تريقون ان يوناتان قد اقبل في جيش كثيف لم يجسر ان يمد يده اليه"},{"n":43,"text":"فتلقاه باكرام واوصى به جميع اصحابه واهدى اليه هدايا وامر جيوشه بان يطيعوه طاعتهم لنفسه"},{"n":44,"text":"وقال ليوناتان لم ثقلت على هؤلاء الشعب كلهم وليس بيننا حرب"},{"n":45,"text":"اطلقهم الى بيوتهم وانتخب لك نفرا قليلا يكونون معك وهلم معي الى بطلمايس فاسلمها اليك هي وسائر الحصون ومن بقي من \nالجيوش وجميع المقلدين على الامور ثم انصرف راجعا فاني لهذا جئت"},{"n":46,"text":"فصدقه وفعل كما قال واطلق الجيوش فانصرفوا الى ارض يهوذا"},{"n":47,"text":"واستبقى لنفسه ثلاثة الاف رجل ترك الفين منهم في الجليل وصحبه الف"},{"n":48,"text":"فلما دخل يوناتان بطلمايس اغلق اهل بطلمايس الابواب وقبضوا عليه وقتلوا جميع الذين دخلوا معه بالسيف"},{"n":49,"text":"وارسل تريفون جيشا وفرسانا الى الجليل والصحراء الواسعة لاهلاك جميع رجال يوناتان"},{"n":50,"text":"لكنهم لما علموا ان يوناتان والذين معه قد قبض عليهم وهلكوا شجعوا انفسهم وتقدموا وهم متضامون متاهبون للقتال"},{"n":51,"text":"واذ راى طالبوهم انهم مستبسلون رجعوا عنهم"},{"n":52,"text":"فوفدوا جميعهم بالسلام الى ارض يهوذا وناحوا على يوناتان والذين معه واشتد خوفهم وكانت عند جميع اسرائيل مناحة عظيمة"},{"n":53,"text":"وطلب كل الامم الذين حولهم ان يدمروهم لانهم قالوا"},{"n":54,"text":"انهم لا رئيس لهم ولا ناصر فلنقاتلهم ولنمح ذكرهم من البشر"}]},{"label":"سفر المكابيين الأول 13","verses":[{"n":1,"text":"وبلغ سمعان ان تريفون قد جمع جيشا عظيما ليغير على ارض يهوذا ويدمرها"},{"n":2,"text":"وراى ان شعبه قد داخله الرعب والرعدة فصعد الى اورشليم وجمع الشعب"},{"n":3,"text":"وشجعهم وقال لهم قد علمتم ما فعلت انا واخوتي واهل بيت ابي من اجل السنن والاقداس وما لقينا من الحروب والشدائد"},{"n":4,"text":"وقد كان في ذلك هلاك اخوتي جميعا لاجل اسرائيل وبقيت انا وحدي"},{"n":5,"text":"والان فحاش لي ان اضن بنفسي في كل موقع ضيق فاني لست خيرا من اخوتي"},{"n":6,"text":"بل انتقم لامتي وللاقداس ولنسائنا واولادنا لان الامم باسرها قد اجتمعت لتدميرنا بغضا"},{"n":7,"text":"فلما سمع الشعب هذا الكلام ثارت نفوسهم"},{"n":8,"text":"واجابوا بصوت عظيم قائلين انت قائد لنا مكان يهوذا ويوناتان اخيك"},{"n":9,"text":"فحارب حربنا ومهما قلت لنا فانا نفعله"},{"n":10,"text":"فحشد جميع رجال القتال وجد في اتمام اسوار اورشليم وحصنها مما حولها"},{"n":11,"text":"ثم وجه يوناتان بن ابشالوم الى يافا في عدد واف من الجيش فطرد الذين كانوا فيها واقام هناك"},{"n":12,"text":"وزحف تريفون من بطلمايس في جيش عظيم قاصدا ارض يهوذا ومعه يوناتان تحت الحفظ"},{"n":13,"text":"وكان سمعان حالا بحاديد قبالة السهل"},{"n":14,"text":"وعلم تريفون ان سمعان قد قام في موضع يوناتان اخيه وانه مزمع ان يلحم الحرب معه فانفذ اليه رسلا"},{"n":15,"text":"يقول انا انما قبضنا على يوناتان اخيك لمال كان عليه للملك فيما باشره من الامور"},{"n":16,"text":"فالان ارسل مئة قنطار فضة وابنيه رهينة لئلا يغدر بنا اذا اطلقناه وحينئذ نطلقه"},{"n":17,"text":"وعلم سمعان انهم انما يكلمونه بمكر الا انه ارسل المال والولدين مخافة ان يجلب على نفسه عداوة عظيمة من قبل الشعب \nويقولوا"},{"n":18,"text":"لسبب انه لم يرسل اليه المال والولدين هلك"},{"n":19,"text":"فوجه الولدين ومئة القنطار الا ان تريفون اخلف ولم يطلق يوناتان"},{"n":20,"text":"وجاء تريفون بعد ذلك ليغير على البلاد ويدمرها ودار في الطريق الى ادورا وكان سمعان وجيشه يقاومونه حيثما تقدم"},{"n":21,"text":"وانفذ الذين في القلعة رسلا الى تريفون يلحون عليه ان ياتيهم في طريق البرية وينفذ اليهم ميرة"},{"n":22,"text":"فجهز تريفون جميع فرسانه للمسير في ذلك الليل لكن اذ تكاثر الثلج جدا منعهم الثلج من المسير فارتحل واتى الى ارض جلعاد"},{"n":23,"text":"ولما ان قارب بسكاما قتل يوناتان ودفنوه هناك"},{"n":24,"text":"ثم رجع تريفون وانصرف الى ارضه"},{"n":25,"text":"فارسل سمعان واخذ عظام يوناتان اخيه ودفنها في مودين مدينة ابائه"},{"n":26,"text":"وناح عليه كل اسرائيل نوحا عظيما وندبوه اياما كثيرة"},{"n":27,"text":"وشيد سمعان على قبر ابيه واخوته بناء عاليا منظورا بحجارة نحتت من وراء ومن امام"},{"n":28,"text":"ونصب على القبور سبعة اهرام واحدا بازاء واحد لابيه وامه واخوته الاربعة"},{"n":29,"text":"وزينها بفنون ونقوش وجعل حولها اعمدة عظيمة مرسوما على الاعمدة اسلحة تخليدا لذكرهم وبجانب الاسلحة سفن منقوشة وكانت \nمنظورة لجميع ركاب البحر"},{"n":30,"text":"هذا هو القبر الذي صنعه بمودين باقيا الى هذا اليوم"},{"n":31,"text":"وسلك تريفون بالغدر مع انطيوكس الملك الصغير وقتله"},{"n":32,"text":"وملك مكانه ولبس تاج اسية وضرب الارض ضربة عظيمة"},{"n":33,"text":"وبنى سمعان حصون اليهودية وعززها بالبروج الرفيعة والاسوار العظيمة والابواب والمزاليج وادخر ميرة في الحصون"},{"n":34,"text":"وانتخب سمعان رجالا وارسل الى ديمتريوس الملك ان يعفي البلاد لان كل ما فعله تريفون انما كان اختلاسا"},{"n":35,"text":"فبعث اليه ديمتريوس الملك بهذا الكلام واجابه وكتب اليه كتابا هذه صورته"},{"n":36,"text":"من ديمتريوس الملك الى سمعان الكاهن الاعظم وصديق الملوك والى الشيوخ وشعب اليهود سلام"},{"n":37,"text":"قد وصل الينا اكليل الذهب والسعفة التي بعثت بها الينا وفي عزمنا ان نعقد معكم سلما وثيقا ونكاتب ارباب الامور ان \nيعفوكم مما عليكم"},{"n":38,"text":"وكل ما رسمنا لكم يبقى مرسوما والحصون التي بنيتموها تكون لكم"},{"n":39,"text":"ولكن ما فرط من هفوة وخطا الى هذا اليوم نتجاوز عنه والاكليل الذي لنا عليكم وكل وضيعة اخرى على اورشليم نعفيكم منها"},{"n":40,"text":"وان كان فيكم اهل للاكتتاب في جندنا فليكتتبوا ولكن فيما بيننا سلم"},{"n":41,"text":"وفي السنة المئة والسبعين خلع نير الامم عن اسرائيل"},{"n":42,"text":"وبدا شعب اسرائيل يكتب في توقيع الصكوك والعقود في السنة الاولى لسمعان الكاهن الاعظم قائد اليهود ورئيسهم"},{"n":43,"text":"في تلك الايام نزل سمعان على غزة وحاصرها بجيوشه وصنع دبابات وادناها من المدينة وضرب احد البروج واستولى عليه"},{"n":44,"text":"وهجم الذين في الدبابة على المدينة فوقع اضطراب عظيم في المدينة"},{"n":45,"text":"وصعد الذين في المدينة مع النساء الى السور ممزقة ثيابهم وصرخوا بصوت عظيم الى سمعان يسالونه الامان"},{"n":46,"text":"وقالوا لا تعاملنا بحسب مساوئنا بل بحسب رافتك"},{"n":47,"text":"فرق لهم سمعان وكف عن قتالهم واخرجهم من المدينة وطهر البيوت التي كانت فيها اصنام ثم دخلها بالتسبيح والشكر"},{"n":48,"text":"وازل منها كل رجاسة واسكن هناك رجالا من المتمسكين بالشريعة وحصنها وبنى له فيها منزلا"},{"n":49,"text":"واما الذين في قلعة اورشليم فاذ كانوا قد منعوا من الخروج ودخول البلد ومن البيع والشراء اشتدت مجاعتهم ومات كثير منهم"},{"n":50,"text":"فصرخوا الى سمعان يسالون الامان فامنهم واخرجهم من هناك وطهر القلعة من النجاسات"},{"n":51,"text":"ودخلها في اليوم الثالث والعشرين من الشهر الثاني في السنة المئة والحادية والسبعين بالحمد والسعف والكنارات والصنوج والعيدان والتسابيح والاناشيد لانحطام العدو الشديد من اسرائيل"},{"n":52,"text":"ورسم ان يعيد ذلك اليوم بسرور كل سنة"},{"n":53,"text":"ثم حصن جبل الهيكل الذي بجانب القلعة وسكن هناك هو والذين معه"},{"n":54,"text":"وراى سمعان ان يوحنا ابنه رجل باس فجعله قائدا على جميع الجيوش واقام بجازر"}]},{"label":"سفر المكابيين الأول 14","verses":[{"n":1,"text":"وفي السنة المئة والثانية والسبعين جمع ديمتريوس الملك جيوشه وسار الى ماداي يستمد نجدة لمحاربة تريفون"},{"n":2,"text":"وبلغ ارساكيس ملك فارس وماداي ان ديمتريوس قد دخل تخومه فارسل بعض رؤسائه ليقبض عليه حيا"},{"n":3,"text":"فذهب وضرب جيش ديمتريوس وقبض عليه واتى به ارساكيس فجعله في السجن"},{"n":4,"text":"فهدات ارض يهوذا كل ايام سمعان وجعل همه مصلحة امته فكانوا مبتهجين بسلطانه ومجده كل الايام"},{"n":5,"text":"وفضلا عن ذلك المجد كله جعل يافا مرسى وفتح مجازا لجزائر البحر"},{"n":6,"text":"ووسع تخوم امته واستحوذ على البلاد"},{"n":7,"text":"وجمع اسرى كثيرين وامتلك جازر وبيت صور والقلعة واخرج منها النجاسات ولم يكن من يقاومه"},{"n":8,"text":"وكانوا يفلحون ارضهم بسلام والارض تعطي اتاءها واشجار الحقول اثمارها"},{"n":9,"text":"وكان الشيوخ يجلسون في الساحات يتفاوضون جميعا في مصالح الامة والشبان متسربلين بالبهاء وعليهم حلل الحرب"},{"n":10,"text":"وكان سمعان يمير المدن بالطعام ويهيئ فيها اسباب التحصين حتى صار ذكر مجده الى اقاصي الارض"},{"n":11,"text":"وقرر السلم في ارضه فلبث اسرائيل في فرح عظيم"},{"n":12,"text":"وجلس كل واحد تحت كرمته وتينته ولم يكن من يذعرهم"},{"n":13,"text":"ولم يبق في الارض من يحاربهم وقد انكسرت الملوك في تلك الايام"},{"n":14,"text":"وقوى كل من كان ضعيفا في شعبه وغار على الشريعة واستاصل كل اثيم وشرير"},{"n":15,"text":"وعظم الاقداس واكثر من الانية المقدسة"},{"n":16,"text":"وبلغ خبر وفاة يوناتان الى رومية واسبرطة فاسفوا اسفا شديدا"},{"n":17,"text":"واذ بلغهم ان سمعان اخاه قد تقلد الكهنوت الاعظم مكانه وصارت البلاد وما بها من المدن تحت سلطانه"},{"n":18,"text":"كتبوا اليه على الواح من نحاس يجددون معه ما كانوا قد قرروه مع يهوذا ويوناتان اخويه من الموالاة والمناصرة"},{"n":19,"text":"فقرئت الالواح بمشهد الجماعة في اورشليم وهذه صورة الكتب التي انفذها الاسبرطيون"},{"n":20,"text":"من رؤساء الاسبرطيين ومن المدينة الى سمعان الكاهن الاعظم والى الشيوخ والكهنة وسائر شعب اليهود اخوتنا سلام"},{"n":21,"text":"لقد اخبرنا الرسل الذين انفذتموهم الى شعبنا بما انتم فيه من العزة والكرامة فسررنا بوفدهم"},{"n":22,"text":"ودونا ما قالوه في دواوين الشعب هكذا قد قدم علينا نومانيوس بن انطيوكس وانتيباتير ابن ياسون رسولا اليهود ليجددا \nمابيننا من الموالاة"},{"n":23,"text":"فحسن لدى الشعب ان يلتقي الرجلين باكرام ويثبت صورة كلامهما في سجلات الشعب المخصصة لتكون تذكارا عند شعب الاسبرطيين وقد \nكتبنا بنسختها الى سمعان الكاهن الاعظم"},{"n":24,"text":"وبعد ذلك ارسل سمعان نومانيوس الى رومية ومعه ترس عظيم من الذهب وزنه الف منا ليقرر المناصرة بينه وبينهم"},{"n":25,"text":"فلما سمع الشعب ذلك الكلام قالوا بماذا نكافئ سمعان وبنيه"},{"n":26,"text":"على ثباته هو واخوته وبيت ابيه ودفعه عن اسرائيل اعداءه وتمتيعه له بالحرية وكتب في الواح من نحاس جعلوها على انصابفي جبل صهيون"},{"n":27,"text":"ما صورته في اليوم العاشر من شهر ايلول في السنة المئة والثانية والسبعين وهي السنة الثالثة لسمعان الكاهن الاعظم في سرمال"},{"n":28,"text":"في مجمع عظيم من الكهنة والشعب ورؤساء الامة وشيوخ البلاد ثبت عندنا ان قد وقعت حروب كثيرة في البلاد"},{"n":29,"text":"وان سمعان بن متتيا من بني ياريب واخوته قد القوا بانفسهم في المخاطر وناهضوا اعداء امتهم صيانة لاقداسهم والشريعة \nواولوا امتهم مجدا كبيرا"},{"n":30,"text":"وان يوناتان جمع شمل امته وتقلد فيهم الكهنوت الاعظم ثم انضم الى قومه"},{"n":31,"text":"فهم اعداؤهم بالغارة على ارضهم ليدمروا بلادهم ويلقوا ايديهم على اقداسهم"},{"n":32,"text":"حينئذ نهض سمعان وقاتل عن امته وانفق كثيرا من امواله وسلح رجال الباس من امته واجرى عليهم الارزاق"},{"n":33,"text":"وحصن مدن اليهودية وبيت صور التي عند حدود اليهودية حيث كانت اسلحة الاعداء من قبل وجعل هناك حرسا من رجال اليهود"},{"n":34,"text":"وحصن يافا التي على البحر وجازر التي عند حدود اشدود حيث كان الاعداء مقيمين من قبل واسكن هناك يهودا وجعل فيهما كل ما \nياول الى اعزاز شانهما"},{"n":35,"text":"فلما راى الشعب ما فعل سمعان والمجد الذي شرع في انشائه لامته اقاموه قائدا لهم وكاهنا اعظم لما صنعه من ذلك كله ولاجل \nعدله والوفاء الذي حفظه لامته والتماسه اعزاز شعبه بجميع الوجوه"},{"n":36,"text":"وفي ايامه تم النجح على يديه باجلاء الامم عن البلاد وطرد الذين في مدينة داود باورشليم وكانوا قد بنوا لانفسهم قلعة \nيخرجون منها وينجسون ما حول الاقداس ويفسدون الطهارة افسادا عظيما"},{"n":37,"text":"واسكن فيها رجالا من اليهود وحصنها لصيانة البلاد والمدينة ورفع اسوار اورشليم"},{"n":38,"text":"واقره الملك ديمتريوس في الكهنوت الاعظم"},{"n":39,"text":"وجعله من اصدقائه وعظمه جدا"},{"n":40,"text":"اذ بلغه ان الرومانيين يسمون اليهود اولياء لهم ومناصرين واخوة وقد تلقوا رسل سمعان باكرام"},{"n":41,"text":"وان اليهود وكهنتهم قد حسن لديهم ان يكون سمعان رئيسا وكاهنا اعظم مدى الدهر الى ان يقوم نبي امين"},{"n":42,"text":"ويكون قائدا لهم ويهتم بالاقداس ويقيم منهم اناسا على الاعمال والبلاد والاسلحة والحصون"},{"n":43,"text":"ويتولى امر الاقداس وان يطيعه الجميع وتكتب باسمه جميع الصكوك في البلاد ويلبس الارجوان والذهب"},{"n":44,"text":"ولا يحل لاحد من الشعب والكهنة ان ينقض شيئا من ذلك او يخالف شيئا مما يامر به او يجمع مجمعا بدونه في البلاد او يلبس \nالارجوان وعروة الذهب"},{"n":45,"text":"ومن فعل خلاف ذلك ونقض شيئا منه فهو مجرم"},{"n":46,"text":"وقد رضي الشعب كله بان يقلد سمعان جميع ما ذكر"},{"n":47,"text":"وقبل سمعان ورضي ان يكون كاهنا اعظم وقائدا ورئيسا لامة اليهود وللكهنة وحاكما على الجميع"},{"n":48,"text":"ورسموا بان تدون هذه الكتابة في الواح من نحاس توضع في رواق الاقداس في موضع مشهود"},{"n":49,"text":"وتوضع صورها في الخزانة حتى تبقى لسمعان وبنيه"}]},{"label":"سفر المكابيين الأول 15","verses":[{"n":1,"text":"وانفذ انطيوكس بن ديمتريوس الملك كتبا من جزائر البحر الى سمعان الكاهن رئيس امة اليهود والى الشعب اجمع"},{"n":2,"text":"وهذه فحواها من انطيوكس الملك الى سمعان الكاهن الاعظم رئيس الامة والى شعب اليهود سلام"},{"n":3,"text":"انه اذ كان قوم من ذوي الفساد قد تسلطوا على مملكة ابائنا كان من همي الان ان استخلص المملكة حتى اعيدها الى ما كانت \nعليه منقبل وقد حشدت جيوشا كثيرة وجهزت اسطولا للحرب"},{"n":4,"text":"وانا عازم ان اتقدم على البلاد لانتقم من الذين افسدوا في بلادنا وخربوا مدنا كثيرة في المملكة"},{"n":5,"text":"فالان اقرر لك كل حطيطة حطها عنك الملوك من قبلي وكل ما اعفوك منه من التقادم"},{"n":6,"text":"وقد ابحت لك ان تضرب في بلادك سكة خاصة"},{"n":7,"text":"وان تكون اورشليم والاقداس حرة وكل ما جهزته من الاسلحة وبنيته من الحصون التي في يدك فليبق لك"},{"n":8,"text":"وكل ضريبة ملكية كانت فيما سلف او تكون فيما ياتي تفعى منها من الان على طول الزمان"},{"n":9,"text":"واذا فزنا بمملكتنا اعززناك انت وامتك والهيكل اعزازا عظيما حتى يتلالا مجدكم في الارض كلها"},{"n":10,"text":"وفي السنة المئة والرابعة والسبعين خرج انطيوكس الى ارض ابائه فاجتمع اليه جميع الجيوش حتى لم يبق مع تريفون الا نفر \nيسير"},{"n":11,"text":"فتعقبه انطيوكس الملك فانطلق هاربا الى دورا التي على البحر"},{"n":12,"text":"اذ ايقن ان قد تراكم عليه الشر وخذلته الجيوش"},{"n":13,"text":"فنزل انطيوكس على دورا ومعه مئة وعشرون الفا من رجال الحرب وثمانية الاف فارس"},{"n":14,"text":"واحاط بالمدينة وتقدم الاسطول من البحر فضايق المدينة برا وبحرا ولم يدع احدا يدخل او يخرج"},{"n":15,"text":"وقدم نومانيوس والذين معه من رومية كتبا الى الملوك والبلاد كتب فيها هكذا"},{"n":16,"text":"من لوكيوس وزير الرومانيين الى بطلماوس الملك سلام"},{"n":17,"text":"لقد اتانا رسل اليهود اوليائنا ومناصرينا يجددون قديم الموالاة والمناصرة مرسلين من قبل سمعان الكاهن وشعب اليهود"},{"n":18,"text":"ومعهم ترس من ذهب وزنه الف منا"},{"n":19,"text":"فلذلك راينا ان نكتب الى الملوك والبلاد ان لا يطلبوهم بسوء ولا يقيموا عليهم حربا ولا على شيء من مدنهم وبلادهم ولا يناصروا \nمن يحاربهم"},{"n":20,"text":"وحسن لدينا ان نقبل منهم الترس"},{"n":21,"text":"فان فر اليكم من بلادهم بعض من رجال الفساد فاسلموهم الى سمعان الكاهن الاعظم لينتقم منهم على مقتضى شريعتهم"},{"n":22,"text":"وكتب مثل ذلك الى ديمتريوس الملك واتالس وارياراطيس وارساكيس"},{"n":23,"text":"والى جميع البلاد الى لمساكس واسبرطة وديلس ومندس وسيكيون وكارية وسامس وبمفيلية وليكية واليكرنسس ورودس وفسيليس وكوس \nوسيدن وارادس وجرتينة وكنيدس وقبرس والقيروان"},{"n":24,"text":"وكتبوا بنسخة تلك الكتب الى سمعان الكاهن الاعظم"},{"n":25,"text":"وعاد انطيوكس الملك فحاصر دورا ولم يزل يضايقها وينصب عليها المجانيق واحاط بالتريفون لئلا يدخل ويخرج"},{"n":26,"text":"فارسل اليه سمعان الفي رجل منتخبين نصرة له وفضة وذهبا وانية كثيرة"},{"n":27,"text":"فابى انطيوكس ان يقبلها ونقض كل ما كان عاهده به من قبل وتغير عليه"},{"n":28,"text":"وارسل اليه اتينوبيوس احد اصحابه ليفاوضه قائلا انكم مستولون على يافا وجازر والقلعة التي باورشليم وهي من مدن مملكتي"},{"n":29,"text":"وقد خربتم تخومها وضربتم الارض ضربة عظيمة وتسلطتم على اماكن كثيرة في مملكتي"},{"n":30,"text":"فالان اسلموا المدن التي استحوذتم عليها وادوا خراج الاماكن التي تسلطتم عليها في خارج تخوم اليهودية"},{"n":31,"text":"والا فادوا عنها خمس مئة قنطار فضة وعن الاتلاف الذي اتلفتموه وعن خراج المدن خمس مئة قنطار اخرى والا وفدنا عليكم مقاتلين"},{"n":32,"text":"فجاء اتينوبيوس صاحب الملك الى اورشليم وشاهد مجد سمعان وخزانة انيته الفضية والذهبية واثاثا وافرا فبهت واخبرهبكلام \nالملك"},{"n":33,"text":"فاجاب سمعان وقال له انا لم ناخذ ارضا لغريب ولم نستول على شيء لاجنبي ولكنه ميراث ابائنا الذي كان اعداؤنا قد استولوا \nعليه ظلما حينا من الدهر"},{"n":34,"text":"فلما اصبنا الفرصة استرددنا ميراث ابائنا"},{"n":35,"text":"فاما يافا وجازر اللتان تطالب بهما فانهما كانتا تجلبان على الشعب في بلادنا نكبات شديدة غير انا نؤدي عنهما مئة قنطار \nفلم يجبه اتينوبيوس بكلمة"},{"n":36,"text":"ورجع الى الملك مغضبا واخبره بهذا الكلام وبمجد سمعان وكل ما شاهده فغضب الملك غضبا شديدا"},{"n":37,"text":"وركب تريفون في سفينة وفر الى ارطوسياس"},{"n":38,"text":"ففوض الملك قيادة الساحل الى كندباوس وجعل تحت يده جنودا من الرجالة وفرسانا"},{"n":39,"text":"وامره ان يزحف على اليهودية واوعز اليه ان يبني قدرون ويحصن الابواب ويقاتل الشعب ثم ان الملك تعقب تريفون"},{"n":40,"text":"فبلغ كندباوس الى يمنيا وجعل يرغم الشعب ويغير على اليهودية ويسبي في الشعب ويقتل وبني قدرون"},{"n":41,"text":"وجعل فيها فرسانا وجنودا ليخرجوا وينتشروا في طرق اليهودية كما رسم له الملك"}]},{"label":"سفر المكابيين الأول 16","verses":[{"n":1,"text":"فصعد يوحنا من جازر واخبر سمعان اباه بما صنع كندباوس"},{"n":2,"text":"فدعا سمعان ابنيه الاكبرين يهوذا ويوحنا وقال لهما انا لم نزل انا واخوتي وبيت ابي نحارب حروب اسرائيل منذ صغرنا الى هذا \nاليوم وقد انجح على ايدينا خلاص اسرائيل مرارا كثيرة"},{"n":3,"text":"والان فاني قد شخت وانتما برحمة الله قد بلغتما اشدكما فقوما مقامي ومقام اخي واخرجا وقاتلا عن امتكما وليؤازركما النصر من \nالسماء"},{"n":4,"text":"وانتخب من البلاد عشرين الفا من رجال الحرب والفرسان فزحفوا على كندباوس وباتوا بمودين"},{"n":5,"text":"ثم قاموا في الغد وانطلقوا الى السهل فاذا تلقائهم جيش عظيم من الرجالة والفرسان وكان بين الفريقين واد"},{"n":6,"text":"فنزل يوحنا بازائهم هو وشعبه واذ راى الشعب خائفا من عبور الوادي عبر هو اولا فلما راه الرجال عبروه وراءه"},{"n":7,"text":"ففرق الشعب وجعل الفرسان في وسط الرجالة وكانت فرسان العدو كثيرة جدا"},{"n":8,"text":"ثم نفخوا في الابواق المقدسة فانكسر كندباوس وجيشه وسقط منهم قتلى كثيرين وفر الباقون الى الحصن"},{"n":9,"text":"حينئذ جرح يهوذا اخو يوحنا وتعقبهم يوحنا حتى بلغ كندباوس الى قدرون التي بناها"},{"n":10,"text":"ففروا الى البروج التي بارض اشدود فاحرقها بالنار فسقط منهم الفا رجل ثم رجع الى ارض يهوذا بسلام"},{"n":11,"text":"وكان بطلماوس بن ابوبس قد اقيم قائدا في بقعة اريحا وكان عنده من الفضة والذهب شيء كثير"},{"n":12,"text":"وكان صهر الكاهن الاعظم"},{"n":13,"text":"فتشامخ في قلبه وطلب ان يستولي على البلاد وقد نوى الغدر بسمعان وبنيه حتى يهلكهم"},{"n":14,"text":"وكان سمعان يجول في مدن البلاد ينظر في مهماتها فنزل الى اريحا هو ومتتيا ويهوذا ابناه في السنة المئة والسابعة والسبعين في شهر شباط"},{"n":15,"text":"فانزلهم ابن ابوبس بحصين كان قد بناه يقال له دوق وهو يضمر لهم الغدر وصنع لهم مادبة عظيمة واخفى هناك رجالا"},{"n":16,"text":"فلما سكر سمعان وبنوه قام بطلماوس ومن معه واخذوا سلاحهم ووثبوا على سمعان في المادبة وقتلوه هو وابنيه وبعضا من غلمانه"},{"n":17,"text":"وخان خيانة فظيعة وكافا الخير بالشر"},{"n":18,"text":"ثم كتب بطلماوس بذلك وارسل الى الملك ان يوجه اليه جيشا لنصرته فيسلم اليه البلاد والمدن"},{"n":19,"text":"ووجه قوما الى جازر لاهلاك يوحنا وانفذ كتبا الى رؤساء الالوف ان ياتوه حتى يعطيهم فضة وذهبا وهدايا"},{"n":20,"text":"وارسل اخرين ليستولوا على اورشليم وجبل الهيكل"},{"n":21,"text":"فسبق واحد واخبر يوحنا في جازر بهلاك ابيه واخويه وان بطلماوس قد بعث من يقتله"},{"n":22,"text":"فلما سمع ذلك بهت جدا وقبض على الرجال الذين اتوا ليقتلوه وقتلهم لعلمه انهم يريدون اهلاكه"},{"n":23,"text":"وبقية اخبار يوحنا وحروبه وما ابداه من الحماسة وبناؤه الاسوار التي بناها واعماله"},{"n":24,"text":"مكتوبة في كتاب ايام كهنوته الاعظم منذ تقلد الكهنوت الاعظم بعد ابيه"}]}],"sources":["https://ar.wikisource.org/wiki/سفر_المكابيين_الأول"]},{"name":"المكابيين الثاني","chapters":[{"label":"سفر المكابيين الثاني 1","verses":[{"n":1,"text":"الى الاخوة اليهود الذين في مصر سلام اليكم من الاخوة اليهود الذين في اورشليم وبلاد اليهودية اطيب السلام"},{"n":2,"text":"ليبارككم الله ويذكر عهده مع ابراهيم واسحق ويعقوب عبيده الامناء"},{"n":3,"text":"و ليؤتكم جميعا قلبا لان تعبدوه وتصنعوا مشيئته بصدر مشروح ونفس راضية"},{"n":4,"text":"ويفتح قلوبكم لشريعته ووصاياه ويجعلكم في سلام"},{"n":5,"text":"وليستجب لصلواتكم ويتب عليكم ولا يخذلكم في اوان السوء"},{"n":6,"text":"ونحن ههنا نصلي من اجلكم"},{"n":7,"text":"كنا نحن اليهود قد كتبنا اليكم في عهد ديمتريوس في السنة المئة والتاسعة والستين حين الضيق والشدة التي نزلت بنا في تلك السنين بعد انصراف ياسون والذين معه من الارض المقدسة والمملكة"},{"n":8,"text":"فانهم احرقوا الباب وسفكوا الدم الزكي فابتهلنا الى الرب فاستجاب لنا وقربنا الذبيحة والسميذ واوقدنا السرج وقدمنا الخبز"},{"n":9,"text":"فالان عليكم ان تعيدوا ايام المظال التي في شهر كسلو"},{"n":10,"text":"في السنة المئة والثامنة والثمانين من سكان اورشليم واليهودية والشيوخ ويهوذا الى ارسطوبولس مؤدب بطلماوس الملك الذي \nمن ذرية الكهنة المسحاء والى اليهود الذين في مصر سلام وعافية"},{"n":11,"text":"نشكر الله الشكر الجزيل على انه خلصنا من اخطار جسيمة عند مناصبتنا للملك"},{"n":12,"text":"ودحر الذين يقاتلوننا في المدينة المقدسة"},{"n":13,"text":"فانه اذ كان الملك في فارس يقود جيشا لا يثبت امامه احد نكبوا في هيكل النناية بحيلة احتالها عليهم كهنة النناية"},{"n":14,"text":"وذلك انه جاء انطيوكس ومن معه من اصحابه الى هناك متظاهرا بانه يريد ان يقارنها وفي نفسه ان ياخذ الاموال على سبيل \nالصداق"},{"n":15,"text":"فابرز كهنة النناية الاموال ودخل هو مع نفر يسير الى داخل المعبد ثم اغلقوا الهيكل"},{"n":16,"text":"فلما دخل انطيوكس فتحوا بابا خفيا كان في ارض الهيكل وقذفوا حجارة رجموا بها القائد ثم قطعوهم قطعا وحزوا رؤوسهم \nوالقوها الى الذين كانوا في الخارج"},{"n":17,"text":"ففي كل شيء تبارك الهنا الذي اسلم الكفرة"},{"n":18,"text":"وبعد فإذ كنا مزمعين ان نعيد عيد تطهير الهيكل في اليوم الخامس والعشرين من شهر كسلو راينا من الواجب ان نعلن اليكم انتعيدوا انتم ايضا عيد المظال والنار التي ظهرت حين بنى نحميا الهيكل والمذبح وقدم الذبيحة"},{"n":19,"text":"فانه حين اجلي اباؤنا الى فارس اخذ بعض اتقياء الكهنة من نار المذبح سرا وخباوها في جوف بئر لا ماء فيها وحافظوا عليها \nبحيث بقي الموضع مجهولا عند الجميع"},{"n":20,"text":"وبعد انقضاء سنين كثيرة حين شاء الله ارسل ملك فارس نحميا الى هنا فبعث اعقاب الكهنة الذين خباوا النار لالتماسها الا انهم \nكما حدثونا لم يجدوا نارا بل ماء خاثرا"},{"n":21,"text":"فامرهم ان يغرفوا وياتوا به ولما احضرت الذبائح امر نحميا الكهنة ان ينضحوا بهذا الماء الخشب والموضوع عليه"},{"n":22,"text":"فصنعوا كذلك ولما برزت الشمس وقد كانت محجوبة بالغيم اتقدت نار عظيمة حتى تعجب الجميع"},{"n":23,"text":"وعند احراق الذبيحة كان الكهنة كلهم يصلون وكان يوناتان يبدا والباقون يجيبونه"},{"n":24,"text":"وهذا ما صلى به نحميا ايها الرب الرب الاله خالق الكل المرهوب القوي العادل الرحيم يا من هو وحده الملك والبار"},{"n":25,"text":"يا من هو وحده المتفضل العادل القدير الازلي مخلص اسرائيل من كل شر الذي اصطفى اباءنا وقدسهم"},{"n":26,"text":"تقبل الذبيحة من اجل جميع شعبك اسرائيل وصن ميراثك وقدسه"},{"n":27,"text":"واجمع شتاتنا واعتق المستعبدين عند الامم وانظر الى الممتهنين والممقوتين ولتعلم الامم انك انت الهنا"},{"n":28,"text":"وعاقب الظالمين والقاذفين بتجبر"},{"n":29,"text":"واغرس شعبك في مكانك المقدس كما قال موسى"},{"n":30,"text":"وكان الكهنة يرنمون بالاناشيد"},{"n":31,"text":"ولما احرقت الذبيحة امر نحميا بان يريقوا ما بقي من الماء على الحجارة الكبيرة"},{"n":32,"text":"فلما صنعوا ذلك اتقد اللهيب فاطفاه النور المنبعث من المذبح"},{"n":33,"text":"فشاع ذلك واخبر ملك فارس ان الموضع الذي خبا فيه الكهنة النار حين جلائهم قد ظهر فيه ماء وبه طهر الذين مع نحميا \nالذبيحة"},{"n":34,"text":"فسيجه الملك وصيره مقدسا بعد الفحص عن الامر"},{"n":35,"text":"وانعطف الملك اليهم واخذ عطايا كثيرة ووهبها لهم"},{"n":36,"text":"وسماه الذين مع نحميا نفطار اي تطهيرا ويعرف عند كثيرين بنفطاي"}]},{"label":"سفر المكابيين الثاني 2","verses":[{"n":1,"text":"قد جاء في السجلات ان ارميا النبي امر اهل الجلاء ان ياخذوا النار كما ذكر وكما امر النبي اهل الجلاء"},{"n":2,"text":"اذ اوصاهم ان لا ينسوا وصايا الرب ولا تغوى قلوبهم اذا راوا تماثيل الذهب والفضة وما عليها من الزينة"},{"n":3,"text":"وحرضهم بمثل هذا الكلام على ان لا يزيلوا الشريعة من قلوبهم"},{"n":4,"text":"وجاء في هذه الكتابة ان النبي بمقتضى وحي سار اليه امر ان يذهب معه بالمسكن والتابوت حتى يصل الى الجبل الذي صعد اليه موسى وراى ميراث الله"},{"n":5,"text":"ولما وصل ارميا وجد كهفا فادخل اليه المسكن والتابوت ومذبح البخور ثم سد الباب"},{"n":6,"text":"فاقبل بعض من كانوا معه ليسموا الطريق فلم يستطيعوا ان يجدوه"},{"n":7,"text":"فلما اعلم بذلك ارميا لامهم وقال ان هذا الموضع سيبقى مجهولا الى ان يجمع الله شمل الشعب ويرحمهم"},{"n":8,"text":"وحينئذ يبرز الرب هذه الاشياء ويبدو مجد الرب والغمام كما ظهر في ايام موسى وحين سال سليمان ان يقدس الموضع تقديسا بهيا"},{"n":9,"text":"اذ اشتهر وابدى حكمته بتقديم الذبيحة لتدشين الهيكل وتتميمه"},{"n":10,"text":"فكما دعا موسى الرب فنزلت النار من السماء وافنت الذبيحة كذلك دعا سليمان فنزلت النار من السماء وافنت المحرقات"},{"n":11,"text":"وقال موسى انما افنيت ذبيحة الخطيئة لانها لم تؤكل"},{"n":12,"text":"وكذلك عيد سليمان للتدشين ثمانية الايام"},{"n":13,"text":"وقد شرح ذلك في السجلات والتذاكر التي لنحميا وكيف انشا مكتبة جمع فيها اخبار الملوك والانبياء وكتابات داود ورسائل \nالملوك في التقادم"},{"n":14,"text":"وكذلك جمع يهوذا كل ما فقد منا في الحرب التي حدثت لنا وهو عندنا"},{"n":15,"text":"فان كانت لكم حاجة بذلك فارسلوا من ياخذه اليكم"},{"n":16,"text":"واذ قد ازمعنا ان نعيد عيد التطهير كتبنا اليكم وانكم لتحسنون الصنع اذا عيدتم هذه الايام"},{"n":17,"text":"والله الذي خلص جميع شعبه ورد على الجميع الميراث والملك والكهنوت والمقدس"},{"n":18,"text":"كما وعد في الشريعة نرجو منه ان يرحمنا قريبا ويجمعنا مما تحت السماء الى الموضع المقدس"},{"n":19,"text":"فانه قد انقذنا من شرور عظيمة وطهر الموضع"},{"n":20,"text":"ان الحوادث التي وقعت ليهوذا المكابي واخوته وتطهير الهيكل العظيم وتدشين المذبح"},{"n":21,"text":"والحروب التي وقعت مع انطيوكس الشهير وابنه اوباطور"},{"n":22,"text":"والايات التي ظهرت من السماء في حقل الذين تحمسوا لدين اليهود حتى انهم مع قلتهم تسلطوا على البلاد بجملتها وطردوا \nجماهير الاعاجم"},{"n":23,"text":"واستردوا الهيكل الذي اشتهر ذكره في المسكونة باسرها وحرروا المدينة واحيوا الشرائع التي كادت تضمحل لان الرب عطف عليهم \nبكثرة مراحمه"},{"n":24,"text":"تلك الامور التي شرحها ياسون القيرواني في خمسة كتب قد اقبلنا نحن على اختصارها في درج واحد"},{"n":25,"text":"ولما راينا تكاثر الحوادث والصعوبة التي تعترض من اراد الخوض في اخبار التاريخ لكثرة المواد"},{"n":26,"text":"كان من همنا ان نجعل فيما كتبناه فكاهة للمطالع وسهولة للحافظ وفائدة للجميع"},{"n":27,"text":"فلم يكن تكلفنا لهذا الاختصار امرا سهلا وانما تم بالعرق والسهر"},{"n":28,"text":"كما ان الذي يعد مادبة ويبتغي بها منفعة الناس لا يكون الامر عليه سهلا غير انا لاجل مرضاة الكثيرين سنتحمل هذا النصب عن \nطيبة نفس"},{"n":29,"text":"تاركين التدقيق في تفاصيل الحوادث لاصحاب التاريخ وملتزمين في الاختصار استقراء اهم الوقائع"},{"n":30,"text":"فانه كما ينبغي لمن يهندس بيتا جديدا ان يهتم بجميع اجزاء البنيان ولمن يباشر الوسم والتصوير ان يتطلب اسباب الزينة \nهكذا ما نحن فيه على ما ارى"},{"n":31,"text":"فان التبحر والكلام على كل امر والبحث عن جزء فجزء من شان مصنف التاريخ"},{"n":32,"text":"واما الملخص فمرخص له ان يسوق الحديث باختصار مع اهمال التدقيق في المباحث"},{"n":33,"text":"وههنا نشرع في ايراد الحوادث مقتصرين من التمهيد على ما ذكرناه اذ ليس من الاصابة الاطناب فيما قبل التاريخ والايجاز في \nالتاريخ"}]},{"label":"سفر المكابيين الثاني 3","verses":[{"n":1,"text":"حين كانت المدينة المقدسة عامرة امنة والشرائع محفوظة غاية الحفظ لما كان عليه اونيا الكاهن الاعظم من الورع والبغض للشر"},{"n":2,"text":"كان الملوك انفسهم يعظمون المقدس ويكرمون الهيكل بافخر التقادم"},{"n":3,"text":"حتى ان سلوقس ملك اسية كان يؤدي من دخله الخاص جميع النفقات المختصة بتقديم الذبائح"},{"n":4,"text":"وان رجلا اسمه سمعان من سبط بنيامين كان مقلدا الوكالة على الهيكل وقعت مخاصمة بينه وبين الكاهن الاعظم لاجل ظلم جناه \nعلىالمدينة"},{"n":5,"text":"واذ لم يمكنه التغلب على اونيا انطلق الى ابلونيوس بن ترساوس وكان اذ ذاك قائدا في بقاع سورية وفينيقية"},{"n":6,"text":"واخبره ان الخزانة التي في اورشليم مشحونة من الاموال بما لا يستطاع وصفه حتى ان الدخل لا يحصى لكثرته وان ذلك ليس بمختص \nبنفقة الذبائح فيتهيا للملك ادخال ذلك كله في حوزته"},{"n":7,"text":"ففاوض ابلونيوس الملك واعلمه بالاموال التي وصفت له فاختار هليودورس قيم المصالح وارسله وامره بجلب الاموال المذكورة"},{"n":8,"text":"فتوجه هليودورس لساعته قاصدا في الظاهر التطوف في مدن بقاع سورية وفينيقية وكان في الواقع يقصد انفاذ مرام الملك"},{"n":9,"text":"فلما جاء اورشليم احسن الكاهن الاعظم ملتقاه فحدثه بما كوشفوا به وصرح له بسبب قدومه وساله هل الامر في الحقيقة كماذكر له"},{"n":10,"text":"فذكر له الكاهن الاعظم ان المال هو ودائع للارامل واليتامى"},{"n":11,"text":"وان قسما منه لهركانس بن طوبيا احد عظماء الاشراف ثم ان الامر ليس على ما وشى به سمعان المنافق وانما المال كله اربعون \nقنطار فضة ومئتا قنطار ذهب"},{"n":12,"text":"فلا يجوز بوجه من الوجوه هضم الذين ائتمنوا قداسة الموضع ومهابة وحرمة الهيكل المكرم في المسكونة كلها"},{"n":13,"text":"لكن هليودورس بناء على امر الملك اصر على حمل الاموال الى خزانة الملك"},{"n":14,"text":"وعين يوما دخل فيه للفحص عن ذلك فكان في جميع المدينة ارتعاش شديد"},{"n":15,"text":"وانطرح الكهنة امام المذبح بحللهم الكهنوتية يبتهلون نحو السماء الى الذي سن في الودائع ان تصان لمستودعها"},{"n":16,"text":"وكان من راى وجه الكاهن الاعظم يتفطر فؤاده لان منظره وامتقاع لونه كانا ينبئان بما في نفسه من الارتعاش"},{"n":17,"text":"اذ كان الرجل قد اشتمل عليه الرعب والقشعريرة فكانا يدلان الرائين على ما في قلبه من الكابة"},{"n":18,"text":"وكان الناس يتبادرون من البيوت افواجا ليصلوا صلاة عامة لسبب الهوان المشرف على الموضع"},{"n":19,"text":"وكانت النساء يزدحمن في الشوارع وهن متحزمات بالمسوح تحت ثديهن والعذارى ربات الخدور يتجارين بعضهن الى الابواب وبعضهن \nالى الاسوار واخريات يتطلعن من الكوى"},{"n":20,"text":"وكلهن باسطات ايديهن الى السماء يتضرعن بالابتهال"},{"n":21,"text":"فكان انكسار الجمهور وانتظار الكاهن الاعظم وهو في ارتعاش شديد مما يصدع القلب رحمة"},{"n":22,"text":"وكانوا يتضرعون الى الاله القدير ان يحفظ الودائع موفوره لمستودعيها"},{"n":23,"text":"اما هليودورس فكان اخذا في اتمام ما قضى به وقد حضر هناك مع شرطه في الخزانة"},{"n":24,"text":"فصنع رب ابائنا وسلطان كل قدرة اية عظيمة حتى ان جميع الذين اجتراوا على الدخول صرعتهم قدرة الله واخذهم الانحلال والرعب"},{"n":25,"text":"وذلك انه ظهر لهم فرس عليه راكب مخيف وجهازه فاخر فوثب وضرب هليودورس بحوافر يديه وكانت عدة الراكب كانها من ذهب"},{"n":26,"text":"وتراءى ايضا لهليودورس فتيان عجيبا القوة بديعا البهاء حسنا اللباس فوقفا على جانبيه يجلدانه جلدا متواصلا حتى اثخناه \nبالضرب"},{"n":27,"text":"فسقط لساعته على الارض وغشيه ظلام كثيف فرفعوه وجعلوه على محمل"},{"n":28,"text":"فاذا به بعد ان دخل الخزانة المذكورة في موكب حافل وجند كثير قد اصبح محمولا لا مغيث له وقد تجلت لهم قدرة الله علانية"},{"n":29,"text":"فكان مطروحا بالقوة الالهية ابكم منقطع الرجاء من الخلاص"},{"n":30,"text":"واليهود يباركون الرب الذي مجد مقدسه وقد امتلا الهيكل ابتهاجا وتهللا اذ تجلى فيه الرب القدير بعدما كان قبيل ذلك مملوء \nاخوفا واضطرابا"},{"n":31,"text":"فبادر بعض من اصحاب هليودورس وسالوا اونيا ان يبتهل الى العلي ويمن عليه بالحياة اذ كان قد اصبح على اخر رمق"},{"n":32,"text":"فخالج قلب الكاهن الاعظم ان الملك ربما اتهم اليهود بمكيدة كادوها لهليودورس فقدم الذبيحة من اجل خلاص الرجل"},{"n":33,"text":"وبينما الكاهن الاعظم يقدم الكفارة اذ عاد ذانك الفتيان فظهر لهليودورس بلباسهما الاول ووقفا وقالا عليك بجزيل الشكر \nلاونيا الكاهن الاعظم فان الرب قد من عليك بالحياة من اجله"},{"n":34,"text":"وانت ايها المجلود فاخبر الجميع بقدرة الله العظيمة قالا ذلك وغابا عن النظر"},{"n":35,"text":"فقدم هليودورس ذبيحة للرب وصلى اليه صلوات عظيمة على انه من عليه بالحياة وشكر اونيا ورجع بجيشه الى الملك"},{"n":36,"text":"وكان يعترف امام الجميع بما عاينه من اعمال الله العظيم"},{"n":37,"text":"وسال الملك هليودورس من ترى يكون اهلا لان نعود فنرسله الى اورشليم فقال"},{"n":38,"text":"ان كان لك عدو او صاحب دسيسة في المملكة فارسله الى هناك فيرجع اليك مجلودا ان نجا فان في ذلك الموضع قدرة الهية لا \nمحالة"},{"n":39,"text":"لان الذي مسكنه في السماء هو يراقب الموضع ويدافع عنه فيضرب الذين يقصدون بالشر ويهلكهم"},{"n":40,"text":"هذا ما كان من امر هليودورس وحماية الخزانة"}]},{"label":"سفر المكابيين الثاني 4","verses":[{"n":1,"text":"وكان سمعان المذكور الذي وشى في امر الاموال والوطن يقذف اونيا كانه هو اغرى هليودورس بذلك وجلب عليه ذلك الشر"},{"n":2,"text":"وبلغ من وقاحته انه وصف المحسن الى المدينة والقائم بمصلحة اهل وطنه والغيور على الشريعة بانه صاحب دسيسة"},{"n":3,"text":"فاشتدت العداوة حتى ان احد خواص سمعان شرع في القتل"},{"n":4,"text":"فلما تبين اونيا ما في ذلك الخصام من الخطر مع حماقة ابلونيوس قائد بقاع سورية وفينيقية الذي كان يمد سمعان في خبثه قصد \nالملك"},{"n":5,"text":"لا واشيا باهل وطنه ولكن ابتغاء لمصالح تعم الشعب برمته"},{"n":6,"text":"لانه راى انه بغير عناية الملك لا يمكن ان تكون الاحوال في سلام ولا ان يقلع سمعان عن رعونته"},{"n":7,"text":"وكان انه بعد وفاة سلوقس واستيلاء انطيوكس الملقب بالشهير على الملك طمع ياسون اخو اونيا في الكهنوت الاعظم"},{"n":8,"text":"فوفد على الملك ووعده بثلاث مئة وستين قنطار فضة وبثمانين قنطارا من دخل اخر"},{"n":9,"text":"وما عدا ذلك ضمن له مئة وخمسين قنطارا غيرها ان رخص له بسلطة الملك في اقامة مدرسة للتروض وموضع للغلمان وان يكتتب اهل \nاورشليم في رعوية انطاكية"},{"n":10,"text":"فاجابه الملك الى ذلك فتقلد الرئاسة وما لبث ان صرف شعبه الى عادات الامم"},{"n":11,"text":"والغى الاختصاصات التي انعم بها الملوك على اليهود على يد يوحنا ابي اوبولمس الذي قلد السفارة الى الرومانيين في عقد \nالموالاة والمناصرة وابطل رسوم الشريعة وادخل سننا تخالف الشريعة"},{"n":12,"text":"وبادر فاقام مدرسة للتروض تحت القلعة وساق نخبة الغلمان فجعلهم تحت القبعة"},{"n":13,"text":"فتمكن الميل الى عادات اليونان والتخلق باخلاق الاجانب بشدة فجور ياسون الذي هو كافر لا كاهن اعظم"},{"n":14,"text":"حتى ان الكهنة لم يعودوا يحرصون على خدمة المذبح واستهانوا بالهيكل واهملوا الذبائح لينالوا حظا في جوائز الملعب \nالمحرمة بعد المباراة في رمي المطاث"},{"n":15,"text":"وكانوا يستخفون بماثر ابائهم ويتنافسون بمفاخر اليونان"},{"n":16,"text":"فلذلك احاقت بهم رزيئة شديدة فان الذين اولعوا برسومهم وحرصوا على التشبه بهم هم صاروا اعداء لهم ومنتقمين"},{"n":17,"text":"لان النفاق في الشريعة الالهية لا يذهب سدى كما يشهد بذلك ما سيجيء"},{"n":18,"text":"ولما جرت في صور المصارعة التي تجري كل سنة خامسة والملك حاضر"},{"n":19,"text":"انفذ ياسون الخبيث رسلا من اورشليم انطاكيي الرعوية ومعهم ثلاث مئة درهم فضة لذبيحة هركليس لكن هؤلاء طلبوا ان لا تنفق على الذبيحة لان ذلك كان غير لائق بل تنفق في شيء اخر"},{"n":20,"text":"فكان هذا المال في قصد مرسله لذبيحة هركليس لكنه بسعي الذين حملوه انفق في بناء سفن ثلاثية"},{"n":21,"text":"وارسل ابولنيوس بن منستاوس الى مصر لمبايعة بطلماوس فيلوماتور الملك فعلم انطيوكس انه قد نحي عن تدبير الامور فوجه \nاهتمامه الى تحصين نفسه ورجع الى يافا ثم سار الى اورشليم"},{"n":22,"text":"فاستقبله ياسون واهل المدينة استقبالا جليلا ودخل بين المشاعل والهتاف ثم انصرف من هناك بالجيش الى فينيقية"},{"n":23,"text":"وبعد مدة ثلاث سنين وجه ياسون منلاوس اخا سمعان المذكور ليحمل اموالا للملك ويفاوضه في امور مهمة"},{"n":24,"text":"فتزلف الى الملك واطرا عظمة سلطانه واحال الكهنوت الاعظم الى نفسه بان زاد ثلاث مئة قنطار فضة على ما اعطى ياسون"},{"n":25,"text":"ثم رجع ومعه اوامر الملك ولم يكن على شيء مما يليق بالكهنوت الاعظم وانما كانت له اخلاق غاشم عنيف واحقاد وحش ضار"},{"n":26,"text":"وهكذا فان ياسون الذي ختل اخاه ختله اخر فطرد وفر الى ارض بني عمون"},{"n":27,"text":"واستولى منلاوس على الرئاسة الا انه لم يوف شيئا من الاموال التي كان وعد بها الملك"},{"n":28,"text":"فكان سستراتس رئيس القلعة يطالبه لانه كان مولي امر الجباية ولهذا السبب استدعيا كلاهما الى الملك"},{"n":29,"text":"فاستخلف منلاوس ليسيماكس اخاه على الكهنوت الاعظم واستخلف سستراتس كراتيس والي القبرسيين"},{"n":30,"text":"وحدث بعد ذلك ان اهل طرسوس وملو تمردوا لانهم جعلوا هبة لانطيوكيس سرية الملك"},{"n":31,"text":"فبادر الملك لاطفاء الفتنة واستخلف مكانه اندرونكس احد ذوي المناصب"},{"n":32,"text":"فراى منلاوس انه قد اصاب فرصة فسرق من الهيكل انية من الذهب اهدى بعضها الى اندرونكس وباع بعضها في صور والمدن \nالتيبجوارها"},{"n":33,"text":"ولما تيقن اونيا ذلك حجه به وكان قد انصرف الى حمى بدفنة بالقرب من انطاكية"},{"n":34,"text":"فخلا منلاوس باندرونكس واغراه ان يقبض على اونيا فصار الى اونيا وخدعه بمكره وعاقده بقسم حتى حمله على الخروج من الحمى \nوان كان غير واثق به ثم اغتاله من ساعته ولم يرع للعدل حرمة"},{"n":35,"text":"فوقع ذلك موقع المقت عند اليهود بل عند كثير من سائر الامم وشق عليهم قتل الرجل بغيا"},{"n":36,"text":"فلما رجع الملك من نواحي قيلقية رفع اليه يهود المدينة مع ساءته هذه الجناية من اليونانيين مقتل اونيا عدوانا"},{"n":37,"text":"فتاسف انطيوكس ورق رحمة وبكى على حكمة ذلك المفقود وكثرة ادبه"},{"n":38,"text":"واضطرم غضبا ولساعته نزع الارجوان عن اندرونكس ومزق حلله واطافه في المدينة كلها ثم اباد ذلك القاتل في الموضع الذي فتك \nفيه باونيا فانزل به الرب العقوبة التي استحقها"},{"n":39,"text":"وكان ليسيماكس في المدينة قد سلب باغراء منلاوس كثيرا من مال الاقداس فذاع الخبر في الخارج بان قد اخذ كثير من الذهب \nفاجتمع الجمهور على ليسيماكس"},{"n":40,"text":"فلما راى ليسيماكس هيجان الجموع وشدة غضبهم سلح ثلاثة الاف رجل واعمل ايدي الظلم تحت قيادة رجل عات قد تناهى في السن والحماقة جميعا"},{"n":41,"text":"فلما راوا ما عزم عليه ليسيماكس تناول بعضهم حجارة وبعضهم هراوى وبعضهم رمادا حثوه من كل جانب على اصحاب ليسيماكس"},{"n":42,"text":"فجرحوا كثيرين منهم وصرعوا بعضا وهزموهم باجمعهم وقتلوا سالب الاقداس عند الخزانة"},{"n":43,"text":"واقيم الحكم في هذه الامور على منلاوس"},{"n":44,"text":"فلما قدم الملك الى صور ارسلت المشيخة ثلاثة رجال فرفعوا عليه الدعوى"},{"n":45,"text":"واذ راى منلاوس انه مغلوب وعد بطلماوس بن دوريمانس بمال جزيل ليستميل الملك"},{"n":46,"text":"فدخل بطلماوس على الملك وهو في بعض الاروقة يتنسم الهواء وصرفه عن رايه"},{"n":47,"text":"فحكم لمنلاوس الذي هو علة الشر كله بالبراءة مما شكى به وقضى بالموت على اولئك المساكين الذين لو رفعوا دعواهم الى \nالاسكوتيين لحكم لهم بالبراءة"},{"n":48,"text":"ولم يلبث اولئك المحاجون عن المدينة والشعب والاقداس ان حل بهم العقاب الجائر"},{"n":49,"text":"فشق هذا التعدى حتى على الصوريين وبذلوا نفقات دفنهم بسخاء"},{"n":50,"text":"واستقر منلاوس في الرئاسة بشره ذوي الاحكام وكان لا يزداد الا خبثا ولم يزل لاهل وطنه كمينا مهلكا"}]},{"label":"سفر المكابيين الثاني 5","verses":[{"n":1,"text":"في ذلك الزمان تجهز انطيوكس لغزو مصر ثانية"},{"n":2,"text":"فحدث انه ظهر في المدينة كلها مدة اربعين يوما فرسان تعدو في الجو وعليهم ملابس ذهبية وفي ايديهم رماح وهم مكتبون كتائب"},{"n":3,"text":"وقنابل من الخيل مصطفة وهجوم وكر بين الفريقين وتقليب تروس وحراب كثيرة واستلال سيوف ورشق نبال ولمعان حلي ذهبية ودروع \nمن كل صنف"},{"n":4,"text":"فكان الجميع يسالون ان يكون مال هذه الاية خيرا"},{"n":5,"text":"وارجف قوم ان انطيوكس قد مات فاتخذ ياسون جيشا ليس باقل من الف نفس وهجم على المدينة بغتة حتى اذا دفع الذين على الاسوار \nواوشك ان ياخذ المدينة هرب منلاوس الى القلعة"},{"n":6,"text":"فطفق ياسون يذبح اهل وطنه بغير رحمة ولم يفطن ان الظفر بالاخوان هو عين الخذلان حتى كان نصرته هذه انما كانت على اعداء لا \nعلى بني امته"},{"n":7,"text":"لكنه لم يحز الرئاسة وانما احاق به اخيرا خزي كيده فهرب ثانية الى ارض بني عمون"},{"n":8,"text":"وكانت خاتمة امره منقلبا سيئا لان ارتاس زعيم العرب طرده فجعل يفر من مدينة الى مدينة والجميع ينبذونه ويبغضونه بغضة من \nارتد عن الشريعة ويمقتونه مقت من هو قتال لاهل وطنه حتى دحر الى مصر"},{"n":9,"text":"فكان ان الذي غرب كثيرين هلك في الغربة في ارض لكديمون اذ لجا الى هناك بوسيلة القرابة"},{"n":10,"text":"والذي طرح كثيرين بغير قبر اصبح لم يبك عليه ولم يدفن ولم يكن له قبر في وطنه"},{"n":11,"text":"فلما بلغت الملك هذه الحوادث اتهم اليهود بالانتقاض عليه فزحف من مصر وقد تنمر في قلبه واخذ المدينة عنوة"},{"n":12,"text":"وامر الجنود ان يقتلوا كل من صادفوه دون رحمة ويذبحوا المختبئين في البيوت"},{"n":13,"text":"فطفقوا يهلكون الشبان والشيوخ ويبيدون الرجال والنساء والاولاد ويذبحون العذارى والاطفال"},{"n":14,"text":"فهلك ثمانون الف نفس في ثلاثة ايام منهم اربعون الفا في المعركة وبيع منهم عدد ليس باقل من القتلى"},{"n":15,"text":"ولم يكتف بذلك بل اجترا ودخل الهيكل الذي هو اقدس موضع في الارض كلها وكان دليله منلاوس الخائن للشريعة والوطن"},{"n":16,"text":"واخذ الانية المقدسة بيديه الدنستين مع ما اهدته ملوك الاجانب لزينة الموضع وبهائه وكرامته وقبض عليها بيديه النجستين \nومضى"},{"n":17,"text":"فتشامخ انطيوكس في نفسه ولم يفطن الى ان الله غضب حينا لاجل خطايا سكان المدينة وانه لذلك اهمل الموضع"},{"n":18,"text":"ولولا انهم انهمكوا بخطايا كثيرة لجلد حال دخوله وردع عن جسارته كما وقع لهليودورس الذي بعثه سلوقس الملك لافتقاد \nالخزانة"},{"n":19,"text":"ولكن الرب لم يتخذ الامة لاجل الموضع بل الموضع لاجل الامة"},{"n":20,"text":"ولذلك بعدما اشترك الموضع في مصائب الامة عاد فاشترك في نعم الرب وبعدما خذله القدير في غضبه ادرك كل مجد عند توبته \nتعالى"},{"n":21,"text":"وحمل انطيوكس من الهيكل الفا وثماني مئة قنطار وبادر الرجوع الى انطاكية وقد خيلت اليه كبرياؤه وتشامخ نفسه انه يقطع \nالبر بالسفن والبحر بالقدم"},{"n":22,"text":"وترك عمالا يراغمون الامة منهم فيلبس في اورشليم وهو فريجي الاصل وكان اشرس اخلاقا من الذي نصبه"},{"n":23,"text":"واندرونكس في جرزيم وايضا منلاوس الذي كان اشد جورا على الرعية من كليهما"},{"n":24,"text":"ثم حمله ما كان عليه من المقت لرعايا اليهود على ان ارسل ابلونيوس الرئيس البغيض في اثنين وعشرين الف جندي وامره ان \nيذبح كل بالغ منهم ويبيع النساء والصبيان"},{"n":25,"text":"فلما وفد الى اورشليم اظهر السلام وتربص الى يوم السبت المقدس حتى اذا دخل اليهود في عطلتهم امر اصحابه بان يتسلحوا"},{"n":26,"text":"وذبح جميع الخارجين للتفرج ثم اقتحم المدينة بالسلاح واهلك خلقا كثيرا"},{"n":27,"text":"وان يهوذا المكابي كان قد انصرف الى البرية وهو عاشر عشرة فلبث مع اصحابه في الجبال يعيشون عيشة الوحوش وياكلون العشب \nلئلا يشتركوا في النجاسة"}]},{"label":"سفر المكابيين الثاني 6","verses":[{"n":1,"text":"وبعد ذلك بيسير ارسل الملك شيخا اثينيا ليضطر اليهود ان يرتدوا عن شريعة ابائهم ولا يتبعوا شريعة الله"},{"n":2,"text":"وليدنس هيكل اورشليم ويجعله على اسم زوس الاولمبي ويجعل هيكل جرزيم على اسم زوس مؤوي الغرباء لان اهل الموضع كانوا غرباء"},{"n":3,"text":"فاشتد انفجار الشر وعظم على الجماهير"},{"n":4,"text":"وامتلا الهيكل عمرا وقصوفا واخذ الامم يفسقون بالمابونين ويضاجعون النساء في الدور المقدسة ويدخلون اليها ما لا يحل"},{"n":5,"text":"وكان المذبح مغطى بالمحارم التي نهت الشريعة عنها"},{"n":6,"text":"ولم يكن لاحد ان يعيد السبت ولا يحفظ اعياد الاباء ولا يعترف بانه يهودي اصلا"},{"n":7,"text":"وكانوا كل شهر يوم مولد الملك يساقون قسرا للتضحية وفي عيد ديونيسيوس يضطرون الى الطواف اجلالا له وعليهم اكاليل من اللبلاب"},{"n":8,"text":"وصدر امر الى المدن اليونانية المجاورة باغراء البطالمة ان يلزموا اليهود بمثل ذلك وبالتضحية"},{"n":9,"text":"وان من ابى ان يتخذ السنن اليونانية يقتل فذاقوا بذلك امر البلاء"},{"n":10,"text":"فان امراتين سعي بهما انهما ختنتا اولادهما فعلقوا اطفالهما على اثديهما وطافوا بهما في المدينة علانية ثم القوهما عن السور"},{"n":11,"text":"ولجا قوم الى مغاور كانت بالقرب منهم لاقامة السبت سرا فوشي بهم الى فيلبس فاحرقهم بالنار وهم لا يجترئون ان يدافعواعن \nانفسهم اجلالا لهذا اليوم العظيم"},{"n":12,"text":"واني لارجو من مطالعي هذا الكتاب ان لا يستوحشوا من هذه الضربات وان يحسبوا هذه النقم ليست للهلاك بل لتاديب امتنا"},{"n":13,"text":"فانه اذا لم يهمل الكفرة زمنا طويلا بل عجل عليهم بالعقاب فذلك دليل على رحمة عظيمة"},{"n":14,"text":"لان الرب لا يمهل عقابنا بالاناة الى ان يستوفى كيل الاثام كما يفعل مع سائر الامم"},{"n":15,"text":"فقد قضى فينا بذلك لئلا تبلغ اثامنا غايتها وينتقم منا اخيرا"},{"n":16,"text":"فهو لا يزيل عنا رحمته ابدا واذا ادب شعبه بالشدائد فلا يخذله"},{"n":17,"text":"نقول هذا على سبيل التذكرة ونرجع الى تتمة الحديث بكلام موجز"},{"n":18,"text":"كان رجل يقال له العازار من متقدمي الكتبة طاعن في السن رائع المنظر في الغاية فاكرهوه بفتح فيه على اكل لحم الخنزير"},{"n":19,"text":"فاختار ان يموت مجيدا على ان يحيا ذميما وانقاد الى العذاب طائعا"},{"n":20,"text":"وقذف لحم الخنزير من فيه ثم تقدم كما يليق بمن يتمنع بشجاعة عما لا يحل ذوقه رغبة في الحياة"},{"n":21,"text":"فخلا به الموكلون بامر الضحايا الكفرية لما كان بينهم وبينه من قديم المعرفة وجعلوا يحثونه ان ياتي بما يحل له تناوله \nمن اللحم مهيأ بيده ويتظاهر بانه ياكل من لحم الضحايا التي امر بها الملك"},{"n":22,"text":"لينجو من الموت اذا فعل ذلك وينال منهم الجميل لاجل مودته القديمة لهم"},{"n":23,"text":"لكنه عول على الراي النزيه الجدير بسنه وكرامة شيخوخته وما بلغ اليه من جلالة المشيب وبكمال سيرته الحسنة منذ حداثته \nبلب الشريعة المقدسة الالهية واجاب بغير توقف وقال بل اسبق الى الجحيم"},{"n":24,"text":"لانه لا يليق بسننا الرئاء لئلا يظن كثير من الشبان ان العازار وهو ابن تسعين سنة قد انحاز الى مذهب الاجانب"},{"n":25,"text":"ويضلوا بسببي لاجل رئائي وحبي لحياة قصيرة فانية فاجلب على شيخوختي الرجس والفضيحة"},{"n":26,"text":"فاني ولو نجوت الان من نكال البشر لا افر من يدي القدير لا في الحياة ولا بعد الممات"},{"n":27,"text":"ولكن اذا فارقت الحياة ببسالة فقد وفيت بحق شيخوختي"},{"n":28,"text":"وابقيت للشبان قدوة شهامة ليتلقوا المنية ببسالة وشهامة في سبيل الشريعة الجليلة المقدسة ولما قال هذا انطلق من ساعته \nالى عذاب التوتير والضرب"},{"n":29,"text":"فتحول اولئك الذين ابدوا له الرافة قبيل ذلك الى القسوة لحسبانهم ان كلامه كان عن كبر"},{"n":30,"text":"ولما اشرف على الموت من الضرب تنهد وقال يعلم الرب وهو ذو العلم المقدس اني وانا قادر على التخلص من الموت اكابد في \nجسدي عذاب الضرب الاليم واما في نفسي فاني احتمل ذلك مسرورا لاجل مخافته"},{"n":31,"text":"وهكذا قضى هذا الرجل تاركا موته قدوة شهامة وتذكار فضيلة لامته باسرها فضلا عن الشبان بخصوصهم"}]},{"label":"سفر المكابيين الثاني 7","verses":[{"n":1,"text":"وقبض على سبعة اخوة مع امهم فاخذ الملك يكرههم عل تناول لحوم الخنزير المحرمة ويعذبهم بالمقارع والسياط"},{"n":2,"text":"فانتدب احدهم للكلام وقال ماذا تبتغي وعم تستنطقنا انا لنختار ان نموت ولا نخالف شريعة ابائنا"},{"n":3,"text":"فحنق الملك وامر باحماء الطواجن والقدور ولما احميت"},{"n":4,"text":"امر لساعته بان يقطع لسان الذي انتدب للكلام ويسلخ جلد راسه وتجدع اطرافه على عيون اخوته وامه"},{"n":5,"text":"ولما عاد جذمة امر بان يؤخذ الى النار وفيه رمق من الحياة ويقلى وفيما كان البخار منتشرا من الطاجن كانوا هم وامهم يحض \nبعضهم بعضا ان يقدموا على الموت بشجاعة"},{"n":6,"text":"قائلين ان الرب الاله ناظر وهو يتمجد بنا كما صرح موسى في نشيده الشاهد في الوجوه اذ قال ويستمجد بعبيده"},{"n":7,"text":"ولما قضى الاول على هذه الحال ساقوا الثاني الى الهوان ونزعوا جلد راسه مع شعره ثم سالوه هل ياكل قبل ان يعاقب في جسده \nعضوا عضوا"},{"n":8,"text":"فاجاب بلغة ابائه وقال لا فاذاقوه بقية العذاب كالاول"},{"n":9,"text":"وفيما كان على اخر رمق قال انك ايها الفاجر تسلبنا الحياة الدنيا ولكن ملك العالمين اذا متنا في سبيل شريعته فسيقيمنا لحياة ابدية"},{"n":10,"text":"وبعده شرعوا يستهينون بالثالث وامروه فدلع لسانه وبسط يديه بقلب جليد"},{"n":11,"text":"وقال اني من الرب السماء اوتيت هذه الاعضاء ولاجل شريعته ابذلها واياه ارجو ان استردها من بعد"},{"n":12,"text":"فبهت الملك والذين معه من بسالة قلب ذلك الغلام الذي لم يبال بالعذاب شيئا"},{"n":13,"text":"ولما قضى عذبوا الرابع ونكلوا به بمثل ذلك"},{"n":14,"text":"ولما اشرف على الموت قال حبذا ما يتوقعه الذي يقتل بايدي الناس من رجاء اقامة الله له اما انت فلا تكون لك قيامة للحياة"},{"n":15,"text":"ثم ساقوا الخامس وعذبوه فالتفت الى الملك وقال"},{"n":16,"text":"انك بما لك من السلطان على البشر مع كونك فانيا تفعل ما تشاء ولكن لا تظن ان الله قد خذل ذريتنا"},{"n":17,"text":"اصبر قليلا فترى باسه الشديد كيف يعذبك انت ونسلك"},{"n":18,"text":"وبعده ساقوا السادس فلما قارب ان يموت قال لا تغتر بالباطل فانا نحن جلبنا على انفسنا هذا العذاب لانا خطانا الى الهنا \nولذلك وقع لنا ما يقضي بالعجب"},{"n":19,"text":"واما انت لا تحسب انك تترك سدى بعد تعرضك لمناصبة الله"},{"n":20,"text":"وكانت امهم اجدر الكل بالعجب والذكر الحميد فانها عاينت بنيها السبعة يهلكون في مدة يوم واحد وصبرت على ذلك بنفس طيبة \nثقة بالرب"},{"n":21,"text":"وكانت تحرض كلا منهم بلغة ابائها وهي ممتلئة من الحكمة السامية وقد القت على كلامها الانثوي بسالة رجلية"},{"n":22,"text":"قائلة لهم اني لست اعلم كيف نشاتم في احشائي ولا انا منحتكم الروح والحياة ولا احكمت تركيب اعضائكم"},{"n":23,"text":"على ان خالق العالم الذي جبل تكوين الانسان وابدع لكل شيء تكوينه سيعيد اليكم برحمته الروح والحياة لانكم الان تبذلون \nانفسكم في سبيل شريعته"},{"n":24,"text":"وان انطيوكس اذ تخيل انه يستخف به وخشي صوت معير يعيره اخذ يحرض بالكلام اصغرهم الباقي بل اكد له بالايمان انه يغنيه \nويسعده اذا ترك شريعة ابائه ويتخذه خليلا له ويقلده المناصب"},{"n":25,"text":"ولمل لم يصخ الغلام لذلك البتة دعا الملك امه وحثها ان تشير على الغلام بما يبلغ الي خلاصه"},{"n":26,"text":"والح عليها حتى وعدت بانها تشير على ابنها"},{"n":27,"text":"ثم انحنت اليه واستهزات بالملك العنيف وقالت بلغة ابائها يا بني ارحمني انا التي حملتك في جوفها تسعة اشهر وارضعتك ثلاث \nسنين وعالتك وبلغتك الى هذه السن وربتك"},{"n":28,"text":"انظر يا ولدي الى السماء والارض واذا رايت كل ما فيهما فاعلم ان الله صنع الجميع من العدم وكذلك وجد جنس البشر"},{"n":29,"text":"فلا تخف من هذا الجلاد لكن كن مستاهلا لاخوتك واقبل الموت لاتلقاك مع اخوتك بالرحمة"},{"n":30,"text":"وفيما هي تتكلم قال الغلام ماذا انتم منتظرون اني لا اطيع امر الملك وانما اطيع امر الشريعة التي القيت الى ابائنا على يد موسى"},{"n":31,"text":"وانت ايها المخترع كل شر على العبرانيين انك لن تنجو من يدي الله"},{"n":32,"text":"فنحن انما نعاقب على خطايانا"},{"n":33,"text":"وربنا الحي وان سخط علينا حينا يسيرا لتوبيخنا وتاديبنا سيتوب على عبيده من بعد"},{"n":34,"text":"واما انت ايها المنافق يا اخبث كل بشر فلا تتشامخ باطلا وتتنمر بامالك الكاذبة وانت رافع يدك على عبيده"},{"n":35,"text":"لانك لم تنج من دينونة الله القدير الرقيب"},{"n":36,"text":"ولقد صبر اخوتنا على الم ساعة ثم فازوا بحياة ابدية وهم في عهد الله واما انت فسيحل بك بقضاء الله العقاب الذي تستوجبه \nبكبريائك"},{"n":37,"text":"وانا كاخوتي ابذل جسدي ونفسي في سبيل شريعة ابائنا وابتهل الى الله ان لا يبطئ في توبته على امتنا وان يجعلك بالمحن \nوالضربات تعترف بانه هو الاله وحده"},{"n":38,"text":"وان ينتهي في وفي اخوتي غضب القدير الذي حل على امتنا عدلا"},{"n":39,"text":"فحنق الملك ولم يحتمل ذلك الاستهزاء فزاده نكالا على اخوته"},{"n":40,"text":"وهكذا قضى هذا الغلام طاهرا وقد وكل الى الرب كل امره"},{"n":41,"text":"وفي اخر الامر هلكت الام على اثر بنيها"},{"n":42,"text":"وبما اوردناه عن الضحايا والتعذيبات المبرحة كفاية"}]},{"label":"سفر المكابيين الثاني 8","verses":[{"n":1,"text":"وكان يهوذا المكابي ومن معه يتسللون الى القرى ويندبون ذوي قرابتهم ويستضمون الذين ثبتوا على دين اليهود حتى جمعوا ستة الاف"},{"n":2,"text":"وكانوا يبتهلون الى الرب ان ينظر الى شعبه الذي اصبح يدوسه كل احد ويعطف على الهيكل الذي دنسه اهل النفاق"},{"n":3,"text":"ويرحم المدينة المتهدمة التي اشرفت على الامحاء ويصغي الى صوت الدماء الصارخة اليه"},{"n":4,"text":"ويذكر اهلاك الاطفال الابرئاء ظلما والتجاديف على اسمه ويجهر ببغضته للشر"},{"n":5,"text":"ولما اصبح المكابي في جيش لم تعد الامم تثبت امامه اذ كان سخط الرب قد استحال الى رحمة"},{"n":6,"text":"فجعل يفاجئ المدن والقرى ويحرقها حتى اذا استولى على مواضع توافقه تغلب على الاعداء في مواقع جمة"},{"n":7,"text":"وكان اكثر غاراته ليلا فذاع خبر شجاعته في كل مكان"},{"n":8,"text":"فلما راى فيلبس ان الرجل اخذ في التقدم شيئا فشيئا وقد اوتي الفوز في اكثر اموره كتب الى بطلماوس قائد بقاع سورية \nفينيقية يساله المناجدة لصيانة مصالح الملك"},{"n":9,"text":"فاختار لساعته نكانور بن بتركلس من خواص اصدقاء الملك وجعل تحت يده لفيفا من الامم يبلغ عشرين الفا ليستاصل ذرية اليهود \nعن اخرهم وضم اليه جرجياس وهو من القواد المحنكين في امر الحرب"},{"n":10,"text":"فرسم نكانور ان يؤخذ من مبيع سبي اليهود الفا القنطار التي كانت للرومانيين على الملك"},{"n":11,"text":"وارسل في الحال الى مدن الساحل يدعو الى مشتري رقاب اليهود مسعرا كل تسعين رقبة بقنطار ولم يخطر له ما سيحل به من نقمة \nالقدير"},{"n":12,"text":"فاتصل بيهوذا خبر مقدم نكانور فاخبر الذين معه بمجيء الجيش"},{"n":13,"text":"فبدا الذين خافوا ولم يثقوا بعدل الله ينسابون كل واحد من مكانه"},{"n":14,"text":"وباع اخرون كل ما كان باقيا لهم وكانوا يبتهلون الى الرب ان ينقذهم من نكانور الكافر الذي باعهم قبل الملتقى"},{"n":15,"text":"وذلك ان لم يكن من اجلهم فمن اجل عهده مع ابائهم وحرمة اسمه العظيم الذي هم مسمون به"},{"n":16,"text":"فحشد المكابي اصحابه وهم ستة الاف وحرضهم ان لا يرتاعوا من الاعداء ولا يخافوا من كثرة الامم المجتمعة عليهم بغيا وان \nيقاتلوا بباس"},{"n":17,"text":"جاعلين نصب عيونهم الاهانة التي الحقوها بالموضع المقدس عدوانا وما انزلوه بالمدينة من القهر والعار مع نقض سنن الاباء"},{"n":18,"text":"وقال ان هؤلاء انما يتوكلون على سلاحهم وجسارتهم واما نحن فنتوكل على الله القدير الذي يستطيع في لمحة ان يبيد الثائرين \nعلينا بل العالم باسره"},{"n":19,"text":"ثم ذكر لهم النجدات التي امد بها اباؤهم وما كان من ابادة المئة والخمسة والثمانين الفا على عهد سنحاريب"},{"n":20,"text":"والواقعة التي كانت لهم في بابل مع الغلاطيين كيف برزوا للقتال وهم ثمانية الاف رجل ومعهم اربعة الاف من المكدونيين وكيف \nحين وهل المكدونيين اهلك اولئك الثمانية الالاف مئة وعشرين الفا بالنجدة التي اوتها من السماء وعادوا بخير جزيل"},{"n":21,"text":"وبعدما شددهم بهذا الكلام حتى اضحوا مستعدين للموت في سبيل الشريعة والوطن قسمهم اربع فرق"},{"n":22,"text":"واقام كل واحد من اخوته سمعان ويوسف ويوناتان قائدا على فرقة وجعل تحت يده الفا وخمس مئة"},{"n":23,"text":"ثم امر العازار ان يتلو عليهم الكتاب المقدس وجعل لهم كلمة السر نصرة الله ثم اتخذ قيادة الكتيبة الاولى وحمل على نكانور"},{"n":24,"text":"فايدهم القدير فقتلوا من الاعداء ما يزيد على تسعة الاف وتركوا اكثر جيش نكانور مجرحين مجدعي الاعضاء والجاوا الجميع الى \nالهزيمة"},{"n":25,"text":"وغنموا اموال الذين جاءوا لشرائهم ثم تعقبوهم مسافة غير قصيرة"},{"n":26,"text":"الى ان حضرت الساعة فامسكوا وعادوا وقد ادركوا السبت ولذلك لم يطيلوا تعقبهم"},{"n":27,"text":"وجمعوا اسلحة الاعداء واخذوا اسلابهم ثم حفظوا السبت وهم يباركون الرب كثيرا ويعترفون له اذ انقذهم ليعيدوا ذلك اليوم \nومن عليهم باستئناف رحمته"},{"n":28,"text":"ولما انقضى السبت وزعوا على الضعفاء والارامل واليتامى نصيبهم من الغنائم واقتسموا الباقي بينهم وبين اولادهم"},{"n":29,"text":"وبعدما فرغوا من ذلك اقاموا صلاة عامة سائلين الرب الرحيم ان يعود فيتوب على عبيده"},{"n":30,"text":"وقتلوا ما يزيد على عشرين الفا من جيوش تيموتاوس وبكيديس واستولوا على حصون مشيدة واقتسموا كثيرا من الاسلاب جعلوها \nسهاما متساوية لهم وللضعفاء واليتامى والارامل والشيوخ"},{"n":31,"text":"ولما جمعوا اسلحة العدو رتبوا كل شيء في موضعه اللائق به وحملوا ما بقي من الغنائم الى اورشليم"},{"n":32,"text":"وقتلوا رئيس جيش تيموتاوس وكان رجلا شديد النفاق الحق باليهود اضرارا كثيرة"},{"n":33,"text":"وبينا هم يحتفلون بالظفر في وطنهم احرقوا كلستانيس وقوما معه في بيت كانوا قد فروا اليه وكانوا قد احرقوا الابواب \nالمقدسة فنالهم الجزاء الذي استوجبوه بكفرهم"},{"n":34,"text":"واما نكانور الشديد الفجور الذي كان قد استصحب معه الف تاجر لمشتري اليهود"},{"n":35,"text":"فلما راى الذين كان يحتقرهم قد اذلوه بامداد الرب خلع ما عليه من الثياب الفاخرة وانساب في كبد البلاد منفردا كالابق حتى \nلحق بانطاكية وهو متفجع غاية التفجع لانقراض جيشه"},{"n":36,"text":"وبعدما كان قد وعد الرومانيين بان يفيهم الخراج من سبي اورشليم عاد يذيع ان اليهود لهم الله نصير وانهم لذلك لا يغلبون اذ \nهم متبعون ما رسم لهم من الشرائع"}]},{"label":"سفر المكابيين الثاني 9","verses":[{"n":1,"text":"واتفق في ذلك الزمان ان انطيوكس كان منصرفا عن بلاد فارس بالخزي"},{"n":2,"text":"وكان قد زحف على مدينة اسمها برسابوليس وشرع يسلب الهياكل ويعسف المدينة فثار الجموع الى السلاح ودفعوه فانهزم انطيوكس \nمنقلبا بالعار"},{"n":3,"text":"ولما كان عند احمتا بلغه ما وقع لنكانور واصحاب تيموتاوس"},{"n":4,"text":"فاستشاط غضبا وازمع ان يحيل على اليهود ما الحقه به الذين هزموه من الشر فامر سائق عجلته بان يجد في السير بغير انقطاع \nوقد حلبه القضاء من السماء فانه قال في تجبره لآتين اورشليم ولأجعلنها مدفنا لليهود"},{"n":5,"text":"لكن الرب اله اسرائيل البصير بكل شيء ضربه ضربة معضلة غير منظورة فانه لم يفرغ من كلامه ذاك حتى اخذه داء في احشائه لا \nدواء له ومغص اليم في جوفه"},{"n":6,"text":"وكان ذلك عين العدل في حقه لانه عذب احشاء كثيرين بالالام المتنوعة الغريبة لكنه لم يكن ليكف عن عتيه"},{"n":7,"text":"وانما بقي صدره ممتلئا من الكبرياء ينفث نار الحنق على اليهود ويحث على الاسراع في السير حتى انه من شدة الجري سقط من \nعجلته فترضضت بتلك السقطة الهائلة جميع اعضاء جسمه"},{"n":8,"text":"فاصبح بعدما خيل له بزهوه الذي لم يبلغ اليه انسان انه يحكم على امواج البحر ويجعل قمم الجبال في كفة الميزان مصروعا \nعلى الارض محمولا في محفة شهادة للجميع بقدرة الله الجليلة"},{"n":9,"text":"حتى كانت الديدان تنبع من جسد ذلك المنافق ولحمه يتساقط وهو حي بالالام والاوجاع وصار الجيش كله يتكره نتن رائحته"},{"n":10,"text":"حتى انه بعدما كان قبيل ذلك يزين له انه يمس كواكب السماء لم يكن احد يطيق حمله لشدة رائحته التي لا تحتمل"},{"n":11,"text":"فلما راى نفسه في تلك الحال من تمزق جسمه اخذ ينزل عن كبريائه المفرطة ويتعقل الحق اذ كانت الاوجاع تزداد فيه على \nالساعات بالضربة الالهية"},{"n":12,"text":"حتى انه هو نفسه امسى لا يطيق نتنه فقال حق على الانسان ان يخضع لله وان لا يحمله الكبر وهو فان على ان يحسب نفسه معادلا لله"},{"n":13,"text":"وكان ذلك الفاجر يتضرع الى الرب لكن الرب لم يكن ليرحمه من بعد ونذر"},{"n":14,"text":"ان المدينة المقدسة التي كان يقصدها حثيثا ليمحو اثارها ويجعلها مدفنا سيجعلها حرة"},{"n":15,"text":"وان اليهود الذين كان قد قضى عليهم بان لا يدفنوا بل يلقوا مع اطفالهم ماكلا للطيور والوحوش سيسويهم جميعا بالاثينيين"},{"n":16,"text":"وان الهيكل المقدس الذي كان قد انتهبه سيزينه بافخر التحف ويرد الانية المقدسة اضعافا ويؤدي النفقات المفروضة للذبائح \nمن دخله الخاص"},{"n":17,"text":"بل انه هو نفسه يتهود ويطوف كل معمور في الارض ينادي بقدرة الله"},{"n":18,"text":"واذ لم تسكن الامه لان قضاء الله العادل كان قد حل عليه قنط من نفسه وكتب الى اليهود رسالة في معنى التوسل وهذه صورتها"},{"n":19,"text":"من انطيوكس الملك القائد الى رعايا اليهود الافاضل السلام الكثير والعافية والغبطة"},{"n":20,"text":"اذا كنتم في سلامة وكان اولادكم وكل شيء لكم على ما تحبون فاني اشكر الله شكرا جزيلا اما انا فرجائي منوط بالسماء"},{"n":21,"text":"وبعد فاني منذ اعتللت لم ازل اذكركم بالمودة ناويا لكم الكرامة والخير فاني في ايابي من نواحي فارس اصابني داء شديد \nفرايت من الواجب ان اصرف العناية الى مصلحة الجميع"},{"n":22,"text":"ليس لاني قانط من نفسي فان لي رجاء وثيقا ان اتخلص من علتي"},{"n":23,"text":"ثم اني تذكرت ان ابي حين سار بجيشه الى الاقاليم العليا عين الولي لعهده"},{"n":24,"text":"وانا اخاف ان يقع امر غير منتظر او يذيع خبر مشؤوم فيضطرب مقلدوا الامور في البلاد عند بلوغه اليهم"},{"n":25,"text":"وقد تبين لي ان من حولنا من ذوي السلطان ومجاوري المملكة يترصدون الفرص ويتوقعون حادثا يحدث فلذلك عينت للملك ابني \nانطيوكسالذي سلمته غير مرة الى كثيرين منكم واوصيتهم به عند مسيري الى الاقاليم العليا وقد كتبت اليه في هذا المعنى"},{"n":26,"text":"فانشدكم وارغب اليكم ان تذكروا ما اوليتكم من النعم العامة والخاصة وان يبقى كل منكم على ما كان له من الولاء لي ولابني"},{"n":27,"text":"ولي الثقة بانه سياتم بقصدي فيعاملكم بالرفق والمرؤة"},{"n":28,"text":"ثم قضى هذا السفاك الدماء المجدف بعد الام مبرحة كما كان يفعل بالناس ومات ميتة شقاء على الجبال في ارض غربة"},{"n":29,"text":"فنقل جثته فيلبس رضيعه ثم انصرف الى مصر الى بطلماوس فيلوماتور خوفا من ابن انطيوكس"}]},{"label":"سفر المكابيين الثاني 10","verses":[{"n":1,"text":"اما المكابي والذين معه فبامداد الرب استردوا الهيكل والمدينة"},{"n":2,"text":"وهدموا المذابح التي كان الاجانب قد بنوها في الساحة وخربوا المعابد"},{"n":3,"text":"وطهروا الهيكل وصنعوا مذبحا اخر واقتدحوا حجارة اقتبسوا منها نارا وقدموا ذبيحة بعد فترة سنتين وهياوا البخور والسرج وخبز التقدمة"},{"n":4,"text":"وبعدما اتموا ذلك ابتهلوا الى الرب وقد خروا بصدورهم ان لا يصابوا بمثل تلك الشرور لكن اذا خطئوا يؤدبهم هو برفق ولا \nيسلمهم الى امم كافرة وحشية"},{"n":5,"text":"واتفق انه في مثل اليوم الذي فيه نجست الغرباء الهيكل في ذلك اليوم عينه ثم تطهير الهيكل وهو اليوم الخامس والعشرون من \nذلك الشهر الذي هو شهر كسلو"},{"n":6,"text":"فعيدوا ثمانية ايام بفرح كما في عيد المظال وهم يذكرون كيف قضوا عيد المظال قبيل ذلك في الجبال والمغاور مثل وحوش \nالبرية"},{"n":7,"text":"ولذلك سبحوا لمن يسر تطهير هيكله وفي ايديهم غصون ذات اوراق وافنان خضر وسعف"},{"n":8,"text":"ورسموا رسما عاما على جميع امة اليهود ان يعيدوا هذه الايام في كل سنة"},{"n":9,"text":"هكذا كانت وفاة انطيوكس الملقب بالشهير"},{"n":10,"text":"ولنشرع الان في خبر ابن ذاك المنافق ونذكر ما كان من رزايا الحروب بالايجاز"},{"n":11,"text":"انه لما استولى هذا على الملك فوض تدبير الامور الى ليسياس قائد القواد في بقاع سورية وفينيقية"},{"n":12,"text":"وذلك ان بطلماوس المسمى بمكرون عزم على ان ينصف اليهود مما كانوا فيه من الظلم واجتهد في معاملتهم بالسلم"},{"n":13,"text":"فلذلك سعى به اصحابه الى اوباطور وكثر كلام الناس فيه بانه خائن لانه تخلى عن قبرس التي كان فيلوماطور قد استعمله عليها \nوانحاز الى انطيوكس الشهير واذ ذهبت عنه كرامة السلطان بلغ منه الكمد فقتل نفسه بسم"},{"n":14,"text":"فولى جرجياس قيادة البلاد وشرع يجيش من الاجانب وناصب اليهود حربا متواصلة"},{"n":15,"text":"وكذلك الادوميون الذين كانت لهم حصون ملائمة كانوا يرغمون اليهود ويقبلون المهاجرين من اورشليم ويتجهزون للحرب"},{"n":16,"text":"فابتهل الذين مع المكابي وتضرعوا الى الله ان يكون لهم نصيرا ثم هجموا على حصون الادوميين"},{"n":17,"text":"واندفعوا عليها بشدة وامتلكوا مواضع منها وصدموا جميع الذين كانوا يقاتلون على السور وكل من اقتحمهم قتلوه فاهلكوا \nمنهم عشرين الفا"},{"n":18,"text":"وفر تسعة الاف منهم الى برجين حصينين جدا مجهزين بكل اسباب الدفاع"},{"n":19,"text":"فخلف المكابي سمعان ويوسف وزكا وعددا من اصحابه كافيا لمحاصرتهما وانصرف الى مواضع اخرى كانت اشد اقتضاء له"},{"n":20,"text":"غير ان الذين كانوا مع سمعان استغواهم حب المال فارتشوا من بعض الذين في البرجين وخلوا سبيلهم بعد ان اخذوا منهم سبعين \nالف درهم"},{"n":21,"text":"فلما اخبر المكابي بما وقع جمع رؤساء الشعب وشكا ما فعلوا من بيع اخوتهم بالمال اذ اطلقوا اعدائهم عليهم"},{"n":22,"text":"ثم قتل اولئك الخونة ومن فوره استولى على البرجين"},{"n":23,"text":"وقرنت اسلحته بكل فوز على يده فاهلك في البرجين ما يزيد على عشرين الفا"},{"n":24,"text":"ثم ان تيموتاوس الذي كان اليهود قد قهروه من قبل حشد جيشا عظيما من الغرباء وجمع من فرسان اسية عددا غير قليل ونزل على \nاليهودية نزول مستفتح قهرا"},{"n":25,"text":"فعندما اقترب توجه اصحاب المكابي الى الابتهال الى الله وقد حثوا التراب على رؤوسهم وحزموا احقاءهم بالمسوح"},{"n":26,"text":"وخروا عند رجل المذبح وابتهلوا اليه ان يكون راحما لهم ومعاديا لاعدائهم ومضايقا لمضايقيهم كما ورد في الشريعة"},{"n":27,"text":"ولما فرغوا من الدعاء اخذوا السلاح وتقدموا حتى صاروا عن المدينة بمسافة بعيدة ولما قاربوا العدو وقفوا"},{"n":28,"text":"وعند طلوع الشمس تلاحم الفريقان وهؤلاء متوكلون على الرب كفيلا بالفوز والنصر مع بسالتهم واولئك متخذون البأس قائدهم في \nالحروب"},{"n":29,"text":"فلما اشتد القتال تراءى للاعداء من السماء خمسة رجال رائعي المنظر على خيل لها لجم من ذهب فجعل اثنان منهم يقدمان \nاليهود"},{"n":30,"text":"وهما قد اكتنفا المكابي يحفزانه باسلحتهما ويقيانه الجراح وهم يرمون بالسهام والصواعق حتى عميت ابصارهم وجعلوا يخبطون \nويتصرعون"},{"n":31,"text":"فقتل عشرون الفا وخمس مئة ومن الفرسان ست مئة"},{"n":32,"text":"وانهزم تيموتاوس الى الحصن المسمى بجازر وهو حصن منيع وكان تحت امرة كيراوس"},{"n":33,"text":"فاستبشر اصحاب المكابي وحاصروا المعقل اربعة ايام"},{"n":34,"text":"وان الذين في داخله لثقتهم بمناعة المكان تمادوا في التجديف وافحشوا في الكلام"},{"n":35,"text":"فلما كان صباح اليوم الخامس هجم عشرون فتى من اصحاب المكابي على السور وهم متقدون غيظا من التجاديف وطفقوا يذبحون \nببسالة وتنمر كل من عرض امامهم"},{"n":36,"text":"وعطف اخرون فتسلقوا الى الذين في الداخل واضرموا البرجين واحرقوا اولئك المجدفين احياء في النيران المتقدة"},{"n":37,"text":"وكسر اخرون الابواب وادخلوا بقية الجيش فاستحوذوا على المدينة وكان تيموتاوس مستخفيا في جب فذبحوه هو وكيراوس اخاه \nوابلوفانيس"},{"n":38,"text":"وبعد ذلك باركوا الرب بالنشيد والاعتراف على احسانه العظيم الى اسرائيل وتاييده لهم بالنصر"}]},{"label":"سفر المكابيين الثاني 11","verses":[{"n":1,"text":"وبعد ذلك بزمان يسير اذ كانت هذه الحوادث قد شقت جدا ليسياس وكيل الملك وذي قرابته والمقلد تدبير الامور"},{"n":2,"text":"جمع نحو ثمانين الفا والفرسان كلهم وزحف على اليهود زاعما انه يجعل المدينة مسكنا لليونانيين"},{"n":3,"text":"ويجعل الهيكل موضعا للكسب كسائر معابد الامم ويعرض الكهنوت الاعظم للبيع سنة فسنة"},{"n":4,"text":"غير متفكر في قدرة الله لكن متوكلا برعونة قلبه على ربوات الرجالة والوف الفرسان وفيلته الثمانين"},{"n":5,"text":"فدخل اليهودية وبلغ الى بيت صور وهي موضع منيع على نحو خمس غلوات من اورشليم وضايقها"},{"n":6,"text":"فلما علم اصحاب المكابي انه يحاصر الحصون ابتهلوا الى الرب مع الجموع بالنحيب والدموع ان يرسل ملاكه الصالح لخلاص اسرائيل"},{"n":7,"text":"ثم اخذ المكابي سلاحه اولا وحرض الاخرين على الاقتحام معه لنجدة اخوتهم"},{"n":8,"text":"فاندفعوا متحمسين بقلب واحد وفيما هم بعد عند اورشليم تراءى فارس عليه لباس ابيض يتقدمهم وهو يخطر بسلاح من ذهب"},{"n":9,"text":"فطفقوا باجمعهم يباركون الله الرحيم وتشجعوا في قلوبهم حتى كانوا مستعدين ان يبطشوا باضرى الوحوش فضلا عن الناس ويخترقوا \nالاسوار الحديدية"},{"n":10,"text":"واخذوا يتقدمون بانتظام وقد اتتهم السماء نصرة والرب رحمة"},{"n":11,"text":"وحملوا على الاعداء حملة الاسود وصرعوا منهم احد عشر الفا ومن الفرسان الفا وست مئة"},{"n":12,"text":"والجاوا سائرهم الى الفرار وكان اكثر الذين نجوا بانفسهم جرحى عراة وانهزم ليسياس اقبح هزيمة"},{"n":13,"text":"واذ كان الرجل صاحب دهاء اخذ يفكر فيما اصابه من الخسران وفطن ان العبرانيين قوم لا يقهرون لان الله القدير مناصر لهم \nفراسلهم"},{"n":14,"text":"ووعد بانه يسلم بكل ما هو حق ويستميل الملك الى موالاتهم"},{"n":15,"text":"فرضي المكابي بكل ما سال ليسياس ابتغاء لما هو انفع وكل ما طلب المكابي من ليسياس بالكتابة ان يقضى لليهود قضاه الملك"},{"n":16,"text":"وهذا نص الرسائل التي كتب بها ليسياس الى اليهود من ليسياس الى شعب اليهود سلام"},{"n":17,"text":"قد سلم الينا يوحنا وابشالوم الموجهان من قبلكم كتاب جوابكم وسالا قضاء فحواه"},{"n":18,"text":"فشرحت للملك ما ينبغي انهاؤه اليه فامضى منه ما تحتمله الحال"},{"n":19,"text":"وان بقيتم على الاخلاص فيما بيننا من الامور فاني اتوخى ان اكون لكم فيما ياتي سببا للخير"},{"n":20,"text":"واما تفصيل الامور فقد اوصيناهما مع من نحن مرسلون من قبلنا ان يفاوضوكم فيه"},{"n":21,"text":"والسلام في السنة المئة والثامنة والاربعين في الرابع والعشرين من شهر ديوس كورنتي"},{"n":22,"text":"وهذه صورة رسالة الملك من الملك انطيوكس الى اخينا ليسياس سلام"},{"n":23,"text":"انا منذ انتقل والدنا الى الالهة لم يزل همنا ان يكون اهل مملكتنا بغير بلبال منقطعين الى شؤونهم"},{"n":24,"text":"واذ قد بلغنا ان اليهود غير راضين بما امرهم والدنا من التحول الى سنن اليونان لكنهم متمسكون بمذهبهم ولذلك يسالون \nانتباح لهم سننهم"},{"n":25,"text":"ونحن نريد لهذا الشعب ان يكون كغيره خاليا عن البلبال فانا نحكم بان يرد لهم الهيكل وان يساسوا بمقتضى عادات ابائهم"},{"n":26,"text":"فاذا ارسلت اليهم وعاقدتهم ليطمئنوا اذا علموا راينا فيهم ويقبلوا على مصالحهم بارتياح فنعما تفعل"},{"n":27,"text":"وهذه رسالة الملك الى الامة من الملك انطيوكس الى مشيخة اليهود وسائر اليهود سلام"},{"n":28,"text":"ان كنتم في خير فهذا ما نحب ونحن ايضا في عافية"},{"n":29,"text":"قد اطلعنا منلاوس انكم تودون ان تنزلوا فتقيموا مع قومكم"},{"n":30,"text":"فالذين يرتحلون الى اليوم الثلاثين من شهر كسنتكس يكونون في امان"},{"n":31,"text":"وقد ابحنا لليهود اطعمتهم وشرائعهم كما كانوا عليه من قبل وكل من هفا منهم فيما سلف فلا اعنات عليه"},{"n":32,"text":"وانا مرسل اليكم منلاوس ليشافهكم"},{"n":33,"text":"والسلام في السنة المئة والثامنة والاربعين في الخامس عشر من شهر كسنتكس"},{"n":34,"text":"وارسل الرومانيون اليهم رسالة هذه صورتها من كونتس مميوس وتيطس منليوس رسولي الرومانيين الى شعب اليهود سلام"},{"n":35,"text":"ما رخص لكم فيه ليسياس نسيب الملك نحن موافقون عليه"},{"n":36,"text":"وما استحسن ان يرفع الى الملك تشاوروا فيه وبادروا بارسال واحد لنقضي ما يوافقكم فانا متوجهان الى انطاكية"},{"n":37,"text":"فعجلوا في ارسال من ترسلون لنكون على بصيرة مما تبتغون"},{"n":38,"text":"والسلام في السنة المئة والثامنة والاربعين في الخامس عشر من شهر كسنتكس"}]},{"label":"سفر المكابيين الثاني 12","verses":[{"n":1,"text":"وبعد ابرام هذه المواثيق انصرف ليسياس الى الملك واقبل اليهود على حرث اراضيهم"},{"n":2,"text":"الا ان القواد الذين في البلاد وهم تيموتاوس وابلونيوس بن جنايوس وايرونيمس وديمفون وكذلك نكانور حاكم قبرس لم يدعوا لهم \nراحة ولا سكينة"},{"n":3,"text":"واتى اهل يافا اغتيالا فظيعا وذلك انهم دعوا اليهود المساكنين لهم ان يركبوا هم ونساؤهم واولادهم قوارب كانوا اعدوها لهم \nكان لا عداوة بينهم"},{"n":4,"text":"واذ كان ذلك باجماع اهل المدينة كلهم رضي به اليهود وهم واثقون منهم بالاخلاص وغير متهمين لهم بسوء فلما امعنوا في البحر \nاغرقوهم وكان عددهم يبلغ المئتين"},{"n":5,"text":"فلما بلغ يهوذا ما وقع على بني امته من الغدر الوحشي نادى فيمن معه من الرجال ودعا الله الديان العادل"},{"n":6,"text":"وسار على الذين اهلكوا اخوته واضرم النار في المرفا ليلا واحرق القوارب وقتل الذين فروا الى هناك"},{"n":7,"text":"ولما كانت المدينة مغلقة انصرف في نية الرجوع ومحو دولة اليافيين من اصلها"},{"n":8,"text":"لكن لما علم ان اهل يمنيا ناوون ان يصنعوا بمساكنيهم من اليهود مثل ذلك"},{"n":9,"text":"نزل على اهل يمنيا ليلا واحرق المرفا مع الاسطول حتى رؤى ضوء النار من اورشليم على بعد مئتين واربعين غلوة"},{"n":10,"text":"ثم ساروا من هناك تسع غلوات زاحفين على تيموتاوس فتصدى لهم قوم من العرب يبلغون خمسة الاف ومعهم خمس مئة فارس"},{"n":11,"text":"فاقتتلوا قتالا شديدا وكان الفوز لاصحاب يهوذا بنصرة الله فانكسر عرب البادية وسالوا يهوذا ان يعاقدهم على ان يؤدوا اليهم \nمواشي ويمدوهم بمنافع اخرى"},{"n":12,"text":"ولم يشك يهوذا انه يحصل منهم على جدوى طائلة فرضي بمصالحتهم فعاقدهم فانصرفوا الى اخبيتهم"},{"n":13,"text":"ثم اغار على مدينة حصينة ممنعة بالجسور والاسوار يسكتها لفيف من الامم اسمها كسفيس"},{"n":14,"text":"واذ كان الذين فيها واثقين بمناعة الاسوار ووفرة الميرة اخذوا الامر بالتهاون وطفقوا يشتمون اصحاب يهوذا ويجدفون وينطقون \nبما لا يحل"},{"n":15,"text":"فدعا اصحاب يهوذا رب العالمين العظيم الذي اسقط اريحا على عهد يشوع بغير كباش ولا مجانيق ثم وثبوا على السور كالاسود"},{"n":16,"text":"وفتحوا المدينة بمشيئة الله وقتلوا من الخلق ما لا يحصى حتى ان البحيرة التي هناك وعرضها غلوتان امتلات وطفحت بالدماء"},{"n":17,"text":"ثم ساروا من هناك مسيرة سبع مئة وخمسين غلوة حتى انتهوا الى الكرك الى اليهود الذين يعرفون بالطوبيين"},{"n":18,"text":"فلم يظفروا بتيموتاوس في تلك المواضع لانه كان قد انصرف عنها دون ان يصنع شيئا لكنه ترك في بعض المواضع محرسا منيعا"},{"n":19,"text":"فخرج دوسيتاوس وسوسيباتير من قواد المكابي واهلكا من الجند الذي تركه تيموتاوس في الحصن ما ينيف على عشرة الاف"},{"n":20,"text":"وقسم المكابي جيشه فرقا واقامهما على الفرق وحمل على تيموتاوس وكان معه مئة وعشرون الف راجل والفان وخمس مئة فارس"},{"n":21,"text":"فلما بلغ تيموتاوس مقدم يهوذا وجه النساء والاولاد وسائر الثقل الى مكان يسمى قرنيم وكان موضعا منيعا يصعب فتحه والاقدام \nعليه لانه محاط بالمضايق"},{"n":22,"text":"ولما بدت اول فرقة من جيش يهوذا داخل الاعداء الرعب والرعدة اذ تراءى لهم من يرى كل شيء فبادروا المفر من كل وجه حتى ان بعضهم كان يؤذي بعضا واصاب بعضهم بعضا بحد السيوف"},{"n":23,"text":"وشد يهوذا في اثارهم يثخن في اولئك الكفرة حتى اهلك منهم ثلاثين الف رجل"},{"n":24,"text":"ووقع تيموتاوس في ايدي اصحاب دوسيتاوس وسوسيباتير فطفق يتضرع اليهم بكل وسيلة ان يطلقواه حيا بحجة ان عنده كثيرين من \nابائهم واخوتهم اذا هلك يخذلون"},{"n":25,"text":"واكد لهم العهد بضمانات كثيرة انه يطلقهم سالمين فخلوا سبيله لاجل خلاص اخوتهم"},{"n":26,"text":"ثم اغار يهوذا على قرنيم وهيكل اترجتيس وقتل خمسة وعشرون الف نفس"},{"n":27,"text":"وبعد انكسار اولئك وهلكتهم زحف يهوذا على عفرون احدى المدن الحصينة وكان يسكنها ليسياس وامم شتى وكان على اسوارها شبان \nمن ذوي الباس يقاتلون بشدة ومعهم كثير من المجانيق والسهام"},{"n":28,"text":"فدعا اصحاب يهوذا القدير الذي يحطم باس العدو بشدة فاخذوا المدينة وصرعوا من الذين في داخلها خمسة وعشرين الفا"},{"n":29,"text":"ثم ارتحلوا من هناك وهجموا على مدينة بيت شان وهي على ست مئة غلوة من اورشليم"},{"n":30,"text":"الا ان اليهود المقيمين هناك شهدوا بان اهل بيت شان مصافون لهم وانهم عاملوهم بالاحسان في ازمنة الضيق"},{"n":31,"text":"فشكروهم على صنيعهم واوصوهم ان لا يزالوا معهم على المصافاة ثم جاءوا اورشليم لقرب عيد الاسابيع"},{"n":32,"text":"وبعد العيد المعروف بعيد الخمسين اغاروا على جرجياس قائد ارض ادوم"},{"n":33,"text":"فبرز اليهم في ثلاثة الاف راجل واربع مئة فارس"},{"n":34,"text":"واقتتل الفريقان فسقط من اليهود نفر قليل"},{"n":35,"text":"وكان فيهم فارس ذو باس يقال له دوسيتاوس من رجال بكينور فادرك جرجياس وقبض على ثوبه واجتذبه بقوة يريد ان ياسر ذلك \nالمنافق حيا فعدا عليه فارس من التراكيين وقطع كتفيه وفر جرجياس الى مريشة"},{"n":36,"text":"وتمادى القتال على اصحاب اسدرين حتى كلوا فدعا يهوذا الرب لياخذ بنصرتهم ويقاتل في مقدمتهم"},{"n":37,"text":"وجعل يهتف بالاناشيد بلسان ابائه ثم صرخ وحمل على اصحاب جرجياس بغتة وكسرهم"},{"n":38,"text":"ثم جمع يهوذا جيشه وسار به الى مدينة عدلام ولما كان اليوم السابع تطهروا بحسب العادة وقضوا السبت هناك"},{"n":39,"text":"وفي الغد جاء يهوذا ومن معه على ما تقتضيه السنة ليحملوا جثث القتلى ويدفنوهم مع ذوي قرابتهم في مقابر ابائهم"},{"n":40,"text":"فوجدوا تحت ثياب كل واحد من القتلى انواطا من اصنام يمنيا مما تحرمه الشريعة على اليهود فتبين للجميع ان ذلك كان سبب \nقتلهم"},{"n":41,"text":"فسبحوا كلهم الرب الديان العادل الذي يكشف الخفايا"},{"n":42,"text":"ثم انثنوا يصلون ويبتهلون ان تمحى تلك الخطيئة المجترمة كل المحو وكان يهوذا النبيل يعظ القوم ان ينزهوا انفسهم عن \nالخطيئة اذ راوا بعيونهم ما اصاب الذي سقطوا لاجل الخطيئة"},{"n":43,"text":"ثم جمع من كل واحد تقدمة فبلغ المجموع الفي درهم من الفضة فارسلها الى اورشليم ليقدم بها ذبيحة عن الخطيئة وكان ذلك من \nاحسن الصنيع واتقاه لاعتقاده قيامة الموتى"},{"n":44,"text":"لانه لو لم يكن مترجيا قيامة الذين سقطوا لكانت صلاته من اجل الموتى باطلا وعبثا"},{"n":45,"text":"ولاعتباره ان الذين رقدوا بالتقوى قد ادخر لهم ثواب جميل"},{"n":46,"text":"وهو راي مقدس تقوي ولهذا قدم الكفارة عن الموتى ليحلوا من الخطيئة"}]},{"label":"سفر المكابيين الثاني 13","verses":[{"n":1,"text":"في السنة المئة والتاسعة والاربعين بلغ اصحاب يهوذا ان انطيوكس اوباطور قادم على اليهودية بجيش كثيف"},{"n":2,"text":"ومعه ليسياس الوكيل وقيم المصالح ومعهما جيش من اليونان مؤلف من مئة وعشرة الاف راجل وخمسة الاف وثلاث مئة فارس واثنين \nوعشرين فيلا وثلاث مئة عجلة ذات مناجل"},{"n":3,"text":"فانضم اليهم منلاوس وجعل يحرض انطيوكس بكل نوع من المؤالسة غير مبال بخلاص الوطن بل كان همه ان يرد الى الرئاسة"},{"n":4,"text":"ولكن ملك الملوك هيج سخط انطيوكس على ذلك الكافر فان ليسياس اشربه ان الرجل كان هو السبب في تلك النوازل باسرها فامر \nبان يذهب به الى بيرية ليقتل على عادة البلاد"},{"n":5,"text":"وهناك برج علوه خمسون ذراعا مملوء رمادا وفيه الة مستديرة تهوي براكبها من جميع جهاتها الى الرماد"},{"n":6,"text":"ففي ذلك الموضع اهلك ذلك المختاس للهيكل الذي كان سببا لشرور شتى مدفوعا اليه بايدي الجميع"},{"n":7,"text":"وبهذه المنية هلك منلاوس المنافق ولم يحصل على تربة يوارى فيها"},{"n":8,"text":"وكان ذلك بكل عدل فانه اذ كان قد اجترم جرائم كثيرة على المذبح الذي ناره ورماده مطهران ذاق منيته في الرماد"},{"n":9,"text":"واما الملك فما زال متقدما بعتوه وقساوته متوعدا اليهود بامر من البلايا التي انزلها بهم ابوه"},{"n":10,"text":"فلما علم يهوذا بذلك امر الشعب بالابتهال الى الرب نهارا وليلا ان ينصرهم في ذلك اليوم كما كان يفعل من قبل"},{"n":11,"text":"اذ قد اشرفوا على اضمحلال الشريعة والوطن والهيكل المقدس وان لا يدع الامم المجدفة تذل شعبه الذي لم يفرج عنه الا من \nامديسير"},{"n":12,"text":"ففعلوا كلهم وتضرعوا الى الرب الرحيم بابكاء والصوم والسجود مدة ثلاثة ايام بلا انقطاع ثم حرضهم يهوذا وامرهم بالاجتماع"},{"n":13,"text":"وخلا بالشيوخ وابرم معهم مشورة ان يخرجوا ويقضوا الامر بتاييد الرب قبل ان يدخل جيش الملك اليهودية ويستحوذ على المدينة"},{"n":14,"text":"ففوض الامر الى خالق الكائنات وحض اصحابه ان يقاتلوا ببسالة ويبذلوا انفسهم دون الشريعة والهيكل والمدينة والوطن \nوالدولة ونصب محلته عند مودين"},{"n":15,"text":"وجعل لهم كلمة السر النصر بالله ثم اختار قوما من نخب الشبان وهجم ليلا على مخيم الملك في المحلة وقتل اربعة الاف رجل \nواهلك اول الفيلة مع القوم الذين كانوا في برجه"},{"n":16,"text":"وملاوا المحلة رعبا واضطرابا وانقلبوا فائزين بوقاية الرب التي كانت تكتنفه"},{"n":17,"text":"وتمت له هذه النصرة عند طلوع الفجر"},{"n":18,"text":"فلما ذاق الملك ما عند اليهود من البطش عمد الى اخذ المعاقل بالحيلة"},{"n":19,"text":"فحاصر بيت صور وهي محرس منيع ليهود فانكسر وارتد منكوسا خاسرا"},{"n":20,"text":"وكان يهوذا يمد الذين فيها بما يحتاجون اليه"},{"n":21,"text":"وان رجلا من جيش اليهود اسمه رودكس كاشف العدو باسرارهم فطلبوه وقبضوا عليه وسجنوه"},{"n":22,"text":"فعاد الملك وخاطب اهل بيت صور وعرض عليهم الصلح فعاقدوه وانصرف"},{"n":23,"text":"وبعد ان قاتل يهوذا وانكسر بلغه ان فيلبس الذي كان قد ترك في انطاكية لتدبير الامور قد تمرد عليه فوقع في حيرة وتوسل \nالى اليهود ودان لهم وحالفهم على اعطاء حقوقهم كلها وسالمهم وقدم ذبيحة واكرم الهيكل واحسن الى الموضع"},{"n":24,"text":"وصافى المكابي ونصبه قائدا وحاكما على البلاد من بطلمايس الى حدود الجرانيين"},{"n":25,"text":"ثم جاء الى بطلمايس وكان اهل المدينة قد شق عليهم ذلك العهد وانكروا عليه فسخ عهودهم"},{"n":26,"text":"فانطلق ليسياس الى الديوان واورد ما استطاع من الحجج فاقنعهم وسكنهم وميلهم الى الرفق ثم عاد الى انطاكية وهكذا انقضى \nمقدم الملك ورجوعه"}]},{"label":"سفر المكابيين الثاني 14","verses":[{"n":1,"text":"وبعد مدة ثلاث سنين بلغ اصحاب يهوذا ان ديمتريوس بن سلوقس قد ركب البحر من ميناء طرابلس بجيش كثيف واسطول"},{"n":2,"text":"واستولى على البلاد بعد ما قتل انطيوكس وليسياس وكيله"},{"n":3,"text":"وان الكيمس الذي كان قد قلد الكهنوت الاعظم ثم انقاد الى النجاسة ايام الاختلاط ايقن ان لا خلاص له البتة ولا سبيل الى ارتقاء \nالمذبح المقدس"},{"n":4,"text":"فاتى ديمتريوس الملك في السنة المئة والحادية والخمسين واهدى اليه اكليلا من ذهب وسعفة واغصانا من زيتون مما يختص \nبالهيكل وبقي في ذلك اليوم ساكتا"},{"n":5,"text":"ثم اصاب فرصة توافق رعونة مقاصده فان ديمتريوس دعاه الى ديوانه وساله عن احوال اليهود وما في نياتهم"},{"n":6,"text":"فقال ان الحسيديين من اليهود الذين عليهم يهوذا المكابي لا يزالون في الحروب والفتن ولا يدعون للملكة راحة"},{"n":7,"text":"وهاءنذا قد سلبت كرامة ابائي اعني الكهنوت الاعظم فقدمت الى هنا"},{"n":8,"text":"اولا لاوفي خدمتي فيما ياول الى مصلحة الملك وثانيا للسعي في مصلحة قومي لان سفه اولئك الناس قد انزل بامتنا البلاء الشديد"},{"n":9,"text":"فاذ قد اطلعت ايها الملك على تفصيل ذلك فالتفت الى بلادنا وامتنا المبغي عليها بما فيك من الرفق والاحسان الى الجميع"},{"n":10,"text":"فانه ما دام يهوذا باقيا فمن المحال ان تكون الاحوال في دعة"},{"n":11,"text":"ولما اتم مقاله جعل سائر اصدقاء ديمتريوس وهم اعداء ليهوذا ويوغرونه عليه"},{"n":12,"text":"فاستحضر من ساعته نكانور مدبر الفيلة واقامه قائدا على اليهودية وارسله"},{"n":13,"text":"وامره ان يقتل يهوذا ويبدد اصحابه ويقيم الكيمس كاهنا اعظم للهيكل الشهير"},{"n":14,"text":"فاخذ الامم الذين في اليهودية يفرون عن يهوذا وينضمون افواجا الى نكانور وهم يعدون نكبات اليهود ورزاياهم حظا لهم"},{"n":15,"text":"ولما بلغ اليهود قدوم نكانور وانضمام الامم اليه حثوا التراب على رؤوسهم وابتهلوا الى الذي اقام شعبه ليبقى مدى الدهر \nمدافعا عن ميراثه بايات بينة"},{"n":16,"text":"ثم امرهم القائد فبادروا المسير من هناك والتقوهم عند قرية دساو"},{"n":17,"text":"وكان سمعان اخو يهوذا قد نازل نكانور فجاءته نجدة على حين بغتة فادركه بعض الفشل"},{"n":18,"text":"ولكن لما سمع نكانور بما ابداه اصحاب يهوذا من الباس والبسالة في مدافعاتهم عن الوطن اشفق من ان يفصل الامر بالسلاح"},{"n":19,"text":"فارسل بوسيدونيوس وتاودوتس ومتتيا لعرض الصلح وامضائه"},{"n":20,"text":"فبحثوا في الامر طويلا وعرض القائد ذلك على الجمهور فاجمعوا كلهم على راي واحد وقبلوا العهد"},{"n":21,"text":"وعينوا يوما يواجهونهم فيه سرا فاقبل نكانور وجيء بالكراسي من الجانبين"},{"n":22,"text":"واقام يهوذا رجالا متسلحين متاهبين في المواضع الموافقة مخافة ان يدهمهم الاعداء بشر ثم تفاوضوا وعقدوا الاتفاق"},{"n":23,"text":"واقام نكانور باورشليم لا ياتي منكرا واطلق الجيوش التي اجتمعت اليه افواجا"},{"n":24,"text":"وكان كثير التردد الى يهوذا وصبا اليه بقلبه"},{"n":25,"text":"وحثه على الزواج والاستيلاد فتزوج ولبث في راحة وطيب عيش"},{"n":26,"text":"ولما راى الكيمس ما هما فيه من التصافي والتعاهد عاد فاتى الى ديمتريوس وقال ان نكانور يرى في الامور راي الفساد وانه \nقد عين في موضعه يهوذا الكامن للملكة كاهنا اعظم"},{"n":27,"text":"فاستشاط الملك غضبا ووغر صدره بسعاية ذلك الفاجر فكتب الى نكانور يقول انه ساخط من ذلك العهد ويامره بان يبادر الى \nارسال المكابي مقيدا الى انطاكية"},{"n":28,"text":"فلما وقف نكانور على ذلك ادركته الحيرة وصعب عليه ان ينقض عهده ولم ير من الرجل ظلما"},{"n":29,"text":"ولكن اذ لم يجد سبيلا الى مقاومة الملك تربص فرصة ليمضي الامر بالمكيدة"},{"n":30,"text":"وراى المكابي ان نكانور قد تغير عليه ولم يعد يتلقاه ببشاشته المالوفة ففطن ان هذا التغير ليس عن خير فجمع عددا من \nاصحابه وتغيب عن نكانور"},{"n":31,"text":"فلما راى نكانور ان الرجل قد سبقه بحزمه ودهائه انطلق الى الهيكل العظيم المقدس وكان الكهنة يقدمون الذبائح على عادتهم \nفامرهم ان يسلموا اليه الرجل"},{"n":32,"text":"فاقسموا وقالوا انهم لا يعلمون اين الذي يطلبه فمد يمينه على الهيكل"},{"n":33,"text":"واقسم قائلا لئن لم تسلموا الي يهوذا موثقا لاهدمن بيت الله هذا الى الارض ولاقلعن المذبح واشيدن هنا هيكلا شهيرا لديونيسيوس"},{"n":34,"text":"قال هذا وانصرف فرفع الكهنة ايديهم الى السماء ودعوا من هو نصير امتنا على الدوام قائلين"},{"n":35,"text":"يا من هو رب الجميع الغني عن كل شيء لقد حسن لديك ان يكون هيكل سكناك فيما بيننا"},{"n":36,"text":"فالان ايها الرب يا قدوس كل قداسة صن هذا البيت الذي قد طهر عن قليل واحفظه طاهرا الى الابد"},{"n":37,"text":"وكان في اورشليم شيخ اسمه رازيس وهو رجل محب لوطنه محمود السمعة يسمى بابي اليهود لما كان عنده من الغيرة عليهم فوشي \nبه الى نكانور"},{"n":38,"text":"وكان فيما سلف من ايام الاختلاط مخلص التمسك بدين اليهود ولم يزل يبذل جسمه ونفسه في سبيل الدين"},{"n":39,"text":"واراد نكانور ان يبدي ما كان عنده من الحنق على اليهود فارسل اكثر من خمس مئة جندي ليقبضوا عليه"},{"n":40,"text":"لاعتقاده انه ان امسكه فقد انزل بهم مصيبة عظيمة"},{"n":41,"text":"فلما راى الجنود قد اوشكوا ان يستولوا على البرج ويفتحوا باب الدار وقد اطلقوا النار لاحراق الابواب واصبح محاطا من كل \nجانب وجا نفسه بالسيف"},{"n":42,"text":"واختار ان يموت بكرامة ولا يصير في ايدي المجرمين ويشتم بما لا يليق باصله الكريم"},{"n":43,"text":"ولكنه لعجلته اخطا المقتل واذ كانت الجنود قد هجمت الى داخل الابواب رقي الى السور بقلب جليد والقى بنفسه من فوق الجنود"},{"n":44,"text":"فانفرجوا لحينهم فسقط في وسط الفرجة"},{"n":45,"text":"واذ كان به رمق وقد اشتعلت فيه الحمية قام ودمه يتفجر كالينبوع وجراحه بالغة واخترق الجنود عدوا"},{"n":46,"text":"واستولى قائما على صخرة عالية وقد نزف دمه ثم اخرج امعاءه وحملها بيديه وطرحها على الجند ودعا رب الحياة والروح ان \nيردهما عليه ثم فاضت نفسه"}]},{"label":"سفر المكابيين الثاني 15","verses":[{"n":1,"text":"وبلغ نكانور ان اصحاب يهوذا في نواحي السامرة فعزم على مفاجاته يوم السبت دون تعرض لخطر الحرب"},{"n":2,"text":"فقال له اليهود الذين شايعوه اضطرارا لا تاخذ القوم بهذه القسوة والخشونة بل ارع حرمة يوم قد اكرمه وقدسه الرقيب على كل شيء"},{"n":3,"text":"فسال ذلك الفاجر وهل في السماء قدير امر بحفظ يوم السبت"},{"n":4,"text":"فقالوا ان في السماء الرب الحي القدير وهو الذي اوصى بحفظ اليوم السابع"},{"n":5,"text":"فقال الرجل وانا ايضا قدير في الارض فامر باخذ السلاح وامضاء اوامر الملك ولكنه لم يتمكن من قضاء ماربه الخبيث"},{"n":6,"text":"وكان نكانور بما عنده من الزهو والصلف مضمرا ان ينصب تذكارا يشير به الى جميع غلباته على اصحاب يهوذا"},{"n":7,"text":"واما المكابي فلم يزل يثق كل الثقة بان الرب سيؤتيه النصر"},{"n":8,"text":"فحرض اصحابه ان لا يجزعوا من غارة الامم بل يذكروا النجدات التي طال ما امدوا بها من السماء وينتظروا الظفر والنصرة التي \nسيؤتونها من عند القدير"},{"n":9,"text":"ثم كلمهم عن الشريعة والانبياء وذكر لهم الوقائع التي باشروها حتى اذكى حماستهم"},{"n":10,"text":"وبعدما ثبت عزائمهم شرح لهم كيف نقضت الامم عهودها وحنثت بايمانها"},{"n":11,"text":"وسلح كلا منهم بتعزية كلامه الصالح اكثر مما سلحهم بالتروس والرماح ثم قص عليهم رؤيا يقينية تجلت له في الحلم فشرح بها \nصدورهم اجمعين"},{"n":12,"text":"وهذه هي الرؤيا قال رايت اونيا الكاهن الاعظم رجل الخير والصلاح المهيب المنظر الحليم الاخلاق صاحب الاقوال الرائعة المواظب \nمنذ صبائه على جميع ضروب الفضائل باسطا يديه ومصليا لاجل جماعة اليهود باسرها"},{"n":13,"text":"ثم تراءى لي رجل كريم الشيبة اغر البهاء عليه جلالة عجيبة سامية"},{"n":14,"text":"فاجاب اونيا وقال هذا محب الاخوة المكثر من الصلوات لاجل الشعب والمدينة المقدسة ارميا نبي الله"},{"n":15,"text":"ثم ان ارميا مد يمينه وناول يهوذا سيفا من ذهب وقال"},{"n":16,"text":"خذ هذا السيف المقدس هبة من عند الله به تحطم الاعداء"},{"n":17,"text":"فطابت قلوبهم باقوال يهوذا الصالحة التي حركت بقوتها حماستهم واثارت نفوس الشبان وعقدوا عزمهم على ان لا يعسكروا بل \nيهجموا بشجاعة ويحاربوا بكل بسالة حتى يفصلوا الامر اذ كانت المدينة والاقداس والهيكل في خطر"},{"n":18,"text":"وكان اضطرابهم على النساء والاولاد والاخوة وذوي القرابات ايسر وقعا من خوفهم على الهيكل المقدس الذي كان هو الخوف الاعظم \nوالاول"},{"n":19,"text":"وكان الباقون في المدينة في اضطراب شديد من قبل القتال الذي كانوا يتوقعونه في الفضاء"},{"n":20,"text":"وبينا كان الجميع ينتظرون ما ياول اليه الامر وقد ازدلف العدو واصطف الجيش واقيمت الفيلة في مواضعها وترتبت الفرسان على \nالجناحين"},{"n":21,"text":"تفرس المكابي في كثرة الجيوش وتوفر الاسلحة المختلفة وضراوة الفيلة فرفع يديه الى السماء ودعا الرب الرقيب صانع \nالمعجزات لعلمه ان ليس الظفر بالسلاح ولكنه بقضائه يؤتي الظفر من يستحقه"},{"n":22,"text":"وصلى قائلا انك يا رب قد ارسلت ملاكك في عهد حزقيا ملك يهوذا فقتل من جند سنحاريب مئة وخمسة وثمانين الفا"},{"n":23,"text":"والان يا ملك السماوات ارسل ملاكا صالحا امامنا يوقع الرعب والرعدة وبعظمة ذراعك"},{"n":24,"text":"ليتروع الذين وافوا على شعبك المقدس مجدفين وكان يهوذا يصلي هكذا"},{"n":25,"text":"واصحاب نكانور يتقدمون بالابواق والاغاني"},{"n":26,"text":"فواقعهم اصحاب يهوذا بالدعاء والصلوات"},{"n":27,"text":"وفيما هم يقاتلون بالايدي كانوا يصلون الى الله في قلوبهم فصرعوا خمسة وثلاثين الفا وهم في غاية التهلل بمحضر الله ونصرته"},{"n":28,"text":"ولما فرغوا من الجهاد ورجعوا مبتهجين وجدوا نكانور بسلاحه وقد خر قتيلا"},{"n":29,"text":"حينئذ ارتفع الهتاف والزجل وسبحوا الملك العظيم بلسان ابائهم"},{"n":30,"text":"ثم ان يهوذا الذي لم يزل في مقدمة اهل وطنه باذلا دونهم جسده ونفسه وراعيا لبني امته المودة التي اثرهم بها منذ حداثته \nامر بقطع راس نكانور ويده مع كتفه وحملهما الى اورشليم"},{"n":31,"text":"ولما بلغ الى هناك دعا بني امته والكهنة وقام امام المذبح واستحضر الذين في القلعة"},{"n":32,"text":"واراهم راس نكانور الفاحش ويد ذلك الفاجر التي مدها متجبرا على بيت القدير المقدس"},{"n":33,"text":"ثم قطع لسان نكانور المنافق وامر بان يقطع قطعا ويطرح الى الطيور وتعلق يد ذلك الاحمق تجاه الهيكل"},{"n":34,"text":"وكان الجميع يباركون الى السماء الرب الحاضر لنصرتهم قائلين تبارك الذي حفظ موضعه من كل دنس"},{"n":35,"text":"وربط راس نكانور على القلعة ليكون دليلا بينا جليا على نصرة الله"},{"n":36,"text":"ثم رسم الجميع بتوقيع عام ان لا يترك ذلك اليوم بدون احتفال"},{"n":37,"text":"بل يكون عيدا وهو اليوم الثالث عشر من الشهر الثاني عشر الذي يقال له اذار بلسان ارام قبل يوم مردكاي بيوم واحد"},{"n":38,"text":"هذا ما تم من امر نكانور ومنذ تلك الايام عادت المدينة في حوزة العبرانيين وههنا انا ايضا اجعل ختام الكلام"},{"n":39,"text":"فان كنت قد احسنت التاليف واصبت الغرض فذلك ما كنت اتمنى وان كان قد لحقني الوهن والتقصير فاني قد بذلت وسعي"},{"n":40,"text":"ثم كما ان اشرب الخمر وحدها او شرب الماء وحده مضر وانما تطيب الخمر ممزوجة بالماء وتعقب لذة وطربا كذلك تنميق الكلام \nعلى هذا الاسلوب يطرب مسامع مطالعي التاليف. انتهى."}]}],"sources":["https://ar.wikisource.org/wiki/سفر_المكابيين_الثانى"]}];